  [85] = "Ihr Satz enthält kein Verb.*",
  [86] = "Ihr Satz ergibt für mich keinen Sinn.*",
  [87] = "Ich verstehe \"alles\" nicht.*",
  [88] = "Ihr Satz enthält kein Objekt.*",
  [89] = "Ich verstehe Ihren Satz nicht.*",
  [90] = "Was wollen Sie nehmen?*",
  [91] = "Hier liegt nichts zum Mitnehmen.*",
