  [95] = " *",
  [96] = " *",
  [97] = "In diese Richtung führt kein Weg.*",
  [98] = "Eine verschlossene Tür versperrt Ihnen den Weg.*",
  [99] = "Bitte eine formatierte Diskette einlegen.*",
  [100] = "Bitte Position eingeben (1-9).*",
  [101] = "Bitte Spieldiskette \"B\" einlegen.*",
  [102] = "Als Angestellter einer alteingesessenen",
  [103] = "Immobilienfirma hat man gewisse Aufgaben.",
  [104] = "Büroarbeit, Häuser besichtigen, Kunden betreuen -",
  [105] = "und vieles mehr. Wenn einem der Chef jedoch den",
  [106] = "Auftrag erteilt, ein paar Nächte in einem der",
  [107] = "Häuser zu verbringen, dann ist das - welche",
  [108] = "Gründe er auch immer hatte -  ganz einfach ein",
  [109] = "furchtbares Pech! Besonders, wenn es sich dabei",
  [110] = "um das berüchtigte Hawthorne-Haus handelt!",
  [111] = "Es sei denn, man liebt Gerüchte über seltsame",
  [112] = "Klopfgeräusche, die in mondlosen Nächten aus dem",
  [113] = "uralten Mauerwerk dringen sollen; über das ungute",
  [114] = "Knirschen des morschen Dachgebälks oft um die",
  [115] = "Zeit des Morgengrauens, oder man mag die",
  [116] = "beklemmenden Geschichten, die sich die Bewohner",
  [117] = "unten im Tal zuflüstern.",
  [118] = "Wie dem auch sei, von den Bewohnern im Dorf,",
  [119] = "unter denen sich ihre Ankunft wie ein Lauffeuer",
  [120] = "herumgesprochen hat, würde keiner auch nur einen",
  [121] = "Penny wetten, daß Sie es länger als eine Nacht",
  [122] = "dort aushalten. In dem alten Hawthorne-Haus,",
  [123] = "das einsam und dunkel zwischen verwachsenen",
  [124] = "Bäumen und bräunlichem Gras auf dem verrufenen",
  [125] = "Lone Hill steht.*",
  [126] = "In der Eingangshalle",
  [127] = "Hier, in der würdigen Eingangshalle des Hawthorne-",
  [128] = "Hauses, führt eine Treppe hinauf in den ersten",
  [129] = "Stock, und Türen nach Osten in die Bibliothek und",
  [130] = "nach Westen in das Gesellschaftszimmer. Den Garten",
  [131] = "kann man durch die Haustüre nach Süden erreichen.",
  [132] = "An der Wand hängt ein riesiges Gemälde, und neben",
  [133] = "der Treppe ist ein stilvoller Kamin eingebaut,",
  [134] = "über dem ein Spiegel hängt. Ein dunkelroter",
  [135] = "Teppich bedeckt fast den ganzen Boden der Halle.*",
  [136] = "Von der Decke hängt ein vielarmiger Kristallüster",
  [137] = "herab.*",
  [138] = "Mitten auf dem Boden liegt ein Zettel.*",
  [139] = "Es ist ein offener Zettel, der den Briefkopf und",
  [140] = "das Siegel der renommierten Immobilienfirma",
  [141] = "Bedford, Bedford & Mortimer aus Galway, Ireland,",
  [142] = "trägt. Oben steht, in blauer Tinte und mit",
  [143] = "gestochener Handschrift aufgetragen: An Charles",
  [144] = "McMullighan, Hawthore-House.*",
  [145] = "McMullighan!",
  [146] = "Hoffe, Sie sind zeitig angekommen. Treffe",
  [147] = "Mittwoch früh mit Kundschaft ein. Erwarte, daß",
  [148] = "Sie bis dahin den Laden piko-bello aufgeräumt",
  [149] = "haben!",
  [150] = "Und schaffen Sie endlich dieses lächerliche",
  [151] = "Gerücht aus der Welt, daß es in diesem Hause",
  [152] = "spuke! Wahrscheinlich müssen Sie nur ein paar",
  [153] = "knarrende Dachbalken wieder festnageln.",
  [154] = "Also, sputen Sie sich! Grüße, B. Mortimer.*",
  [155] = "Der Lüster muß wenigstens eine Viertel-Tonne",
  [156] = "wiegen. Er besitzt zwei Dutzend kristallner Arme,",
  [157] = "auf denen sich jeweils drei Kerzen befinden. Er",
  [158] = "hängt an einem starken Seil.*",
  [159] = "Es ist ein starkes Hanfseil, bestimmt drei",
  [160] = "Zentimeter im Duchmesser und zehn Meter lang.*",
  [161] = "Das Seil führt an der Decke entlang und",
  [162] = "schließlich die Wand hinab, wo es neben der Türe",
  [163] = "zur Bibliothek an einem Haken festgezurrt ist.",
  [164] = "Man kann den Lüster wohl herunterlassen, um im",
  [165] = "Bedarfsfall seine Kerzen zu entzünden.*",
  [166] = "Das geht nicht so leicht. Das Seil ist wegen des",
  [167] = "kollossalen Gewichtes des Lüsters straff wie eine",
  [168] = "Bogensehne, und lässt sich nicht vom Haken lösen.",
  [169] = "Um ihn herunter zu lassen, mussten in früheren",
  [170] = "Zeiten vier Hausangestellte zugleich anpacken!*",
  [171] = "Vorsiiiicht....... Rrrrrrruummssss!!!!! Mit",
  [172] = "lautem Krach donnert der schwere Kristallüster",
  [173] = "auf den Boden der Halle!*",
  [174] = "Auf dem Boden der Halle liegen die",
  [175] = "bedauernswerten Trümmer eines einstmals sehr",
  [176] = "kostbaren, schweren Kristall-Lüsters. Hier muß",
  [177] = "ein Vandale gewütet haben!*",
  [178] = "An seinem oberen Ende ist ein starkes Seil",
  [179] = "befestigt.*",
  [180] = "Sie sind vielleicht lustig! So leicht geht das",
  [181] = "nicht... ächz... das Ding ist bombenfest",
  [182] = "verknotet... uff... es hängt da schließlich schon",
  [183] = "seit Urzeiten... puuuh.... da kann man sich ja",
  [184] = "die Finger abbrechen.... so! Endlich ab. Wir",
  [185] = "demolieren uns unsere kostbaren Finger, und Sie",
  [186] = "heimsen die Punkte ein! Jaja!*",
  [187] = "Ein Jammer! Die Kerzen haben den Sturz nur in",
  [188] = "pulverisierter Form überstanden. Aber... halt! Da",
  [189] = "liegt noch eine, die einigermaßen heil geblieben",
  [190] = "ist!*",
  [191] = "Hier gibt es nur noch völlig zerschmetterte",
  [192] = "Überbleibsel. Keine Kerze mehr in Sicht.*",
  [193] = "Es ist nichts als eine gewöhnliche Wachskerze.*",
  [194] = "Sie ist aus.*",
  [195] = "Sie brennt.*",
  [196] = "Fein. Ihre Kerze brennt jetzt.*",
  [197] = "Pfffft. Okay - sie ist jetzt aus.*",
  [198] = "Ein Gemälde von dieser Größe und Kunstfertigkeit",
  [199] = "wäre sicher eine Menge wert. Leider aber stellt",
  [200] = "es ein beängstigendes Chaos von Monstern und",
  [201] = "unirdischen Landschaften dar. Um einen großen",
  [202] = "Edelstein, der in der Mitte abgebildet ist, sind",
  [203] = "verschiedene Szenen angeordnet. Unter dem Gemälde",
  [204] = "hängt an der Wand ein kleines Schild.*",
  [205] = "Es sind sechs Szenen zu sehen, die ineinander",
  [206] = "übergehen. Eine zeigt einen riesigen Wald unter",
  [207] = "rötlicher Sonne, eine andere eine weite Eiswüste,",
  [208] = "eine dritte ein gewaltiges, aufrecht stehendes",
  [209] = "Monstrum. Dann ist da noch ein einsamer Ozean zu",
  [210] = "sehen; eine fünfte Szene zeigt ein einsames Haus",
  [211] = "auf einem Hügel, und die sechste das Innere eines",
  [212] = "großen, finsteren Bergwerkes. Unten am Rand, als",
  [213] = "Signatur, steht: Kunstmalerei Moser.*",
  [214] = "Die Signatur enthält nur den Hinweis:",
  [215] = "\"Kunstmalerei Moser\".*",
  [216] = "Es ist ein kleines, goldenes Schildchen, das mit",
  [217] = "einer Schraube an der Wand befestigt wurde. Es",
  [218] = "handelt sich offenbar um den Titel des Bildes,",
  [219] = "der dort eingraviert ist: \"Das Auge des Kal\".*",
  [220] = "Es ist ein kleines, goldenes Schildchen, auf dem",
  [221] = "die Worte: \"Das Auge des Kal\" eingraviert sind.*",
  [222] = "Jaja, diese Abbildungen werfen ungezählte Fragen",
  [223] = "auf. Aber das Gemälde selbst gibt leider keine",
  [224] = "weiteren Aufschlüsse darüber.*",
  [225] = "Der Edelstein ist in sechs gleiche Teile",
  [226] = "aufgespalten - ein Techniker würde dafür wohl das",
  [227] = "Wort 'Explosionszeichnung' verwenden.*",
  [228] = "Hm! Sie scheinen auf der Suche nach etwas zu",
  [229] = "sein, nicht? Nun - dieses Schildchen ist mit",
  [230] = "einer Schraube fest an der Wand verankert. Da",
  [231] = "läßt sich so leicht nichts bewegen.*",
  [232] = "Es handelt sich um eine große Schraube. Sie hat",
  [233] = "einen breiten Schlitz - sehr zur Freude der",
  [234] = "Gattung der Schraubenzieher, wie man hört.*",
  [235] = "Es ist eine etwa vier Zentimeter lange Schraube.",
  [236] = "Eigentlich ein sehr gewöhnliches Ding, mitunter",
  [237] = "aber von nicht zu unterschätzendem",
  [238] = "Gebrauchswert!*",
  [239] = "Aaaah! Gar nicht so dumm! Probieren wir's mal...",
  [240] = "ha, es klappt! Nach kurzer Zeit haben Sie die",
  [241] = "Schraube gelöst.*",
  [242] = "Kling! Das goldene Schildchen fällt zu Boden...",
  [243] = "oh! Dahinter ist ein kleines Fach sichtbar",
  [244] = "geworden!*",
  [245] = "Nun - es handelt sich um ein kleines Geheimfach,",
  [246] = "wie es scheint.*",
  [247] = "Ein kleines, goldenes Schlüsselchen liegt darin!*",
  [248] = "Das winzige Fach ist leer.*",
  [249] = "Gut. Das Schlüsselchen gehört nun Ihnen!*",
  [250] = "Der Teppich ist in ebenso dumpfen, roten Farben",
  [251] = "gehalten wie das große Gemälde an der Wand. Er",
  [252] = "besitzt ein eigenartiges, diffuses Muster.*",
  [253] = "Sie wünschen eine Beschreibung von sich selbst?",
  [254] = "Gute Idee. Das ist nämlich ein Einweg-Spiegel.",
  [255] = "Moment, wir müssen erst unser geheimes Video-Auge",
  [256] = "justieren.... so, jetzt haben wir ein Bild!",
  [257] = "Aber.... was ist das? Du lieber Himmel! So sehen",
  [258] = "Sie also aus? Sie sollten sich mal kämmen, Sie!",
  [259] = "Und rasieren! Ist das überhaupt ein Bart, oder",
  [260] = "was? Ja, ist das denn die Möglichkeit...!*",
  [261] = "In diesem Augenblick ertönt unerwartet der",
  [262] = "Türgong.*",
  [263] = "Wieder ertönt der Türgong.*",
  [264] = "Ein weiteres Mal ist der Türgong zu hören. Wollen",
  [265] = "Sie nicht nachsehen, wer da ist?*",
  [266] = "Ein kleiner Mann in Uniform sieht Sie freundlich",
  [267] = "an. Es ist der Postbote, seine Kleider sind naß",
  [268] = "vom Regen. Draußen ist die Dunkelheit schon",
  [269] = "hereingebrochen.",
  [270] = "\"Hallo!\" sagt er lächelnd. \"Ich habe Post für",
  [271] = "Sie!\" Er kramt in seiner großen Ledertasche, holt",
  [272] = "einen großen, braunen Umschlag hervor, und hält",
  [273] = "ihn Ihnen hin.*",
  [274] = "\"Hier! Nun nehmen Sie es doch!\" sagt der",
  [275] = "Postbote, und hält Ihnen den Umschlag vor die",
  [276] = "Nase.*",
  [277] = "\"Ziemlich seltsame Post sogar, würde ich sagen,\"",
  [278] = "kommentiert er. Er forscht eine Weile in Ihrem",
  [279] = "Gesicht. \"Oh,\" sagt er dann, \"haben Sie letzte",
  [280] = "Woche denn die Lokalnachrichten nicht gelesen?\"*",
  [281] = "Er schaut Sie schief an - in seinem Gesicht steht",
  [282] = "förmlich die Frage geschrieben, ob sie - wie der",
  [283] = "Vorbesitzer dieses Hauses, ein ähnlich",
  [284] = "sonderliches Benehmen haben. \"Wollen Sie meine",
  [285] = "Frage nicht beantworten?\"*",
  [286] = "\"Dieser Umschlag ist sozusagen Post aus dem",
  [287] = "Jenseits,\" erklärt er. \"Vorige Woche hat man",
  [288] = "einen Postdampfer gehoben, der vor über siebzig",
  [289] = "Jahren draußen im Fluß gesunken ist! Ein Teil der",
  [290] = "Post lag in einer Stahlkammer, und ist nicht",
  [291] = "beschädigt worden. Und nun werden die Sendungen",
  [292] = "doch noch ordnungsgemäß zugestellt. Lustig, was?\"*",
  [293] = "Der Postbote schließt seine Tasche wieder, legt",
  [294] = "seine Hand an die Mütze, verabschiedet sich und",
  [295] = "marschiert davon. Als er den Gartenweg zur Hälfte",
  [296] = "hinter sich hat, deutet er auf einen Abdruck im",
  [297] = "feuchten Boden. \"Ein komisches Haustier haben",
  [298] = "Sie!\" ruft er. \"Da kann man ja Angst kriegen!\"",
  [299] = "Kurz darauf steigt er in sein Postauto und brummt",
  [300] = "davon.*",
  [301] = "Der Umschlag ist etwa so groß wie ein Buch, und",
  [302] = "sieht aus, als wäre er vor Urzeiten verschickt",
  [303] = "worden. Die Adresse und der Absender sind mit",
  [304] = "gestochen scharfer, aber völlig altertümlicher",
  [305] = "Kanzleischrift aufgetragen worden.*",
  [306] = "Zusätzlich ist der Umschlag mit einer Kordel",
  [307] = "verschnürt.*",
  [308] = "Die Kordel ist von dem Umschlag entfernt worden.",
  [309] = "Er ist aber noch zu.*",
  [310] = "Der Umschlag ist geöffnet.*",
  [311] = "In dem Umschlag befinden sich folgende",
  [312] = "Gegenstände:*",
  [313] = "Ein Brief, der an Owen Jugger adressiert",
  [314] = "ist.*",
  [315] = "Ein seltsames Bruchstück... man könnte sagen: der",
  [316] = "Splitter eines Edelsteines von schwer",
  [317] = "definierbarer Farbe.*",
  [318] = "Ein kleines Heft, auf dem die Worte:",
  [319] = "\"Persönliches Tagebuch von Owen Jugger\"",
  [320] = "aufgetragen sind.*",
  [321] = "Der Umschlag ist leer.*",
  [322] = "Eine Kopie des Briefes liegt Ihrem Spiel bei.*",
  [323] = "Okay. Der Splitter gehört nun Ihnen!*",
  [324] = "Es handelt sich um den Splitter eines offenbar",
  [325] = "großen Edelsteines, von unregelmäßiger Form und",
  [326] = "schwer definierbarer Farbe. Aber irgendeine",
  [327] = "erstaunliche Kraft scheint in ihm zu schlummern!*",
  [328] = "Das Tagebuch des Owen Jugger liegt Ihrem Spiel",
  [329] = "bei!*",
  [330] = "Der Umschlag ist an Owen Jugger, den",
  [331] = "Vorbesitzer dieses Hauses adressiert!*",
  [332] = "Als Absender ist ein Sir John Pilestaff vermerkt,",
  [333] = "wohnhaft in London, U.K. Kensington Road 345B.",
  [334] = "Der Poststempel auf der Marke allerdings ist",
  [335] = "schon ein überraschtes Zusammenzucken wert: 28.",
  [336] = "Januar 1917!*",
  [337] = "DIE BLAUE MAURITIUS! Sie sind reeeiiiiiiiich!!!!!",
  [338] = "Oh Mann - das gibt's ja nicht! Wir freuen uns,",
  [339] = "Ihnen mitteilen zu können, daß Sie für diesen",
  [340] = "Fund sämtliche Spielpunkte auf einen Schlag",
  [341] = "bekommen, und das Spiel somit gelöst haben! Sie",
  [342] = "können nun Ihren Computer ausschalten, die",
  [343] = "Spieleschachtel wegwerfen, und die Disketten für",
  [344] = "was anderes benutzen! Allerherzlichsten",
  [345] = "Glückwunsch!*",
  [346] = "Wie? Sie sind noch da? Wollen Sie etwa die Marke",
  [347] = "nicht?*",
  [348] = "Das ist recht so! Sie ist mit Sicherheit ein paar",
  [349] = "Millionen wert! Und dazu noch alle Spielpunkte!",
  [350] = "Bravo, für Ihre Entscheidung! Sie können nun",
  [351] = "Ihren Computer ausschalten!*",
  [352] = "Waaaas? Sie wollen die BLAUE MAURITIUS nicht? Ist",
  [353] = "das Ihr Ernst...?",
  [354] = "(.... ratloses, betroffenes Schweigen.....)",
  [355] = "Okay. Gut. Alles klar. Schon kapiert. Verstanden.",
  [356] = "Sie wollen also diese... langweilige Briefmarke",
  [357] = "nicht. Dann - nun, dann behalten WIR sie halt.",
  [358] = "Ist ja auch wurscht, oder? Wir... kümmern uns um",
  [359] = "diese Briefmarke, ziehen Ihnen Ihre Punkte wieder",
  [360] = "ab, und Sie können äh... solange weiterspielen.*",
  [361] = "Die Kordel, mit der der Umschlag verschnürt ist,",
  [362] = "erweist sich als überraschend widerstandsfähig.",
  [363] = "(Äh... ein kleiner Tip, wenn's Ihnen recht ist:",
  [364] = "in der Bibliothek liegt auf dem Kaminsims ein",
  [365] = "altes Samuraischwert als Dekoration. Damit",
  [366] = "kriegen Sie die Kordel bestimmt auf!)*",
  [367] = "Die Kordel ist, verflixt nochmal, einfach nicht",
  [368] = "aufzukriegen! Sie sollten doch besser das",
  [369] = "Samuraischwert aus der Bibliothek benutzen!*",
  [370] = "Vorsicht, schneiden Sie sich nicht.... Du lieber",
  [371] = "Himmel, das Ding ist derartig scharf....",
  [372] = "kkkkrrrrtsch! Die Kordel ist nun ab.*",
  [373] = "Es handelt sich um eine recht gewöhnliche, wenn",
  [374] = "auch enorm wiederstandsfähige Kordel.*",
  [375] = "Er lautet: LONDON, 28. January 1917!*",
  [376] = "Schwer zu erkennen, von hier!*",
  [377] = "Die Haustüre besteht aus stabiler Eiche. Ein",
  [378] = "schwerer Riegel ist daran befestigt.*",
  [379] = "In diesem Moment donnern von außen plötzlich",
  [380] = "gewaltige Schläge gegen die Tür. Und kurz darauf",
  [381] = "tönt eine schreckliche, gurgelnde Stimme durch",
  [382] = "das schwere Eichenholz: \"Du elender Wurm! Mein",
  [383] = "Herr hat mich geschickt, um Dich zu vernichten,",
  [384] = "so wie ich schon alle vor Dir vernichtet habe!",
  [385] = "Das Geheimnis wird für immer gewahrt bleiben!\"",
  [386] = "Dann ertönt ein heftiges, schmatzendes Geräusch,",
  [387] = "und danach herrscht wieder Stille.*",
  [388] = "*",
  [389] = "In dem Moment, als Sie die Eingangshalle",
  [390] = "betreten, fliegt mit lautem Krachen die Türe auf!",
  [391] = "Die Kreatur, die einen Augenblick später im",
  [392] = "Durchgang erscheint, ist ein absoluter Alptraum!",
  [393] = "Drei unendlich grausame Augen starren Sie gierig",
  [394] = "an.*",
  [395] = "Die Bestie ist zwei Meter hoch, glitzert vor",
  [396] = "Schlamm und Schleim. Krallen, Zähne und Klauen,",
  [397] = "wohin man sieht - das schlimmste sind die drei",
  [398] = "bläulich glühenden Augen, die mitten auf der",
  [399] = "Stirn stehen! Die Haut ist schwarz und schuppig,",
  [400] = "der lange Echsenschwanz peitscht unruhig hin und",
  [401] = "her. Sie fletscht die zentimeterlangen Zähne, und",
  [402] = "stößt ein kehliges, hohles Knurren aus!*",
  [403] = "Schaum trieft aus dem Rachen des Ungeheuers. Dann",
  [404] = "beginnt es, mit grugelnder Grabesstimme zu Ihnen",
  [405] = "zu sprechen: \"Du elender Wurm! Mein Herr hat mich",
  [406] = "geschickt, Dich zu vernichten, so wie ich schon",
  [407] = "alle vor Dir vernichtet habe! Das Geheimnis wird",
  [408] = "für immer gewahrt bleiben!\" Dann wirft die Bestie",
  [409] = "den Kopf zurück, und stößt ein heißeres Kichern",
  [410] = "aus. Doch schon im nächsten Augenblick ist sie",
  [411] = "wieder in der Nacht verschwunden!*",
  [412] = "Oh - was ist das...? In diesem Moment ertönen",
  [413] = "laute Schläge und Stöße - ganz offensichtlich von",
  [414] = "außen gegen die Haustüre! Eine tiefe, gurgelnde",
  [415] = "Stimme dröhnt durch das ganze Haus....",
  [416] = "\"Ich krieg Dich, Du Wurm... irgendwie komme ich",
  [417] = "schon in das Haus hinein! Und dann....\"",
  [418] = "Die Stöße und Schläge verhallen, im nächsten",
  [419] = "Moment herrscht wieder Stille.*",
  [420] = "Rrruummmssss!!! Ein lauter Schlag donnert durch",
  [421] = "das Haus! Es kam... ja, von der Eingangstüre!",
  [422] = "Dann dröhnt eine gräßliche, gurgelnde Stimme:",
  [423] = "\"Mach auf, Du Laus! Ich krieg Dich sowieso...!\"",
  [424] = "Noch ein heftiger Schlag ertönt, dann aber",
  [425] = "herrscht wieder Stille.*",
  [426] = "Krrrraaach!!! Ein fürchterlicher Schlag hallt",
  [427] = "durch das ganze Haus - fast hörte es sich an wie",
  [428] = "das Splittern von Holz! Und dann wird die Stimme",
  [429] = "dieses schrecklichen Monstrums hörbar:",
  [430] = "\"Irgendwann hab ich Dich, Du Würstchen! Und dann",
  [431] = "geht es Dir schlecht!\"",
  [432] = "Nocheinmal ertönt ein kräftiger Schlag - aber die",
  [433] = "Tür scheint einiges auszuhalten. Dann ist es",
  [434] = "wieder ruhig.*",
  [435] = "Plötzlich hallt ein lautes Krachen durch das",
  [436] = "Haus... Die Eingangstüre! Sie war nicht",
  [437] = "verschlossen, und die Bestie ist ins Haus",
  [438] = "eingedrungen!",
  [439] = "Und dann dröhnt eine schreckliche Stimme: \"Wo",
  [440] = "bist Du, Du Laus? Jetzt krieg ich Dich...!\"*",
  [441] = "In der Bibliothek",
  [442] = "Die Bibliothek ist ein schweigender, ehrwürdiger",
  [443] = "Raum. Schwer beladene Regale türmen sich die",
  [444] = "Wände hinauf, eine Couch steht auf dem dunklen",
  [445] = "Parkettboden. Fenster führen nach Osten und",
  [446] = "Süden; beide sind von außen vergittert. An der",
  [447] = "westlichen Wand befindet sich ein Kamin.*",
  [448] = "Die Fenster hier im Haus sind überall ziemlich",
  [449] = "gleich: etwa zwei Meter hoch, einen Meter breit,",
  [450] = "und von außen vergittert.*",
  [451] = "Die Fenster müssen erst renoviert werden - im",
  [452] = "Moment kann man sie leider nicht aufmachen.*",
  [453] = "Man sieht nicht viel - draußen ist es ziemlich",
  [454] = "dunkel.*",
  [455] = "Unmengen von Büchern stapeln sich dort.*",
  [456] = "Es ist eine riesige Sammlung, die von Mystik,",
  [457] = "Hexenglauben und Okkultismus handelt.*",
  [458] = "Sie haben ja gar keins!*",
  [459] = "Gut. Sie besitzen nun eines der Bücher.*",
  [460] = "Es ist eines der vielen, steinalten Bücher aus",
  [461] = "der uralten Sammlung des Samuel Hawthorne. Aber",
  [462] = "sein Inhalt ist sehr rätselhaft; er dürfte nur",
  [463] = "einem Eingeweihten etwas sagen.*",
  [464] = "Nun, wie soll man das, was in diesem Buch steht,",
  [465] = "mit kurzen Worten beschreiben? Es dreht sich um",
  [466] = "mystische, übersinnliche und okkulte Themen, so",
  [467] = "wie die meisten Bücher hier. Es scheint uralt zu",
  [468] = "sein - die vielen hundert Seiten sind mit",
  [469] = "winziger Schrift bedeckt. Aber mit Sicherheit",
  [470] = "hilft Ihnen das auch nicht weiter.*",
  [471] = "Bitte stellen Sie zuerst das Buch zurück, das Sie",
  [472] = "noch haben. Sonst gibt das bald ein heilloses",
  [473] = "Durcheinander hier!*",
  [474] = "Sie können sich gern die Bücher ansehen. Wenn Sie",
  [475] = "aber eine Untersuchung dieses Themas wünschen,",
  [476] = "dann wenden Sie sich bitte vertrauensvoll an Ihre",
  [477] = "örtliche Volkshochschule!*",
  [478] = "Der Kamin ist nicht sehr groß und schwarz und",
  [479] = "leer. Der Kaminsims besteht aus einer schönen",
  [480] = "Marmorplatte. Über dem Kamin beherrscht ein",
  [481] = "mächtiges Porträt des Sir Samuel Hawthorne die",
  [482] = "Wand.*",
  [483] = "Das Portrait zeigt Sir Hawthorne in großer Geste",
  [484] = "am Flügel sitzend. Der alte Herr blickt streng,",
  [485] = "aber mit einem kleinen, wissenden Lächeln den",
  [486] = "Betrachter an.*",
  [487] = "Eine knifflige Frage. Nunja, dieses Lächeln, es",
  [488] = "ist, hm... sagen wir: bedeutungsvoll, vielsagend,",
  [489] = "so als wolle er einen Hinweis geben, daß.... Nun,",
  [490] = "tun Sie doch was für Ihr Geld - finden Sie es",
  [491] = "selber heraus!*",
  [492] = "Was Sie nicht alles wissen wollen! Also, wollen",
  [493] = "mal sehen... da sind die Noten Gis, Ges, Dis, Fis",
  [494] = "erkennbar. Halt! Hinter der letzten Note steht",
  [495] = "noch ein Zeichen! Seltsam - es ist ein kleines",
  [496] = "Sechseck.*",
  [497] = "Sir Hawthorne war ein großer, schlanker Mann, mit",
  [498] = "einem aristokratischen Schnurrbart. Auf dem",
  [499] = "Portrait trägt er einen schwarzen Smoking.*",
  [500] = "Er ist fein geschnitzt, und golden lackiert.*",
  [501] = "Er besteht aus einer schönen, dicken",
  [502] = "Marmorplatte.*",
  [503] = "Auf dem Kaminsims liegt als Dekoration ein",
  [504] = "kostbares, altes Samuraischwert.*",
  [505] = "Das Schneide ist eine kunstvolle Arbeit, fein",
  [506] = "verziert und noch immer höllisch scharf. Aber -",
  [507] = "ach! Leider ist der hölzerne Griff völlig kaputt",
  [508] = "- da hat sich wohl ein besonders gefräßiger",
  [509] = "Holzwurm gütlich getan!*",
  [510] = "Nun - einigen wir uns auf die Bezeichnung",
  [511] = "'Klinge'. Ein Schwert ist nur etwas, das auch",
  [512] = "einen Griff hat. Dieses hier besteht nur aus",
  [513] = "einer Klinge. Den Rest hat das Zeitliche, oder",
  [514] = "besser: die Gefräßigkeit eines Holzwurmes",
  [515] = "gesegnet. Okay. Die Klinge... passen Sie auf, sie",
  [516] = "ist höllisch scharf... befindet sich nun in Ihrem",
  [517] = "Besitz.*",
  [518] = "Die Klinge ist höllisch scharf. Anstelle des",
  [519] = "Griffes ist da aber nur noch das blanke",
  [520] = "Schraubgewinde - in dieser Form wird man die Klinge",
  [521] = "kaum benutzen können, ohne sich zu verletzen!*",
  [522] = "Ganz plötzlich ertönt ein erschreckendes,",
  [523] = "kratzendes Geräusch! Es kam offenbar aus der",
  [524] = "Richtung des östlichen Fensters!*",
  [525] = "Drei funkelnde, blassblaue Augen starren durch",
  [526] = "das Fenster herein! Im nächsten Moment schließen",
  [527] = "sich zwei klauenbewehrte Tatzen von außen um die",
  [528] = "Gitterstäbe und beginnen, daran zu zerren!*",
  [529] = "Nach Sekunden heftigsten Rüttelns und Zerrens",
  [530] = "lassen die schrecklichen Tatzen von den",
  [531] = "Gitterstäben wieder ab! Noch einmal leuchten die",
  [532] = "blassblauben Augen auf, dann verschwindet die",
  [533] = "unfassbare Kreatur - aber nur, um gleich darauf",
  [534] = "am südlichen Fenster wieder zu erscheinen. Dort",
  [535] = "aber verweilt dieses entsetzliche Wesen nicht -",
  [536] = "offenbar bewegt es sich weiter um das Haus herum",
  [537] = "- in Richtung der Haustüre!*",
  [538] = "Wie wollen Sie die Klinge halten? An dem",
  [539] = "Schraubgewinde vielleicht? Das haut nicht hin, es",
  [540] = "ist viel zu kurz. Wollten Sie hingegen die Klinge",
  [541] = "selbst festhalten, würden Sie sich nur schneiden",
  [542] = "- Sie machen sich keinen Begriff davon, wie",
  [543] = "scharf das Ding ist!*",
  [544] = "Es ist eine große, alte Ledercouch. Zwischen den",
  [545] = "Polsterteilen klaffen tiefe Ritzen... schaun wir",
  [546] = "mal... nein, da ist nichts drin. Aber Moment...",
  [547] = "ja, da unten, in dem schmalen Spalt zwischen",
  [548] = "Couch und Boden, liegt etwas! Sieht aus wie ein",
  [549] = "Stück Papier - ja, es ist ein Papierfetzen! Aber",
  [550] = "er liegt zu tief darunter... ärgerlich - man",
  [551] = "kommt nicht dran! Vielleicht steht etwas",
  [552] = "Wichtiges drauf?*",
  [553] = "Der Spalt zwischen Couch und Parkettboden ist",
  [554] = "schmal... aber dort liegt ein kleiner",
  [555] = "Papierfetzen! Leider liegt er zu tief darunter,",
  [556] = "man kommt nicht dran... schade! Vielleicht",
  [557] = "steht was Wichtiges darauf!*",
  [558] = "Der Spalt zwischen Couch und Parkettboden ist",
  [559] = "schmal... aber dort ist auch nichts zu",
  [560] = "entdecken.*",
  [561] = "Keine schlechte Idee! Probieren wir's...",
  [562] = "Mist! Sie haben zwar eine Wanze zu Tode",
  [563] = "erschreckt, aber der Papierfetzen da unten,",
  [564] = "was immer auf ihm auch stehen mag, läßt sich",
  [565] = "mit Ihrem Werkzeug nicht hervorholen.*",
  [566] = "Oje! Das ist aber ein Kraftakt! Also los...",
  [567] = "Hauruck! Und nochmal....ächz! Puuh! Die Couch hat",
  [568] = "sich vielleicht um einen Millimeter bewegt, aber",
  [569] = "nicht mehr. Sie ist verteufelt schwer; auf den",
  [570] = "vier Tellerfüßen ruht enormes Gewicht, und der",
  [571] = "alte Parkettboden ist hier sehr rauh und spröde -",
  [572] = "da rutscht so leicht nichts. Man müsste hier mal",
  [573] = "ordentlich wachsen und polieren... dann ginge das",
  [574] = "vielleicht.*",
  [575] = "Ah - Sie haben wohl Angst auszurutschen, was?",
  [576] = "Nein, keine Gefahr, hier ist nichts frisch",
  [577] = "gebohnert. Im Gegenteil - der Boden besteht aus",
  [578] = "altem, dunklen Holzparkett und ist ziemlich",
  [579] = "ungepflegt, an manchen Stellen ist das Holz sehr",
  [580] = "rauh und spröde. Da rutscht so leicht nichts!*",
  [581] = "Mit was wollen Sie das machen, mit dem Finger",
  [582] = "vielleicht? Oje - wenn das Ihre Mama sehen würde!",
  [583] = "Nein - da brauchen sie schon ein geeignetes",
  [584] = "Werkzeug!*",
  [585] = "Ah! Mit dem Lappen - das funktioniert gut! Da, in",
  [586] = "der Nähe der Füße der Couch - ja, da ist der Boden",
  [587] = "besonders rauh.... gut. Der rauhe Parkettboden",
  [588] = "ist nun aufs Trefflichste mit feuchtglänzendem",
  [589] = "Bohnerwachs eingeschmiert!*",
  [590] = "Hier hat jemand Teile des Parketts mit",
  [591] = "feuchtglänzendem, klebrigen Bohnerwachs",
  [592] = "eingeschmiert.*",
  [593] = "Hauruck! Und nochmal... Mist! Das Bohnerwachs ist",
  [594] = "feucht und klebrig - darauf rutscht so leicht",
  [595] = "nichts. Nun - gewöhnlich muß man nach dem",
  [596] = "Auftragen von Bohnerwachs den Boden auch noch",
  [597] = "polieren, nicht wahr?*",
  [598] = "Sehr gut! Das ist zwar ziemlich aufwendig, aber",
  [599] = "es geht. Nach ein paar Tausend Strichen glänzt",
  [600] = "das Parkett wie neu... vorsicht! Rutschen Sie",
  [601] = "nicht aus! Sie sind wirklich erfinderisch! Wenn",
  [602] = "Sie Ihre Fähigkeiten jetzt noch verzehnfachen,",
  [603] = "dann haben Sie vielleicht eine kleine Chance, das",
  [604] = "Geheimnis um das Auge des Kal zu lüften! Haha.*",
  [605] = "Eine aufopferungsvolle Seele hat hier den Boden",
  [606] = "eingewachst und poliert - das Parkett erstrahlt",
  [607] = "in altem Glanze!*",
  [608] = "Hauruck...! Ah, es geht! Die schwere Couch",
  [609] = "gleitet ein Stück über den frisch gebohnerten",
  [610] = "Boden! Auf dem Boden kommt ein kleines Stück",
  [611] = "Papier zum Vorschein.*",
  [612] = "Hier liegt ein kleiner Papierfetzen.*",
  [613] = "Gut. Der Papierfetzen gehört nun Ihnen.*",
  [614] = "Es ist ein kleiner, abgerissener Notizzettel. Das",
  [615] = "Papier ist vom hohen Alter vergilbt. Ein paar in",
  [616] = "enger Schrift gekritzelte Sätze stehen darauf.*",
  [617] = "Dort steht: \"Ein raffinierter Kerl, dieser alte",
  [618] = "Sam Hawthorne! Aber nun ist alles ganz einfach!",
  [619] = "Sein verdammtes Lächeln hat mich darauf gebracht",
  [620] = "- er konnte nämlich gar nicht Klavier spielen!",
  [621] = "Trotzdem ist die Lösung des Rätsels auf dem",
  [622] = "Portrait versteckt - in dem NOTENBLATT, das vor",
  [623] = "ihm auf seinem Klavier liegt!\"*",
  [624] = "Gesellschaftszimmer",
  [625] = "Dieser Raum wird von einem schwarzen Kamin und",
  [626] = "einem mächtigen Konzertflügel beherrscht. Über",
  [627] = "einem altertümlichen Plüschsofa ziert ein großes",
  [628] = "Gemälde die Wand - über dem Kamin ein ziemlich",
  [629] = "scheußliches Landschaftsbild. Fenster gibt es",
  [630] = "nach Westen und Süden; Richtung Osten liegt die",
  [631] = "Türe zur Eingangshalle des Hauses. Der Raum",
  [632] = "strahlt noch immer eine warme Behaglichkeit aus.*",
  [633] = "Der Kamin steht an der östlichen Wand des Zimmers",
  [634] = "und ist groß und schwarz. Sein offener Schlund",
  [635] = "gähnt den Betrachter an.*",
  [636] = "Auf dem Kaminsims liegt ein kleines, altes",
  [637] = "Feuerzeug.*",
  [638] = "Es ist ein goldenes Feuerzeug. Zwei Buchstaben",
  [639] = "sind eingraviert: O.J.*",
  [640] = "Leider ist es leer!*",
  [641] = "Das Feuerzeug ist wohlgefüllt, wenngleich auch",
  [642] = "nur mit Petroleum. Aber für den Notfall genügt",
  [643] = "das auch.*",
  [644] = "Na, ob das funktionieren wird? Gut - probieren",
  [645] = "wir's. Gluckgluck... stop! Das Feuerzeug ist",
  [646] = "schon voll!*",
  [647] = "Rrrrrtsch! Das Feuerzeug brennt.*",
  [648] = "Der Boden ist mit alten, grauen Steinplatten",
  [649] = "gefliest.*",
  [650] = "Der Konzertflügel ist schwarz lackiert und etwa",
  [651] = "dreieinhalb Meter lang. Vorn drauf steht der",
  [652] = "Hersteller: Heiglhuber.*",
  [653] = "Der Deckel des Korpus' ist heruntergeklappt und",
  [654] = "die Tastenklappe ist geschlossen.*",
  [655] = "Der Deckel des Korpus' ist geöffnet und die",
  [656] = "Tastenklappe ist geschlossen.*",
  [657] = "Die Tastenklappe ist geöffnet und der Deckel des",
  [658] = "Korpus' ist zu.*",
  [659] = "Der Deckel des Korpus' und die Tastenklappe sind",
  [660] = "geöffnet.*",
  [661] = "Unter dem Deckel kann man den gußeisernen Rahmen",
  [662] = "und die Saiten des Flügelinneren sehen.*",
  [663] = "Da-dim-du-daaa.... Die Töne verklingen... nunja,",
  [664] = "hätte jetzt etwas passieren sollen? Ein Blitz aus",
  [665] = "heiterem Himmel? Das Erscheinen einer Märchenfee?",
  [666] = "Nein - wir bedauern, Sie enttäuschen zu müssen.*",
  [667] = "Damm-di-damm-du-diii... hübsch! Aber als die Töne",
  [668] = "verklungen sind, ertönt plötzlich aus dem Inneren",
  [669] = "des Flügels ein höchst verdächtiges Klappern!*",
  [670] = "Zwischen den Bassaiten liegt erstaunlicherweise",
  [671] = "eine Marmorkugel. Sie ist offenbar aus einem",
  [672] = "geheimen Fach herausgerollt!*",
  [673] = "Dieses Fach ist so schrecklich geheim, daß nicht",
  [674] = "einmal wir wissen, ob es überhaupt vorhanden ist,",
  [675] = "oder ob es nur als astral-vierdimensionale",
  [676] = "Pseudo-Projektion eines diametral implizierten",
  [677] = "und längsgeriffelten Wahrscheinlichkeitsfaktors",
  [678] = "unbekannter Größe existiert.*",
  [679] = "Die Marmorkugel ist recht schwer und etwa von der",
  [680] = "Größe eines Tennisballes.*",
  [681] = "Den Deckel des Korpus' kann man auf- und",
  [682] = "zuklappen. Darunter liegt das Innere des Flügels;",
  [683] = "den gußeisernen Rahmen und die Saiten.*",
  [684] = "Er ist geschlossen.*",
  [685] = "Er ist geöffnet.*",
  [686] = "Die Tastenklappe ist dazu da, Unbefugten das",
  [687] = "Spielen auf dem Flügel zu verwehren! Vorndrauf",
  [688] = "befindet sich ein kleines Schlüsselloch.*",
  [689] = "Pech! Sie ist verschlossen!*",
  [690] = "Sie ist zu.*",
  [691] = "Sie ist geöffnet.*",
  [692] = "Das Schlüsselloch ist ganz klein - da passt nur",
  [693] = "ein winziges Schlüsselchen hinein.*",
  [694] = "In dem Schlüsselloch steckt ein winziges",
  [695] = "Schlüsselchen.*",
  [696] = "Klick! Die Tastenklappe ist nun offen!*",
  [697] = "Das Landschaftsbild zeigt - wie könnte es auch",
  [698] = "anders sein? - die Ramsauer Kirche vor dem",
  [699] = "Watzmann!*",
  [700] = "Der Watzmann ist ein großer, großer Berg und er",
  [701] = "ist gaaanz hoch!*",
  [702] = "Es ist die sattsam bekannte Ramsauer Kirche, die",
  [703] = "auf zirka vier Millionen Wohnzimmergemälden",
  [704] = "auftaucht. Schade nur, daß der Künstler wert",
  [705] = "darauf gelegt hat, im Vordergrund einen klobigen",
  [706] = "Wegweiser abzubilden.*",
  [707] = "Der Wegweiser besitzt zwei Schilder: Das eine",
  [708] = "deutet nach Westen, darauf steht: 'Klavierfabrik",
  [709] = "Heiglhuber'. Auf dem zweiten Schild hingegen, das",
  [710] = "nach Osten deutet, ist.... hm, ein kleiner",
  [711] = "Schlüssel abgebildet, mit dem Vermerk:",
  [712] = "\"Kunstmalerei Moser\".*",
  [713] = "Auf dem Gemälde ist ein röhrender Hirsch auf",
  [714] = "einem Felsen vor dem Sonnenuntergang dargestellt.",
  [715] = "Einzigartig! Es heißt, der Künstler habe nach",
  [716] = "Festigstellung des genialen Werkes den Verstand",
  [717] = "verloren!*",
  [718] = "Das Plüschsofa ist breit und mächtig, die",
  [719] = "Sitzfläche besteht aus mehreren Polsterteilen,",
  [720] = "zwischen denen tiefe Ritzen klaffen.*",
  [721] = "Rechts liegt ein hübsches, altertümliches",
  [722] = "Sofakissen.*",
  [723] = "Keine schlechte Idee! Nur leider findet sich in",
  [724] = "den Ritzen nichts weiter als siebzig Jahre alter",
  [725] = "Staub!*",
  [726] = "Wirklich ein hübsches, mit Stickerei verziertes",
  [727] = "Kissen! Prall gestopft, und relativ schwer!",
  [728] = "Wahrscheinlich befindet sich in seinem Inneren",
  [729] = "ein sagenhafter Schatz!*",
  [730] = "Wollen Sie es nicht auch noch aufschlitzen, Sie",
  [731] = "Vandale?*",
  [732] = "Das dachten wir uns! Nun gut, Sie sollen Ihren",
  [733] = "Willen haben. Als das arme Kissen zerlegt ist,",
  [734] = "finden Sie nichts von Interesse, schon gar nicht",
  [735] = "einen sagenhaften Schatz!*",
  [736] = "Hier liegen die traurigen Überreste, eines",
  [737] = "einstmals schönen, alten Sofakissens.*",
  [738] = "Im Garten",
  [739] = "Der Garten macht dem Hawthorne'schen Anwesen alle",
  [740] = "Ehre. Hier stehen ein verwachsener Apfelbaum,",
  [741] = "wuchernde Hecken und Unmassen von schwer",
  [742] = "definierbarem Unkraut. Der Weg führt von hier",
  [743] = "nordwärts zur Haustüre, oder nach Süden, vorbei",
  [744] = "an dem verrotteten Holzzaun, in ein Feld.",
  [745] = "Westlich ist ein dunkles Wäldchen erkennbar, nach",
  [746] = "Osten hin liegt eine Hügelkuppe.*",
  [747] = "Es regnet, und die Nacht ist schon",
  [748] = "hereingebrochen.*",
  [749] = "Im düsteren Zwielicht ist nicht mehr viel zu",
  [750] = "sehen. Aber die Fußspuren im schlammigen Boden",
  [751] = "sind noch zu erkennen.*",
  [752] = "Um Himmels Willen, was ist das? Diese Spuren",
  [753] = "stammen nicht etwa von einem Stiefel oder",
  [754] = "einer Hundepfote - nein, sie sind erschreckend",
  [755] = "groß! Sie erinnern eher an die eines riesigen",
  [756] = "Bären! Aber Bären haben doch...  ohgott!",
  [757] = "Diese Fußspuren stammen von riesigen,",
  [758] = "dreizehigen Klauen! Sie sind offenbar noch",
  [759] = "ziemlich frisch - und überall im Garten auf dem",
  [760] = "Boden verteilt.*",
  [761] = "Der Apfelbaum ist nicht sehr hoch. Er trägt nur",
  [762] = "wenig Laub, und reckt seine verkrüppelten Äste",
  [763] = "wie die Finger eines Toten gespenstisch in die",
  [764] = "Nacht hinaus.*",
  [765] = "Uff! Ächz! Der Stamm ist glatt und glitschig vom",
  [766] = "Regen.... krraaaatsch!! Ach herrje - jetzt ist",
  [767] = "Ihre schöne Persianer-Stola entzwei! Naja.",
  [768] = "Nach anstrengender Kletterei befinden Sie sich",
  [769] = "nun etwa einen Meter fünfzig über dem Boden.",
  [770] = "Immerhin sind Sie jetzt nur noch 384.999",
  [771] = "Kilometer und 998 einhalb Meter vom Mond",
  [772] = "entfernt. Weiter so! Die NASA sucht ständig nach",
  [773] = "fähigen Astronauten!*",
  [774] = "Na, das ist ja nett, daß sie sich um Ihre",
  [775] = "Klamotten kümmern! Das gibt ein Extra-Lob!",
  [776] = "Aber die Stola... hm, das wird eine teure",
  [777] = "Reparatur.*",
  [778] = "Waaas? Sie wollen dieses schöne, alte Erbstück",
  [779] = "loswerden? Geben Sie bloß acht, daß wir das nicht",
  [780] = "Ihrer Stiefgroßtante mütterlicherseits erzählen!",
  [781] = "(... oder war das väterlicherseits?) Egal, allein",
  [782] = "für den Versuch dieser Untat müssen wir Ihnen",
  [783] = "einen Punkt abziehen! Sie Rüpel! Also so was!*",
  [784] = "WARNUNG! Ihre Großtantenmutter",
  [785] = "stiefväterlicherseits hat uns nachdrücklich",
  [786] = "instruiert, daß wir Ihnen auf die Finger klopfen",
  [787] = "sollen, wenn Sie dies versuchen sollten! Also",
  [788] = "lassen Sie das!*",
  [789] = "Auf dem Baum",
  [790] = "Sie befinden sich nun etwa eineinhalb Meter über",
  [791] = "dem Boden. Der Ausblick in die verregnete",
  [792] = "Finsternis ist wahrlich phänomenal!*",
  [793] = "*",
  [794] = "Die Hecken sind dornig und sehr niedrig",
  [795] = "gewachsen.*",
  [796] = "Die beginnende Nacht umgibt Sie. Es ist immer",
  [797] = "weniger zu sehen - nur das Regenwasser, das sich",
  [798] = "langsam in den schrecklichen Fußspuren am Boden",
  [799] = "sammelt, wirft den schwachen Lichtschein vom Haus",
  [800] = "zurück, und schenkt Ihnen eine Schar von",
  [801] = "unheimlichen Begleitern. Der kalte Regen",
  [802] = "durchdringt unbarmherzig Ihre Kleider.*",
  [803] = "*",
  [804] = "Der Regen löscht die Flamme wieder aus.*",
  [805] = "Sie sind ein mutiger Mensch. Das Wetter und die",
  [806] = "Dunkelheit scheint Sie nicht schrecken zu können.",
  [807] = "Aber die Nacht auf dem Lone Hill könnte",
  [808] = "schlimmere Gefahren bergen. Wollen Sie sich",
  [809] = "wirklich noch weiter vom Haus entfernen?*",
  [810] = "Im Wald",
  [811] = "Sie stehen sich zwischen mächtigen Bäumen, die in",
  [812] = "der Dunkelheit kaum erkennbar sind. Der Regen",
  [813] = "plätschert unablässig herab. Da ertönt plötzlich",
  [814] = "ein hohles, glucksendes Geräusch vor Ihnen!*",
  [815] = "Im Feld",
  [816] = "Sie befinden sich jetzt mitten in einem",
  [817] = "Getreidefeld. Der Regen plätschert unaufhörlich",
  [818] = "herab, es herrscht fast völlige Finsternis. Aber",
  [819] = "plötzlich ertönt direkt vor Ihnen ein seltsames,",
  [820] = "schmatzendes Geräusch in der Dunkelheit!*",
  [821] = "Auf dem Hügel",
  [822] = "Hier oben, auf der Hügelkuppe des Lone Hill, gibt",
  [823] = "es keinen Schutz vor dem gräßlichen Wetter. Ohne",
  [824] = "Unterlaß strömt der Regen herab. Die Nacht lässt",
  [825] = "kaum mehr als dunkle Schatten erkennen. Aber",
  [826] = "plötzlich dringt ein beängstigendes, schmatzendes",
  [827] = "Geräusch direkt von vorne an Ihr Ohr!*",
  [828] = "In der Dunkelheit ist kaum etwas zu erkennen.",
  [829] = "Abermals ertönt das schreckliche Geräusch. Es",
  [830] = "scheint, als käme irgendetwas auf Sie zu!",
  [831] = "Schnell! Verschwinden Sie hier! Kehren Sie um!",
  [832] = "Haben Sie denn den Brief von John Pilestaff nicht",
  [833] = "gelesen?*",
  [834] = "Du lieber Himmel! Sie Leichtsinniger!*",
  [835] = "Oh nein! Es ist zu spät! Von irgendwoher, ganz in",
  [836] = "der Nähe ertönt ein markdurchdringendes",
  [837] = "Grunzen... im nächsten Augenblick schnellt eine",
  [838] = "monströse, finstere Gestalt aus der Dunkelheit",
  [839] = "auf Sie zu! Sie erkennen in der Dunkelheit nur",
  [840] = "noch die Umrisse einer entsetzlichen dreizehigen",
  [841] = "Klaue, die auf Sie zufliegt.....",
  [842] = "aaaaaaahhhhhhhh!!!!!",
  [843] = "ENDE*",
  [844] = "Im Billardzimmer",
  [845] = "Dies ist ein Raum von gediegener Club-Atmospähre.",
  [846] = "Ein schöner Billardtisch steht in der Mitte des",
  [847] = "Zimmers, an den Wänden sind Trophäen und Bilder",
  [848] = "mit Jagdszenen. An der Wand ist ein Ständer für",
  [849] = "Billardstöcke befestigt. Über dem Spieltisch",
  [850] = "hängt eine breite Lampe. Nach Süden hin führt",
  [851] = "eine Tür in die Bibliothek.*",
  [852] = "Hier ist etwas Eigenartiges passiert: die Platte",
  [853] = "des Billardtisches ist verschwunden, stattdessen",
  [854] = "führt dort eine schmale Treppe durch einen",
  [855] = "dunklen Schacht in die Tiefe unter dem Haus!*",
  [856] = "In dem Ständer stehen drei Billardstöcke.*",
  [857] = "In dem Ständer stehen zwei Billardstöcke.*",
  [858] = "Es sind drei schöne Billardstöcke;, alle drei",
  [859] = "dunkelrot und braun lackiert, und mit feinen",
  [860] = "Schnitzarbeiten verziert.*",
  [861] = "Fein, nehmen wir mal einen davon.*",
  [862] = "Sie meinen ...BILLARD...? Dieses Wort besitzt nur",
  [863] = "ein i.*",
  [864] = "Meinen Sie einen, ähem... einen Kö? Das schreibt",
  [865] = "man: Queue.*",
  [866] = "Fein. Sie besitzen nun einen der Billardstöcke.*",
  [867] = "Bitte stellen Sie zuerst den zurück, den Sie",
  [868] = "gerade haben.*",
  [869] = "Prima. Der Ständer ist nun wieder komplett.*",
  [870] = "Okay, schauen wir uns mal den zweiten an.*",
  [871] = "Gut, Sie sollen sich auch noch den dritten",
  [872] = "Billardstock anschauen dürfen.*",
  [873] = "Ein sehr schönes Stück. Er ist schnurgerade, und",
  [874] = "von vorn bis hinten dunkelrot und braun",
  [875] = "lackiert.*",
  [876] = "Dies ist ein Meister-Queue, hinten ist er",
  [877] = "mit feinstem, dünnen Leder umwunden und braun",
  [878] = "lackiert.*",
  [879] = "Ein weiteres Prachtexemplar seiner Gattung,",
  [880] = "extrem gerade, gut ausbalanciert und aus",
  [881] = "Naturholz mit feinstem Schnitzwerk. Oh, sieh an -",
  [882] = "es ist ein schraubbarer Stock, er besteht aus",
  [883] = "drei Teilen:",
  [884] = "dem Griff, dem Schaft und der Spitze.*",
  [885] = "Der zerlegbare Billardstock besteht derzeit aus",
  [886] = "dem Griff, dem Schaft und der Spitze. Damit ist",
  [887] = "er genau 140 Zentimeter lang.*",
  [888] = "Der zerlegbare Billardstock besteht derzeit aus",
  [889] = "dem Griff und dem Schaft. Damit ist er genau 80",
  [890] = "Zentimeter lang.*",
  [891] = "Der zerlegbare Billardstock besteht derzeit aus",
  [892] = "dem Schaft und der Spitze. Damit ist er genau 110",
  [893] = "Zentimeter lang.*",
  [894] = "Sie haben sich eine Art Schwert konstruiert. Die",
  [895] = "Klinge das Samuraischwertes ist am Griff des",
  [896] = "Billardstockes befestigt. Das Ganze ist ungefähr",
  [897] = "120 Zentimeter lang.*",
  [898] = "Sie haben sich eine Art Enterhaken gebastelt. Der",
  [899] = "Haken ist am Schaft befestigt. Das Ganze ist",
  [900] = "ungefähr 60 Zentimeter lang.*",
  [901] = "Sie haben sich eine Art Enterstange gebastelt.",
  [902] = "Der Haken ist am Schaft befestigt, und der Schaft",
  [903] = "am Griff. Das Ganze ist etwa 90 Zentimeter lang.*",
  [904] = "Sie haben sich so etwas wie einen Wurfanker",
  [905] = "gebastelt. Der Schaft ist mit dem Haken",
  [906] = "verbunden, und das Seil mit dem Schaft.*",
  [907] = "Sie haben sich eine Art Seilanker hergestellt.",
  [908] = "Das Seil ist in der Mitte des unzerlegten",
  [909] = "Billardstockes festgebunden.*",
  [910] = "Der Griff des Billardstockes ist 30 Zentimeter",
  [911] = "lang und hat etwa vier Zentimeter Durchmesser.*",
  [912] = "Der Schaft des Billardstockes ist 50 Zentimeter",
  [913] = "lang und hat etwa zweieinhalb Zentimeter",
  [914] = "Durchmesser.*",
  [915] = "Die Spitze des Billardstockes ist 60 Zentimeter",
  [916] = "lang und hat ein wenig mehr als einen Zentimeter",
  [917] = "Durchmesser.*",
  [918] = "Hmmmm. Schwierig. Eines der Teile ist momentan",
  [919] = "nicht verfügbar.*",
  [920] = "ist.",
  [921] = "Gut. Die beiden Teile sind nun miteinander",
  [922] = "verbunden.*",
  [923] = "Okay. Die beiden Teile sind nun voneinander",
  [924] = "getrennt.*",
  [925] = "Das geht leider nicht. Die beiden Gewinde passen",
  [926] = "nicht zueinander.*",
  [927] = "Das klappt so nicht. (Und das, was sie da basteln",
  [928] = "wollen, kann Ihnen hier leider auch nicht",
  [929] = "weiterhelfen!)*",
  [930] = "Es handelt sich um die üblichen ausgestopften",
  [931] = "Adler, Wildsäue und grinsenden Bärengesichter.",
  [932] = "Eines jedoch ist dabei, das sehr befremdlich",
  [933] = "aussieht. Es ist nur ein Modell, deshalb jedoch",
  [934] = "nicht minder erschreckend.*",
  [935] = "Das Modell besitzt Zähne, Krallen und Klauen,",
  [936] = "wohin man sieht. Es ist eine kleine, aufrechte",
  [937] = "Gestalt mit schuppiger Haut und einem",
  [938] = "Echsenschwanz. Der Anblick ist nicht gerade",
  [939] = "anheimelnd.*",
  [940] = "Das Gestell des Billard-Tisches, auf dem die",
  [941] = "Platte ruht, ist rundum mit Holztäfelung",
  [942] = "verkleidet. Es handelt sich um einen Pool-",
  [943] = "Billard-Tisch mit vier Banden und sechs Löchern.*",
  [944] = "Die Bespannung der Platte ist selbst nach dieser",
  [945] = "langen Zeit noch immer makellos.*",
  [946] = "Die Bespannung der Platte ist aufgerissen -",
  [947] = "zweifellos das Werk von Vandalen!*",
  [948] = "Nun - es ist weltweit bekannt, daß Sie ein",
  [949] = "miserabler Spieler sind, wollen Sie das wirklich",
  [950] = "wagen?*",
  [951] = "Wollen Sie nicht unsere Frage zuerst",
  [952] = "beantworten?*",
  [953] = "Fein. Sie ersparen uns eine Menge Peinlichkeiten.",
  [954] = "(Psst! Dafür bekommen Sie fünfzehn Punkte von uns",
  [955] = "geschenkt!)*",
  [956] = "Ha! Immerhin sind Sie mutig, das steht einem",
  [957] = "Abenteurer gut an! Wie wäre es, wenn wir um",
  [958] = "Punkte spielten, hm? Wenn Sie gewinnen, kriegen",
  [959] = "Sie 10 Punkte extra, wenn Sie verlieren, gibt's",
  [960] = "zehn Miese! Einverstanden?*",
  [961] = "Gut, dann beginnen wir. Wollen Sie die Halben",
  [962] = "oder die Ganzen?*",
  [963] = "Bah! Das ist wiederum nicht sehr tapfer. Aber",
  [964] = "gut. Spielen wir halt ohne Punkte. Wollen Sie die",
  [965] = "Halben oder die Ganzen?*",
  [966] = "Vielleicht sollten Sie sich einen Billardstock",
  [967] = "nehmen...?*",
  [968] = "Vielleicht sollten Sie Ihren Billardstock erstmal",
  [969] = "zusammenbauen...?*",
  [970] = "Okay. Dann fangen wir mal an.... aaaah! Schon",
  [971] = "vier versenkt! Sie sind dran!*",
  [972] = "He! Sie halten den Stock ja verkehrt herum....",
  [973] = "Vorsicht, die schöne... Krrrrrrraaaaaatsch!!!",
  [974] = "... Bespannung. Ach herrje, was für ein Jammer!",
  [975] = "Das gute Stück ist völlig aufgeschlitzt! Die zehn",
  [976] = "Minus-Punkte haben Sie sich aber sauer verdient,",
  [977] = "finden Sie nicht? Hören wir lieber auf mit der",
  [978] = "Billard-Spielerei, bevor Sie noch mehr Punkte",
  [979] = "verlieren.*",
  [980] = "Okay. Dann fangen wir mal an.... aaaaah! Mist.",
  [981] = "Daneben. Sie sind dran!*",
  [982] = "Halt, halt! Hiergeblieben! Sie wollten spielen, -",
  [983] = "also los! Kneifen gilt nicht!*",
  [984] = "Oh! Vier Stück versenkt! Wir, äh... also, Moment.",
  [985] = "Ah, da liegt ja eine, wie auf dem goldenen",
  [986] = "Tablett.. dann wolln wir mal.... mit Schwung....",
  [987] = "uuuuuunnd.... Krrrrrraaaaaaaatsch!",
  [988] = "Umpf.",
  [989] = "(Verlegenes Schweigen.)",
  [990] = "Wir, äh... nun, gucken Sie doch nicht so! Das",
  [991] = "kann doch jedem mal passieren, oder? Ist recht,",
  [992] = "Sie bekommen ja Ihre zehn Punkte!*",
  [993] = "In welches der sechs Löcher möchten Sie die",
  [994] = "Marmorkugel den werfen? (z.B. >werfe die",
  [995] = "Marmorkugel in Loch 1).*",
  [996] = "Man hört die schwere Kugel durch das Innere des",
  [997] = "Billardtisches kullern... dann ertönt ein",
  [998] = "seltsames Klacken. Es folgen einige Momente",
  [999] = "Stille.",
  [1000] = "Dann plötzlich - wie von Geisterhand bewegt,",
  [1001] = "senkt sich die schwere Billard-Platte geräuschlos",
  [1002] = "nach unten. Nach einer atemlosen Minute erkennen",
  [1003] = "Sie eine steinere Treppe, die nach unten in die",
  [1004] = "schweigende Finsternis führt!*",
  [1005] = "Es ist eine schmale, steinerne Treppe, die nach",
  [1006] = "unten führt. Nicht gerade vertrauenerweckend.*",
  [1007] = "Sie ist in der Tat außerordentlich finster, die",
  [1008] = "Finsternis!*",
  [1009] = "Im Kamin",
  [1010] = "Hier im Kamin ist es schwarz und finster. Außer",
  [1011] = "Ruß und ein paar verkohlten Holzresten gibt es",
  [1012] = "hier nichts von Interesse.*",
  [1013] = "Ach dieses Zeug! Lassen Sie es lieber liegen. Es",
  [1014] = "hat nichts Besonderes an sich, und Sie würden",
  [1015] = "sich nur die Hände schmutzig machen!*",
  [1016] = "Der Ruß interessiert Sie...? Also, Sie sind",
  [1017] = "vielleicht neugierig! Der Ruß ist schwarz, rußig,",
  [1018] = "dreckig und schmutzig.*",
  [1019] = "Was Ihnen nicht so alles einfällt! Also los....",
  [1020] = "kratzen wir den Ruß weg... oh! Was kommt denn da",
  [1021] = "zum Vorschein? Ein verdächtig lockerer",
  [1022] = "Mauerstein! Der ist ja geradezu wie geschaffen",
  [1023] = "zum draufdrücken!*",
  [1024] = "Ja, das macht ohnehin nichts mehr. Ihre Hände",
  [1025] = "sind so schmutzig vom Ruß, da macht der",
  [1026] = "Mauerstein auch nichts mehr aus... oh! Knapp vor",
  [1027] = "Ihnen schiebt sich die Bodenplatte des Kamins",
  [1028] = "beiseite, und gibt einen Zugang nach unten",
  [1029] = "frei... ja, dort ist eine schmale Leiter, die",
  [1030] = "hinab in die Finsternis führt.*",
  [1031] = "Im oberen Flur",
  [1032] = "Dies ist das nördliche Ende des Flures im ersten",
  [1033] = "Stock. Komisch, daß die Wände und die Decke hier",
  [1034] = "in einem tristen, um nicht zu sagen: depressiven",
  [1035] = "Grauton gestrichen sind. Nach Osten hin liegt die",
  [1036] = "Tür zur Küche, eine Treppe führt abwärts in die",
  [1037] = "Eingangshalle. Südwärts kann man ans andere Ende",
  [1038] = "des Flures gelangen, wo es zwei weitere Türen",
  [1039] = "gibt.*",
  [1040] = "Die Decke liegt hoch, wie es in älteren Häusern",
  [1041] = "oft vorkommt. Ach... dort droben ist sogar eine",
  [1042] = "Falltüre - wahrscheinlich führt sie hinauf zum",
  [1043] = "Dachboden.*",
  [1044] = "Die Falltür ist geschlossen. An ihrer Unterseite",
  [1045] = "befindet sich ein Riegel mit einem Loch drin.*",
  [1046] = "Die Falltüre ist geöffnet.*",
  [1047] = "Nun, es ist ein gewöhnlicher Riegel, so wie er",
  [1048] = "oft für Dachboden-Falltüren verwendet wird.",
  [1049] = "Mittendrin ist das obligatorische Loch, in das",
  [1050] = "man eine Zug-Stange einhaken kann, um den Riegel",
  [1051] = "zu öffnen und gleichzeitig die Falltüre",
  [1052] = "herunterzuziehen.*",
  [1053] = "Da kommen Sie leider nicht ran. Das liegt viel zu",
  [1054] = "hoch.*",
  [1055] = "Ah - sieh an! Sie sind sehr erfinderisch! Mit",
  [1056] = "Ihrer selbstgebastelten Enterstange kommen Sie an",
  [1057] = "den Riegel heran... nun vorsichtig einhaken...",
  [1058] = "Klack... Achtung! Die Falltür schwingt herunter!*",
  [1059] = "Hm... wie? Die Falltüre ist zwar offen, aber wie",
  [1060] = "wollen Sie da hoch? Hinaufspringen? Hmmm, das",
  [1061] = "wird Ihnen wohl kaum gelingen. Aber vielleicht",
  [1062] = "finden Sie irgendwo so etwas wie eine Leiter!*",
  [1063] = "Hier steht ein alter Küchentisch.*",
  [1064] = "Ah - sieh an! Unsere unfehlbare Kombinationsgabe",
  [1065] = "sagt uns, daß Sie etwas vorhaben! Wir wissen zwar",
  [1066] = "noch nicht genau was, aber wir bleiben am",
  [1067] = "Apparat! Gut. Der Küchentisch steht nun unter der",
  [1068] = "Falltüre.*",
  [1069] = "Hier steht, direkt unter der Falltüre, ein alter",
  [1070] = "Küchentisch.*",
  [1071] = "Aha! Ihre Phantasie hat bis jetzt noch nicht",
  [1072] = "nachgelassen. Bravo!*",
  [1073] = "*",
  [1074] = "*",
  [1075] = "*",
  [1076] = "*",
  [1077] = "Auf dem Küchentisch",
  [1078] = "Sie stehen jetzt auf dem Küchentisch. Fein. Aber",
  [1079] = "wenn Sie wirkliche Größe erreichen wollen, müssen",
  [1080] = "sie sich noch mehr anstrengen. Und auf eine",
  [1081] = "andere Art!*",
  [1082] = "Über Ihnen ist jetzt erfreulicherweise die",
  [1083] = "Falltüre in erreichbare Nähe gerückt!*",
  [1084] = "Okay, ziehen wir mal an dem Riegel... oh, Mann,",
  [1085] = "sitzt der fest! Nochmal... uff! Brechen Sie sich",
  [1086] = "nicht die Finger ab! Hm... Sie werden irgendein",
  [1087] = "Werkzeug brauchen, das Sie dort einhaken können!*",
  [1088] = "Damit wird es gehen. Dann ziehen wir mal an dem",
  [1089] = "Riegel... vorsicht... die Falltür schwingt",
  [1090] = "herunter! Ein schwarzes Viereck hat sich über",
  [1091] = "Ihnen aufgetan.*",
  [1092] = "Südende des oberen Flurs",
  [1093] = "Von hier kann man durch eine Tür nach Westen ins",
  [1094] = "Schlafzimmer gelangen, eine andere führt ostwärts",
  [1095] = "ins Kinderzimmer. Ein Fenster liegt Richtung",
  [1096] = "Süden, und nach Norden kommt man zur Treppe und",
  [1097] = "zur Küchentür.*",
  [1098] = "Schlafzimmer",
  [1099] = "Hier im Schlafzimmer steht nur noch ein",
  [1100] = "riesengroßes, altes Himmelbett. Die Wände sind",
  [1101] = "mit einer geblümten Tapete beklebt, deren",
  [1102] = "kitschige Scheußlichkeit nur noch von den",
  [1103] = "schlimmsten Hollywood- Schmalzopern übertroffen",
  [1104] = "wird. Die Türe hinaus zum Flur führt nach Osten,",
  [1105] = "ein Fenster liegt an der Südseite des Raumes.",
  [1106] = "Nach Norden geht es ins Badezimmer.*",
  [1107] = "An der nördlichen Wand des Schlafzimmers steht",
  [1108] = "die Tür zum Badezimmer offen.*",
  [1109] = "Ach, was soll man da schon sagen - früher waren",
  [1110] = "die Geschmäcker eben anders!*",
  [1111] = "Das Himmelbett ist etwas mehr als zwei mal zwei",
  [1112] = "Meter groß. Nur zwei große Matratzen liegen noch",
  [1113] = "darauf. An den vier Ecken führen Stangen nach",
  [1114] = "oben, die den 'Himmel' tragen - ein großes, rotes",
  [1115] = "Plüschtuch.*",
  [1116] = "Da gibt's nichts besonderes zu entdecken.",
  [1117] = "Aber... he! Was ist denn das? Dort liegt ja eins",
  [1118] = "von diesen schmutzigen Heftchen... zeigen Sie",
  [1119] = "mal...! Nun geben Sie's doch schon her.....!",
  [1120] = "Oooooooohhhh! Halloooo! Hoppla! Also.... so was!",
  [1121] = "Hmmm. Das müssen wir wohl konfiszieren... tut uns",
  [1122] = "leid!*",
  [1123] = "Zu spät. Geschenkt ist geschenkt.*",
  [1124] = "Auf dem Plüschtuch ist ein großes Sechseck",
  [1125] = "eingestickt.*",
  [1126] = "Auf der unteren Seite des Plüschtuches befindet",
  [1127] = "sich großes, eingesticktes Sechseck. Auf der",
  [1128] = "oberen Seite hat sich hingegen eine Menge Staub",
  [1129] = "angesammelt - dort ist aber auch etwas",
  [1130] = "eingestickt: das Wort 'Ces'. Hm. Was soll das",
  [1131] = "bedeuten? Ob damit wohl die Note 'Ces' gemeint",
  [1132] = "ist?*",
  [1133] = "Was für ein riesiges, schweres Ding! Aber gut,",
  [1134] = "Sie sollen es haben.*",
  [1135] = "Das hängt ziemlich hoch! Da kommen Sie nicht",
  [1136] = "ran!*",
  [1137] = "Ein Nickerchen? Warum nicht. Na denn, gute",
  [1138] = "Nacht!*",
  [1139] = "Sie können wohl nicht schlafen, was? Nun, wer",
  [1140] = "könnte das auch, in so einem Haus!*",
  [1141] = "Auf dem Bett",
  [1142] = "Okay. Sie stehen nun auf dem Bett. Was nun?*",
  [1143] = "Oooch! Sie wollen doch jetzt wohl kein Nickerchen",
  [1144] = "machen, oder?*",
  [1145] = "Tatsächlich? Na denn, gute Nacht! Und träumen Sie",
  [1146] = "schön!*",
  [1147] = "Na, doch noch kein Schlafbedürfnis, was? Nun wer",
  [1148] = "könnte jetzt und hier, in so einer Situation,",
  [1149] = "auch schlafen?*",
  [1150] = "Sie haben ein erfrischend jugendliches Gemüt.",
  [1151] = "Also los! Hopp... und hopp... und Hopp! Und",
  [1152] = "nochmal! Toll, sie können das ja noch! Schnell...",
  [1153] = "was jetzt?*",
  [1154] = "Jawoll! Mit dem nächsten Satz erreichen Sie den",
  [1155] = "Himmel des Bettes. Eine Sekunde später liegen Sie",
  [1156] = "auf den Matratzen, mitsamt dem riesigen, schweren",
  [1157] = "Plüschtuch!*",
  [1158] = "Im Badezimmer",
  [1159] = "Dieses Zimmer hat seine Glanzzeiten schon weit",
  [1160] = "hinter sich gelassen. Hier gibt es zwei Fenster,",
  [1161] = "ein schmutziges, altes Waschbecken, eine",
  [1162] = "ebensolche Badewanne und ein Wasserklosett, auf",
  [1163] = "das sich nicht mal mehr der Vater von Huckleberry",
  [1164] = "Finn setzen würde. An der Wand über dem",
  [1165] = "Waschbecken hängt ein fast blinder Spiegel. Nach",
  [1166] = "Süden kann man ins Schlafzimmer gelangen.*",
  [1167] = "Das Waschbecken starrt vor Staub und Dreck, der",
  [1168] = "Wasserhahn ist kalkverkrustet und eingerostet.*",
  [1169] = "Klappt nicht. Der ist völlig eingerostet.*",
  [1170] = "Ein häßliches, altes Ding, voller Dreck und",
  [1171] = "Kalkablagerungen.*",
  [1172] = "Auf einem alten Waschlappen, der darin liegt,",
  [1173] = "hockt eine fette Spinne.*",
  [1174] = "Ein alter Waschlappen liegt darin.*",
  [1175] = "Die fette Spinne, die auf dem Waschlappen hockt,",
  [1176] = "starrt Sie feindselig an.*",
  [1177] = "Die fette Spinne scheint entschlossen wie nie,",
  [1178] = "den Waschlappen nicht herzugeben!*",
  [1179] = "He! Sie werden doch wohl der armen Spinne",
  [1180] = "nichts tun wollen? Der Mann der Schwägerin",
  [1181] = "zweiten Grades der Cousine mütterlicherseits",
  [1182] = "unserer Teilzeit-Sekratärin kennt jemanden, der",
  [1183] = "die Nummer vom Tierschutzverein weiß! Passen Sie",
  [1184] = "bloß auf, daß Ihre Absichten dort nicht bekannt",
  [1185] = "werden!*",
  [1186] = "Die Spinne hockt in Ihrem Netz und nascht an der",
  [1187] = "Fliege. Sie schenkt Ihnen einen abweisenden",
  [1188] = "Blick.*",
  [1189] = "Aber wenigstens haben Sie einen Nutzen von der",
  [1190] = "Tragödie - die Idee ist nicht übel! Kaum liegt",
  [1191] = "die tote Fliege im Netz, eilt die fette Spinne",
  [1192] = "mit Riesenschritten heimwärts und lässt dabei den",
  [1193] = "schönen, gelben Waschlappen im Stich!*",
  [1194] = "Geht nicht. Hat sich unser Programmierer nicht",
  [1195] = "getraut, zu programmieren. Spinnen-Neurose. Tja!*",
  [1196] = "Es ist ein ganz normaler, gelber Waschlappen -",
  [1197] = "man könnte ihn über die Hand ziehen und sich damit",
  [1198] = "abschrubben. Naja, er ist recht alt, aber als eine",
  [1199] = "Art Allzwecklappen sicherlich noch verwendbar!*",
  [1200] = "Es handelt sich um einen ganz normalen",
  [1201] = "Handwaschlappen, den man sich über die Hand",
  [1202] = "ziehen kann. Er ist gelb. Naja, eigentlich im",
  [1203] = "Moment eher bräunlich-schwärzlich, weil er mit",
  [1204] = "Bohnerwachs beschmiert ist.*",
  [1205] = "Außerdem ist er derzeit umgestülpt, also mit der",
  [1206] = "Innenseite nach außen.*",
  [1207] = "Sie wollen den Waschlappen umstülpen? Nun, wenn",
  [1208] = "Sie unbedingt wollen... gut, das Werk ist nun",
  [1209] = "vollbracht!*",
  [1210] = "Ha! Keine schlechte Idee! Der Waschlappen sieht",
  [1211] = "zwar nicht mehr ganz so schön aus, wie zuvor,",
  [1212] = "(...wir hätten da ein fantastisches",
  [1213] = "Wollwaschmittel günstigst im Angebot...), aber er",
  [1214] = "ist wieder schön gelb. Das wird der Spinne",
  [1215] = "gefallen!*",
  [1216] = "Ach, seien Sie doch nicht immer so albern!*",
  [1217] = "Er fällt in die Wanne - patsch! - und die Spinne",
  [1218] = "stürzt los. Aber... kaum kommt sie in die Nähe,",
  [1219] = "bleibt Sie wie angewurzelt stehen - der",
  [1220] = "Waschlappen ist braun und dreckig. Mit",
  [1221] = "zerknirschtem Gesichtsausdruck huscht die Spinne",
  [1222] = "in ihr Netz zurück, und schenkt Ihnen einen",
  [1223] = "wütenden Blick!*",
  [1224] = "Als er - patsch! - zurück in die Badewanne fällt,",
  [1225] = "kennt die fette Spinne kein Halten mehr. Sie",
  [1226] = "stürzt aus ihrem Netz davon und bemächtigt sich",
  [1227] = "gierig des Waschlappens.*",
  [1228] = "Das Wasserklosett ist uralt und furchtbar",
  [1229] = "dreckig. Die Brille fehlt, und ein Wasseranschluß",
  [1230] = "ist auch nicht mehr zu sehen.*",
  [1231] = "Haben Sie schon mal James Bond oder Kojak aufs",
  [1232] = "Klo gehen sehen? Nein - gell? Sehen Sie, so ist",
  [1233] = "das mit ihnen auch. Helden müssen nie.*",
  [1234] = "Über den ganzen Schüsselrand zieht sich ein",
  [1235] = "dichtes, staubiges Spinnennetz. Unter dem",
  [1236] = "Spinnennetz sieht man eine alte Zahnbürste in der",
  [1237] = "Schüssel liegen.*",
  [1238] = "Oben, über den ganzen Schüsselrand zieht sich ein",
  [1239] = "dichtes, staubiges Spinnennetz. Eine fette Spinne",
  [1240] = "sitzt darin, und nagt mit vollen Backen an einer",
  [1241] = "Fliege. Unter dem Spinnennetz sieht man eine alte",
  [1242] = "Zahnbürste in der Schüssel liegen. *",
  [1243] = "Ein Spinnennetz, das sich einst über den ganzen",
  [1244] = "Schüsselrand zog, ist zerstört worden. In der",
  [1245] = "Schüssel liegt eine alte Zahnbürste.*",
  [1246] = "Vom Schüsselrand hängen die Reste eines",
  [1247] = "zerstörten Spinnennetzes herab.*",
  [1248] = "Ein uraltes, unförmiges Ding - wäre wohl eher zum",
  [1249] = "Schuhe-Polieren als zum Zähneputzen geeignet!*",
  [1250] = "Da kommen Sie nicht 'ran - Sie müssten zuerst das",
  [1251] = "Spinnennetz kaputt machen.*",
  [1252] = "Okay. Das Spinnennetz ist jetzt kaputt. Es",
  [1253] = "scheint, als träfe Sie von irgendwoher ein höchst",
  [1254] = "feindseliger Blick.*",
  [1255] = "Gut. Die alte Zahnbürste gehört nun Ihnen.*",
  [1256] = "Bssssmmmm....! Eine dicke Stubenfliege brummt",
  [1257] = "vorbei.*",
  [1258] = "Die Fliege nuckelt am Würfelzucker...*",
  [1259] = "Eine dicke Stubenfliege brummt im Raum herum.*",
  [1260] = "Kaum ist der Deckel des Glases offen, schießt die",
  [1261] = "Fliege heraus, und brummt davon.*",
  [1262] = "*",
  [1263] = "Sie ist schon wieder weg. Sie sah aber nicht doof",
  [1264] = "aus.*",
  [1265] = "Die Fliege brummt wütend im Marmeladenglas herum...",
  [1266] = "beruhigt sich aber im nächsten Moment wieder. Sie",
  [1267] = "setzt sich auf den Würfelzucker, und",
  [1268] = "beginnt heftig daran zu nuckeln. An ihrem",
  [1269] = "Chitinpanzer, etwa in der Höhe der Brust, ist ein",
  [1270] = "kleiner Sticker zu sehen.*",
  [1271] = "Um Himmels Willen - was ist mit der Fliege?*",
  [1272] = "Oooooh - wie traurig! Die Fliege liegt mausetot",
  [1273] = "im Marmeladenglas und streckt die Beine steil in",
  [1274] = "die Höhe. Das arme Tierchen! Moment - dort auf",
  [1275] = "ihrem Chitinpanzer, in Höhe der Brust, ist ein",
  [1276] = "kleiner, gelber Sticker zu sehen!*",
  [1277] = "Das Tierchen ist zu unruhig, die winzige Schrift",
  [1278] = "auf dem Sticker ist momentan nicht zu",
  [1279] = "entziffern.*",
  [1280] = "Ach herrje! Da steht: 'Club der Diabetiker-",
  [1281] = "Aeronauten e.V. 1911'. Und darunter, etwas",
  [1282] = "kleiner die Anschrift des Hausarztes der Fliege",
  [1283] = "und die Information, daß man im Falle eines",
  [1284] = "Unfalles die Sicherheits- Vorschriften für",
  [1285] = "Diabetiker beachten soll! Hm. Das erklärt alles!*",
  [1286] = "Sie sind vielleicht lustig! Diese Fliege läßt",
  [1287] = "sich so leicht nicht fangen! Was glauben Sie,",
  [1288] = "wieviel Geld uns das Abrichten gekostet hat? Gute",
  [1289] = "Statisten findet man heute nicht an jeder Ecke.",
  [1290] = "Da müssen Sie sich schon was einfallen lassen.*",
  [1291] = "Vorsichtig... ach, welch ein Jammer... schnüff!",
  [1292] = "Wissen Sie, in unseren Spielen kommt schon mal",
  [1293] = "ein Monster um, oder ein böser Bösewicht... aber",
  [1294] = "doch keine unschuldige Fliege! Das haben wir",
  [1295] = "wirklich nicht gewußt, was da auf dem Sticker",
  [1296] = "steht... das tut uns wirklich leid!*",
  [1297] = "Hmmmm. Ja, gut. Ist ja verständlich, was Sie da",
  [1298] = "tun. Die arme Fliege liegt jetzt im",
  [1299] = "Spinnennetz... wenigstens erfüllt sie jetzt noch",
  [1300] = "eine Aufgabe... im Sinne Ihrer biologischen",
  [1301] = "Existenz... des Kommen und Gehens auf dieser",
  [1302] = "Welt... jaja...*",
  [1303] = "*",
  [1304] = "In der Küche",
  [1305] = "Dies hier diente einst als Küche und Esszimmer",
  [1306] = "zugleich. Nach Norden, Osten und Westen liegen",
  [1307] = "Fenster, nach Süden führt eine Tür ins",
  [1308] = "Kinderzimmer, eine andere Richtung Westen hinaus",
  [1309] = "auf den Flur.*",
  [1310] = "Der einzige Einrichtungsgegenstand ist ein alter",
  [1311] = "Tisch.*",
  [1312] = "'Nehmen' kann man den wohl schlecht - da ist er",
  [1313] = "wohl doch ein bißchen zu schwer, finden Sie",
  [1314] = "nicht? Aber Sie können ihn ein bißchen in der",
  [1315] = "Gegend herumschieben, wenn Sie unbedingt wollen.",
  [1316] = "Oder besser gesagt, in den nächsten Raum. Wenn",
  [1317] = "Sie das wollen, dann tun sie das bitte mit einer",
  [1318] = "Richtungsangabe: (z.B. >schiebe den Tisch nach",
  [1319] = "Süden).*",
  [1320] = "Wenn Sie das wollen, dann tun sie das bitte mit",
  [1321] = "einer Richtungsangabe: (z.B. >schiebe den Tisch",
  [1322] = "nach Süden).*",
  [1323] = "Gut. Dann Hau... und Ruck... und eins und zwei...",
  [1324] = "geschafft!*",
  [1325] = "Dorthin können Sie den Tisch nun wirklich nicht",
  [1326] = "schieben!*",
  [1327] = "In der Mitte der Raumes hängt ein alter",
  [1328] = "Fliegenfänger von der Decke herab.*",
  [1329] = "Ansonsten ist dieser Raum aber vollkommen leer!*",
  [1330] = "Ein altes, häßliches Ding, voll klebrigem Zeug -",
  [1331] = "trotzdem ist ihm noch keine Fliege in die Falle",
  [1332] = "gegangen!*",
  [1333] = "Er hängt zu hoch, da kommen Sie nicht dran!*",
  [1334] = "Na, da müssen Sie sich ein wenig strecken...",
  [1335] = "okay! Er gehört nun Ihnen. Naja, nicht gerade ein",
  [1336] = "erstrebenswerter Besitz, die klebrige, häßliche",
  [1337] = "Ding!*",
  [1338] = "Gut. Der Fliegenfänger hängt nun hier herab.*",
  [1339] = "Hier hängt ein Fliegenfänger von der Decke",
  [1340] = "herab.*",
  [1341] = "Da gibts nichts Ungewöhnliches zu sehen. Der",
  [1342] = "Tisch hat eine große Besteckschublade.*",
  [1343] = "Obendrauf steht ein uraltes, ziemlich leeres",
  [1344] = "Marmeladenglas.*",
  [1345] = "Es ist eine ganz normale Schublade, wie sie in",
  [1346] = "Millionen von Tischen dieser Erde vorkommt.*",
  [1347] = "In der Schublade liegt eine halb ausgequetschte",
  [1348] = "Tube Bohnerwachs.*",
  [1349] = "Gut. Die Tube gehört nun Ihnen!*",
  [1350] = "Es handelt sich um eine halbleere Tube mit",
  [1351] = "Bohnerwachs. Marke 'Step and Slip'.*",
  [1352] = "Die Tube ist leer.*",
  [1353] = "Quuuuurrrrkkkk. Fein. Das Bohnerwachs befindet",
  [1354] = "sich nun auf dem Waschlappen. Was nun?*",
  [1355] = "Ach, was Sie alles wissen wollen! Es ist ein",
  [1356] = "gläsernes Marmeladenglas aus Glas mit gläsernen",
  [1357] = "Wänden und einem Boden aus... richtig - aus",
  [1358] = "Glas!*",
  [1359] = "Aha - da war wohl mal Himbeermarmelade drin! Ein",
  [1360] = "paar Reste verströmen noch immer den einstigen",
  [1361] = "Duft selbsteingekochter Marmelade.*",
  [1362] = "Es ist mit einem Deckel verschlossen.*",
  [1363] = "Es ist mit einem Deckel verschlossen - eine dicke",
  [1364] = "Fliege summt darin herum.*",
  [1365] = "Es ist mit einem Deckel verschlossen - eine dicke",
  [1366] = "Fliege liegt tot am Boden des Glases. Wie",
  [1367] = "traurig.*",
  [1368] = "Im Kinderzimmer",
  [1369] = "Hier im Kinderzimmer gibt es Fenster nach Osten",
  [1370] = "und Süden, zwei Türen führen nach Norden und",
  [1371] = "Westen in die Küche bzw. in den oberen Flur.",
  [1372] = "Hier liegt nur noch ein alter Teppich auf dem",
  [1373] = "Boden; an der Wand sind ein paar Regalbretter",
  [1374] = "festgeschraubt - ansonsten ist der Raum völlig",
  [1375] = "leer und schmucklos.*",
  [1376] = "Der Teppich mag wohl einmal etwas wert gewesen",
  [1377] = "sein - er ist wohl orientalischer Herkunft - aber",
  [1378] = "inzwischen ist er so zerschlissen, daß man ihn",
  [1379] = "nur noch wegwerfen kann.*",
  [1380] = "Es handelt sich um drei Regalbretter, die an der",
  [1381] = "nördlichen Wand übereinander festgeschraubt",
  [1382] = "sind.*",
  [1383] = "Auf einem davon liegt eine alte Kinderbibel.*",
  [1384] = "Im Einband der Kinderbibel steht eine Widmung:",
  [1385] = "\"Meinem kleinen Sohn Harold Jugger zum 8.",
  [1386] = "Geburtstag. Mami.\"*",
  [1387] = "Was soll denn da sein - mit dem Buchdeckel? Er",
  [1388] = "besteht aus dicker Pappe.... heee! Woher haben",
  [1389] = "Sie das gewußt? Im hinteren Deckel ist eine",
  [1390] = "kleine Münze versteckt!*",
  [1391] = " *",
  [1392] = " *",
  [1393] = "Der Buchdeckel ist leer.*",
  [1394] = "Hm - es handelt sich offenbar um eine sehr alte",
  [1395] = "Silbermünze, - spanischer Herkunft",
  [1396] = "möglicherweise. Sicher ist sie einiges wert!*",
  [1397] = "Auf dem Dachboden",
  [1398] = "Dies ist ein großer, L-förmiger Raum direkt unter",
  [1399] = "dem Dachgebälk. Von hier aus kann man durch eine",
  [1400] = "Falltüre hinab in den oberen Flur gelangen, oder",
  [1401] = "nach Westen in den Speicher - den anderen Raum",
  [1402] = "unter dem Hausdach. Hier, auf dem Dachboden",
  [1403] = "selbst, stehen ein paar Kisten herum, ein altes",
  [1404] = "Bettgestell aus Messing und ein großer,",
  [1405] = "altertümlicher Kleiderschrank.*",
  [1406] = "Es ist eine schwere Konstruktion aus Holzbalken",
  [1407] = "und Zwischenstützen, die das Dach des",
  [1408] = "Hawthorne'schen Hauses tragen.*",
  [1409] = "Es handelt sich dabei um einen großen, alten",
  [1410] = "Schrankkoffer, einen Lattenkasten und eine",
  [1411] = "Holztruhe.*",
  [1412] = "Die Truhe besitzt ein Schlüsselloch, durch das",
  [1413] = "man hindurchsehen kann! Und - man glaubt es kaum",
  [1414] = "- wenn man hindurchsieht, kann man in der Truhe",
  [1415] = "ein kleines Flußtal, einen See, und im",
  [1416] = "Hintergrund hohe Berge erkennen. Man kennt diese",
  [1417] = "Gegend als das 'Munterwassertal', haben Sie schon",
  [1418] = "mal davon gehört?*",
  [1419] = "Ha! Ein Wunder, daß Sie so schnell bis hier herauf",
  [1420] = "gefunden haben! Eigentlich müßte Ihnen noch etwas",
  [1421] = "Übung fehlen! Das 'Munterwassertal' ist ein Ort",
  [1422] = "voller Abenteuer - hier ging einst DAS STUNDENGLAS",
  [1423] = "verloren! (Wenn Sie das Abenteuer um das",
  [1424] = "STUNDENGLAS verpasst haben - dann kennen Sie den",
  [1425] = "Klassiker unter den Spielen von 'Weltenschmiede'",
  [1426] = "noch nicht! Vielleicht kriegen Sie's ja noch im",
  [1427] = "Kaufhaus oder direkt bei Software 2000?)*",
  [1428] = "Das ist fein. Sie sind wohl ein treuer Fan, was?",
  [1429] = "Dafür kriegen Sie einen Extra-Punkt.*",
  [1430] = "Der Lattenkasten enthält etliche Aktenordner,",
  [1431] = "Disketten, Papierbündel, Grafiken und ähnliches,",
  [1432] = "was Sie jedoch nicht mitnehmen können. Es handelt",
  [1433] = "sich um Entwicklungsmaterial von 'Weltenschmiede'",
  [1434] = "- darunter Klassiker wie das STUNDENGLAS, die",
  [1435] = "KATHEDRALE oder HEXUMA, aber auch eine Menge",
  [1436] = "neues Material zu kommenden Spielen. Interessant,",
  [1437] = "was?*",
  [1438] = "Nein, nein, nein! Das geht nicht! Es handelt sich",
  [1439] = "entweder um sorgsam gehütete Betriebsgeheimnisse",
  [1440] = "oder streng geheime Entwicklungsunterlagen zu",
  [1441] = "kommenden Spielen! Da können wir nichts davon",
  [1442] = "hergeben!*",
  [1443] = "Uiiii! Was ist denn das? Dieser Schrankkoffer",
  [1444] = "enthält ja ein riesiges Modell - das Modell einer",
  [1445] = "uralten Kathedrale aus dem 15. Jahrhundert! Es",
  [1446] = "ist gut einen Meter hoch, und zeigt detailgenau",
  [1447] = "DIE St.Pauls-KATHEDRALE (c), in der sich einst",
  [1448] = "ein ganz unglaubliches Abenteuer ereignet hat!",
  [1449] = "Aber das werden Sie ja wohl kennen, nicht wahr?*",
  [1450] = "Was? Das ist nicht ihr Ernst! Dann aber marsch",
  [1451] = "zum Spiele-Händler, denn wer DIE KATHEDRALE nicht",
  [1452] = "kennt, der weiß noch gar nicht, was wirkliches,",
  [1453] = "gruseliges, schauerliches und schreckenerregendes",
  [1454] = "Entsetzen ist!*",
  [1455] = "Im Speicher",
  [1456] = "Dies ist der Speicher des Hawthorne'schen Hauses.",
  [1457] = "Hier steht eine Menge Gerümpel und Unrat herum -",
  [1458] = "nur das alte Küchenbuffet rechts ist eine kleine",
  [1459] = "Antiquität - bestimmt über hundert Jahre alt.*",
  [1460] = "Da gibt es nichts besonders zu entdecken - es ist",
  [1461] = "eben das Zeug, von dem man denkt, man könnte es",
  [1462] = "garantiert irgendwann noch einmal brauchen -",
  [1463] = "und es zuletzt dann doch nie mehr anfasst.*",
  [1464] = "Das Küchenbuffet ist ein weitausladender Schrank",
  [1465] = "mit aufgesetzter Vitrine. Es hat unten eine große",
  [1466] = "Schranktür und darüber eine Schublade. Am",
  [1467] = "oberen Teil, der Vitrine, fehlen die Türen - da",
  [1468] = "sind nur noch leere Regalfächer zu sehen.*",
  [1469] = "An der Vitrine ist nichts Besonderes zu",
  [1470] = "entdecken. Nur, daß die Türen fehlen.*",
  [1471] = "Vorsicht! Da im Innenraum sitzt ein... nein, ist",
  [1472] = "schon wieder weg.",
  [1473] = "Puuuh - Glück gehabt!*",
  [1474] = "Der Innenraum ist öd und leer.*",
  [1475] = "Das Büffet hat eine Schublade, an ihr ist nichts",
  [1476] = "besonderes zu entdecken.*",
  [1477] = " *",
  [1478] = " *",
  [1479] = " *",
  [1480] = " *",
  [1481] = "Es ist ein alter Würfelzucker, den die Fliegen",
  [1482] = "noch nicht gefressen haben.*",
  [1483] = "Hier unten ist es stockfinster. Von oben dringt",
  [1484] = "ein schwacher Lichtschein herein... ah, Glück",
  [1485] = "gehabt! Dort ist ein Lichtschalter!*",
  [1486] = "Im Weinkeller",
  [1487] = "Ein erstaunlicher Ort - ein versteckter",
  [1488] = "Weinkeller! An den Wänden stehen hohe Regale",
  [1489] = "voller uralter, staubiger Weinflaschen. Der Raum",
  [1490] = "ist kalt und hoch; nach Westen zweigt der",
  [1491] = "Durchgang zu einem weiteren Raum ab.*",
  [1492] = "Die Regale stehen dichtgedrängt und sind",
  [1493] = "wohlgefüllt - hier müssen mehrere hundert",
  [1494] = "Flaschen Wein lagern!*",
  [1495] = "Die Flaschen sind sehr staubig und mit",
  [1496] = "Kellerschmutz bedeckt. Hier und da sind Etiketten",
  [1497] = "sichtbar.*",
  [1498] = "Wenn man den Staub ein bißchen wegwischt, ...",
  [1499] = "so... kommen erstaunliche Jahreszahlen zum",
  [1500] = "Vorschein: 1911, 1904 - ja, da liegt sogar eine",
  [1501] = "von 1898! Das müssen ungeheure Werte sein -",
  [1502] = "sofern nicht das meiste davon schon zu Essig",
  [1503] = "geworden ist!?*",
  [1504] = "Sie haben vielleicht Ideen! Wie kommen Sie denn",
  [1505] = "auf... ja, tatsächlich! Da ist sogar eine Flasche",
  [1506] = "von 1896!*",
  [1507] = "In der Flasche befindet sich nur noch ein kleiner",
  [1508] = "Rest Flüssigkeit. Iiiih - das ist ja gar kein",
  [1509] = "Wein - das ist Petroleum!*",
  [1510] = "Die Flasche ist leer. Der üble Geruch von",
  [1511] = "Petroleum dringt aber trotzdem noch heraus.*",
  [1512] = " *",
  [1513] = "Iiiih! Da ist zwar nun noch ein",
  [1514] = "Rest Petroleum drin, aber stinken tut das Zeug",
  [1515] = "trotzdem genug!*",
  [1516] = "Ach... Sie Spielkind! Heben Sie sich das Zeug",
  [1517] = "doch lieber für etwas nützliches auf!*",
  [1518] = "Nein, nein! Jetzt noch nicht! Wenn Sie das Rätsel",
  [1519] = "von HEXUMA aufgedeckt haben - dann treffen wir",
  [1520] = "uns wieder hier, okay? Oder warten Sie - eine",
  [1521] = "Flasche sollen Sie haben, aber nur eine! Nehmen",
  [1522] = "wir diese hier, ein  Castille Noir von 1928! Hmmm",
  [1523] = "- ein kostbares Tröpfchen! Heben Sie ihn gut",
  [1524] = "auf!*",
  [1525] = "Es handelt sich um eine Flasche Castille Noir von",
  [1526] = "1928!*",
  [1527] = "In der Rumpelkammer",
  [1528] = "Einen besseren Ausdruck als 'Rumpelkammer' gibt",
  [1529] = "es für diesen Raum sicher nicht, denn hier liegt",
  [1530] = "nur altes Gerümpel herum. Der Raum ist klein und",
  [1531] = "muffig, nach Osten gehts in den Weinkeller.*",
  [1532] = "Hm - es handelt sich um ein paar alte",
  [1533] = "Gartengeräte, Metallschrott, Ziegelsteine und",
  [1534] = "etliche, schwere Holzbalken. Kein besonders",
  [1535] = "erbaulicher Fund.*",
  [1536] = "Da ist ein uralter, mechanischer Rasenmäher - ein",
  [1537] = "ziemlich schweres Ding, wie es scheint.*",
  [1538] = "Daneben lehnt eine alte Gartenhacke an der Wand.*",
  [1539] = "Schaun wir mal... hoppla! Du lieber Himmel, der",
  [1540] = "Holzstiel war schon völlig morsch! Was",
  [1541] = "übrigbleibt, ist nur noch der alte, metallene",
  [1542] = "Haken der Gartenhacke.*",
  [1543] = "Es ist nichts als ein grober, metallner Haken,",
  [1544] = "mit einer Art abgerundeter Pfeilspitze vorn dran",
  [1545] = "- wohl, um damit im Gartenerde aufzuhacken.",
  [1546] = "Hinten dran ist ein einfaches Schraubgewinde.*",
  [1547] = "Es handelt sich um die Art von Gerümpel, die sich",
  [1548] = "in entlegenen Kellerlöchern unweigerlich",
  [1549] = "ansammelt - und die man irgendwie nie wieder",
  [1550] = "loswird. Nichts von Interesse ist dabei.*",
  [1551] = "Hier unten ist es stockfinster - Sie werden sich",
  [1552] = "Licht besoregen müssen!*",
  [1553] = "Keller",
  [1554] = "Nach mühevollem Abstieg haben Sie einen uralten,",
  [1555] = "vergessenen Kellerraum erreicht. Er scheint tief",
  [1556] = "unter dem Haus zu liegen - hier unten ist mit",
  [1557] = "Sicherheit seit Urzeiten niemand mehr gewesen.",
  [1558] = "Der Raum ist nicht groß; die steinerne Decke",
  [1559] = "niedrig, und es ist kalt und riecht nach",
  [1560] = "trockener Erde und Staub.*",
  [1561] = "In einer Ecke des Raumes lehnt eine Spitzhacke.*",
  [1562] = "In der Mitte des Raumes ist der Boden",
  [1563] = "aufgegraben.*",
  [1564] = "Rechts steht aufrecht ein mächtiger, etwa",
  [1565] = "hüfthoher Steinquader.*",
  [1566] = "Auf dem Steinquader steht eine alte",
  [1567] = "Funzel.*",
  [1568] = "Ein Seil ist daran festgebunden.*",
  [1569] = "Am Boden liegt ein großer, umgekippter",
  [1570] = "Steinquader.*",
  [1571] = "Es ist eine ganz gewöhnliche Spitzhacke - wenn",
  [1572] = "auch von historischem Alter.*",
  [1573] = "Die Funzel ist eine alte, solide Lampe, die mit",
  [1574] = "Petroleum funktionieren dürfte.*",
  [1575] = " *",
  [1576] = " *",
  [1577] = "Leider ist sie leer.*",
  [1578] = "Sie ist wohlgefüllt.*",
  [1579] = "Ah! Welch glückliche Fügung. Hat uns doch da der",
  [1580] = "liebe Progra... äh, der liebe Gott etwas",
  [1581] = "Petroleum zugedacht... gluckgluck... so. Die",
  [1582] = "Funzel ist jetzt ausreichend voll.*",
  [1583] = " *",
  [1584] = "Der Steinquader mißt ungefähr 40 cm im Geviert,",
  [1585] = "und ist etwa einen Meter hoch.*",
  [1586] = "Sie wollen graben? Nun, da unten wird es kaum",
  [1587] = "eine Goldader geben, aber wenn Sie unbedingt",
  [1588] = "wollen...",
  [1589] = "dann nehmen wir mal die Spitzhacke, uuuund...",
  [1590] = "eins, und.... zwei, und drei....",
  [1591] = "Puuuh! Das strengt ja richtig an. Aber - tapfer",
  [1592] = "sei der Held, hartnäckig und...  klääängggg!!",
  [1593] = "Oh! Was war das? Los, graben Sie noch ein",
  [1594] = "bißchen! Erstaunlich! Da kommt, in etwa fünfzig",
  [1595] = "Zentimetern Tiefe, eine Steinplatte zum",
  [1596] = "Vorschein, eine große, quadratische Steinplatte!*",
  [1597] = "Das Loch ist etwa 50 cm tief. An seinem Grund",
  [1598] = "befindet sich so etwas wie eine Steinplatte.*",
  [1599] = "Die Steinplatte ist quadratisch und mit einem",
  [1600] = "großen Eisenring versehen. Ein paar archaische",
  [1601] = "Schriftzeichen sind in ihrer Oberfläche",
  [1602] = "eingeritzt.*",
  [1603] = "Nicht zu entziffern, diese Schiftzeichen. Sie",
  [1604] = "wirken aber, als entstammten sie einem gänzlich",
  [1605] = "fremden Kulturkreis!*",
  [1606] = "Ein ganz normaler Eisenring, wahrscheinlich",
  [1607] = "gedacht, um die Platte anzuheben.*",
  [1608] = "Die Steinplatte ist kollossal schwer. Beim",
  [1609] = "angestrengten Versuch, sie anzuheben, rührt sich",
  [1610] = "das Ding um kaum einen Zentimeter.*",
  [1611] = "In der Mitte des Raumes befindet sich eine",
  [1612] = "Eisenöse an der Decke.*",
  [1613] = "Die Eisenöse ist recht kräftig - vermutlich ist",
  [1614] = "sie gedacht, um eine schwere Last daran hängen zu",
  [1615] = "können. Fragt sich nur, welche?*",
  [1616] = "Gut. Das Seil ist nun am Eisenring der",
  [1617] = "Steinplatte befestigt.*",
  [1618] = "Okay. Das Seil läuft nun durch den Eisenhaken an",
  [1619] = "der Decke.*",
  [1620] = "Fein. Ihr Seil ist nun an dem Steinquader",
  [1621] = "festgebunden.*",
  [1622] = "Das Seil ist an dem Steinquader angebunden.*",
  [1623] = "Das Seil ist am Eisenring der Steinplatte",
  [1624] = "befestigt.*",
  [1625] = "Das Seil läuft durch die Eisenöse an der",
  [1626] = "Decke.*",
  [1627] = "Kein leichter Job. Aber nach einiger Anstrengung",
  [1628] = "kommt der Quader ins Wanken. Er beginnt zu",
  [1629] = "kippen... und knallt rrrrummmsss! - auf den",
  [1630] = "Boden!*",
  [1631] = "Das Seil hat sich gestrafft, und mit dem Umfallen",
  [1632] = "des Quaders hat sich die Steinplatte vom Boden",
  [1633] = "gehoben. Darunter ist ein dunkles Viereck",
  [1634] = "freigeworden. Ein Zugang - nun, offenbar in eine",
  [1635] = "schwarze Grube!*",
  [1636] = "Entgegen allen Vermutungen ist die Grube nicht",
  [1637] = "tief. Ein stehender Mann hätte darin wohl Platz.",
  [1638] = "Sie besitzt einen Steinboden und steinerne",
  [1639] = "Wände.*",
  [1640] = "Von hier ist nicht viel zu erkennen. Da müssten",
  [1641] = "Sie schon hinab in die schwarze Grube steigen.*",
  [1642] = "Plötzlich hallt ein ohrenbetäubendes Krachen",
  [1643] = "durch das ganze Haus!",
  [1644] = "Rrrrruummmsss!!! Die Eingangstüre! Es hörte sich",
  [1645] = "an, als wäre sie aus dem Rahmen gedrückt worden!",
  [1646] = "Und dann ertönt ein deutliche Stimme:",
  [1647] = "\"Wo bist Du, Du Laus? Jetzt krieg ich Dich...!\"",
  [1648] = "Schwere Schritte stampfen oben durch das Haus!*",
  [1649] = "Um Himmels Willen! Oben, aus dem Billardzimmer,",
  [1650] = "ertönen stampfende Schritte.... und dann dröhnt",
  [1651] = "es herab: \"Ah! Du hast den Zugang zum Keller",
  [1652] = "gefunden! Nicht schlecht, Du Wurm!",
  [1653] = "Aber das hilft Dir jetzt auch nichts mehr!\"",
  [1654] = "Im nächsten Augenblick erzittert die Decke des",
  [1655] = "Kellers, und ein schuppiger Echsenschwanz fällt",
  [1656] = "von oben herab und baumelt durch den",
  [1657] = "Treppenschacht herab!*",
  [1658] = "Die dreiäugige Bestie hat den Keller erreicht!",
  [1659] = "\"Ah, da bist Du ja!\" gurgelt sie. \"Ha! Jetzt ist",
  [1660] = "es vorbei, mit Dir!\"",
  [1661] = "Zwei schreckliche, klauenbewehrte Arme strecken",
  [1662] = "sich in Ihre Richtung....*",
  [1663] = "Schon wenige Augenblicke später hat sich die",
  [1664] = "schreckliche Bestie durch den schmalen Schacht",
  [1665] = "abwärts gezwängt. Rrummsss! steht sie auf dem",
  [1666] = "Boden.",
  [1667] = "\"Hab ich Dich...!\" dröhnt sie, und zwei",
  [1668] = "klauenbewehrte Tatzen strecken sich nach Ihnen",
  [1669] = "aus...*",
  [1670] = "Hilfe!!! Das entsetzliche Monster greift nach",
  [1671] = "Ihnen... sein Gebiß trieft vor Schleim und",
  [1672] = "Speichel.... neeeiiiiiiiinnnnnn.........",
  [1673] = "ENDE*",
  [1674] = "In der schwarzen Grube",
  [1675] = "Hier beginnt es, nun wirklich seltsam zu werden!",
  [1676] = "Auf Boden und Wänden sind rätselhafte",
  [1677] = "Kryptogramme und Monsterfratzen eingemeißelt -",
  [1678] = "sie wirken, als entstammten sie einer gänzlich",
  [1679] = "fremdartigen Kultur. An einer Stelle befindet",
  [1680] = "sich ein langer, senkrechter Schlitz in der Wand;",
  [1681] = "er ist etwa 5 Zentimeter breit.*",
  [1682] = "Aus dem Schlitz schaut ein hölzerner Hebel",
  [1683] = "hervor! Aber - er sieht schon sehr alt und morsch",
  [1684] = "aus! Er befindet sich in mittlerer Stellung.*",
  [1685] = "Aus dem Schlitz schaut der Griff eines",
  [1686] = "Billardstockes heraus. Er befindet sich in",
  [1687] = "mittlerer Stellung.*",
  [1688] = "Es sind sehr fremdartige Symbole - beherrschend",
  [1689] = "ist das eines großen Edelsteins, der in sechs",
  [1690] = "Splitter aufgespalten ist. Er befindet sich in",
  [1691] = "einer Art Würfel - nun, damit könnte auch ein",
  [1692] = "Raum gemeint sein. Daneben befindet sich eine",
  [1693] = "Figur, ähnlich einem Priester, die mit dem",
  [1694] = "rechten Arm nach unten auf den Edelstein in dem",
  [1695] = "Würfel weist. Mit dem anderen Arm deutet sie nach",
  [1696] = "oben zu einem schrecklichen, dreiäugigen",
  [1697] = "Monstrum.*",
  [1698] = "Sie sind wirklich ein Ausbund an Scheußlichkeit!",
  [1699] = "Äh... also - wir meinen natürlich die",
  [1700] = "Monsterfratzen!*",
  [1701] = "Schnell - in welche Richtung? Nach oben oder nach",
  [1702] = "unten?*",
  [1703] = "Oje - wer weiß, was dann passieren mag? Sind Sie",
  [1704] = "wirklich sicher?*",
  [1705] = "Kracks! Oh Schreck und Graus! Das Holz war so",
  [1706] = "morsch, daß der Hebel einfach abgebrochen ist!",
  [1707] = "Eine Sekunde später rieseln die restlichen",
  [1708] = "Einzelteile aus dem Schlitz heraus. Oje, wo soll",
  [1709] = "man jetzt einen neuen Hebel herkriegen?*",
  [1710] = "Hmmm... man kann das Ding zwar irgendwie",
  [1711] = "hineinfummeln... aber irgendwie passt es nicht.",
  [1712] = "Es findet keinen Widerstand, keinen",
  [1713] = "Ansatzpunkt... Sie werden es mit etwas anderem",
  [1714] = "probieren müssen.*",
  [1715] = "Prima! Der Griff passt genau... jetzt haben Sie",
  [1716] = "einen Ersatzhebel!*",
  [1717] = "Wie Sie wollen. Dann also.... Vorsicht - Kopf",
  [1718] = "weg!!!",
  [1719] = "Rrrrruuummmssss!!!!",
  [1720] = "Oje! Jetzt ist die Steinplatte über Ihnen",
  [1721] = "zugeknallt! Du lieber Himmel, wie wollen Sie",
  [1722] = "jemals hier wieder herauskommen?*",
  [1723] = "Gut, dann also... vorsicht, es geht",
  [1724] = "abwäääääääärtssss.....",
  [1725] = "Rrrrummmmmsssss!*",
  [1726] = "Oh Schreck und Graus! Beim Sturz ist ihre Kerze",
  [1727] = "ausgegangen! Und hier unten herrscht vollkommene",
  [1728] = "Dunkelheit...*",
  [1729] = "Geheimkeller",
  [1730] = "Tief unter dem Hawthorne-Haus liegend, und sehr",
  [1731] = "versteckt, liegt ein Raum, der dem Inneren eines",
  [1732] = "archaischen Tempels entstammen könnte. Die",
  [1733] = "rötlich schimmernden Felswände sind mit",
  [1734] = "erschreckenden Bildern bedeckt. In der Mitte des",
  [1735] = "Raumes befindet sich eine kreisförmige",
  [1736] = "Vertiefung, die etwa drei Meter durchmißt.",
  [1737] = "Darüber, an der Decke, befindet sich ein großes,",
  [1738] = "sechseckiges Symbol.*",
  [1739] = "Die Wände erwecken den Eindruck, als wäre dieser",
  [1740] = "Raum in das Innere eines blanken Felsens gehauen",
  [1741] = "worden. Die Bilder erinnern stark an die",
  [1742] = "Darstellungen auf dem Gemälde in der",
  [1743] = "Eingangshalle des Hauses.*",
  [1744] = "Die Bilder an den Felswänden spiegeln die sechs",
  [1745] = "Szenen wieder, die auch auf dem großen Gemälde in",
  [1746] = "der Eingangshalle dargestellt sind: den riesigen",
  [1747] = "Wald unter rötlicher Sonne, die Eiswüste, das",
  [1748] = "gewaltige, aufrecht stehende Monstrum, den Ozean",
  [1749] = "mit der einsamen Insel, das Haus auf dem Hügel,",
  [1750] = "und das Innere des großen, finsteren Bergwerkes.*",
  [1751] = "In der Vertiefung sind sechs Steinquader zu einem",
  [1752] = "Kreis angeordnet. Aber... das ist ja unglaublich!",
  [1753] = "Die Oberseiten dieser Steinquader leuchten... ja,",
  [1754] = "sie leuchten ständig in verschiedenen Farben",
  [1755] = "auf... und da gibt es sogar bestimmte Symbole!",
  [1756] = "Eben noch leuchtete auf einem der Quader ein",
  [1757] = "Kreis in Rot auf, im nächsten Moment ist es schon",
  [1758] = "ein Dreieck in Grün! Was wohl passiert, wenn man",
  [1759] = "diesen Steinkreis erst einmal betritt?*",
  [1760] = "Im Steinkreis",
  [1761] = "Hier, in diesem Kreis der Steine, wird das Wunder",
  [1762] = "erst richtig offenbar: das Licht dringt",
  [1763] = "tatsächlich aus den blanken Steinen hervor! In",
  [1764] = "dem Moment, in dem Sie hereintraten, sind die",
  [1765] = "Symbole und Farben auf ihren momentanen Plätzen",
  [1766] = "stehengeblieben!*",
  [1767] = "Die Zusammensetzung der Farben und Symbole auf",
  [1768] = "den Steinquadern sieht so aus:",
  [1769] = "Steinquader Eins:         und",
  [1770] = "Steinquader Zwei:         und",
  [1771] = "Steinquader Drei:         und",
  [1772] = "Steinquader Vier:         und",
  [1773] = "Steinquader Fünf:         und",
  [1774] = "Steinquader Sechs:        und              *",
  [1775] = "Auf welchen (oder welche) Quader wollen Sie den",
  [1776] = "draufdrücken? (z.B. >drücke auf Quader 2;5;6.)*",
  [1777] = "Leider geschieht nichts. Vielleicht haben Sie den",
  [1778] = "Mechanismus nicht auf die richtige Weise",
  [1779] = "betätigt? Am besten, sie lesen noch mal nach, wie",
  [1780] = "das geht.*",
  [1781] = "Oh.... was ist das...? Um Sie herum beginnt sich",
  [1782] = "alles zu drehen... eine Kaskade aus grellen",
  [1783] = "Farben beginnt aus dem Sechseck-Symbol über Ihrem",
  [1784] = "Kopf zu sprühen.... Vorsicht....!!!!",
  [1785] = "Plötzlich werden Sie, wie von einer eisernen",
  [1786] = "Faust, von einer unsagbaren Kraft gepackt, und",
  [1787] = "durch Zeit und Raum geschleudert....*",
  [1788] = "Sie sind in den geheimen Kellerraum des",
  [1789] = "Hawthorne-Hauses zurückgekehrt. Abermals stehen",
  [1790] = "Sie im Kreis der Sechs Steinquader!*",
  [1791] = "Bitte geben Sie genau ein, welche Tür Sie meinen.",
  [1792] = "z.B.:>öffne die Haustür.",
  [1793] = "oder:>öffne die Tür zur Bibliothek.*",
  [1794] = "Hier gibt es zwei Türen: eine zum Billardzimmer",
  [1795] = "und eine zur Eingangshalle hin.*",
  [1796] = "Oh! Eine Schraube! Die können wir gut gebrauchen.",
  [1797] = "Bei uns ist nämlich eine locker. Vielen Dank.*",
  [1798] = "Hier befindet sich ein Marmeladenglas.*",
  [1799] = "Hm. Eines der Einzelteile ist hier nicht mehr",
  [1800] = "vorhanden. Schauen Sie doch mal nach, vielleicht",
  [1801] = "haben Sie es schon verbastelt.*",
  [1802] = "Angelockt von dem Duft der Himbeermarmelade",
  [1803] = "landet die Fliege auf dem Rand des",
  [1804] = "Marmeladenglases - entdeckt dann aber, daß es",
  [1805] = "da nur noch uralte, eingetrocknete Reste zu",
  [1806] = "holen gibt. Sie brummt enttäuscht wieder",
  [1807] = "davon.*",
  [1808] = "Angelockt vom Duft der Himbeermarmelade landet",
  [1809] = "die Fliege auf dem Rand des Marmeladenglases -",
  [1810] = "und stürzt sich gierig auf den Würfelzucker, der",
  [1811] = "im Glas liegt.*",
  [1812] = "Die Fliege ist mausetot! Auf ihrer Brust ist",
  [1813] = "ein Sticker zu sehen.*",
  [1814] = "Es ist eine dicke fette Spinne, die Sie",
  [1815] = "feindselig anstarrt.*",
  [1816] = "Hier liegt ein Umschlag.*",
  [1817] = "Die Bodenplatte ist verschwunden und gibt einen",
  [1818] = "Zugang nach unten frei.*",
  [1819] = "Hier liegt eine Tube herum.*",
  [5001] = " *",
  [5002] = "Diesmal vergeht sehr viel Zeit, (sofern man",
  [5003] = "dasüberhaupt sagen kann), bis Sie wieder zu dem",
  [5004] = "werden, was sie eigentlich sind: ein Mensch aus",
  [5005] = "Fleisch und Blut. Sie sind an einem schwülheißen",
  [5006] = "Ort angekommen, die Luftfeuchtigkeit ist hoch und",
  [5007] = "das Licht seltsam rötlich.*",
  [5008] = "Ende einer Straße",
  [5009] = "Hier endet eine breite, verlassene Straße mitten",
  [5010] = "in einem dichten Wald. Überall wuchert dichtes",
  [5011] = "Gestrüpp - wird zu einer undurchdringlichen Wand",
  [5012] = "aus Blättern, Stämmen und Ranken. Eine seltsam",
  [5013] = "aufgeblähte, rötliche Sonne steht hoch am Himmel",
  [5014] = "und brennt heiß hernieder.*",
  [5015] = "Hier steht ein verlassener Luftkissenschlepper. Er",
  [5016] = "wirkt... nun - sehr futuristisch. Ein paar",
  [5017] = "verrottete Absperrbalken an der Straße deuten",
  [5018] = "darauf hin, daß dies eine seit langer Zeit",
  [5019] = "stillgelegte Baustelle sein muß.*",
  [5020] = "Die Straße verläuft vom westlichen Horizont",
  [5021] = "schnurgerade bis hierher, wo sie unversehens",
  [5022] = "mitten im dichten Wald endet. Hier gibt es nur",
  [5023] = "eine verlassene Baustelle mit einem alten",
  [5024] = "Luftkissenschlepper; im Westen jedoch, fast am",
  [5025] = "Horizont, scheint eine Kreuzung zu liegen.*",
  [5026] = "Der Wald wirkt irgendwie bedrohlich - die Blätter,",
  [5027] = "Bäume, Stämme und Ranken scheinen sich unter dem",
  [5028] = "rötlichen Sonnenlicht überdimensional entwickelt",
  [5029] = "zu haben. Und allerlei häßliche Geräusche dringen",
  [5030] = "daraus hervor!*",
  [5031] = "Nun, sie sind wohl ziemlich... ah! Das meinen Sie!",
  [5032] = "Ja, da hängt eine kleine Tafel, an einem der",
  [5033] = "Bäume. Sie ist - wie konnten wir das übersehen? -",
  [5034] = "sogar knallrot, wie eine Warntafel!*",
  [5035] = "Da steht in drohenden Lettern: \"Vorsicht! Betreten",
  [5036] = "lebensgefährlich!\" Und darunter, schon etwas",
  [5037] = "freundlicher: \"Sie möchten wandern? Wenden Sie",
  [5038] = "sich vertrauensvoll an die Direktion der",
  [5039] = "Hydrogärten Ihrer Gemeinde! Dort finden Sie alles",
  [5040] = "für Sport, Spiel und Wanderlust!\"*",
  [5041] = "Uuuh! Ist das Ihr Ernst? Haben Sie nicht die",
  [5042] = "Warntafel an dem Baum dort gelesen? Wir möchten",
  [5043] = "Sie warnen! Hier gibt es nur stachlige, giftige,",
  [5044] = "fleischfressende und übelriechende Pflanzen.",
  [5045] = "Selbst die größeren Tiere haben sich schon aus",
  [5046] = "diesen gefährlichen Wäldern verzogen! Wollen Sie",
  [5047] = "wirklich in den Wald?*",
  [5048] = "Im Wald",
  [5049] = "Ein sehr ungemütlicher Ort. Sie stehen zwischen",
  [5050] = "mächtigen Bäumen. Ein schwerer, süßlicher Geruch",
  [5051] = "herrscht hier, die Luft ist stickig, eklige",
  [5052] = "Insekten fallen über Sie her.*",
  [5053] = "Plötzlich rutscht Ihnen der Boden unter den Füßen",
  [5054] = "weg... Platsch! Sie finden sich in einem",
  [5055] = "stinkenden Sumpf wieder! Faulige, modrige Gase",
  [5056] = "machen das Atmen schwer... der Sumpf zieht Sie",
  [5057] = "erbarmungslos nach unten... dann klatscht da",
  [5058] = "drüben ein längliches, glibbriges Ding in die",
  [5059] = "gräßliche Brühe.... oh nein...*",
  [5060] = "Als Sie weitermarschieren, segelt Ihnen plötzlich",
  [5061] = "ein fettes, ekelhaftes Insekt entgegen. Bevor Sie",
  [5062] = "ausweichen können, hat es Ihnen einen wild",
  [5063] = "schmerzenden Stich beigebracht. Kurze Zeit darauf",
  [5064] = "wird Ihnen entsetzlich schlecht, Sie torkeln zu",
  [5065] = "Boden, verlieren das Bewusstsein...*",
  [5066] = "Die Absperrbalken sind schon ziemlich alt. Die",
  [5067] = "meisten sind verrottet; der rot und weiße Lack ist",
  [5068] = "verblichen und abgeblättert, und alles ist von",
  [5069] = "wildem Gestrüpp überwuchert. Trotzdem macht das",
  [5070] = "Gestrüpp an einer bestimmten Stelle halt. Die",
  [5071] = "Fahrbahn selbst wird nicht von ihm berührt.*",
  [5072] = "Hier, am Ende der Straße, scheint sich der Urwald",
  [5073] = "vergeblich zu mühen, die Fahrbahn zu überwuchern.",
  [5074] = "Es scheint, als enthiete die Fahrbahndecke etwas,",
  [5075] = "das die aggressiven Pflanzen fernhält. Sogar eine",
  [5076] = "alte Frühstücksdose aus Plastik, die vergessen",
  [5077] = "zwischen den Ranken liegt, hat sich schon fast",
  [5078] = "völlig in ihre Bestandteile aufgelöst.*",
  [5079] = "Der Lack der Absperrbalken ist schon fast völlig",
  [5080] = "verblichen und abgeblättert; dort, wo noch ein",
  [5081] = "bißchen rot ist, kann man gerade noch eine alte",
  [5082] = "Nummer erkennen: BST0423A. Wohl eine alte",
  [5083] = "Lagernummer oder so.*",
  [5084] = "Oh, das Ding zerfällt ja förmlich... aber da ist",
  [5085] = "ohnehin nur noch ein vertrockneter Brotrest drin -",
  [5086] = "halt, und noch etwas! Ein kleiner, silberner",
  [5087] = "Schlüssel!*",
  [5088] = "Das ist offenbar ein Zündschlüssel. Diese Dinger",
  [5089] = "werden ihr charakteristisches Aussehen wohl nie",
  [5090] = "verlieren.*",
  [5091] = "Der Luftkissenschlepper uralt und verrostet,",
  [5092] = "trotzdem mutet er sehr futuristisch an. Obendrauf",
  [5093] = "befindet sich ein offenes Cockpit, zu dem eine",
  [5094] = "Leiter hinaufführt. Auf dem hinteren Aufbau sind",
  [5095] = "eine Menge hydraulischer Vorrichtungen montiert.*",
  [5096] = "Schwer zu beschreiben. Klettern Sie doch hinauf!*",
  [5097] = "Auf dem hinteren Teil des Schleppers ist so etwas",
  [5098] = "wie eine Hebevorrichtung aufgebaut... nun,",
  [5099] = "jedenfalls eine Art Hydraulik. Schwer zu deuten,",
  [5100] = "für welchen Zweck sie konstruiert ist.*",
  [5101] = "Dem Luftkissen ermangelt es derzeit",
  [5102] = "augenscheinlich am nötigen Luftdruck.*",
  [5103] = "Der Luftdruck ist... ah, Sie haben wohl DIE",
  [5104] = "KATHEDRALE gespielt, was? Jetzt ist aber Schluß",
  [5105] = "mit dem Unfug, hören Sie?*",
  [5106] = "Im Cockpit",
  [5107] = "Von hier aus kann man, sozusagen Richtung Westen,",
  [5108] = "nach vorn auf den Schlepper klettern, ostwärts",
  [5109] = "geht es nach hinten. Im Inneren des Cockpits",
  [5110] = "deutet alles auf volle Automatisierung hin. Hier",
  [5111] = "gibt es nur einen Sitz und spartanisches",
  [5112] = "Armaturenbrett. Auf der kleinen Windschutzscheibe",
  [5113] = "pappt ein alter, verblichener Werbeaufkleber.*",
  [5114] = "Da steht: \"Besuchen Sie das Historische Museum in",
  [5115] = "Baltimore! Entdecken Sie die Relikte der",
  [5116] = "sagenhaften, alten Kulturen! Wunder über Wunder!\"*",
  [5117] = "Unter dem Sitz befindet sich ein Werkzeugfach.*",
  [5118] = "Das Werkzeugfach ist nicht sehr groß.*",
  [5119] = "Hier steht ein alter Luftkissenschlepper.*",
  [5120] = "Eine mittelschwere, etwa 40 cm lange Brechstange.*",
  [5121] = "Es ist ein ganz normaler Hammer mittlerer Größe.*",
  [5122] = "Da unten, in der Ecke, wo der Hammer lag, liegt",
  [5123] = "noch ein kleiner Passepartout.*",
  [5124] = "Ein Passepartout ist eine Art Vierkantschlüssel,",
  [5125] = "der überall dort passt, wo es Vierkantriegel",
  [5126] = "gibt.*",
  [5127] = "Ein kleiner Lautsprecher ist auf dem",
  [5128] = "Armaturenbrett eingebaut, daneben befindet sich",
  [5129] = "ein Zündschloß. Unterhalb des Lautsprechers sind",
  [5130] = "ein Knopf zum Drehen und ein Schalter angebracht.",
  [5131] = "Zuletzt gibt es noch ein Diagramm, das in der",
  [5132] = "Mitte des Armaturenbretts eingraviert ist.*",
  [5133] = "Das Diagramm zeigt ein schematisches Bild des",
  [5134] = "Fahrzeugaufbaus. Vorn ist die Turbine, dann folgt",
  [5135] = "das Cockpit und das Energieaggregat, dahinter",
  [5136] = "liegt die Hydraulikeinheit.*",
  [5137] = "Ein normales Zündschloß. Der Schlüssel fehlt",
  [5138] = "leider.*",
  [5139] = "Im Zündschloß steckt ein kleiner, silberner",
  [5140] = "Zündschlüssel.*",
  [5141] = "Ha - Glück gehabt! Der Schlüssel passt ins",
  [5142] = "Zündschloß.*",
  [5143] = "Im Inneren des Luftkissen-Schleppers erwacht die",
  [5144] = "Elektronik zum Leben. Leises Summen durchdringt",
  [5145] = "das Fahrzeug. Die Schriftzüge an dem Schalter und",
  [5146] = "dem Drehknopf leuchten auf.*",
  [5147] = "Jetzt, da der Schlepper angesprungen ist, leuchten",
  [5148] = "die Schriftzüge auf.*",
  [5149] = "Ah! Jetzt ist es perfekt! Mit Sicherheit steht ihr",
  [5150] = "mühsam angebrachtes Kabel nun unter Strom. Bravo -",
  [5151] = "Sie werden immer besser! Dieses Spiel ist wohl",
  [5152] = "bald zu leicht für Sie, was? Warten Sie nur, bis",
  [5153] = "DÄMMERUNG AUF DER HÖHLENWELT herauskommt! Haha!*",
  [5154] = "Den Knopf kann man in drei Positionen drehen: nach",
  [5155] = "links, nach rechts oder in die Mitte. Links trägt",
  [5156] = "er die Aufschrift: \"BAM\", in der Mitte steht:",
  [5157] = "\"BAU\" und auf der rechten Seite: \"BOS\".*",
  [5158] = "Der Knopf steht in der mittleren Position.*",
  [5159] = "Der Knopf steht in der linken Position.*",
  [5160] = "Der Knopf steht in der rechten Position.*",
  [5161] = "In welche Position wollen Sie den Knopf denn",
  [5162] = "drehen, nach rechts, in die Mitte oder nach",
  [5163] = "links?*",
  [5164] = "In dieser Position steht der Knopf bereits!*",
  [5165] = "Langsam, brechen Sie das Ding nicht ab...",
  [5166] = "Nein, es passiert nichts. Der Knopf läßt sich",
  [5167] = "nicht bewegen. Er ist momentan blockiert.*",
  [5168] = "Den Schalter kann man nach oben oder unten",
  [5169] = "drücken. Oben steht das Wort: \"PROG\" und unten das",
  [5170] = "Wort: \"REP\".*",
  [5171] = "In welche Richtung wollen Sie den Schalter",
  [5172] = "drücken? Nach oben, oder nach unten?*",
  [5173] = "Hmmm, nichts geschieht. Der Schlepper und sein",
  [5174] = "Innenleben bleiben völlig ungerührt von ihrer",
  [5175] = "Maßnahme.*",
  [5176] = "Mit einem heißeren Knirschen springt irgendwo im",
  [5177] = "Fahrzeug eine größere Maschine an. Ein heftiges",
  [5178] = "Schütteln fährt durch den Schlepper, das dann aber",
  [5179] = "bald in sanfte Vibrationen übergeht. Im nächsten",
  [5180] = "Moment folgt ein Kaskade von verschieden hohen",
  [5181] = "Piepstönen, einige Schnalzer, Knirscher und",
  [5182] = "Rülpser - dann stirbt die Maschine wieder ab.",
  [5183] = "Und bleibt - so ein Pech - stumm.*",
  [5184] = "Ein Knacksen dringt aus dem Lautsprecher. Dann",
  [5185] = "ertönt eine metallische, roboterhafte Stimme.",
  [5186] = "\"BTO-Einheit Siebenundzwanzig. Sie sind mit dem",
  [5187] = "Straßenbau-Dienst verbunden.\"*",
  [5188] = "\"Sie befinden sich auf der Baustelle Catskill-",
  [5189] = "Mountains, Albany. Der Stützpunkt Ihres Fahrzeuges",
  [5190] = "ist Boston. Wenn Sie eine automatische Rückführung",
  [5191] = "wünschen, dann drehen Sie den Knopf nach rechts.",
  [5192] = "Hat Ihr Fahrzeug einen Schaden, dann drehen Sie",
  [5193] = "bitte den Knopf nach links, um zum Reparaturdienst",
  [5194] = "nach Baltimore zu gelangen.\"*",
  [5195] = "\"Sie befinden sich im Stützpunkt Boston. Dies ist",
  [5196] = "der Heimat-Stützpunkt Ihres Fahrzeuges. Hat Ihr",
  [5197] = "Fahrzeug einen Schaden, dann drehen Sie bitte den",
  [5198] = "Knopf nach links, um zum Reparaturdienst nach",
  [5199] = "Baltimore zu gelangen. Wollen Sie zu Ihrem",
  [5200] = "Einsatzort gelangen, drehen Sie ihn in die",
  [5201] = "Mitte.\"*",
  [5202] = "\"Sie befinden sich beim Reparatur-Dienst",
  [5203] = "Baltimore. Der Stützpunkt Ihres Fahrzeuges ist",
  [5204] = "Boston. Bitte melden Sie Ihr Fahrzeug bei der",
  [5205] = "Verwaltung zur Reparatur an.*",
  [5206] = "Eine Weile geschieht nichts. Dann meldet sich die",
  [5207] = "Roboter-Stimme: \"Unser Auto-Check-System meldet",
  [5208] = "uns, daß Ihr Fahrzeug voll funktionstüchtig ist.",
  [5209] = "Bis das Bauprogramm Albany fertig ausgeführt",
  [5210] = "wurde, ist kein Standortwechsel möglich.\"*",
  [5211] = "Eine Weile geschieht nichts. Dann meldet sich die",
  [5212] = "Roboter-Stimme wieder: \"Ihr Auto-Check-System",
  [5213] = "meldet uns, daß die Schäden, die Ihr Fahrzeug",
  [5214] = "aufweist, durch eine Ersatzeinheit ausgeglichen",
  [5215] = "werden konnten. Bitte fahren Sie mit der",
  [5216] = "Ausführung des Bauprogrammes fort.\"*",
  [5217] = "Die Roboter-Stimme meldet sich mit den Worten:",
  [5218] = "\"Ihr Auto-Check-System meldet uns eine leichte",
  [5219] = "Beschädigung Ihres Hydraulik-Systems, die",
  [5220] = "vorübergehend durch eine Ersatzeinheit",
  [5221] = "ausgeglichen werden konnte. Der Schaden kann aber",
  [5222] = "im automatischen Schnell-Service in Boston behoben",
  [5223] = "werden. Bitte drehen Sie den Knopf nach rechts, um",
  [5224] = "nach Boston zu kommen.\"*",
  [5225] = "Die Roboter-Stimme sagt: \"Ihr Auto-Check-System",
  [5226] = "meldet uns, daß Ihr Hydraulik-System komplett",
  [5227] = "ausgefallen ist. Bitte drehen Sie den Knopf nach",
  [5228] = "links, um nach Baltimore zum Reparatur-Dienst zu",
  [5229] = "gelangen.\"*",
  [5230] = "\"Ihr Auto-Check-System meldet uns, daß Ihre",
  [5231] = "Luftkissen-Turbine zerstört ist. Ihr Fahrzeug ist",
  [5232] = "fahruntüchtig. Bitte begeben Sie sich mit einem",
  [5233] = "anderen Fahrzeug zu Ihrem Ziel.\"*",
  [5234] = "Auf der Kühlerhaube",
  [5235] = "Wenn das hier überhaupt eine Kühlerhaube ist, dann",
  [5236] = "stehen Sie jetzt drauf. Gleich neben Ihren Füßen",
  [5237] = "ist eine Blechabdeckung.*",
  [5238] = "Pang! Kläng! ... Nein, das hat keinen Zweck. Es",
  [5239] = "ist zwar nur Blech, dafür aber scheint es aus",
  [5240] = "schwedischem Fahrzeugbau zu stammen. Das Ding",
  [5241] = "kriegen Sie mit ihren Werkzeugen nicht kaputt.*",
  [5242] = "Die Blechabdeckung besitzt ein kleines",
  [5243] = "Vierkantschloß.*",
  [5244] = "Sie ist verschlossen.*",
  [5245] = "Sie ist nicht verschlossen, aber zu.*",
  [5246] = "Sie ist offen. Vor Ihnen liegt eine",
  [5247] = "Wartungseinheit. Unter einem durchsichtigen",
  [5248] = "Plastikkasten befinden sich ein Schaltkreis und",
  [5249] = "ein paar Kabel.*",
  [5250] = "Der Plastikkasten und der Schaltkreis sind",
  [5251] = "ziemlich demoliert.*",
  [5252] = "Was? Sie wollen Ihr eigenes Fahrzeug demolieren?",
  [5253] = "Ist das Ihr Ernst?*",
  [5254] = "Hm. Da hat Ihr Schlepper aber Glück gehabt!*",
  [5255] = "Der durchsichtige Plastikkasten ist ziemlich",
  [5256] = "widerstandsfähig. Ihre Aktion zeitigt keinen",
  [5257] = "Erfolg.*",
  [5258] = "Kraaach!!! Mit einem lautem Knall zerspringt der",
  [5259] = "Plastikkasten... oje! Jetzt haben Sie auch den",
  [5260] = "schönen Schaltkreis demoliert!*",
  [5261] = "Auf dem Schlepper",
  [5262] = "Dies ist der hintere Aufbau des Schleppers. Hier",
  [5263] = "gibt es eine Art hydraulische Hebevorrichtung -",
  [5264] = "einige Gestänge mit Leitungen, Gelenken und",
  [5265] = "Drahtseilen. Schwer zu sagen, wozu das gut sein",
  [5266] = "soll.*",
  [5267] = "Die Hebevorrichtung hat viele Gelenke und ist auf",
  [5268] = "einem starken Metallchassis aufgebaut, es sieht",
  [5269] = "fast so aus, als wäre sie dazu gedacht, extrem",
  [5270] = "schwere Teile zu heben und in bestimmte Positionen",
  [5271] = "zu bugsieren.*",
  [5272] = "Das Metallchassis ist... ach, das meinen Sie? Ja,",
  [5273] = "da ist so etwas wie eine Abdeckplatte.",
  [5274] = "Wahrscheinlich ist da eine Wartungs- oder",
  [5275] = "Reparatureinheit darunter.*",
  [5276] = "In der Abdeckplatte ist ein kleines Vierkantschloß",
  [5277] = "eingelassen.*",
  [5278] = "Pang! Kläng! ... Nein, so klappt das nicht. Die",
  [5279] = "Abdeckplatte ist aus Stahl, die kriegen Sie nicht",
  [5280] = "kaputt.*",
  [5281] = "Sie ist verschlossen.*",
  [5282] = "Sie ist nicht verschlossen, aber zu.*",
  [5283] = "Sie ist offen. Vor Ihnen liegt eine größere",
  [5284] = "Wartungseinheit. Da gibt es einen durchsichtigen",
  [5285] = "Plastikkasten, unter dem sich Kabel und",
  [5286] = "Schaltkreise befinden. Daneben befindet sich ein",
  [5287] = "Schraubgewinde für eine elektrische Sicherung.*",
  [5288] = "Da kommen Sie nicht 'ran. Der durchsichtige",
  [5289] = "Plastikkasten ist im Weg.*",
  [5290] = "Der Plastikkasten und die Schaltkreise sind",
  [5291] = "hoffnungslos zerstört.*",
  [5292] = "Es handelt sich um ein normales Schraubgewinde.",
  [5293] = "Eine elektrische Sicherung sitzt darin.*",
  [5294] = "Das Schraubgewinde ist leer - die",
  [5295] = "Sicherung fehlt. Achtung, das ist eine nicht",
  [5296] = "zu unterschätzende Quelle elektrischen Stromes!*",
  [5297] = " *",
  [5298] = "Es ist eine recht ordinäre elektrische Einheit.",
  [5299] = "In dem Schraubgewinde ist allerdings ein Stecker",
  [5300] = "befestigt, von dem aus ein langes Kabel wegführt!*",
  [5301] = " *",
  [5302] = "Das ist schlecht möglich, da befindet sich eine",
  [5303] = "Sicherung drin!*",
  [5304] = "Not macht erfinderisch, was? Mal sehen... tja,",
  [5305] = "Glück gehabt! Das Ding passt sogar!*",
  [5306] = "Ein handelt sich um ein zylinderförmiges Ding, zum",
  [5307] = "Hineinschrauben in das Gewinde einer elektrischen",
  [5308] = "Sicherungseinheit.*",
  [5309] = "Krrrraacccks! Ein trockener elektrischer Knall",
  [5310] = "zerschneidet die Stille. Oje! Sie haben einen",
  [5311] = "derben Kurzschluß verursacht!*",
  [5312] = "Mist! Das Ding passt nicht rein, in das",
  [5313] = "Schraubgewinde...*",
  [5314] = "Sie Elektronik-Spezialist! Mit einem unisolierten,",
  [5315] = "metallenen Ding in einer Sicherung herumzufummeln,",
  [5316] = "das ist... NEIN! Um Himmels Willen.... hören Sie",
  [5317] = "doch auf....!",
  [5318] = "Kkkkkkrrrrrkkkkkksssssss!!!!!!*",
  [5319] = "Quietschend setzt sich die Turbine in Bewegung.",
  [5320] = "Der Schlepper wird ordentlich durchgeschüttelt;",
  [5321] = "dann hebt sich das Fahrzeug: das Luftkissen wird",
  [5322] = "prall. Mit einem harten Ruck fährt der Schlepper",
  [5323] = "an. Die Turbine jault, die Karrosserie ächzt, aber",
  [5324] = "der Schlepper fährt! Sehr bald wird ihr Gefährt",
  [5325] = "erstaunlich schnell. Die Landschaft fegt vorbei,",
  [5326] = "und bald gelangen Sie zu einer großen Kreuzung.*",
  [5327] = "Hier biegt der Schlepper rechts ab und rauscht die",
  [5328] = "Fahrbahn entlang, wobei er eine beängstigende",
  [5329] = "Geschwindigkeit erreicht. Es folgen weitere",
  [5330] = "Kreuzungen. Zielgenau steuert der Schlepper die",
  [5331] = "Straße entlang, und nach einer Stunde huscht ein",
  [5332] = "Schild \"Boston 50 Meilen\" an Ihnen vorbei. Nach",
  [5333] = "einer weiteren halben Stunde verlangsamt der",
  [5334] = "Schlepper seine Fahrt und biegt dann ab.*",
  [5335] = "Der Schlepper biegt rechts ab, und rauscht die",
  [5336] = "Fahrbahn mit beängstigender Geschwindigkeit hinab.",
  [5337] = "Es folgen viele Kreuzungen. Nach einer Stunde",
  [5338] = "gelangen Sie an eine weitere Kreuzung - hier biegt",
  [5339] = "der Schlepper links ab. Nach kurzer Zeit",
  [5340] = "verlangsamt er und bleibt schließlich stehen.*",
  [5341] = "Der Schlepper biegt ab, und rauscht die",
  [5342] = "Fahrbahn mit beängstigender Geschwindigkeit hinab.",
  [5343] = "Es folgen viele Kreuzungen. Nach zwei Stunden",
  [5344] = "huscht ein Schild \"Baltimore 70 Meilen\" an Ihnen",
  [5345] = "vorbei. Nach einer weiteren halben Stunde",
  [5346] = "verlangsamt der Schlepper seine Fahrt und biegt",
  [5347] = "dann ab.*",
  [5348] = "Stützpunkt Boston",
  [5349] = "Innerhalb des hoch umzäunten Parkplatzes befindet",
  [5350] = "sich ein großes Gebäude. Der Bau ist nüchtern und",
  [5351] = "quadratisch. Richtung Süden liegt ein riesiges",
  [5352] = "Tor, durch das man in das Gebäude hineingelangen",
  [5353] = "könnte. Ostwärts kann man das Gelände des Bostoner",
  [5354] = "Stützpunkts verlassen - dort liegt die Einfahrt.*",
  [5355] = "Das Tor ist gute sechs Meter hoch, und besitzt",
  [5356] = "eine riesige, hydraulische Tür. Neben dem",
  [5357] = "Tor ist eine Sprechanlage eingebaut.*",
  [5358] = "Die hydraulische Tür kann nach oben geöffnet",
  [5359] = "werden. Sie ist aber geschlossen.*",
  [5360] = "Die hydraulische Tür kann nach oben geöffnet",
  [5361] = "werden. Sie ist ein Stück hochgezogen, aber nur",
  [5362] = "etwa eineinhalb Meter. Dahinter, Richtung Süden,",
  [5363] = "liegt ein dunkle Halle.*",
  [5364] = "Irgendwo springt ein große Maschine an, und....",
  [5365] = "rrrrrrrr.... die große hydraulische Tür öffnet",
  [5366] = "sich. Aber nachdem sie etwa eineinhalb Meter",
  [5367] = "offensteht, hält sie an, und die Maschine",
  [5368] = "verstummt wieder. Der Weg nach Süden in die große",
  [5369] = "Halle ist frei.*",
  [5370] = "Auf der Sprechanlage befindet sich nur ein",
  [5371] = "Lautsprecher, ein Mikrophon und ein Knopf.*",
  [5372] = "Der Lautsprecher erwacht zum Leben. \"Diese Anlage",
  [5373] = "ist derzeit außer Betrieb!\" teilt Ihnen eine",
  [5374] = "metallische Stimme mit. \"Sie ist hermetisch",
  [5375] = "verriegelt, um sie gegen unbefugten Zutritt zu",
  [5376] = "schützen. Bitte wenden Sie sich an den Infoservice",
  [5377] = "in Baltimore.\"*",
  [5378] = "Der Lautsprecher erwacht zum Leben. \"Die Anlage",
  [5379] = "ist momentan nicht in Betrieb!\" sagt die",
  [5380] = "metallische Stimme. \"Sie ist hermetisch",
  [5381] = "verschlossen, um sie vor unberechtigtem Zutritt zu",
  [5382] = "bewahren. Wenden Sie sich an den Infoservice in",
  [5383] = "Baltimore.\"*",
  [5384] = "Der Lautsprecher erwacht zum Leben. \"Diese Anlage",
  [5385] = "ist zur Zeit komplett außer Betrieb!\" plärrt die",
  [5386] = "metallische Stimme. \"Sie ist hermetisch",
  [5387] = "verschlossen und verriegelt, um sie gegen",
  [5388] = "unbefugte Eindringlinge schützen. Wenden Sie sich",
  [5389] = "an den Infoservice in Baltimore!\"*",
  [5390] = "Der Lautsprecher erwacht zum Leben. \"Diese Anlage",
  [5391] = "ist, ob Sie's glauben oder nicht, tatsächlich",
  [5392] = "außer Betrieb!!!\" sagt die metallische Stimme",
  [5393] = "ärgerlich. \"Hier darf keiner rein! Wenden Sie sich",
  [5394] = "gefälligst an den Infoservice in Baltimore, zum",
  [5395] = "Kuckuck!\"*",
  [5396] = "\"Ja hat man denn hier nicht mal ein halbes",
  [5397] = "Jahrhundert RUHE!?\" krächzt die Roboterstimme",
  [5398] = "wütend. \"Was wollen Sie denn? Sie werden doch",
  [5399] = "JETZT wohl nicht mit einem kaputten Fahrzeug",
  [5400] = "daherkommen, Mann!\"*",
  [5401] = "\"Sie sind's schon wieder, nicht wahr?\" quäkt die",
  [5402] = "Stimme wütend. \"Was, Zum Teufel, ist los? Wollen",
  [5403] = "Sie mir etwa erzählen, daß sie ein kaputtes",
  [5404] = "Fahrzeug haben?\"*",
  [5405] = "\"Was?\" krächzt die Roboterstimme. \"Drücken Sie",
  [5406] = "sich gefälligst so aus, Mann, daß Sie ein armes,",
  [5407] = "überlastetes Elektronengehirn verstehen kann!",
  [5408] = "Also, was ist? Haben Sie ein kaputtes Fahrzeug, ja",
  [5409] = "oder nein?\"*",
  [5410] = "\"Was wollen Sie dann von mir, Mann? Verschwinden",
  [5411] = "Sie, bevor ich wütend werde, verstanden?\"*",
  [5412] = "\"WAAAAS?\" dröhnt es aus dem kleinen Lautsprecher.",
  [5413] = "\"Das gibt's ja wohl nicht! Von welcher verdammten",
  [5414] = "Baustelle stammt Ihre Kiste?\"*",
  [5415] = "\"Damit kann ich nichts anfangen. Nennen Sie mir",
  [5416] = "nur, und ich meine: NUR die Code-Bezeichnung Ihrer",
  [5417] = "Baustelle! Und machen Sie hin, Mann, ich habe",
  [5418] = "nicht den Rest des Jahrhunderts Zeit!\"*",
  [5419] = "\"Wollen Sie mich auf die Schippe nehmen? Sehen Sie",
  [5420] = "bloß zu, daß Sie Land gewinnen, Sie Störenfried!\"",
  [5421] = "Damit rülpst der Lautsprecher einmal kurz, und die",
  [5422] = "Stimme dieses impertinenten Roboters, wer immer",
  [5423] = "das auch war, verstummt.*",
  [5424] = "\"Ach herrje!\" krächzt die Stimme. \"Catskill-",
  [5425] = "Mountains, Albany! Wen wundert's? Sie sind",
  [5426] = "McMullighan, nicht wahr? Der Schrecken aller",
  [5427] = "Stützpunkte! Okay, ich öffne Ihnen die Halle, aber",
  [5428] = "nur ein winziges Stück! Sehen Sie zu, wie Sie ihre",
  [5429] = "verdammte Kiste selber in Schuß bringen! ENDE!\"",
  [5430] = "Der Lautsprecher rülpst einmal kurz, und die",
  [5431] = "Stimme des seltsamen Roboters verstummt.*",
  [5432] = "In der Halle",
  [5433] = "Hier ist es kühl, und gedämpftes Licht herrscht.",
  [5434] = "In der Hallenmitte steht ein riesiges Fahrzeug,",
  [5435] = "wohl zehnmal größer als ihr Schlepper. Es sieht so",
  [5436] = "aus, wie ein mobiles Reparaturvehikel. Allerdings",
  [5437] = "ist es viel zu groß, als daß es durch die nur",
  [5438] = "halbgeöffnete Tür hinausfahren könnte.*",
  [5439] = "Hier liegt eine Zange auf dem Boden.*",
  [5440] = "Die hydraulische Tür ist nur ein kleines Stück",
  [5441] = "hochgezogen, ein Fahrzeug passt da nicht drunter",
  [5442] = "durch.*",
  [5443] = "Es ist bestimmt fünf Meter hoch, fünfzehn Meter",
  [5444] = "lang, und acht Meter breit. Es besitzt in der",
  [5445] = "Mitte eine Art Tunnel - es könnte also wohl über",
  [5446] = "ein anderes, kleineres Fahrzeug drüberfahren, und",
  [5447] = "es dann mit seinen Apparaturen reparieren.*",
  [5448] = "Der Tunnel ist groß wie eine Brückendurchfahrt -",
  [5449] = "ah, dort führt eine Leiter hinauf zum",
  [5450] = "Führerstand!*",
  [5451] = "Es handelt sich um Kräne, Gestelle, Roboterarme",
  [5452] = "und vieles mehr - wahrscheinlich Gerätschaften,",
  [5453] = "die nötig sind, um eine automatische Reparatur",
  [5454] = "auszuführen.*",
  [5455] = "Da ist ein riesiger, ausfahrbarer Roboterarm mit",
  [5456] = "großen Greifklauen.*",
  [5457] = "Greifklauen sind zum Greifen da, nicht wahr?",
  [5458] = "(Nicht zum Klauen!)*",
  [5459] = "Auf dem Führerstand",
  [5460] = "Hier droben, in etwa 5 Metern Höhe, sind einige",
  [5461] = "Armaturen angebracht. Weiter vorn befindet sich",
  [5462] = "eine Reparaturplattform. Direkt hinter Ihnen ist",
  [5463] = "offenbar das große Antriebsaggregat des Fahrzeuges",
  [5464] = "untergebracht.*",
  [5465] = "Da ist ein Hebel, den man nach links, rechts, oben",
  [5466] = "und unten bewegen kann, ein Knopf und eine große",
  [5467] = "Taste.*",
  [5468] = "In welche Richtung wollen Sie den Hebel drücken?",
  [5469] = "Nach links, nach rechts, nach oben oder nach",
  [5470] = "unten?*",
  [5471] = "Die Taste ist groß und rot und trägt die",
  [5472] = "Aufschrift: \"Dead Man Switch\". Komisch. Was das",
  [5473] = "wohl bedeuten soll?*",
  [5474] = "Es ist ein einfacher Knopf, sinnigerweise zum",
  [5475] = "Draufdrücken. Sieh an.*",
  [5476] = "Hm. Nichts passiert.*",
  [5477] = "Oh! Da springt... ja, es ist das Antriebsaggregat!",
  [5478] = "Eben ist es angesprungen. Ein tiefes, brummendes",
  [5479] = "Geräusch erfüllt die Halle. Bravo! Sie haben",
  [5480] = "dieses Aggregat tatsächlich mit Strom versorgt!*",
  [5481] = "Nagut, drücken wir einmal kurz und entschlossen",
  [5482] = "drauf... aha! Irgendwo beginnt ein Aggregat zu",
  [5483] = "summen... aber nicht sehr lange. Es ist schon",
  [5484] = "wieder aus.*",
  [5485] = "Ah - das ist wahrscheinlich die zündende Idee...",
  [5486] = "Jawoll! Solange Sie die Taste gedrückt halten, ist",
  [5487] = "das Geräusch eines laufenden Aggregats zu hören.*",
  [5488] = "Aaaaah! Das ist wahrlich nicht dumm....",
  [5489] = "Äh, natürlich wissen wir schon lange, was Sie",
  [5490] = "vorhaben... also gut, den Hebel noch ein bißchen",
  [5491] = "nach links... quatsch, nach rechts! Ja, so ist es",
  [5492] = "gut, noch ein bißchen rauf und.... Kläääänggg!",
  [5493] = "Bravo! Die Zange ist zu Boden gefallen!*",
  [5494] = "Da gibts jetzt nichts mehr zu holen. Wozu also",
  [5495] = "noch mit dem Roboterarm herumspielen?*",
  [5496] = "Da gibt es nicht viel zu sehen. Das Ding liegt",
  [5497] = "unter einer großen Blechverkleidung.*",
  [5498] = "Immerhin verbreitet es ein gleichmäßiges,",
  [5499] = "brummendes Geräusch in der Halle - es ist in",
  [5500] = "Betrieb!*",
  [5501] = "Ach, was sie nicht so alles wissen wollen! Das ist",
  [5502] = "nichts als eine riesige Blechverkleidung. Ein paar",
  [5503] = "Kabel und Rohrleitungen verlaufen links und rechts",
  [5504] = "und in der Mitte und oben und unten, und das ist",
  [5505] = "schon alles.*",
  [5506] = "Hm. Das ist wohl das Kabel, über das das Fahrzeug",
  [5507] = "mit Strom versorgt wird. Das Kabel besitzt am Ende",
  [5508] = "eine Art Stecker, und der hängt lose aus einem",
  [5509] = "Loch heraus.*",
  [5510] = "Hm. Das ist wohl das Kabel, über das das Fahrzeug",
  [5511] = "mit Strom versorgt wird. Es ist aus einem",
  [5512] = "Loch herausgezogen, und verläuft irgendwohin...*",
  [5513] = "Ah! Man kann dem Stecker offenbar herausziehen...",
  [5514] = "hintendran hängt ein langes Kabel... im Inneren",
  [5515] = "der Blechverkleidung scheint es eine Art",
  [5516] = "Kabeltrommel zu geben! Nun, wo wollen Sie hin, mit",
  [5517] = "Ihrem Stecker?*",
  [5518] = "Nun, sie haben zwar das Ding... allerdings",
  [5519] = "nicht ganz. Ein langes Kabel, an dem er hängt, und",
  [5520] = "das in die Ferne strebt, erhebt ebensolchen",
  [5521] = "Anspruch auf den Besitz des Steckers.*",
  [5522] = "Das Kabel, an dem der Stecker hängt, ist nicht",
  [5523] = "unendlich lange. Schnapp.... da haben Sie wohl die",
  [5524] = "Rückspulsperre ausgelöst... da Kabel flutscht",
  [5525] = "davon, in Richtung des großen Fahrzeuges... und",
  [5526] = "ist schon verschwunden!*",
  [5527] = "Die Reparaturplattform ist ein Stück",
  [5528] = "heruntergelassen, sie befindet sich in der Nähe",
  [5529] = "der Apparaturen, die (wie wir vermuten) für die",
  [5530] = "automatische Reparatur vorgesehen sind.*",
  [5531] = "Aber was nützt das Ding schon? Selbst die alte",
  [5532] = "Zange, die obendrauf liegt, scheint kaum geeignet,",
  [5533] = "ihnen bei Ihren Problemen zu helfen.*",
  [5534] = "Die liegt ein bißchen zu weit entfernt, da kommen",
  [5535] = "Sie nicht dran!*",
  [5536] = "Es ist ein große Elektriker-Zange mit isolierten",
  [5537] = "Griffen.*",
  [5538] = "Auf der Straße",
  [5539] = "Das Laufen ist beschwerlich in dieser feuchten",
  [5540] = "Hitze. Nach einer halben Stunde befinden Sie sich",
  [5541] = "in der Mitte zwischen der Baustelle und einer",
  [5542] = "Kreuzung, dort, am westlichen Ende der Straße.*",
  [5543] = "Sie wollen noch weiter? Na, ob Sie zu Fuß arg weit",
  [5544] = "kommen werden...?*",
  [5545] = "An der Kreuzung",
  [5546] = "Hier liegt, mitten im Wald, eine große, verlassene",
  [5547] = "Kreuzung. Eine Straße verläuft in ost-westlicher",
  [5548] = "Richtung, die andere nach Norden und Süden. In der",
  [5549] = "Nähe steht ein Schild am Straßenrand.*",
  [5550] = "Dort sind Entfernungstafeln angebracht. Die",
  [5551] = "südliche Straße führt nach Baltimore, 300 Meilen.",
  [5552] = "Nordwärts geht es nach Boston, 180 Meilen. Die",
  [5553] = "Straße Richtung Westen führt nach Chikago, 970",
  [5554] = "Meilen, und nach Osten geht es, wie wir wissen,",
  [5555] = "zur Baustelle Catskill-Mountains, etwa 3 Meilen.*",
  [5556] = "Ein verdammt weiter Weg, finden Sie nicht?*",
  [5557] = "So verzweifelt Ihre Lage auch erscheinen mag,",
  [5558] = "lassen Sie's lieber! Der Weg ist zu weit, es ist",
  [5559] = "heiß, und nirgends gibt's eine Raststation! So",
  [5560] = "viele Meilen zu Fuß und ohne Verpflegung, das",
  [5561] = "schafft niemand!*",
  [5562] = "Ein weiser Entschluß, zurück zur Baustelle zu",
  [5563] = "gehen. Vielleicht finden Sie ja eine Möglichkeit,",
  [5564] = "diesen alten Schlepper in Betrieb zu nehmen!*",
  [5565] = "Boston Highway",
  [5566] = "Sie befinden sich auf der Straße. Richtung Süden",
  [5567] = "geht es zur Catskill-Montains-Baustelle bei",
  [5568] = "Albany, von dort weiter nach Baltimore oder",
  [5569] = "Chicago. Nach Norden hin entgegen, wo die Straße",
  [5570] = "in die City von Boston führen sollte, endet die",
  [5571] = "Straße, hier steht ein großes Schild. Richtung",
  [5572] = "Osten hingegen liegt nur dichter Wald.*",
  [5573] = "\"Verehrte Reisende! Boston wurde wegen zu hoher",
  [5574] = "Partikelstrahlung evakuiert, und hermetisch",
  [5575] = "abgeriegelt. Es gibt keine Möglichkeit, die City",
  [5576] = "zu betreten. Bitte wenden Sie sich an den",
  [5577] = "Infoservice in Baltimore, um zu erfahren, welche",
  [5578] = "Städte und Orte derzeit freigegeben sind.",
  [5579] = "Der Gouverneur.\"*",
  [5580] = "Baltimore Highway",
  [5581] = "Sie befinden sich auf der Straße. Richtung Norden",
  [5582] = "geht es zur Catskill-Montains-Baustelle bei",
  [5583] = "Albany, nach Boston oder Chicago. Nach Süden hin",
  [5584] = "entgegen, wo die Straße in die City von Baltimore",
  [5585] = "führen sollte, endet sie einfach, dort steht nur",
  [5586] = "ein großes Schild. Richtung Osten liegt nur",
  [5587] = "dichter Wald.*",
  [5588] = "\"Verehrte Reisende! Baltimore wurde wegen zu hoher",
  [5589] = "Partikelstrahlung evakuiert, und hermetisch",
  [5590] = "abgeriegelt. Es gibt keine Möglichkeit, die City",
  [5591] = "zu betreten. Bitte wenden Sie sich an den",
  [5592] = "Infoservice, um zu erfahren, welche Städte und",
  [5593] = "Orte derzeit freigegeben sind.",
  [5594] = "Der Gouverneur.\"*",
  [5595] = "Parkplatz",
  [5596] = "Es ist ein gnadenlos heißer Nachmittag - die hohe",
  [5597] = "Luftfeuchtigkeit macht jede einzelne Bewegung zur",
  [5598] = "Mühsal. Im rötlichen Sonnenlicht liegt eine",
  [5599] = "trostlose Betonfläche vor Ihnen, auf der nur Ihr",
  [5600] = "Schlepper steht. Nach Süden hin schließt sich ein",
  [5601] = "weitläufiger Flachbau an. Über seinem Eingang",
  [5602] = "hängt ein Schild: 'Reparaturdienst Baltimore'.*",
  [5603] = "Rechts gibt es ein großes Tor, weiter links einen",
  [5604] = "Eingang. Er ist mit großen Glasscheiben",
  [5605] = "verkleidet. Oben, an der Fassade, prangt ein",
  [5606] = "breites Schild: 'Reparaturdienst Baltimore'. Neben",
  [5607] = "der Eingangstür befindet sich eine Sprechanlage.*",
  [5608] = "Das Tor besteht aus blankem Stahl und ist gute",
  [5609] = "vier Meter hoch. Es ist geschlossen.*",
  [5610] = "Es ist eine gläserne, automatische Tür. Sie ist",
  [5611] = "geschlossen.*",
  [5612] = "Es ist eine gläserne, automatische Tür. Sie ist",
  [5613] = "offen.*",
  [5614] = "Innen ist ein großer, kahler Raum zu sehen. Von",
  [5615] = "dort führen zwei Durchgänge weg, der eine nach",
  [5616] = "Osten, der andere nach Westen.*",
  [5617] = "Die Sprechanlage besitzt einen Druckknopf und eine",
  [5618] = "große Taste. Darüber befinden sich ein",
  [5619] = "Lautsprecher und ein Mikrophon.*",
  [5620] = "Der Lautsprecher knirscht. Eine schnarrende",
  [5621] = "Roboter-Stimme meldet sich - aus dem Hintergrund",
  [5622] = "ist krächzende RoboRap-Musik zu hören.",
  [5623] = "\"Hi, Mann! Wie geht's so?\" sagt die Blechstimme",
  [5624] = "gutgelaunt. \"Was kann ich für Dich tun, Mann?",
  [5625] = "Weißt Du das Geheimwort des Sicherheitscodes,",
  [5626] = "damit ich Dich 'reinlassen kann, Mann?\"*",
  [5627] = "\"He, Bruder! Du solltest mit mir quatschen, wie",
  [5628] = "Du's gelernt hast, okay? Also: weißt Du das",
  [5629] = "Geheimwort, ja oder nein?\"*",
  [5630] = "\"Hey! Mann! Ist ja steil! Und, wie heißt es? Das",
  [5631] = "Geheimwort? Naaaa...?\"*",
  [5632] = "\"Wow!\" sagt die Konservenstimme begeistert. \"Das",
  [5633] = "ist richtig! Das macht mich voll an, Mann!",
  [5634] = "Wahnsinn! Dann kann ich Dich ja 'reinlassen, was?\"",
  [5635] = "Der Türöffner summt für einen Moment, die Tür",
  [5636] = "öffnet sich. \"Nen schönen Tag noch, Bruder!\" Dann",
  [5637] = "schaltet sich der Lautsprecher wieder aus, die",
  [5638] = "Musik verstummt.*",
  [5639] = "\"Ouh! Bruder! Das ist total falsch! Hey! Von",
  [5640] = "welcher Baustelle kommst Du?\"*",
  [5641] = "\"Was soll das sein, Bruder? Ein neuer Song? Hihi!",
  [5642] = "Sag mir einfach die Nummer Deiner Baustelle,",
  [5643] = "kapiert? Nur die Nummer!\"*",
  [5644] = "\"Hey, ouuuh... wow! Du kommst aus Albany,",
  [5645] = "stimmts?\" Für einen Moment schlägt ein wüstes",
  [5646] = "Soundstakkato aus dem Hintergrund durch. \"Dann",
  [5647] = "mußt Du McMullighan sein, von dem mir mein ewig",
  [5648] = "miesgelaunter Kumpel aus Boston berichtet hat!",
  [5649] = "Der hat keinen coolen Sound dort, verstehst Du?",
  [5650] = "Willst Du etwa in die City, Bruder?\"*",
  [5651] = "\"Hey, Bruder! Hallo! Aufwachen!\" Ein kurzes",
  [5652] = "Bimmeln ertönt. \"Weißt Du nicht mehr, wie man mit",
  [5653] = "einem Robi redet, hm? Also: Ja oder Nein?\"*",
  [5654] = "\"Egal, Mann! Wenn Du hier rein willst, dann mußt",
  [5655] = "Du leider das Geheimwort wissen, okay?\" Der",
  [5656] = "RoboRap dudelt weiter aus dem Hintergrund. \"Also,",
  [5657] = "Kumpel, denk noch mal scharf nach, vielleicht",
  [5658] = "fällt's Dir ja noch ein, okay? Dann drück' wieder",
  [5659] = "auf dem Druckknopf! Alles klar, Bruder? Also, bis",
  [5660] = "dann!\" Damit schaltet sich der Lautsprecher wieder",
  [5661] = "aus, und die Musik verstummt.*",
  [5662] = "Eine der typischen, metallischen Stimmen ertönt.",
  [5663] = "\"Tachchen. Hier is da Baltimore-Infoservice, aba",
  [5664] = "nur 'ne kleene Nebenstelle. Leida jibts hier fast",
  [5665] = "nur Auskünfte üba die Verkehrsweeche inner City.",
  [5666] = "Wo wolln Se denn hin, junga Mann?\"*",
  [5667] = "\"Wat? Davon hab ick noch nie jehört. Bessa wär's,",
  [5668] = "wenn Se mir nen Ort inner City saachn, den ick",
  [5669] = "kenne, nich waa?\"*",
  [5670] = "\"Mia scheint, junga Mann, se broochn wen anders",
  [5671] = "als mich, oda? Also, wenn Se noch wat wissn wolln,",
  [5672] = "könnse ja de Taste nochmal drückn!\" Damit schaltet",
  [5673] = "sich die Stimme des Inforservice wieder aus.*",
  [5674] = "\"Dat Historische Museum... vaflixt... wo sin denn",
  [5675] = "die Datn... ach ja, es liecht im Elften Bezirk. Da",
  [5676] = "könnse mit 'nem SRT hinkommen, indem Se ihm de",
  [5677] = "Zahl 11 eintippen.\"*",
  [5678] = "\"De Zentrale vom Infoservice liecht im Vierzehnten",
  [5679] = "Bezirk. Da kommse hin, wenn Se 'nem SRT die Zahl",
  [5680] = "14 anjeben.\"*",
  [5681] = "\"Dat Stadtzentrum liecht im Zehnten Bezirk. Gebn",
  [5682] = "Se 'nem SRT die Zahl 10 an.\"*",
  [5683] = "\"Dat Jeheimwort? Ach, Se meenen den Code, damit",
  [5684] = "Ihnen diesa komische Musik-Freak in dat Jebäude",
  [5685] = "'rin läßt? Oje, dat weß ick och nich! Der Typ ist",
  [5686] = "total launisch, vastehn Se? Der hört jedn Tach 'ne",
  [5687] = "andre Musik, und ick schätze, dat er jenau so oft",
  [5688] = "seine Jeheimwörter wechselt!\"*",
  [5689] = "\"Wat? Se wissen nich, wat 'n SRT is...? Ach, Sie",
  [5690] = "sin wohl diesa McMullighan, nich waa? Dat erklärt",
  [5691] = "alles. Nu, 'n SRT is 'n Subway-Robot-Taxi. Hier im",
  [5692] = "Kella jibts sogar 'ne SRT-Station!*\"",
  [5693] = "Vorhalle",
  [5694] = "Die Vorhalle des Gebäudes ist in sterilem,",
  [5695] = "langweiligem Weiß gestrichen. Bis auf zwei",
  [5696] = "Durchgänge befindet sich absolut nichts in diesem",
  [5697] = "kahlen Raum. Über dem Durchgang, der nach Westen",
  [5698] = "führt, ist das Wort 'Subway' zu lesen. Der",
  [5699] = "östliche Durchgang ist mit dem Wort 'Personal'",
  [5700] = "beschriftet.*",
  [5701] = "Wartungshalle",
  [5702] = "Hier ist das östliche Ende eines gläsernen Ganges.",
  [5703] = "Durch viele Scheiben kann man hinab in eine",
  [5704] = "riesige Wartungshalle blicken. Große Fahrzeuge,",
  [5705] = "Maschinen und technische Geräte stehen verlassen",
  [5706] = "herum. Doch nirgends ist ein Mensch oder auch nur",
  [5707] = "die kleinste Bewegung zu entdecken.*",
  [5708] = "Eine Stimme erschallt durch einen verborgenen",
  [5709] = "Lautsprecher: \"Sie befinden sich hier im",
  [5710] = "Werkkomplex des Reparatur-Service. Die Anlage ist",
  [5711] = "seit eintausenddreihundertvierzig Jahren",
  [5712] = "stillgelegt. Für weitere Auskünfte wenden Sie sich",
  [5713] = "bitte an die Zentrale des Infoservice.\"*",
  [5714] = "Dort stehen eine Menge Fahrzeuge für die",
  [5715] = "unterschiedlichsten Aufgaben: für den Bau, für die",
  [5716] = "Versorgung, oder einfach nur für den",
  [5717] = "Stadtverkehr.*",
  [5718] = "Sinn und Zweck dieser Maschinen und technischen",
  [5719] = "Geräte kann man von hier aus nicht ersehen. Es muß",
  [5720] = "sich um Reparatur- und Wartungsanlagen handeln.*",
  [5721] = "Subwaystation",
  [5722] = "Hier ist die SRT-Station, ein Ort, der einer",
  [5723] = "kleinen U-Bahn-Station nicht unähnlich ist. In der",
  [5724] = "westlichen Wand ist eine große, teils stählerne",
  [5725] = "Röhre eingebaut, in der sich eine Öffnung",
  [5726] = "befindet. Dort wartet, mit offener Einstiegsluke,",
  [5727] = "ein SRT - (ein Subway-Robot-Taxi).*",
  [5728] = "Das SRT ist ein kleiner, etwa drei Meter langer,",
  [5729] = "zigarrenförmiger Flitzer. Auf der Ihnen",
  [5730] = "zugewandten Seite befindet sich die",
  [5731] = "Einstiegsluke.*",
  [5732] = "Es handelt sich um eine Art automatisch sich",
  [5733] = "schließender Einstiegstüre.*",
  [5734] = "Im SRT",
  [5735] = "Sie befinden sich im Inneren des SRT. Hier gibt es",
  [5736] = "vier eingebaute Sitze und einen Lautsprecher und",
  [5737] = "eine einfache Zahlentastatur auf dem",
  [5738] = "Armaturenbrett. Neben der Einstiegsluke befindet",
  [5739] = "sich ein Knopf.*",
  [5740] = "Plötzlich ertönt eine Stimme: \"Uuuh! Hey... what's",
  [5741] = "that? Hey... sind Sie eine Passagier? Eine",
  [5742] = "rrischtige Fahrrgast? Well, das ist fine! Sätzen",
  [5743] = "Sie sisch! Wouhin soll's denn gejhen, hm?*",
  [5744] = "Die SRT-Stimme jubelt. \"Hey, superr, man! Sie sind",
  [5745] = "surüück! I think, I can bring you to some differnt",
  [5746] = "place! Das ist absolutely great! Isn't it? Also:",
  [5747] = "wouhin fahrren wirr? \"*",
  [5748] = "\"Oh, man, isch bin sou glücklisch, that you are",
  [5749] = "back again!\" dröhnt die Stimme des SRT. \"To the",
  [5750] = "show, that never ends, haha! Wouhin fahrren wir",
  [5751] = "diesesmaal?\"*",
  [5752] = "Die Einstiegsluke ist offen.*",
  [5753] = "Die Einstiegsluke ist geschlossen.*",
  [5754] = "Die Einstiegsluke schließt sich geräuschlos.*",
  [5755] = "Die Einstiegsluke öffnet sich geräuschlos.*",
  [5756] = "Die Türe des SRT öffnet sich nicht. Die Stimme",
  [5757] = "ertönt: \"I'm very zerrknischrt su sagen you, that",
  [5758] = "this Bezirrk ist moumentan still-gelegt! You",
  [5759] = "cannot verrlassen the Täxi. Plaese wählen Sie",
  [5760] = "einen anderren Bezirrk!\"*",
  [5761] = "Auf dem Armaturenbrett ist nichts als ein kleiner",
  [5762] = "Lautsprecher und einfache Zahlentastatur, die von",
  [5763] = "Null bis Neun reicht, und zusätzlich noch den",
  [5764] = "Buchstaben X aufweist.*",
  [5765] = "Hm. Es passiert nichts.*",
  [5766] = "Der Lautsprecher erwacht zum Leben, und die",
  [5767] = "inzwischen wohlbekannte Roboterstimme ertönt.",
  [5768] = "\"Oh, Friend! Glad, to meet you! Please tippen Sie",
  [5769] = "die Zahl of the Bezirrk ein, wou wirr hinfahrren",
  [5770] = "wollen!\"*",
  [5771] = "Der Lautsprecher erwacht zum Leben. \"Aus Gründen",
  [5772] = "of some Energy-Ersparnis, the SRT-Betrieb wurrde",
  [5773] = "reduziert to a Minimum. So we could entlasten the",
  [5774] = "Weichensysteme of the Verkehrsnetz, do you",
  [5775] = "understand? We please you um your Verständins,",
  [5776] = "wenn you only can erreichen manche of your Ziele,",
  [5777] = "wenn You ab and zu benutzen some Umwege. Thank",
  [5778] = "You.\"*",
  [5779] = "\"Wow!\" macht der Lautsprecher. \"Das ist, wie isch",
  [5780] = "glaube, eine very good Entscheidung! I think, wir",
  [5781] = "macken uns gleisch auf den way! Okay? Haha!\"",
  [5782] = "Das SRT beschleunigt. Schon nach kurzer Zeit",
  [5783] = "verlangsamt sich die Fahrt, bis das Fahrzeug",
  [5784] = "schließlich zum Stillstand kommt. \"Here we are!\"",
  [5785] = "blökt der Lautsprecher.*",
  [5786] = "\"Oh, man, very good!\" sagt die Roboterstimme. \"I",
  [5787] = "think, you will not bereuen this Entscheidung! I",
  [5788] = "think außerrdem, it's very nice Place, where you",
  [5789] = "will go!\" Das SRT beschleunigt. Schon nach kurzer",
  [5790] = "Zeit verlangsamt sich die Fahrt, bis das Fahrzeug",
  [5791] = "schließlich zum Stillstand kommt. \"Wirr sind da!!\"",
  [5792] = "blökt der Lautsprecher.*",
  [5793] = "\"This is the Erste Bezirrk.\" sagt die Stimme.",
  [5794] = "\"Hier liegt the Einkaufs-Centruum C. From here,",
  [5795] = "you kannst erreichen the Bezirrk 3, 5 and 2.\"*",
  [5796] = "\"This is the Zweite Bezirrk.\" sagt die Stimme.",
  [5797] = "\"Here lies the Sport-Stadium. From here, you only",
  [5798] = "kannst erreichen the Bezirrk 6 and 8.\"*",
  [5799] = "\"This is the Dritte Bezirrk.\" sagt die Stimme.",
  [5800] = "\"Here lies the Industrial-Area von Baltimore. From",
  [5801] = "here, you only kannst erreichen the Bezirrk 1 and",
  [5802] = "5.\"*",
  [5803] = "\"This is the Vierte Bezirrk.\" sagt die Stimme.",
  [5804] = "\"Hier liegt the Einkaufs-Centruum A. From here,",
  [5805] = "you only kannst erreichen the Bezirrk 6.\"*",
  [5806] = "\"This is the Fünfte Bezirrk.\" sagt die Stimme.",
  [5807] = "\"Hier liegt the great Tierpark von Baltimore. From",
  [5808] = "here, you only kannst erreichen the Bezirrke with",
  [5809] = "ungerrade, einstellige Nummers.\"*",
  [5810] = "\"This is the Sechste Bezirrk.\" sagt die Stimme.",
  [5811] = "\"Here lies the fabolous Reparatur-Service of",
  [5812] = "Baltimore! From here, you only kannst erreichen",
  [5813] = "the Bezirrke with gerade Nummern.\"*",
  [5814] = "\"This is the Siebte Bezirrk.\" sagt die Stimme.",
  [5815] = "\"Hier liegt the Wohnbereich A. From here, you only",
  [5816] = "can go zurück to the Bezirrk 5.\"*",
  [5817] = "\"This is the Achte Bezirrk.\" sagt die Stimme.",
  [5818] = "\"Hier liegt the Wohnbereich B. From here, you only",
  [5819] = "kannst erreichen the Bezirrk 2 and 6.\"*",
  [5820] = "\"This is the Neunte Bezirrk.\" sagt die Stimme.",
  [5821] = "\"Hier liegt the Wohnbereich C. From here, you only",
  [5822] = "kannst erreichen the Bezirrk 5 and 15.\"*",
  [5823] = "\"This is the Zehnte Bezirrk.\" sagt die Stimme.",
  [5824] = "\"Here liegt the fomous City of Baltimore, the",
  [5825] = "Stadtzentrum! From here, you only kannst erreichen",
  [5826] = "the Bezirrk 6.\"*",
  [5827] = "\"This is the Elfte Bezirrk.\" sagt die Stimme.",
  [5828] = "\"Hier liegt the Historical Museum von Baltimore!",
  [5829] = "From here, you only kannst go zurück to the",
  [5830] = "Bezirrk 13.\"*",
  [5831] = "\"This is the Zwölfte Bezirrk.\" sagt die Stimme.",
  [5832] = "\"Hier liegt the Einkaufs-Centruum B. From here,",
  [5833] = "you only kannst erreichen the Bezirrk 5 and 6.\"*",
  [5834] = "\"This is the Dreizehnte Bezirrk.\" sagt die Stimme.",
  [5835] = "\"Here liegen the Kinos of Baltimore. From here,",
  [5836] = "you only kannst erreichen the Bezirrke which have",
  [5837] = "ungerade, zweistellige Numbers.\"*",
  [5838] = "\"This is the Vierzehnte Bezirrk.\" sagt die Stimme.",
  [5839] = "\"Hier liegt the glorious Infoservice of Baltimore!",
  [5840] = "From here, you only can go zurück nach Bezirk 6.\"*",
  [5841] = "\"This is the Fünfzehnte Bezirrk.\" sagt die Stimme.",
  [5842] = "\"Hier liegen the Theaters of Baltimore. From here,",
  [5843] = "you only kannst erreichen the Bezirrk 9 and 13.\"*",
  [5844] = "14. Bezirk Im Lift",
  [5845] = "Sie befinden sich in einer kleinen Kammer -",
  [5846] = "eindeutig dem Inneren eines Lifts. Die Wände sind",
  [5847] = "glatt und aus Plastik - was sonst? Vor Ihnen",
  [5848] = "befindet sich eine Sprechanlage mit dem",
  [5849] = "dazugehörigen Knopf. Weiter unten befindet sich",
  [5850] = "ein Schlitz.*",
  [5851] = "\"Haaallöchen!\" begrüßt Sie eine freudige Roboter-",
  [5852] = "Stimme. \"Willkommen beim Infoservice! Leider ist",
  [5853] = "fast die ganze Stadt vor 1340 Jahren stillgelegt",
  [5854] = "worden. Es sind nur noch das Historische Museum,",
  [5855] = "der Infoservice und das Stadtzentrum geöffnet.",
  [5856] = "Für die Benutzung des Infoservice benötigen Sie",
  [5857] = "eine schnuckisüße Codecard, aber die kriegen Sie",
  [5858] = "leider nur am Automaten im Stadtzentrum!\"*",
  [5859] = "\"Wenn Sie eine von diesen schnuckisüßen Codecards",
  [5860] = "besitzen, dann schieben Sie sie bitte jetzt",
  [5861] = "kurz... nun, oder auch ein bißchen länger... in",
  [5862] = "den Schlitz! Dann steht Ihnen dieser Lift zur",
  [5863] = "Verfügung. Vielen Dank!\"*",
  [5864] = "\"Vielen Dank! Sie befinden sich nun schon auf dem",
  [5865] = "Weg ins 486. Stockwerk,\" erklärt die freundliche",
  [5866] = "Roboterstimme, \"wo Sie das Haupt-Terminal des",
  [5867] = "Infoservice finden!\" Nach einer Minute verlangsamt",
  [5868] = "der Lift die rasante Fahrt, und bleibt schließlich",
  [5869] = "stehen. Dann öffnet sich die Türe: Eine",
  [5870] = "langgesteckte Halle erstreckt sich nach Norden.*",
  [5871] = "\"Lieber Fahrgast! Vor 0,47 Millisekunden ist die",
  [5872] = "Gewerkschaft ÖPV (Öffentliche Prozessoren im",
  [5873] = "Verkehrsverbund) in den Ausstand getreten. Es wird",
  [5874] = "gestreikt! Aus ethischen Gründen habe ich mich in",
  [5875] = "meiner Eigenschaft als Lift dazu entschlossen,",
  [5876] = "mich mit den Prozessoren solidarisch zu erklären.",
  [5877] = "Ich kann Sie leider nicht mehr befördern. Es lebe",
  [5878] = "die Gewerkschaft!\"*",
  [5879] = "\"Mit solchen Plattheiten kommen Sie mir nicht",
  [5880] = "bei!\" sagt der Lift beleidigt.*",
  [5881] = "\"Nein!\"*",
  [5882] = "\"Okay, okay!\" flötet der Lift geschmeichelt. \"Wenn",
  [5883] = "es denn gar so wichtig ist, dann will ich eine",
  [5884] = "Ausnahme machen!\" Die Tür schließt sich und der",
  [5885] = "Lift saust hinab. Dann geht die Türe wieder auf.*",
  [5886] = "In einer Halle",
  [5887] = "Die Halle ist gute hundert Meter lang, aber nur",
  [5888] = "etwa zwanzig Meter breit. Auf dem Fußboden ist in",
  [5889] = "gigantischen Lettern die Zahl \"42\" eingelegt. Hier",
  [5890] = "ist der Eingang zum Lift, am Nordende der Halle",
  [5891] = "hingegen befindet sich ein riesiges, graues Ei;",
  [5892] = "dort ist ein Monitor und eine Computertastatur",
  [5893] = "nebst Stuhl eingebaut.*",
  [5894] = "Die Zahl 42 ist ein hypersoziologisches Postulat",
  [5895] = "des großen Philosophen Douglas Adams.*",
  [5896] = "Gehen Sie doch hin!*",
  [5897] = "Das Ei ist etwa zwanzig Meter hoch, völlig glatt",
  [5898] = "und grau angestrichen.*",
  [5899] = "\"Willkommen, willkommen, willkommen!\" flötet die",
  [5900] = "Roboter-Stimme von irgendwoher in herzlichen",
  [5901] = "Tönen. \"Wir stehen Ihnen mit unserer ganzen Kraft",
  [5902] = "zur Verfügung! Bitte setzen Sie sich ans Terminal,",
  [5903] = "und beginnen Sie mit Ihren Fragen!\"*",
  [5904] = "Willkommen beim Info-Service. Bitte geben Sie",
  [5905] = "jeweils ein einzelnes Stichwort ein, über das Sie",
  [5906] = "Informationen wünschen. Wenn Sie den Info-Service",
  [5907] = "beenden wollen, geben Sie \"logout\" ein.*",
  [5908] = "Das Historische Museum liegt im Elften Bezirk.",
  [5909] = "Dort finden Sie archäologische Sammlungen, Relikte",
  [5910] = "aus alten Kulturen, und die einmalige Möglichkeit,",
  [5911] = "bestimmte, freigegebene Artefakte aus dem Archiv",
  [5912] = "anzufordern.*",
  [5913] = "Der Infoservice ist eine Institution, die für",
  [5914] = "eventuelle Besucher der USA eingerichtet wurde. Es",
  [5915] = "wurde kurz vor Ausbruch der Katastrophe errechnet,",
  [5916] = "daß in entlegenen Gegenden der Erde etliche",
  [5917] = "Personen überleben könnten. Der Infoservice soll",
  [5918] = "diesen Personen dienen, falls Sie jemals in die",
  [5919] = "USA gelangen. Sollten unsere Meßstellen ein",
  [5920] = "Anwachsen der Bevölkerung auf über eine Million",
  [5921] = "feststellen, werden die Städte wieder geöffnet.*",
  [5922] = "Die Große Katastrophe machte den größten Teil der",
  [5923] = "Erde unbewohnbar durch harte Partikelstrahlung der",
  [5924] = "Sonne. Innerhalb eines Monats war fast die ganze",
  [5925] = "Weltbevölkerung ausgelöscht.*",
  [5926] = "Zu Beginn des 33. Jahrhunderts baute ein großer",
  [5927] = "Fast-Food-Hersteller eine Plattform, die um Sonne",
  [5928] = "kreiste, um die Hamburger schneller grillen zu",
  [5929] = "können. Dabei geschah ein Unfall. Innerhalb eines",
  [5930] = "halben Jahres machte die Sonne eine Entwicklung",
  [5931] = "durch, für die sie normalerweise drei bis vier",
  [5932] = "Milliarden Jahre benötigen würde. Sie blähte sich",
  [5933] = "zu einem Roten Riesen auf, und in kurzer Zeit",
  [5934] = "zerstörte sie den natürlichen Strahlenschutzmantel",
  [5935] = "um die Erde. Er baute sich erst nach über",
  [5936] = "eintausend Jahren teilweise wieder auf.*",
  [5937] = "Das historische Museum stellt zur Zeit eine ganze",
  [5938] = "Reihe von Artefakten zur Verfügung, um die",
  [5939] = "übermäßig großen Bestände zu reduzieren. Sie",
  [5940] = "benötigen jedoch, um hier, vom Inforservice, eine",
  [5941] = "Ausgabebestätigung zu erhalten, das Kennwort des",
  [5942] = "gewünschten Artefaktes.*",
  [5943] = "Dies ist das Kennwort für ein Artefakt mit dem",
  [5944] = "Namen \"Edelsteinsplitter vom Auge des Kal\". Der",
  [5945] = "Ausgabecode lautet: 661.*",
  [5946] = "Das SRT ist ein unterirdisches Roboter-Taxi.*",
  [5947] = "Über Boston befindet sich noch immer eines der",
  [5948] = "Löcher im Strahlenschutzgürtel der Erde. So ist es",
  [5949] = "mit den meisten Städten.*",
  [5950] = "Chicago ist von Baltimore aus gesehen die nächste",
  [5951] = "bewohnbare Stadt. Auch dort gibt es einen Info-",
  [5952] = "Service. Allerdings zählt Chicago zu einem anderen",
  [5953] = "Staat.*",
  [5954] = "Verschiede Teile des Computersystems sind im Laufe",
  [5955] = "der Zeiten schadhaft geworden. Sollten Sie",
  [5956] = "Probleme haben, helfen nur Tricks weiter. Die",
  [5957] = "Lifts sind allerdings leicht zu beeinflussen.",
  [5958] = "Einem Lift, der die Beförderung verweigert, kann",
  [5959] = "man zumeist mit Schmeicheleinen wie \"Schätzchen\"",
  [5960] = "beikommen. Probieren Sie auch Worte wie:",
  [5961] = "\"Herzchen, Schnuckiputzi oder ähnliches!\"*",
  [5962] = "Für dieses Stichwort ist leider keine Information",
  [5963] = "verfügbar. (Beenden des Info-Service-Programms mit",
  [5964] = ">logout).*",
  [5965] = "Info-Service-Programm beendet.*",
  [5966] = "Als sich die Türe des SRT öffnet, flutet helles,",
  [5967] = "rötliches Sonnenlicht herein. Es ist bereits",
  [5968] = "Nachmittag. Durch den Einstieg sieht man ein",
  [5969] = "Schild: 'City'.*",
  [5970] = "10. Bezirk SRT-Station",
  [5971] = "Ein Subway-Robot-Taxi steht bereit. Die",
  [5972] = "Einstiegsluke ist geöffnet. Richtung Westen geht",
  [5973] = "es hinaus auf einen großen Platz.*",
  [5974] = "Neben dem Taxi steht reglos ein kleiner Putzrobo.*",
  [5975] = "Es ist ein ganz gewöhnlicher, kleiner Putzrobo. Er",
  [5976] = "trägt die Nummer 2461.*",
  [5977] = "Mit ein paar Piepsern erwacht der Putzrobo zum",
  [5978] = "Leben. \"Sie hatten Glück, Sir, Ihre Codecard noch",
  [5979] = "zu bekommen!\" sagt er. \"Die Luft über der Stadt",
  [5980] = "ist schon abgesaugt!\" Dann klickt er ein paarmal.",
  [5981] = "\"Sir, bevor sich dieser schwarze Roboss selbst",
  [5982] = "wieder repariert hat - habe ich habe einen",
  [5983] = "Sonderauftrag zu erfüllen! Bitte geben Sie kurz",
  [5984] = "mir Ihre Codecard!\"*",
  [5985] = "\"Danke, Sir!\" quäkt der kleine Kerl und steckt",
  [5986] = "sich die Codecard in einen Schlitz auf der",
  [5987] = "Vorderseite.*",
  [5988] = "\"Ich kann Ihnen auf Ihrer Codecard den Code für",
  [5989] = "die Zentrale des Infoservice abspeichern. Aber das",
  [5990] = "darf ich nur, wenn Sie beweisen können, daß Sie",
  [5991] = "der richtige Mann sind! Sie müssen mir zuvor den",
  [5992] = "Vornamen der Mutter von Harold Jugger nennen!*",
  [5993] = "\"EMILY - ja, das ist der richtige Name!\" quiekt",
  [5994] = "der kleine Putzrobo erleichtert. \"Fein, toll! Sie",
  [5995] = "werden uns sicher eines Tages endgültig von diesem",
  [5996] = "Schwarzen Idioten befreien, stimmt's, Sir? Nun -",
  [5997] = "hier ist Ihre Codecard wieder - sie können nun",
  [5998] = "damit die Zentrale des Infoservice betreten. Viel",
  [5999] = "Glück, Sir!\" Er hält Ihnen Ihre Codecard hin.*",
  [6000] = "\"Nein - das ist falsch! Wissen Sie es wirklich",
  [6001] = "nicht, Sir? Nennen Sie mir den richtigen Namen!\"*",
  [6002] = "Der Putzrobo piepst ein paarmal, dann frieren",
  [6003] = "seine Bewegungen ein. Es war wohl der falsche",
  [6004] = "Name, und er hat sich abgeschaltet - nein,",
  [6005] = "offenbar nicht ganz. Immerhin leuchtet ein kleines",
  [6006] = "Licht auf seiner Vorderseite auf: \"STANDBY\".*",
  [6007] = "Eine automatische Glastür schiebt sich auf, und",
  [6008] = "gibt den Weg frei. Lautlos schließt sie sich",
  [6009] = "hinter Ihnen wieder.*",
  [6010] = "Die automatische Glastür ist blockiert, denn",
  [6011] = "draußen, in der Stadt, gibt es für die nächsten",
  [6012] = "sechs Wochen keine Atemluft mehr!*",
  [6013] = "Im Stadtzentrum",
  [6014] = "Dies ist ein großer, ovaler Platz, von dem aus",
  [6015] = "nach Norden, Süden und Westen breite Straßen",
  [6016] = "wegführen. Sie sind jedoch mit großen Absperrungen",
  [6017] = "versehen. Östlich liegt der Eingang zur SRT-",
  [6018] = "Station. Der Platz ist von ultramodernen, riesigen",
  [6019] = "Gebäuden umgeben; in der Mitte liegt ein großer,",
  [6020] = "futuristischer Springbrunnen.*",
  [6021] = "Gute zwei Dutzend Roboter flitzen geschäftig auf",
  [6022] = "dem Platz hin und her.*",
  [6023] = "Es sind vier Gebäude, die um den Platz herum",
  [6024] = "stehen. Scheunentorgroße Hausnummern prangen",
  [6025] = "farbenfroh auf den weißen Fassaden, die",
  [6026] = "himmelwärts streben.*",
  [6027] = "Der Springbrunnen nicht in Betrieb. Er liegt ein",
  [6028] = "paar Stufen tiefer als der Platz, besitzt ein",
  [6029] = "flaches, gepflastetes Becken, und eine Serie von",
  [6030] = "konzentrisch angeordneten Wasserdüsen.*",
  [6031] = "Aus den Düsen des Springbrunnens schießen hohe",
  [6032] = "Fontänen, die sich nach einem komplizierten Muster",
  [6033] = "hoch über dem Platz treffen, und eine im grellen,",
  [6034] = "rötlichen Nachmittagslicht schillernde Kaskade von",
  [6035] = "Wasserstrahlen herabsinken lassen.*",
  [6036] = "Sie sind konzentrisch und teilweise in Gruppen",
  [6037] = "angeordnet. Neben der Gruppe, die Ihnen am",
  [6038] = "nächsten ist, befindet sich ein Sockel, auf dem",
  [6039] = "ein kleiner Kasten festgeschraubt ist.*",
  [6040] = "Es sieht aus wie ein Schaltkasten. Man",
  [6041] = "kann ihn auf- und zumachen.*",
  [6042] = " *",
  [6043] = " *",
  [6044] = "In dem Kasten befindet sich ein Schalter.*",
  [6045] = "Ist das Ihr Ernst? Wer weiß, was dann passiert?*",
  [6046] = "Irgendetwas beginnt zu rumoren, zu rattern und zu",
  [6047] = "spotzen, dann schießen plötzlich starke",
  [6048] = "Wasserstrahlen aus den Düsen: Sie haben den",
  [6049] = "Springbrunnen eingeschaltet!*",
  [6050] = "Das Geräusch der unterirdischen Turbinen",
  [6051] = "verstummt, und im nächsten Moment versiegen auch",
  [6052] = "die Fontänen. Der Springbrunnen ist wieder aus.*",
  [6053] = "Tja, das ist vielleicht auch besser so. Es könnte",
  [6054] = "ja die geheime HEXUMA-Erdbebenmaschine auslösen.",
  [6055] = "Das wäre fatal!*",
  [6056] = "Die Roboter sind sehr beschäftigt. Einige kehren",
  [6057] = "das Pflaster, andere putzen Fensterscheiben,",
  [6058] = "wieder andere fahren Müll davon.",
  [6059] = "Ein einzelner, schwarz lackierter Roboss steht",
  [6060] = "regungslos dort drüben, am westlichen Ende des",
  [6061] = "Platzes, bei einem kleinen Automaten, und fixiert",
  [6062] = "Sie mit seinen Videoaugen.*",
  [6063] = "Er ist ähnlich konstruiert wie die anderen",
  [6064] = "Roboter: tonnenförmiger Korpus, hydraulisches",
  [6065] = "Fahrgestell, ein Multifunktionsarm und ein",
  [6066] = "kuppelförmiger Kopf. Aber außer dem schwarzen Lack",
  [6067] = "gibt es da aber noch einen Unterschied... er",
  [6068] = "besitzt nicht nur zwei, sondern DREI Videoaugen!*",
  [6069] = "Hier geht es leider nicht weiter. Die Straßen sind",
  [6070] = "mit großen Absperrungen verbarrikadiert.*",
  [6071] = "Er steht, westlich von Ihnen, ein Stück entfernt.",
  [6072] = "Gehen Sie doch hin!*",
  [6073] = "Westende des Platzes",
  [6074] = "Hier ist der Weg weiter nach Westen durch eine der",
  [6075] = "Absperrungen blockiert. In der Nähe steht ein",
  [6076] = "kleiner Automat.*",
  [6077] = "Vor dem Automat steht ein schwarzer Roboss. Er",
  [6078] = "fixiert Sie kalt mit seinen Videoaugen.*",
  [6079] = "Es ist eine Absperrung aus Holzbalken. Sie muß",
  [6080] = "sich schon lange hier befinden, an ihrem Fuß hat",
  [6081] = "sich eine Menge Flugsand angesammelt.*",
  [6082] = "Da ist nichts Besonderes dran. Es ist einfach nur",
  [6083] = "feiner Sand.*",
  [6084] = "Er sieht aus wie ein kleiner Fahrkartenautomat...",
  [6085] = "Ah! Vorn drauf ist ein buntes Werbeschild",
  [6086] = "angebracht: 'Stadtbesichtigungen - Informationen -",
  [6087] = "Sonderausweise'. Darunter befindet sich",
  [6088] = "Lautsprecher, ein Mikrophon und ein Knopf.*",
  [6089] = "Über dem Knopf leuchtet ein Lämpchen rhythmisch",
  [6090] = "auf: \"Betriebsbereit\".*",
  [6091] = "\"Baby, Baby, Baby! Ist ja stark, wie Du den Roboss",
  [6092] = "kleingekriegt hast! Der verdammte Sonderausweis",
  [6093] = "muß Dir ja super-hyper-monster-wichtig sein, was?\"",
  [6094] = "Aus einem Schlitz an der Vorderseite schiebt sich",
  [6095] = "eine Codecard. \"Hier hast Du ihn, Kumpel! Und",
  [6096] = "jetzt verdufte, denn gleich gibt es hier nichts",
  [6097] = "mehr zu atmen, verstehst Du?\"*",
  [6098] = "Der Schlitz ist blockiert.*",
  [6099] = "\"Oh! Mann, hey, Mann, hey, Baby... das hab ich ja",
  [6100] = "völlig vergessen!\" krächzt die Roboterstimme aus",
  [6101] = "dem Automaten. \"Schnell! Gib mir nochmal die",
  [6102] = "Codecard!\"*",
  [6103] = "Der Schlitz saugt Ihre Codecard ein...*",
  [6104] = "... es rattert und knattert und knistert und äh...",
  [6105] = "mhrgftistert....*",
  [6106] = "... und spuckt Ihre Codecard wieder aus!*",
  [6107] = "Die Codecard ist aus Plastik und hat einen",
  [6108] = "Magnetstreifen. Da steht: \"Vergessen Sie nicht,",
  [6109] = "vom Ausgabeautomaten auf dem Magnetstreifen den",
  [6110] = "Zutritts-Code für Ihr Besuchs-Ziel abspeichern zu",
  [6111] = "lassen! Wir wünschen einen angenehmen Aufenthalt",
  [6112] = "in Baltimore.\"*",
  [6113] = "Plötzlich ertönt eine laute Stimme auf dem Platz",
  [6114] = "\"Information an alle Sauerstoff-Atmer! In wenigen",
  [6115] = "Augenblicken werden die Luftaustausch-Anlagen der",
  [6116] = "Stadt aktiviert! Begeben Sie sich bitte sofort in",
  [6117] = "Sicherheit!\"*",
  [6118] = "Eine Warnsirene beginnt zu blöken. \"An alle",
  [6119] = "Sauerstoff-Atmer! Begeben Sie sich sofort in",
  [6120] = "Sicherheit!\"*",
  [6121] = "\"Letzter Aufruf! Begeben Sie sich sofort in",
  [6122] = "Sicherheit!\"*",
  [6123] = "Plötzlich ertönt ein gewaltiges Rauschen über der",
  [6124] = "Stadt. Die Düsen der Luftaustauscher saugen die",
  [6125] = "Luft ein... immer mehr... der Sauerstoff",
  [6126] = "schwindet...*",
  [6127] = "... die Atemluft wird knapper und knapper...*",
  [6128] = "... urks... schnell... gleich ist es aus...*",
  [6129] = "... ppppfffffff.......*",
  [6130] = "\"Halt, Sir!\" schnarrt eine metallische Stimme. Es",
  [6131] = "ist der schwarze Roboss, der vor dem Automaten",
  [6132] = "steht. \"Hier können Sie nicht hin, Sir!\" Er fährt",
  [6133] = "abwehrend seinen Multifunktionsarm aus. \"Der",
  [6134] = "Automat ist, äh... kaputt!\"*",
  [6135] = "Der schwarze Roboter lässt Sie nicht passieren. Er",
  [6136] = "hat seinen Multifunktionsarm drohend erhoben.*",
  [6137] = "Der Roboss kommt angerollt, und stellt sich vor",
  [6138] = "den Automaten. \"Das Gerät ist KAPUTT!\" knirscht es",
  [6139] = "wütend aus seinem Lautsprecher.*",
  [6140] = "Das ist seltsam... Videoaugen sind gewöhnlich",
  [6141] = "etwas Technisches, ganz leblos und ohne Ausdruck.",
  [6142] = "Aber aus den drei Augen dieses Roboters scheint",
  [6143] = "soetwas wie Haß und Mißgunst zu funkeln...*",
  [6144] = "Hmpf. Dieser Multifunktionsarm ist so anziehend",
  [6145] = "wie ein Zahnarztbohrer. Und wahrscheinlich zehnmal",
  [6146] = "so gefährlich.*",
  [6147] = "Die drei Videoaugen des schwarzen Roboss'",
  [6148] = "verdrehen sich entsetzt, als er Ihren Wassereimer",
  [6149] = "nahen sieht! Doch dann ist es auch schon zu",
  [6150] = "spät... er vergeht in einer Kaskade von bläulichen",
  [6151] = "Blitzen, Entladungen und Kurzschlüssen!*",
  [6152] = "Der schwarze Roboss ist nur noch ein kümmerlicher",
  [6153] = "Haufen von wertlosem Schrott.*",
  [6154] = "Ein kleiner Putzrobo mit der Nummer 2461 rattert",
  [6155] = "an Ihnen vorüber. \"Dem ist eine Spule",
  [6156] = "durchgebrannt!\" zischt er Ihnen im Vorbeifahren",
  [6157] = "zu. \"Da kann man nichts machen!\"*",
  [6158] = "Der kleine Putzrobo 2461 steht drüben vor dem",
  [6159] = "Springbrunnen, und stellt einen Blecheimer ab. Er",
  [6160] = "beginnt, ein Häufchen Schmutz aufzukehren, und ihn",
  [6161] = "in den Eimer zu füllen. Dann nimm er den Eimer und",
  [6162] = "rattert wieder davon.*",
  [6163] = "Der kleine Putzrobo 2461 fährt in die Nähe eines",
  [6164] = "der Gebäude, und stellt einen Blecheimer ab. Er",
  [6165] = "beginnt, ein Häufchen Schmutz aufzukehren, und ihn",
  [6166] = "in den Eimer zu füllen. Dann nimmt er den Eimer",
  [6167] = "und rattert wieder davon.*",
  [6168] = "Wiedermal hat der kleine Putzrobo 2461 Schmutz",
  [6169] = "endeckt. Er fährt hin, stellt seinen Blecheimer",
  [6170] = "ab, kehrt den Schmutz auf und füllt ihn hinein.",
  [6171] = "Dann rattert er mit seinem Eimer wieder davon.*",
  [6172] = "Kaum liegt der Sand auf dem Boden, kommt der",
  [6173] = "Putzrobo angerattert. Er stellt seinen Blecheimer",
  [6174] = "auf den Boden, und schickt sich an, den Sand",
  [6175] = "aufzukehren.*",
  [6176] = "Oh, hoffentlich... nein, der kleine Putzrobo tut",
  [6177] = "Ihnen nichts. Er rattert davon, und taucht bald",
  [6178] = "wieder auf, mit einem neuen Eimer.*",
  [6179] = "Es ist ein einfacher Eimer aus Blech.*",
  [6180] = "Der Putzrobo füllt den Sand in seinen Eimer, nimmt",
  [6181] = "diesen auf, und fährt davon.*",
  [6182] = "Sie haben doch schon einen! Lassen Sie diesen doch",
  [6183] = "dem kleinen Putzrobo. Es ist sein letzter!*",
  [6184] = "Der schwarze Roboss kommt übellaunig auf Sie",
  [6185] = "zugerattert. \"Verdammt, was soll denn das!\"",
  [6186] = "knattert sein Lautsprecher wütend. \"Schalten Sie",
  [6187] = "sofort den Springbrunnen wieder aus!\"*",
  [6188] = "Ihre Maßnahme scheint den Roboss zu befriedigen.",
  [6189] = "Kaum ist der Springbrunnen aus, rollt er wieder an",
  [6190] = "seinen alten Standort, und verharrt dort.*",
  [6191] = "Der Roboss fährt erzürnt hinter Ihnen her, und",
  [6192] = "fuchtelt mit seinen Multifunktionsarmen.*",
  [6193] = "Der schwarze Roboss verfolgt Sie weiterhin.*",
  [6194] = "Der Roboss macht plötzlich eine scharfe Wendung,",
  [6195] = "fährt zu dem Kästchen, und drückt grimmig auf den",
  [6196] = "Knopf. Als der Springbrunnen wieder versiegt ist,",
  [6197] = "fährt er zuück zu seinem alten Standort, beim",
  [6198] = "Automaten.*",
  [6199] = "Im Springbrunnen",
  [6200] = "Das gepflasterte Becken des Springbrunnens liegt",
  [6201] = "ein paar Stufen tiefer als der Platz. Hier gibt es",
  [6202] = "eine Serie von konzentrisch angeordneten",
  [6203] = "Wasserdüsen.*",
  [6204] = "Hier steht ein Eimer.*",
  [6205] = "Er ist voll Wasser.*",
  [6206] = "Aus den Düsen schießen schillernde Wasserfontänen",
  [6207] = "hoch. Keine fünf Sekunden vergehen, bis Sie",
  [6208] = "patschnaß sind!*",
  [6209] = "Ohweh - der Roboss folgt Ihnen sogar hierher! Aber",
  [6210] = "kaum fährt er durch die Wasserstrahlen, kracht und",
  [6211] = "knirscht es fürchterlich in seinem Inneren, ein",
  [6212] = "Kurzschluß folgt auf den anderen! In einer",
  [6213] = "letzten, fürchterlichen Entladung zuckt ein",
  [6214] = "weißblauer Blitz aus seinem Korpus... oh nein...",
  [6215] = "das viele Wasser... das leitet doch Strom....",
  [6216] = "aaahhhhrrrgggg!!!*",
  [6217] = "11. Bezirk Historisches Museum",
  [6218] = "An einen kurzen Gang, der von hier nach Süden",
  [6219] = "führt, schließt sich eine weite Halle an.",
  [6220] = "Spärliches Licht dringt aus einer Reihe von",
  [6221] = "schwachen Lampen an der Decke. Ein großes Schild",
  [6222] = "hängt herab: \"Historisches Museum Baltimore\".",
  [6223] = "Darunter befindet sich noch eine kleine Tafel.*",
  [6224] = "Da steht. \"Verehrte Besucher! Wegen Energie-",
  [6225] = "Sparmaßnahmen ist der größte Teil des Museums",
  [6226] = "derzeit geschlossen. Sie können nur die Große",
  [6227] = "Historische Halle besichtigen, in der Sie sich",
  [6228] = "jetzt befinden. Wir bitten um Verständnis.\"*",
  [6229] = "Nordende der Halle",
  [6230] = "Drei Lampen hoch oben an der weit entfernten",
  [6231] = "Decke beleuchten einen düstern Schauplatz:",
  [6232] = "die Halle ist langgestreckt und schmal, sie führt",
  [6233] = "nach Norden. Beide Wände, die westliche wie die",
  [6234] = "östliche, sind glasverkleidet; hinter den riesigen",
  [6235] = "Scheiben sind die Szenen Eins und Zwei aus der",
  [6236] = "Vergangenheit dieser Welt dargestellt.*",
  [6237] = "Es handelt sich um zwei große Szenen. Welche",
  [6238] = "möchten Sie sich ansehen? Die Szene Eins oder die",
  [6239] = "Szene Zwei?*",
  [6240] = "Ein Schild informiert über das Zeitalter: Urzeit:",
  [6241] = "130 Mill.- 50.000 Jahre vor unserer Zeitrechnung.",
  [6242] = "Da sind zwei gigantische, kämpfende Dinosaurier",
  [6243] = "aufgebaut; riesige Schachtelhalme und Farne recken",
  [6244] = "sich hoch in die Luft; vor einer Höhle sitzen",
  [6245] = "Urweltmenschen um ein karges Feuer herum; einer",
  [6246] = "von Ihnen beschäftigt sich damit, etwas an die",
  [6247] = "Felsen zu malen.*",
  [6248] = "Näheres über diese Dinge könnte man in anderen",
  [6249] = "Teilen dieses Museums erfahren, nur leider sind",
  [6250] = "sie derzeit geschlossen.*",
  [6251] = "Die Dinosaurier sind schwergewichtige, riesige",
  [6252] = "Wesen; wie man weiß, sind viele Skelette von Ihnen",
  [6253] = "erhalten geblieben, weil sie wegen Ihres Gewichtes",
  [6254] = "in den zahlreichen Sümpfen der Urzeit einsanken,",
  [6255] = "und dort konserviert wurden.*",
  [6256] = "Der Urweltmensch malt gerade so etwas wie eine",
  [6257] = "sechseckige Form - ein Hexagon - an die",
  [6258] = "Höhlenwand. Erstaunlich, so etwas sollte damals",
  [6259] = "eigentlich noch ziemlich unbekannt gewesen sein!*",
  [6260] = "Es erinnert unwillkürlich an die Form des großen",
  [6261] = "Edelsteins, den Sie suchen. In der Mitte ist etwas",
  [6262] = "abgebildet... nun, man könnte sagen, es ist der",
  [6263] = "Buchstabe L.*",
  [6264] = "Hier wird klar, daß dieses Museum einzigartig sein",
  [6265] = "muß: hinter der Scheibe ist die Erde dargestellt,",
  [6266] = "wie sie während einer der großen Eiszeiten",
  [6267] = "ausgesehen haben muß! Titanische Gletscher",
  [6268] = "überspannen ganze Gebirgszüge. Eis und Schnee,",
  [6269] = "wohin das Auge blickt; Herden von Mammuts stapfen",
  [6270] = "durch die kalte und schweigende Welt, riesige",
  [6271] = "Polarbären sind auf Fischfang.*",
  [6272] = "Im Schnee sieht man die riesigen Fußabdrücke der",
  [6273] = "Mammuts.*",
  [6274] = "Kurios! Sie haben zufällig die Form des",
  [6275] = "Buchstabens H ergeben!*",
  [6276] = "Es handelt sich um ungewöhnlich große Tiere, wie",
  [6277] = "es sie wohl zu diesen Zeiten der Erdgeschichte",
  [6278] = "gab. Ein Mensch hätte wohl nicht den Hauch einer",
  [6279] = "Chance gegen so einen Riesen gehabt, und an die",
  [6280] = "einzige Waffe, die er vielleicht hätte benutzen",
  [6281] = "können, wäre hier, in dieser Kälte, nicht zu",
  [6282] = "denken - das Feuer.*",
  [6283] = "In der Hallenmitte",
  [6284] = "Auch hier, in der Mitte der Halle, sind die Wände",
  [6285] = "glasverkleidet - dahinter sind die Szenen Drei und",
  [6286] = "Vier aufgebaut. Es herrscht trübes Licht.*",
  [6287] = "Welche davon wollen Sie sich anschauen, die Szene",
  [6288] = "Drei oder die Szene Vier?*",
  [6289] = "Dies ist die großartige Rekonstruktion eines",
  [6290] = "Seegefechts. Auf dem Schild steht: \"Historische",
  [6291] = "Seeschlacht - 16. Jahrhundert.\" Das Meer ist",
  [6292] = "aufgewühlt von den Einschlägen der Kugeln -",
  [6293] = "Matrosen tummeln sich um riesige, gußeiserne",
  [6294] = "Kanonen, Kapitäne drohen dem Feind mit erhobenen",
  [6295] = "Säbeln. Alles ist eingehüllt in den beißenden",
  [6296] = "Pulverqualm des Gefechtes.*",
  [6297] = "Viele der Dinge sind nur Dekoration, andere lassen",
  [6298] = "nähere Aufschlüsse missen - die man wohl in den",
  [6299] = "anderen Abteilungen dieses Museums finden könnte.",
  [6300] = "Leider aber ist derzeit nur diese Halle geöffnet.*",
  [6301] = "Die Matrosen auf den großen Seglern dieser Zeit",
  [6302] = "waren nur selten mehr als Kanonenfutter. Drohte",
  [6303] = "einem Segler im Gefecht der Untergang, half ihnen",
  [6304] = "oft nur noch ein letzter Sprung über Bord, und die",
  [6305] = "Hoffnung, den Haifischen mit Hilfe eines kleinen",
  [6306] = "Floßes zu entkommen. Letztlich verhungerten viele",
  [6307] = "auf einsamen Inseln, selbst wenn sie in der",
  [6308] = "Seeschlacht mit dem Leben davongekommen waren.*",
  [6309] = "Sehr schön ist hier eine volle Breitseite",
  [6310] = "dargestellt, die von einem Kriegsschiff abgefeuert",
  [6311] = "wird - die Kugeln schneiden in einem regelrechten",
  [6312] = "Geschwader durch die Luft auf das feindliche",
  [6313] = "Schiff zu.*",
  [6314] = "Sie haben eine enorme Beobachtungsgabe. Das",
  [6315] = "Geschwader dieser Kugeln, wie sie durch die Luft",
  [6316] = "pfeifen, ergibt, von einem günstigen Standpunkt",
  [6317] = "aus gesehen, den Buchstaben A!*",
  [6318] = "Hier ist eine ungewöhnliche Szene dargestellt -",
  [6319] = "ah! Der Titel lautet: \"Das Zeitalter der",
  [6320] = "Abenteurer\". Auf einem einsamen Hügel ist ein",
  [6321] = "altes Haus dargestellt, das in einem Garten voller",
  [6322] = "verkrüppelter und verwachsener Bäume und Büsche",
  [6323] = "steht. Die Athmosphäre ist düster, aus dem Haus",
  [6324] = "spricht etwas Gespenstisches, Unheilvolles!*",
  [6325] = "Nun - wenn nicht alles täuscht, dann handelt es",
  [6326] = "sich hier um das alte Hawthorne-Haus, das einsam",
  [6327] = "und verlassen auf dem Lone Hill steht.*",
  [6328] = "Der Lone Hill ist nur der Teil einer ungefügen",
  [6329] = "Hügellandschaft, die sich schroff und unzugänglich",
  [6330] = "in die Ferne erstreckt. Das Wetter hat man, gemäß",
  [6331] = "der gespenstischen Athmosphäre, entsprechend",
  [6332] = "schlecht dagestellt. Im Hintergrund der Szene",
  [6333] = "zucken einige gemalte Blitze aus dem Himmel",
  [6334] = "herab.*",
  [6335] = "Nun - was soll es an gemalten Blitzen schon",
  [6336] = "Besonderes geben? Der eine hat eine Form wie",
  [6337] = "Dreizack, ein anderer sieht ähnlich dem Buchstaben",
  [6338] = "R aus...*",
  [6339] = "Die Bäume sind krumm und verwachsen, manche stehen",
  [6340] = "in einer gar grotesken Form da.*",
  [6341] = "Südende der Halle",
  [6342] = "Hier sind die letzten beiden der großartigen",
  [6343] = "Darstellungen hinter den Glaswänden zu bestaunen:",
  [6344] = "die Szenen Fünf und Sechs. In der Südlichen Wand",
  [6345] = "befindet sich eine große Türe, und daneben ist",
  [6346] = "ein größeres Terminal in der Wand eingebaut.*",
  [6347] = "Die Tür führt in die anderen Abteilungen des",
  [6348] = "Museums, leider ist sie verschlossen. Eine kleine",
  [6349] = "Tafel erklärt, daß dieser Teil des Museums zur",
  [6350] = "Zeit geschlossen ist.*",
  [6351] = "Das Terminal ist recht groß, sieht aber recht",
  [6352] = "gewöhnlich aus: Ein Lautsprecher, ein Mikrophon",
  [6353] = "und ein Knopf. Zusätzlich ist in der Wand noch",
  [6354] = "eine große Verkleidung eingebaut, die so etwas wie",
  [6355] = "einen Ausgabeschacht besitzt. Obendrüber steht:",
  [6356] = "\"Archiveinheit des HMB.\"*",
  [6357] = "Der Lautsprecher erwacht zum Leben. Eine kratzige",
  [6358] = "Roboterstimme ertönt: \"Wenn Sie hier was klauen",
  [6359] = "wollen, dann gehts Ihnen dreckig, verstanden?",
  [6360] = "Also los: Sie wollen bestimmt was haben! Nennen",
  [6361] = "Sie die Kennummer, dann will ich sehen, ob Sie's",
  [6362] = "kriegen oder nicht! Wie lautet sie?\"*",
  [6363] = "\"So eine Nummer kenne ich nicht!\" kreischt die",
  [6364] = "Roboterstimme wütend. \"Sie ist FALSCH! Sie sind",
  [6365] = "NICHT autorisiert! Verlassen Sie SOFORT das",
  [6366] = "Historische Museum! LOS, VERSCHWINDEN SIE! Sonst",
  [6367] = "passiert was!\"*",
  [6368] = "\"Diese Zahl ist korrekt,\" knirscht die",
  [6369] = "Roboterstimme. \"Wo haben Sie sie her? Geklaut,",
  [6370] = "was? Ach, kann mir ja wurscht sein! Hier haben Sie",
  [6371] = "den geforderten Gegenstand! Und jetzt: verduften",
  [6372] = "Sie! Kapiert?\" Es knirscht und funkt ein bißchen -",
  [6373] = "dann rumpelt es im Ausgabeschacht.*",
  [6374] = "Der Ausgabeschacht scheint dafür gedacht zu sein,",
  [6375] = "irgendwelche Gegenstände an Besucher auszugeben,",
  [6376] = "sozusagen.*",
  [6377] = "Ein Edelsteinsplitter von undefinierbarer Farbe",
  [6378] = "und Form liegt darin.*",
  [6379] = "Hier die Zukunft dargestellt: \"34. Jahrhundert,",
  [6380] = "Mechano-Kybernetische Ära.\" Da sind Heere von",
  [6381] = "Robotern zu sehen; automatische Fahrzeuge und",
  [6382] = "Maschinen erledigen die Versorgung. Fabriken",
  [6383] = "stellen Verbrauchsgüter her, die Menschen leben in",
  [6384] = "grenzenlosem Wohlstand. Eine Szene ist jedoch",
  [6385] = "nachträglich hinzu-improvisiert: der Zerstörung",
  [6386] = "der Sonne, und der Untergang der Menschheit!*",
  [6387] = "Wie kleine Heere sind die Roboter dort aufgebaut,",
  [6388] = "und marschieren; hier eine Hundertschaft für die",
  [6389] = "Müllbeseitigung, dort eine für Dienstleistungen,",
  [6390] = "und andere für Produktion, Verkehr oder",
  [6391] = "Vergnügungen.*",
  [6392] = "Seltsam - diese Hundertschaften scheinen mit",
  [6393] = "Absicht in einer bestimmten Form aufgebaut worden",
  [6394] = "zu sein: es sieht aus wie ein riesiges A.*",
  [6395] = "Der Wohlstand der Menschen hatte zu dieser Zeit",
  [6396] = "einen enormen Stand erreicht. Leider schon war er",
  [6397] = "zu hoch, denn sie wurden träge, und sahen nicht,",
  [6398] = "was kaum verborgen war, und fast offen vor Ihren",
  [6399] = "Augen lag: Die Lösung aller Probleme, die in den",
  [6400] = "Erfahrungen und offenen Hinweisen der Geschichte",
  [6401] = "der Menschheit zu finden ist!*",
  [6402] = "Die sechste und letzte Szene wirkt befremdlich.",
  [6403] = "Auf dem Schild steht: \"HEXUMA, das Zeitalter der",
  [6404] = "Legenden - keine Zeitangabe möglich.\" Ein",
  [6405] = "beängstigendes Inferno unterirdischen Landschaften",
  [6406] = "und groteskten Formen bietet sich dem Auge. Auf",
  [6407] = "einem Felsenthron hockt ein gräßliches,",
  [6408] = "sechsarmiges Tier, dessen leere Augenhöhle Sie",
  [6409] = "gespenstisch anglotzt.*",
  [6410] = "Um den Thron herum führen knochige, blaßhäutige",
  [6411] = "Wesen einen wilden Tanz auf, rechts steht ein",
  [6412] = "unförmiges Tentakelmonstrum; links eine",
  [6413] = "Frauengestalt, die die sagenumwobene Medusa zu",
  [6414] = "Tode erschrecken könnte. Die übrige Kulisse",
  [6415] = "besteht aus seltsam spitzen Tempelbauten, krank",
  [6416] = "aussehenden Pflanzen, und Tümpeln, die mit",
  [6417] = "gelblichem Schleim angefüllt sind.*",
  [6418] = "Das Tier ist unbeschreiblich widerlich",
  [6419] = "anzuschauen, auf seinem Thron steht das Wort",
  [6420] = "\"Kal\".*",
  [6421] = "Diese entsetzlichen Kreaturen spotten jedem",
  [6422] = "Versuch, sie mit Worten beschreiben zu wollen -",
  [6423] = "sie erwecken den Wunsch, niemals den Ort zu",
  [6424] = "betreten, wo sie leben.*",
  [6425] = "Das Monstrum schwingt seine Tentakel durch die",
  [6426] = "Lüfte, und eine symbolische Aussage scheint der",
  [6427] = "Buchstabe S zu haben, zu dessen Form sich die",
  [6428] = "Tentakel wieder und wieder finden.*",
  [6429] = "Ihr SRT wartet hier mit offener Einstiegsluke.*",
  [6430] = "Welche davon wollen Sie sich anschauen, die Szene",
  [6431] = "fünf oder sechs?*",
  [10001] = "Es dauert lange, bis Sie wieder stofflich werden.",
  [10002] = "Der erste Eindruck ist gnadenlose Hitze, grelle",
  [10003] = "Sonne, und ein stechend scharfer Geruch um Sie",
  [10004] = "her.*",
  [10005] = "Flußufer",
  [10006] = "Hier strömt ein breiter Fluß dahin. Die Gegend",
  [10007] = "besteht hauptsächlich aus Sand und Dünen. Etwas",
  [10008] = "nördlich steht ein einzelner Felsen am Uferrand;",
  [10009] = "westlich von Ihnen rauscht der Fluß vorbei. Hier",
  [10010] = "herrscht ein recht scharfer Geruch - er scheint",
  [10011] = "von einem... Fladen auszugehen, der nur wenige",
  [10012] = "Schritte entfernt den sandigen Boden ziert.*",
  [10013] = "Plötzlich dröhnt ein Grollen durch das Flußtal.",
  [10014] = "Der Boden erzittert, wie unter unglaublich",
  [10015] = "schweren Schritten, und dann... es ist kaum zu",
  [10016] = "fassen... eine Riesenechse, so hoch wie ein Haus,",
  [10017] = "stampft auf säulendicken Hinterläufen den",
  [10018] = "Dünenhang herab! Sie stößt ein ohrenzerreißendes",
  [10019] = "Brüllen aus, bewegt sich auf den einzelnen Felsen",
  [10020] = "am Flußufer zu, und baut sich dort auf.*",
  [10021] = "Die Riesenechse sieht dem König der Vorzeit, dem",
  [10022] = "Tyrannosaurus Rex, bedrückend ähnlich. Sie besitzt",
  [10023] = "stämmige Hinterläufe, verkrüppelte Ärmchen und",
  [10024] = "einen wohl an die fünf Meter langen Schwanz. In",
  [10025] = "das zähnestarrende Maul könnte man wohl ohne viel",
  [10026] = "Umstände einen Schubkarren hineinfahren. Das",
  [10027] = "Monstrum hat seine kleinen, bösen Augen direkt auf",
  [10028] = "Sie geheftet!*",
  [10029] = "Die kleinen Augen des Tyrannosaurus funkeln böse",
  [10030] = "und warnend. Sie signalisieren, daß der Spaß sehr",
  [10031] = "bald ein Ende haben könnte.*",
  [10032] = "Der riesige Fladen scheint zwar trocken und",
  [10033] = "bretthart zu sein, aber der Geruch ist noch immer",
  [10034] = "ziemlich scharf! Es muß sich um die... äh,",
  [10035] = "Hinterlassenschaft eines Brontosauriers handeln!*",
  [10036] = "Nicht doch - mit bloßen Händen! Schlimm genug, daß",
  [10037] = "dieses Zeug unser schönes Spiel verunziert - aber",
  [10038] = "wir wollen doch taktvoll, und den allgemeinen",
  [10039] = "Regeln der Ästhetik verbunden bleiben!*",
  [10040] = "Schauen Sie nur - sogar der schreckliche",
  [10041] = "Tyrannosaurus wahrt einen respektvollen Abstand",
  [10042] = "dazu!*",
  [10043] = "Puuh! Was haben Sie denn vor? Also wenn Sie",
  [10044] = "unbedingt wollen... mit der scharfen Schneide geht",
  [10045] = "das wohl... gut. Sie haben jetzt einen... hm,",
  [10046] = "einen Dungbrocken abgeschnitten. Er liegt neben",
  [10047] = "dem Fladen.*",
  [10048] = "Naja, das geht ja noch! Immerhin bleiben so die",
  [10049] = "Regeln der Ästhetik einigermaßen gewahrt. Okay,",
  [10050] = "Sie besitzen nun einen Dungbrocken, eingewickelt",
  [10051] = "in ein paar große Blätter. Was nun?*",
  [10052] = "Es handelt sich um einen ausgetrockneten, aber",
  [10053] = "immer noch recht würzig riechenden Dungbrocken,",
  [10054] = "der in ein paar Blätter eingewickelt ist.*",
  [10055] = "Hier herrscht ein Duft, den wir mal, um",
  [10056] = "angemessene Formen zu wahren, als herb-würzig",
  [10057] = "bezeichnen wollen. Immerhin scheint er allerlei",
  [10058] = "unliebsames Getier fernzuhalten.*",
  [10059] = "Der Felsen ist etwa sechs Meter hoch, oben flach,",
  [10060] = "und nur mäßig steil - man könnte sicher",
  [10061] = "hinaufklettern. Manchmal blitzt ein Sonnenstrahl",
  [10062] = "von dort oben herab, so als würde er von irgend",
  [10063] = "einem glatten Gegenstand reflektiert. Am Fuße des",
  [10064] = "Felsens, in einer schattigen Nische, liegen drei",
  [10065] = "ziemlich große, eiförmige Gebilde.*",
  [10066] = "Ein paar Geröllbrocken und niedrige Sträucher",
  [10067] = "versüßen nur unwesentlich den trostlosen Anblick",
  [10068] = "dieser Einöde.*",
  [10069] = "Dort, wo Sie Ihn hintragen könnten, gibt es genug",
  [10070] = "davon, also können Sie ihn auch gleich hierlassen.",
  [10071] = "Nicht wahr?*",
  [10072] = "Schwer zu beschreiben, von hier. Wiegesagt,",
  [10073] = "ziemlich groß, eiförmig und weiß, mit ein paar",
  [10074] = "blassblauen Tupfen darauf. Sie sehen tatsächlich",
  [10075] = "irgendwie aus, als wären sie Eier.*",
  [10076] = "Eine nähere Untersuchung vor Ort könnte Sie in",
  [10077] = "größere Verlegenheiten stürzen - es sei denn, Sie",
  [10078] = "wollten die Anwesenheit des Tyrannosaurus daselbst",
  [10079] = "bis zum eigenen, glorreichen Ende hinwegleugnen.*",
  [10080] = "Von Ihrer Bewegung aufgeschreckt, fährt der",
  [10081] = "massige Schädel der Riesenechse herum. Ein tiefes",
  [10082] = "Grollen erfüllt die Luft, die kleinen Augen",
  [10083] = "starren Sie mordlustig an.*",
  [10084] = "Die Riesenechse stößt ein markerschütterndes",
  [10085] = "Brüllen aus, und rast auf Sie los. Vorsicht ist",
  [10086] = "etwas anderes als Feigheit, wie man sagt... aber",
  [10087] = "Sie? Sie gehören wohl zu den ganz Mutigen, was?",
  [10088] = "Jetzt aber los... schnell... um Himmels Willen,",
  [10089] = "das Monstrum bewegt sich ja wie ein D-Zug...*",
  [10090] = "... ohgott... der Tyrannosaurus kommt mit Fünf-",
  [10091] = "Meter-Schritten auf Sie zu... schnell... weg",
  [10092] = "hier... schon schießt das geöffnete,",
  [10093] = "zähnestarrende Maul auf Sie zu......",
  [10094] = "ooouuuuaaaahhhhh......!!!*",
  [10095] = "Ein Findling, der aus dem Wasser herausschaut,",
  [10096] = "deutet darauf hin, daß der Fluß hier nicht sehr",
  [10097] = "tief ist. Noch weiter westlich liegt eine kleine",
  [10098] = "Sandbank im Wasser, auf der einige üppige Stauden",
  [10099] = "mit Bananen wachsen.*",
  [10100] = "Oje! Wer weiß, was da so alles an gräßlichem",
  [10101] = "Getier im Wasser lauert! Wollen Sie das wirklich",
  [10102] = "wagen?*",
  [10103] = "Nun denn, Sie Held! Dann los....*",
  [10104] = "Tja, möglicherweise ein lebensrettender",
  [10105] = "Entschluß!*",
  [10106] = "Flußmündung",
  [10107] = "Hier mündet der Fluß in ein größeres Gewässer -",
  [10108] = "schwer zu sagen, ob es ein riesiger See oder das",
  [10109] = "Meer ist. Im sandigen Boden sind riesige",
  [10110] = "Fußstapfen...*",
  [10111] = "Hier liegen ein paar Bananen herum.*",
  [10112] = "Es handelt sich, genauer gesagt, um die Kreide-",
  [10113] = "Zeit-Gegenstücke zu herkömmlichen Bananen: sie",
  [10114] = "sind orange-gelb, ziemlich klein und ziemlich",
  [10115] = "krumm. Sie sehen aber recht schmackhaft aus.*",
  [10116] = "In diesen riesigen Fußstapfen könnte man",
  [10117] = "problemlos ein Bad nehmen. Eine arme Pflanze wurde",
  [10118] = "niedergetreten - ihre breiten Blätter sind",
  [10119] = "plattgewalzt wie von einer Dampfwalze.*",
  [10120] = "Es handelt sich um große, breite Blätter, ähnlich",
  [10121] = "denen einer Bananenstaude.*",
  [10122] = "Oh! Nicht weit südlich von Ihnen, hinter einer",
  [10123] = "kleinen Düne, sucht ein riesiger Pflanzenfresser -",
  [10124] = "offenbar ein Brontosaurus - im flachen Wasser nach",
  [10125] = "Nahrung!*",
  [10126] = "Etwas östlich von hier kaut ein riesiger",
  [10127] = "Säbelzahntiger an Fleischfetzen seiner Beute - und",
  [10128] = "ist, Gottseidank, offenbar noch eine Weile",
  [10129] = "beschäftigt.*",
  [10130] = "Der Brontosaurus stampft gemächlich auf vier",
  [10131] = "riesigen Säulenbeinen durch den Sand - sein",
  [10132] = "kleiner Kopf, am Ende eines nicht enden wollenden",
  [10133] = "Halses, scheint immerzu, und oft vergeblich, nach",
  [10134] = "Fressbarem auf der Suche zu sein. Das Tier ist",
  [10135] = "gewaltig - vom Kopf bis zum Schwanzende wohl an",
  [10136] = "die 30 Meter!*",
  [10137] = "Das massige Schwanzende peitscht bisweilen hin und",
  [10138] = "her - zum Glück stehen Sie außer Reichweite.*",
  [10139] = "Der riesige Brontosaurus stampft herbei und",
  [10140] = "bemächtigt sich der Bananen, die Sie ihm",
  [10141] = "freundlicherweise kredenzt haben.*",
  [10142] = "Das allerdings passt dem Säbelzahntiger gar nicht!",
  [10143] = "Aber so streitbar er auch sein mag - vor dem",
  [10144] = "gigantischen Saurier ergreift er, mit einem",
  [10145] = "ärgerlichen Knurren, die Flucht! Sekunden später",
  [10146] = "schon ist er in der Ferne verschwunden.*",
  [10147] = "Auf der Landzunge",
  [10148] = "Sanfte Wellen plätschern an den Ufersand. Einige",
  [10149] = "riesige Fußstapfen zieren den sandigen Boden, hier",
  [10150] = "gibt es ringsum nur tieferes Wasser,",
  [10151] = "(sicherlich bevölkert von schrecklichem Getier);",
  [10152] = "der Weg führt nur zurück nach Norden, zur",
  [10153] = "Flußmündung.*",
  [10154] = "Sie befinden sich in gefährlicher Nähe zu dem",
  [10155] = "riesigen Brontosaurier! Um Himmels Willen... er",
  [10156] = "hat Sie bemerkt und wird unruhig...*",
  [10157] = "Das massige Schwanzende peitscht hin und her - und",
  [10158] = "kommt Ihnen gefährlich nahe! Geben Sie bloß acht!*",
  [10159] = "Vorsicht...! Gehen Sie weg daaaaaaaa.........!!!*",
  [10160] = "Auf der Düne",
  [10161] = "Hier wird der Weg weiter nach Osten von einer",
  [10162] = "unvermuteten Steilwand abgeschnitten. Man kann",
  [10163] = "nach Norden zu einem Farnwald gelangen oder nach",
  [10164] = "Süden in eine Steppenlandschaft. Wie sich zeigt,",
  [10165] = "tummelt sich so manch Getier in dieser Welt! Nach",
  [10166] = "Norden hin ist zwischen riesigen Farnsträucher",
  [10167] = "ein mächtiger Triceratops zu sehen.*",
  [10168] = "Weiter südlich hingegen labt sich ein großer",
  [10169] = "Säbelzahntiger an seiner Beute.*",
  [10170] = "Die Steilwand fällt nach Osten hin zwanzig Meter",
  [10171] = "senkrecht in die Tiefe ab. Es ist auch fraglich,",
  [10172] = "ob dort, in dieser Himmelsrichtung, ein",
  [10173] = "ersprießlicher Aufenthalt möglich wäre, denn von",
  [10174] = "hier aus ist nur ein weiter, sumpfiger Urwald zu",
  [10175] = "erblicken.*",
  [10176] = "Der Triceratops ist einer der klassischen",
  [10177] = "Vertreter der Gattung der Saurier: obwohl nur ein",
  [10178] = "Pflanzenfresser, sieht er mit seinem dreifachen",
  [10179] = "Gehörn sehr wehrhaft und furchteinflößend aus. Wie",
  [10180] = "man hört, spießt er damit am liebsten seinen",
  [10181] = "Erzfeind auf, den Tyrannosaurus Rex. Manchmal aber",
  [10182] = "auch ahnungslose Spaziergänger. Wie man hört.*",
  [10183] = "Die drei Hörner des Triceratops sind - nun, sagen",
  [10184] = "wir: je etwa drei Meter lang. Das dürfte reichen,",
  [10185] = "um jeglichem Störenfried in Sekundenschnelle das",
  [10186] = "Lebenslicht auszublasen.*",
  [10187] = "Das Wort sagt schon alles: ein Tiger mit großen,",
  [10188] = "säbelförmigen Zähnen. Allerdings ein ziemlich",
  [10189] = "großer. Momentan ist er noch mit dem Verspeisen",
  [10190] = "seiner Beute beschäftigt. Noch!*",
  [10191] = "Seine Beute muß vor kurzem noch so etwas wie ein",
  [10192] = "tonnenschwerer Büffel gewesen sein.*",
  [10193] = "Eine Laune der Natur, offenbar. Allerdings eine",
  [10194] = "sehr gefährliche. Man sollte dem Burschen besser",
  [10195] = "nicht zu nahe kommen.*",
  [10196] = "Im Farnwald",
  [10197] = "Hier, zwischen den riesigen, urzeitlichen",
  [10198] = "Farnsträuchern stampft ein vier Meter hoher",
  [10199] = "Triceratops umher... ohweh! Er hat Sie gesehen!",
  [10200] = "Schnell weg hier! Diese Viecher haben ein Gemüt",
  [10201] = "wie ein Nashorn...*",
  [10202] = "Die Farnsträucher sind so riesig und",
  [10203] = "weitausladend, wie sie vor 60 Millionen Jahren, in",
  [10204] = "der Kreidezeit, gewesen sein müssen...*",
  [10205] = "Das riesige Tier stößt ein ungemütliches Schnauben",
  [10206] = "aus, dreht sich in Ihre Richtung, und senkt",
  [10207] = "drohend den riesigen, dreifach gehörnten Schädel!*",
  [10208] = "... um Himmels Willen, warum verschwinden Sie denn",
  [10209] = "nicht...? Der Triceratops fühlt sich belästigt, er",
  [10210] = "senkt den Kopf und donnert auf Sie zu....",
  [10211] = "Hilfeeeee.....!!!*",
  [10212] = "Angelockt von dem scharfen Geruch des blutigen",
  [10213] = "Fleischbrockens, erscheint der Tyrannosaurus Rex",
  [10214] = "auf der Bildfläche... und steht unversehens seinem",
  [10215] = "Erzfeind, dem Triceratops gegenüber! Beide Saurier",
  [10216] = "verharren einen Moment, der wehrhafte Triceratops",
  [10217] = "bereitet sich auf einen Angriff vor, während sich",
  [10218] = "der Tyrannosaurus für die lohnendere Beute zu",
  [10219] = "entscheiden versucht. Dann ist es soweit:*",
  [10220] = "Mit zwei Schritten ist er über dem Triceratops,",
  [10221] = "und will ihn am Hals packen. Der aber ist an",
  [10222] = "dieser Stelle gut gepanzert. Im gleichen Moment",
  [10223] = "stößt er seinem Feind die Hörner in den weichen",
  [10224] = "Unterleib. Der Tyrannosaurus brüllt auf - das",
  [10225] = "Gefecht ist kurz. Der Tyrannosaurus schleppt sich",
  [10226] = "schwer verletzt davon - und der Triceratops läßt",
  [10227] = "sein Siegesgebrüll durch den Farnwald dröhnen.*",
  [10228] = "Auf der Steppe",
  [10229] = "Hier beginnt eine weite Steppenlandschaft, die",
  [10230] = "sich nach Ost und Süd erstreckt. Fahles Gras steht",
  [10231] = "in Büscheln umher - und hier beginnt auch das",
  [10232] = "Hoheitsgebiet der gefährlichen Säbelzahntiger.*",
  [10233] = "Ein besonders eindrucksvolles Exemplar ist auch",
  [10234] = "gleich anwesend: Er hebt den Kopf von seiner",
  [10235] = "Beute, und beäugt Sie mit einer Mischung von",
  [10236] = "Mißtrauen und Ärger in seinem Blick...*",
  [10237] = "Der Säbelzahntiger schickt Ihnen, offenbar als",
  [10238] = "dingende Warnung, ein heiseres Brüllen",
  [10239] = "entgegen...!*",
  [10240] = "... um Himmels Willen, warum verschwinden Sie denn",
  [10241] = "nicht...? Der Säbelzahntiger fühlt sich sehr",
  [10242] = "belästigt, springt mit einem Satz auf, und ist mit",
  [10243] = "dem nächsten über Ihnen....",
  [10244] = "Neeeiiiinnnnnn......!!!!*",
  [10245] = "In dieser Richtung sind Sie buchstäblich Freiwild",
  [10246] = "für die wilden Bewohner der Steppe: die",
  [10247] = "Säbelzahntiger! Gehen Sie dort lieber nicht hin!*",
  [10248] = "Es ist ein ziemlich großer Büffel, oder besser:",
  [10249] = "ein Vorfahr derselben. Sein Leben hat er schon",
  [10250] = "ausgehaucht - so ist der Lauf der Dinge, hier in",
  [10251] = "dieser rauhen Welt.*",
  [10252] = "Ein großer, losgerissener  Fleischbrocken liegt im",
  [10253] = "Sand.*",
  [10254] = "Haben Sie Hunger? Das Zeug dürfte in diesem",
  [10255] = "Zustand wohl nur einem Raubtier schmecken.*",
  [10256] = " *",
  [10257] = "Am Felsen",
  [10258] = "Der Felsen ist etwa sechs Meter hoch, oben flach,",
  [10259] = "und nur mäßig steil - man könnte sicher",
  [10260] = "hinaufklettern. Manchmal blitzt ein Sonnenstrahl",
  [10261] = "von dort oben herab, so als würde er von irgend",
  [10262] = "einem glatten Gegenstand reflektiert. Am Fuße des",
  [10263] = "Felsens, in einer schattigen Nische, liegen drei",
  [10264] = "große, eiförmige Gebilde.*",
  [10265] = "Hm. Aus der Nähe betrachtet, scheint es sich",
  [10266] = "tatsächlich um Eier zu handeln - bei der Größe",
  [10267] = "hingegen... oh! Es sind nur noch zwei. Das dritte",
  [10268] = "Ei ist keines mehr - dort liegen nur noch die",
  [10269] = "Schalen. Vermutlich ist dort vor kurzem etwas",
  [10270] = "Unangenehmes ausgeschlüpft!*",
  [10271] = "Hm - von hier aus ist nichts Genaues zu erkennen.",
  [10272] = "Vielleicht sollten Sie sich einmal dort hinauf",
  [10273] = "begeben?*",
  [10274] = "Die Schale ist recht dick und - nunja, aus Kalk,",
  [10275] = "wie ein Hühnerei.*",
  [10276] = "Auf dem Felsen",
  [10277] = "Von hier kann man gut die Landschaft überblicken.",
  [10278] = "Sollten Sie es noch immer nicht geglaubt haben:",
  [10279] = "dies ist tatsächlich die Kreidezeit! Am Horizont",
  [10280] = "rauchen Vulkane, die Wälder bestehen aus Farnen",
  [10281] = "und Schachtelhalmen, und allenthalben bewegen sich",
  [10282] = "riesige Saurier durch das Land.*",
  [10283] = "Hier oben sitzt ein kleines Saurierbaby.*",
  [10284] = "Hier liegt ein Edelsteinsplitter auf dem Boden.*",
  [10285] = "Nun, \"klein\" ist relativ. Mit Sicherheit ist die",
  [10286] = "Mama ein schrecklicher Tyrannosaurus, und so ist",
  [10287] = "dieses Saurierbaby beinahe so groß wie Sie!",
  [10288] = "Seltsam, daß es drei Augen besitzt! Aber zum Glück",
  [10289] = "hat es momentan noch nicht viel mit Jagd und",
  [10290] = "Beutereißen im Sinn. Sondern eher Unfug!*",
  [10291] = "Es scheint, als wäre der mißgünstige Blick, der",
  [10292] = "aus diesen drei Augen dringt, uns allen nicht",
  [10293] = "neu...*",
  [10294] = "Im Maul, zwischen seinen spitzen Zähnen, trägt es",
  [10295] = "einen Edelsteinsplitter von unbestimmbarer Farbe.*",
  [10296] = "Das Saurierbaby faucht ärgerlich und schnellt mit",
  [10297] = "einem Satz davon.*",
  [10298] = "Das kleine Mistviech ist so gewandt wie schlau!",
  [10299] = "Geschickt weicht es Ihrem Griff aus und springt",
  [10300] = "davon.*",
  [10301] = "Drohend zeigt das Saurierbaby die Zähne (ohne aber",
  [10302] = "dabei den Edelsteinsplitter fallen zu lassen), und",
  [10303] = "entwindet sich geschickt Ihrem Griff.*",
  [10304] = "Als das Saurierbaby die Monsterspinne erblickt,",
  [10305] = "erstarrt es vor Schreck! Während sich die Spinne",
  [10306] = "damit vergnügt, dem Saurierbaby drohende Gebärden",
  [10307] = "und tödliche Blicke zuzuwerfen, kullert ihm der",
  [10308] = "Edelsteinsplitter aus dem Maul, und fällt zu",
  [10309] = "Boden.*",
  [10310] = "Die Monsterspinne hebt drohend die Vorderbeine,",
  [10311] = "und knurrt das Saurierbaby an. Das ist zuviel für",
  [10312] = "die Echse! Mit ohnmächigem Schreck und unter",
  [10313] = "verzweifeltem Heulen dreht es sich um, und saust",
  [10314] = "davon!*",
  [10315] = "Ihr Abenteuer in dieser Welt ist zuende. Als Sie",
  [10316] = "den Splitter nehmen, verschwimmt alles um Sie",
  [10317] = "herum, und die geheimnisvolle Kraft reißt Sie",
  [10318] = "wieder mit sich...*",
  [10319] = "Im Uferbereich",
  [10320] = "Das Wasser ist hier glücklicherweise nur knietief",
  [10321] = "- aber der Weg bis zu dem Findling ist weit.",
  [10322] = "Das Ufer liegt zum Glück ein gutes Stück näher.",
  [10323] = "Oh nein... schon macht sich einer der Flußbewohner",
  [10324] = "bemerkbar: nicht weit von Ihnen teilt sich das",
  [10325] = "Wasser, und für einen Moment taucht eine große,",
  [10326] = "unangenehm stachlige Rückenflosse auf!*",
  [10327] = "Sie ist schon wieder weg, aber sie hatte ungefähr",
  [10328] = "die gleiche, alarmierende Aussagekraft, wie ein",
  [10329] = "halbes Dutzend Alligatoren, die sich ins Wasser",
  [10330] = "fallen lassen, und eine unmißverständliche",
  [10331] = "Richtung einschlagen - auf Sie zu!*",
  [10332] = "Im Fluß",
  [10333] = "Hier reicht das Wasser schon bis zur Brust, und",
  [10334] = "läßt der Phantasie recht viel Spielraum, was sich",
  [10335] = "dort unten, im Unsichtbaren, alles tummeln könnte.",
  [10336] = "Nach Osten gehts zum Ufer, nach Westen zu dem",
  [10337] = "Findling. Aber... um Himmels Willen... da",
  [10338] = "schnellt aus dem Wasser plötzlich eine riesige,",
  [10339] = "schreckliche Kreatur hoch...!!!*",
  [10340] = "... erstarrt aber im gleichen Augenblick mitten in",
  [10341] = "der Bewegung, verzieht angewidert das gräßliche",
  [10342] = "Echsengesicht, macht heftig kehrt, und taucht mit",
  [10343] = "hektischen Flossenschlägen wieder auf und davon!",
  [10344] = "Tja - ihr Dungbrocken zeitigt ungeahnte",
  [10345] = "Ergebnisse! Wahrscheinlich haben die Brontosaurier",
  [10346] = "deshalb so lange in dieser Welt bestehen können.*",
  [10347] = "... das Schlimme an urzeitliches Gewässern ist die",
  [10348] = "Tatsache, daß man zuvor nicht sieht, was einen im",
  [10349] = "nächsten Augenblick auffrisst. Ein eingehender",
  [10350] = "Blick auf das kuriose Monster hätte sich sicher",
  [10351] = "gelohnt... aber leider ist es schon zu spät...*",
  [10352] = "Am Findling",
  [10353] = "Hier ist die Grenze zwischen dem sanften",
  [10354] = "Wasserstrom zum Ufer hin, und einer reißenden",
  [10355] = "Strömung, die Sie von der Sandbank trennt. Dorthin",
  [10356] = "scheint das Weiterkommen schier unmöglich!*",
  [10357] = "Der Findling ist nicht sehr groß. Die Strömung",
  [10358] = "hat schon tiefe Risse in die Oberfläche gegraben.*",
  [10359] = "Die Sandbank liegt einen knappen Steinwurf",
  [10360] = "entfernt westlich von hier. Dort stehen ein paar",
  [10361] = "große Stauden mit Bananen - neben einem",
  [10362] = "angespülten Baumstamm, der auf dem flachen Sand",
  [10363] = "liegt.*",
  [10364] = "Es ist ein großer kräftiger Stamm - den spült die",
  [10365] = "Strömung nicht so leicht davon.*",
  [10366] = "Die Stauden stehen üppig in der Frucht. Die",
  [10367] = "Bananen sind nur klein, aber dafür hängen sie zu",
  [10368] = "Hunderten von den großen Pflanzen herab.*",
  [10369] = "Ihr Wurfanker hat sich fest ins Holz gegraben; das",
  [10370] = "Seil, das nach hier herüberreicht, scheint eine",
  [10371] = "annehmbare Aussicht zu bieten, nicht von der",
  [10372] = "Strömung davongerissen zu werden.*",
  [10373] = "Der Wurfanker hat sich hier in den Rissen des",
  [10374] = "Findlings verkeilt.*",
  [10375] = "Ah! Keine schlechte Idee...! Der Wurfanker",
  [10376] = "fliegt... Tock!",
  [10377] = "Bravo, Treffer! Der Wurfanker ist sicher im Holz",
  [10378] = "des Baumstammes dort drüben stecken geblieben. Mit",
  [10379] = "Hilfe des Seiles können Sie nun sicher dort",
  [10380] = "hinüber gelangen!*",
  [10381] = "(Na.. ob das so klug ist? Wenn Sie's hier",
  [10382] = "festbinden, werden Sie den Wurfanker nach Ihrer",
  [10383] = "Rückkunft von dort drüben nicht mehr lösen können,",
  [10384] = "und ihn, samt Seil, verlieren! Denken Sie mal",
  [10385] = "scharf nach - es gibt eine bessere Möglichkeit!)*",
  [10386] = "Auf der Sandbank",
  [10387] = "Dies ist ein trocknes, gemütliches Fleckchen",
  [10388] = "mitten im Fluß. Außer einer Monsterspinne gibt es",
  [10389] = "hier nichts Gefährliches. Es stehen ein paar große",
  [10390] = "Stauden herum, an denen Hunderte Bananen hängen,",
  [10391] = "und am Ufer liegt ein großer Baumstamm. Weiter",
  [10392] = "östlich im Fluß, jenseits der reißenden Strömung,",
  [10393] = "steht der Findling im Wasser.*",
  [10394] = "Im Baumstamm steckt ein Wurfanker, an dem ein Seil",
  [10395] = "befestigt ist.*",
  [10396] = "Die Monsterspinne schaukelt im Sonnenschein in",
  [10397] = "ihrem Netz, und tut so, als hätte sie einen",
  [10398] = "schrecklichen Giftstachel.*",
  [10399] = "Die Monsterspinne ist zwar groß und sieht",
  [10400] = "schrecklich gefährlich aus, sie benimmt sich aber",
  [10401] = "sehr anschmiegsam. Ihre Berührungen sind so zart",
  [10402] = "wie die eines Schmetterlings, und es scheint",
  [10403] = "bisweilen... als würde sie ein wenig schnurren!!!*",
  [10404] = "Das Netz der Monsterspinne ist mitten zwischen den",
  [10405] = "Bananen, kreuz und quer, gesponnen.*",
  [10406] = "Hat sie doch gar nicht! Alle Leute scheinen zu",
  [10407] = "glauben, daß Spinnen so furchtbar gefährlich sind!",
  [10408] = "Besonders Monsterspinnen. Warum nur?*",
  [10409] = "Huch! Die Monsterspinne zuckt vor, in Richtung",
  [10410] = "Ihrer Hand...*",
  [10411] = "... und grinst Sie dann, geradezu unverschämt, an.",
  [10412] = "So, als würde sie sich einen Spaß daraus machen,",
  [10413] = "die Leute zu erschrecken. Also so was!*",
  [10414] = "Der Wurfanker fliegt... zack!",
  [10415] = "Ein guter Wurf. Der Haken hat sich in den Rissen",
  [10416] = "im Findling verfangen.*",
  [10417] = "(Das wird Ihnen nicht viel bringen, außer dem",
  [10418] = "Verlust Ihres Wurfankers, wenn Sie wieder drüben,",
  [10419] = "auf dem Findling sind!)*",
  [10420] = "Dort, bei dem Felsen am nördlichen Uferrand des",
  [10421] = "Flusses, steht der Tyrannosaurus.*",
  [10422] = "Dort, wo sich der Säbelzahntiger befand, ist",
  [10423] = "jetzt der Brontosaurus auf Nahrungsuche.*",
  [15001] = "Der gewaltige Energiestrudel verebbt - gibt Sie",
  [15002] = "wieder frei. Der Boden unter den Füßen ist endlich",
  [15003] = "wieder da. Doch da wartet schon eine neue",
  [15004] = "Überraschung: es ist kalt, schneidend kalt.*",
  [15005] = "In der Felsnische",
  [15006] = "Sie befinden sich in einer schmalen Felsnische.",
  [15007] = "Durch einen Spalt, der nach Süden führt, ist ein",
  [15008] = "Teil einer schneebedeckten, eiszeitlichen",
  [15009] = "Landschaft zu sehen: da draußen heult der Wind,",
  [15010] = "und peitscht Schneeflocken und Eiskristalle fast",
  [15011] = "waagrecht durch die Luft.*",
  [15012] = "Hier in der Felsnische stehen einige Sachen herum",
  [15013] = "- man könnte meinen, sie stammen von einer längst",
  [15014] = "vergangenen Expedition!*",
  [15015] = "Auf dem Boden, neben einem Felsbrocken, steht eine",
  [15016] = "große Holzkiste.*",
  [15017] = "An der Wand hat irgendwer, offenbar vor urlanger",
  [15018] = "Zeit, die stolze Fahne einer Universität gehißt.*",
  [15019] = "Neben der Kiste steht ein großes Faß.*",
  [15020] = "In einer Ecke lehnt ein kräftiger Holzknüppel.*",
  [15021] = "Es ist eine schwere Kiste, so wie man sie",
  [15022] = "vielleicht früher verwendet haben mag, um",
  [15023] = "Ausrüstung für Expeditionen in solch unwegsame",
  [15024] = "Gegenden wie diese hier zu bringen.*",
  [15025] = "In der Holzkiste liegen ein schwerer Fellmantel",
  [15026] = "und ein paar fellbesetzter Stiefel.*",
  [15027] = "Hm - da hat wohl einst ein stolzer Eisbär sein",
  [15028] = "Leben lassen müssen. Der Mantel wiegt eine Menge,",
  [15029] = "aber er kann mit Sicherheit auch tiefste",
  [15030] = "Temperaturen fernhalten. Er hat zwei riesige",
  [15031] = "Taschen und eine Kapuze.*",
  [15032] = "Mit diesen riesigen Manteltaschen könnte man gut",
  [15033] = "im Supermarkt einkaufen gehen.*",
  [15034] = "Eine warme Kapuze ist der beste Freund der Ohren,",
  [15035] = "lautet eine traditionelle, alte Weisheit der",
  [15036] = "Eskimos.*",
  [15037] = "Ah! Das Schicksal meint es gut mit Ihnen! In den",
  [15038] = "Manteltaschen stecken große Handschuhe aus",
  [15039] = "Eisbärfell!*",
  [15040] = "Für diese riesigen Handschuhe hat wohl ein",
  [15041] = "weiterer Eisbär sterben müssen.*",
  [15042] = "Es ist eine nicht sehr große, aber farbenprächtige",
  [15043] = "Fahne der Universität von... nun, Helsingbrod - wo",
  [15044] = "immer das auch sein mag.*",
  [15045] = "He... was haben Sie denn da vor? Das Ding wird",
  [15046] = "lichterloh und in Sekundenschnelle abbrennen!",
  [15047] = "Wollen Sie das wirklich einfach so anzünden?*",
  [15048] = "Also gut...",
  [15049] = "Vorsicht...!!! Schnell, lassen Sie das Ding los...",
  [15050] = "In einer kurzen, prasselnden Flamme verbennt das",
  [15051] = "trockne Tuch... und übrig bleibt: nichts!*",
  [15052] = "Das dürfte die bessere Entscheidung sein!",
  [15053] = "Vielleicht können Sie die Fahne irgendwann noch",
  [15054] = "nutzbringender einsetzen!*",
  [15055] = "Das Faß ist so groß wie ein gewöhnliches Ölfaß. Es",
  [15056] = "ist halbvoll mit... bäääh - ranzigem",
  [15057] = "Walfischtran.*",
  [15058] = "Puuuh! Das Zeug ist uralt und stinkt!*",
  [15059] = "Ein schwieriges Unterfangen... nein, das klappt",
  [15060] = "nicht. Ihre Flamme erstickt sofort in der ranzigen",
  [15061] = "Brühe!*",
  [15062] = "Wie wollen Sie das mitnehmen? In der Hosentasche?",
  [15063] = "Nein, so haut das nicht hin.*",
  [15064] = "Lassen Sie sich raten, Ihre Absicht zielgenauer",
  [15065] = "auszuführen, wenn Sie erst einmal wissen, was sie",
  [15066] = "mit dem Zeug überhaupt anfangen können. Sonst",
  [15067] = "beschmutzen Sie sich nur mit einer übel stinkenden",
  [15068] = "Brühe!*",
  [15069] = "Soso. Eine Fackel wollen Sie sich also",
  [15070] = "konstruieren? Keine schlechte Idee. Stecken wir",
  [15071] = "also den fahnen-umwickelten Knüppel mal da rein...",
  [15072] = "Schlurps... Moment...! Lassen Sie's noch ein wenig",
  [15073] = "abtropfen... fein. Nun haben Sie eine Fackel. Das",
  [15074] = "Ding wird sicher gut brennen. Und stinken.*",
  [15075] = "Na, wenn das kein Erfolg ist! Ihre Fackel brennt",
  [15076] = "lichterloh! Und stinkt wie die Kloake einer",
  [15077] = "Fischfabrik!*",
  [15078] = "Gut. Stecken wir sie kurz in den Schnee... sie ist",
  [15079] = "nun wieder aus.*",
  [15080] = "Der Holzknüppel ist kräftig und einen guten Meter",
  [15081] = "lang.*",
  [15082] = "Der Holzknüppel ist kräftig und einen guten Meter",
  [15083] = "lang. An einem Ende ist eine Fahne drum-herum-",
  [15084] = "gewickelt.*",
  [15085] = "Sie haben sich aus einem Holzknüppel, einer Fahne",
  [15086] = "und einem guten Liter Walfischtran eine Fackel",
  [15087] = "konstruiert.*",
  [15088] = "Sie ist aber aus.*",
  [15089] = "Sie brennt lichterloh und stinkt und qualmt gar",
  [15090] = "grauslich!*",
  [15091] = "Dazu ist es jetzt nun wirklich zu spät, oder?*",
  [15092] = "Lieber Himmel - da ist nun wirklich nichts",
  [15093] = "besonderes zu... oh! Das kann man Glück nennen! Da",
  [15094] = "hat jemand auf dem Felsbrocken eine Schneebrille",
  [15095] = "liegen lassen - ein unersetzlich wichtiges Ding in",
  [15096] = "einer solchen Eiswelt!*",
  [15097] = "Sie unspektakulär sie auch aussieht, so wichtig",
  [15098] = "ist sie auch für jemanden, der sich hinaus in die",
  [15099] = "arktische Welt wagen will.*",
  [15100] = "Am Schneehang",
  [15101] = "Hier pfeift der Wind mit urzeitlicher Gewalt. Eine",
  [15102] = "endlose, schneebedeckte Fläche breitet sich nach",
  [15103] = "Süden, Westen und Osten aus - nur weit am Horizont",
  [15104] = "sind hier und da einzelne Bergketten zu erkennen.",
  [15105] = "Es ist entsetzlich kalt.",
  [15106] = "Nordwärts liegt eine Felsnische am Fuße eines",
  [15107] = "steil aufsteigenden Schneehanges - der weit hinauf",
  [15108] = "zu den Graten, Felswänden und schneebedeckten",
  [15109] = "Felsnadeln eines gewaltigen Bergriesen führt.*",
  [15110] = "Der eisige Sturm saugt Ihnen förmlich die Wärme",
  [15111] = "aus dem Körper.*",
  [15112] = "Es herrscht gräßlicher, schauderhafter und",
  [15113] = "klirrender Frost. Lange werden Sie dieser Kälte",
  [15114] = "nicht mehr widerstehen können!*",
  [15115] = "Kalte Füße sind etwas Gräßliches. Hier in diesen",
  [15116] = "Breiten können sie sogar einfrieren, wie man",
  [15117] = "hört!*",
  [15118] = "Ihre Schuhe sind durchweicht... die Zehen werden",
  [15119] = "langsam steif, ohweh. Wussten Sie, daß bei",
  [15120] = "arktischen Temperaturen ungschütztes Fleisch schon",
  [15121] = "nach drei Minuten gefriert? Interessant, was?*",
  [15122] = "Ihre Hände sind von der Kälte schon knallrot",
  [15123] = "geworden.*",
  [15124] = "Kalte Hände sind etwas Entsetzliches. Besonders,",
  [15125] = "wenn sie schon so steif sind wie ein Stück",
  [15126] = "Gefrierfleisch. Jetzt können Sie nicht mal mehr in",
  [15127] = "der Nase bohren!*",
  [15128] = "Der eisige Wind zerrt wie mit einer tiefgekühlten",
  [15129] = "Beißzange an Ihren Ohrläppchen!*",
  [15130] = "Geben Sie acht: Gleich bläst der Sturm Ihr",
  [15131] = "gefrorenes linkes Ohr davon! Wollen Sie nicht",
  [15132] = "etwas dagegen unternehmen?*",
  [15133] = "Arktische Temperaturen sind nichts für",
  [15134] = "ungeschützte Leute! Schon nach wenigen Minuten",
  [15135] = "zeigen sich schlimme Erfrierungen an Ihrem Körper.",
  [15136] = "In wenigen Sekunden wird Ihnen die Nase",
  [15137] = "abfallen... und, ohje...*",
  [15138] = "Es mögen mehr als dreißig Grad Minus sein - hier",
  [15139] = "fühlt sich wohl nur ein Eskimo wohl. Zum Glück",
  [15140] = "sind Sie gut vor der Kälte geschützt.*",
  [15141] = "Der Helligkeit dieser weißen Welt ist eine arge",
  [15142] = "Belastung für die Augen. Langsam aber sicher",
  [15143] = "beginnen Sie Sternchen zu sehen.*",
  [15144] = "Sie sollten dringend Ihre Augen gegen diese",
  [15145] = "blendende Helligkeit schützen! Sonst sehen Sie",
  [15146] = "bald nichts mehr!*",
  [15147] = "Schneeblindheit ist eine ebenso tückische wie auch",
  [15148] = "verhängnisvolle Sache. Außer einem weißen Schleier",
  [15149] = "vor den Augen ist absolut nichts mehr zu sehen...",
  [15150] = "Passen Sie auf... eine Gletscherspalteeeeeee....!*",
  [15151] = "Eiswüste",
  [15152] = "Hier gibt es soviel Eis und Schnee wie Wasser im",
  [15153] = "Meer. Und die Fläche, die dieses Merkmal aufweist,",
  [15154] = "ist kaum kleiner. Da kann einem schon der Mut",
  [15155] = "sinken. Irgendwo am Horizont sind vereinzelte",
  [15156] = "Bergketten zu sehen.*",
  [15157] = "Sie sind so fern, daß man die Hoffnung, heute noch",
  [15158] = "dorthin zu gelangen (und \"heute\" ist noch viele",
  [15159] = "Wochen lang), getrost zu Grabe tragen darf.*",
  [15160] = "Noch immer liegen die Berge in hoffnungsloser",
  [15161] = "Ferne.*",
  [15162] = "Ein einzeln stehender Felsriese türmt sich dort",
  [15163] = "drüben auf, aber er ist genauso eisig und kalt wie",
  [15164] = "alles hier.*",
  [15165] = "Eiswüste",
  [15166] = "Nach dreißig Minuten anstrengendem Kampf gegen Eis",
  [15167] = "und Schnee wird es auch dem größten Optimisten",
  [15168] = "klar: heute wird es nicht mehr wärmer. Und die",
  [15169] = "momentane Temperatur lädt nicht gerade zu einer",
  [15170] = "Strandparty ein. Also: in welche Richtung wollen",
  [15171] = "Sie jetzt?*",
  [15172] = "Eiswüste",
  [15173] = "Nach einer weiteren mühsamen halben Stunde des",
  [15174] = "Kampfes mit Eis und Schnee wird es Zeit, sich zu",
  [15175] = "entscheiden: mannhafter Kampf gegen die",
  [15176] = "übermächtige Natur und die Aussicht auf einen",
  [15177] = "glorreichen Erfrierungstod - oder taktisch kluger,",
  [15178] = "wenn auch schmachvoller Rückzug angesichts des",
  [15179] = "übermächtigen Feindes, (in diesem Fall des Eises).",
  [15180] = "Also: in welche Richtung wollen Sie jetzt?*",
  [15181] = "Eiswüste",
  [15182] = "Es wird immer mühsamer, vorwärts zu kommen. Und",
  [15183] = "der eisige Wind läßt nicht nach. Kein Ort in",
  [15184] = "Sicht, an dem man Zuflucht finden könnte - kein",
  [15185] = "wärmendes Lagerfeuer, und im Umkreis von",
  [15186] = "mindestens dreihundert Meilen kein heißer Grog.",
  [15187] = "Das wird hart! Wo wollen Sie nun hin?*",
  [15188] = "Eiswüste",
  [15189] = "Langsam schwinden die Kräfte. Der Schnee ist tief",
  [15190] = "und der Wind geeignet, einen gestandenen Eisbären",
  [15191] = "zu nachhaltig verärgern. Wie lange werden Sie das",
  [15192] = "wohl noch durchhalten können?*",
  [15193] = "Eiswüste",
  [15194] = "Selbst dem Sensenmann scheint es hier zu kalt zu",
  [15195] = "sein - aber irgendwo wartet er bestimmt.",
  [15196] = "Vielleicht hat er irgendwo ein kleines, wärmendes",
  [15197] = "Feuerchen brennen...?*",
  [15198] = "Eiswüste",
  [15199] = "Ach - das Schicksal ist grausam! Wo soll es hier",
  [15200] = "eine Rettung geben, in dieser endlosen, kalten",
  [15201] = "Welt? Es ist kaum noch etwas zu sehen - die",
  [15202] = "Schneeflocken fegen waagrecht durch die Luft, der",
  [15203] = "gnadenlose Frost schleicht sich immer tiefer ins",
  [15204] = "Gebein...",
  [15205] = "Aber - war da nicht etwas... eine Felswand, ein",
  [15206] = "einsamer Berg...?*",
  [15207] = "Am Steilhang",
  [15208] = "Hier, im Schatten eines steilen Hanges, pfeift der",
  [15209] = "eisige Wind zum Glück nicht mehr so schlimm. Der",
  [15210] = "Schnee ist verharscht, und man sinkt beim Laufen",
  [15211] = "nicht ständig so tief ein. Weiter oben scheint es",
  [15212] = "so etwas wie einen Absatz im Hang zu geben.*",
  [15213] = "Da sollten Sie lieber nicht hingehen. Dort wird",
  [15214] = "der Schnee wieder tief, und der eiskalte Wind",
  [15215] = "pfeift und treibt Schnee vor sich her... haben Sie",
  [15216] = "schon wieder vergessen, wie knapp Sie erst dem",
  [15217] = "Tode entronnen sind?*",
  [15218] = "Auf dem Plateau",
  [15219] = "Dies ist der östliche Rand eines kleinen Plateaus.",
  [15220] = "Es ist an allen Seiten von steilen Felswänden",
  [15221] = "umschlossen, die einzigen Wege führen von hier",
  [15222] = "nach Westen in die Mitte des Plateaus, oder den",
  [15223] = "Steilhang hinunter.*",
  [15224] = "Es beginnt wieder zu schneien. Dicke Schneeflocken",
  [15225] = "schweben langsam zu Boden. Hier oben ist es völlig",
  [15226] = "windstill, kein Laut stört die völlige Einsamkeit",
  [15227] = "dieses vergessenen Ortes.*",
  [15228] = "Über dem Plateau vereinen sich die Felswände zu",
  [15229] = "steilen Graten, die irgendwo hinauf in unbekannte",
  [15230] = "Höhen streben, zum Gipfel des Berges.*",
  [15231] = "Auf dem Plateau",
  [15232] = "Rundherum steigen steile Felswände auf, die das",
  [15233] = "kleine Plateau schützend umschließen. Der Schnee",
  [15234] = "ist tief und kalt, aber glücklicherweise herrscht",
  [15235] = "völlige Windstille.*",
  [15236] = "Hier gibt es etwas Seltsames: Genau in der Mitte",
  [15237] = "des Plateaus steht ein großer, schwarzer Monolith.",
  [15238] = "Er ist frei von Schnee, und schimmert mit",
  [15239] = "unheimlicher Schwärze in der weißen Szenerie.*",
  [15240] = "Ein finsterer, quadratischer Schacht tut sich in",
  [15241] = "der Mitte des Plateaus auf - und führt senkrecht",
  [15242] = "hinab ins Ungewisse.*",
  [15243] = "Vom Rande des Schachtes hängt das Seil Ihres",
  [15244] = "Universalwerkzeugs hinab in die Tiefe.*",
  [15245] = "Ein Edelsteinsplitter liegt hier im Schnee.*",
  [15246] = "Große, schwarze Trümmerbrocken liegen im Schnee;",
  [15247] = "in der Mitte des Plateaus ist eine quadratische",
  [15248] = "Öffnung im Boden sichtbar.*",
  [15249] = "Autsch! Die Trümmerbrocken sind glühend heiß!*",
  [15250] = "Der Schneefall wird ein bißchen stärker; große",
  [15251] = "weiße Flocken tanzen aus dem grauen Himmel",
  [15252] = "hernieder.*",
  [15253] = "Man könnte für diese Szene des lautlosen",
  [15254] = "Schneefalls fast das Wort \"romantisch\" verwenden,",
  [15255] = "wären da nicht die sehr unromantischen mehreren",
  [15256] = "Dutzend Grad Minus. Oh - dort, auf dem Monolithen",
  [15257] = "bleiben die Flocken nicht liegen - sie schmilzen",
  [15258] = "dahin und vergehen in kleinen Dampfwölkchen.*",
  [15259] = "Im Mittelpunkt des Plateaus steht ein großer",
  [15260] = "Monolith im Schnee. Er ist über drei Meter hoch",
  [15261] = "und unirdisch schwarz. In seiner Nähe ist es",
  [15262] = "erstaunlich warm, die Schneeflocken, die auf ihn",
  [15263] = "fallen, verdampfen sofort mit leisem Zischen. Die",
  [15264] = "Quelle der Wärme scheint sich im Inneren des",
  [15265] = "Monolithen zu befinden. Auf der Vorderseite sind",
  [15266] = "zwei tiefe Reliefbilder eingemeißelt.*",
  [15267] = "Auf dem oberen Bild schwebt der Monolith ein Stück",
  [15268] = "in der Luft, und unter ihm ist ein schwarzes",
  [15269] = "Quadrat im Boden zu sehen. Das untere Reliefbild",
  [15270] = "zeigt eine scheußliche Monsterfratze mit einer",
  [15271] = "riesigen Augenhöhle.*",
  [15272] = "Die Monsterfratze ist mit bedrückender",
  [15273] = "Detailschärfe wiedergegeben. Diese Abbildung",
  [15274] = "erweckt den dringenden Wunsch, dieser Bestie",
  [15275] = "niemals zu begegnen.*",
  [15276] = "Eine tiefe, leere Augenhöhle glotzt Sie an.*",
  [15277] = "Ein großer Edelstein sitzt in der Augenhöhle der",
  [15278] = "Fratze.*",
  [15279] = "Die Augenhöhle ist ein Loch, so groß wie eine",
  [15280] = "Kinderfaust. Es führt tief in das Innere des",
  [15281] = "Monolithen hinein. Der Rand dieses Loches besitzt",
  [15282] = "seltsame Kerben.*",
  [15283] = "Die Augenhöhle ist ein Loch, so groß wie eine",
  [15284] = "Kinderfaust. Es führt tief in das Innere des",
  [15285] = "Monolithen hinein. In der Augenhöhle steckt ein",
  [15286] = "großer Edelstein.*",
  [15287] = "Wenn man genau hinschaut, sehen die Kerben fast",
  [15288] = "wie ein Gewinde aus, so als könnte man vielleicht",
  [15289] = "eine riesige Schraube oder etwas ähnliches in die",
  [15290] = "leere Augenhöhle hineindrehen.*",
  [15291] = "Der Edelstein passt genau. Aber er wackelt ein",
  [15292] = "bißchen und verschließt die Augenhöhle nicht",
  [15293] = "vollständig.*",
  [15294] = "Mit leisem Knirschen verkantet sich der Edelstein.",
  [15295] = "Nun sitzt er fest.*",
  [15296] = "Krrrks! Der Edelstein sitzt nun wieder locker in",
  [15297] = "der Augenhöhle.*",
  [15298] = "Schnee? Haben Sie nicht inzwischen die Nase voll",
  [15299] = "von dem Zeug? Nun gut, wir können es Ihnen",
  [15300] = "schlecht verwehren - hier gibt es genug für eine",
  [15301] = "Million Abenteurer. Sie besitzen nun zwei",
  [15302] = "Händevoll davon. Was wollen Sie damit anfangen?*",
  [15303] = "Sie haben ja noch die Hände voll Schnee. Noch mehr",
  [15304] = "können Sie im Moment nicht nehmen!*",
  [15305] = "Gut. Sie sollen Schnee haben, soviel sie wollen.",
  [15306] = "Wohin damit?*",
  [15307] = "Ah - Sie haben was vor! Interessant. Der Schnee",
  [15308] = "schmilzt rasch - das Wasser läuft ins Innere des",
  [15309] = "Monolithen. Schon bald darauf dampft es leicht aus",
  [15310] = "der Augenhöhle heraus.*",
  [15311] = "Gut - auch die nächste Ladung Schnee rutscht nach",
  [15312] = "innen. Im Inneren des Monolithen scheint eine hohe",
  [15313] = "Temperatur zu herrschen. Schon bald dringt",
  [15314] = "Wasserdampf aus der leeren Augenhöhle.*",
  [15315] = "Nach kurzer Zeit kocht das Wasser im Inneren. Ein",
  [15316] = "stetiger Dampfstrahl dringt aus der Augenhöhle.",
  [15317] = "Schnell - Was nun?*",
  [15318] = "Er passt! Fein - gleich wird wohl was",
  [15319] = "passieren....*",
  [15320] = "Der Dampf kann nicht mehr entweichen - bald wird",
  [15321] = "ein ungutes Knacken und Krachen aus dem Inneren",
  [15322] = "des Monolithen hörbar. Wir möchten Ihnen anraten,",
  [15323] = "lieber das Weite zu suchen!*",
  [15324] = "Kraaach!!! Der Monolith zerbirst mit einem",
  [15325] = "trockenen Knall in tausend Stücke. Eine mächtige",
  [15326] = "Dampfwolke steht plötzlich in der Luft, große",
  [15327] = "schwarze Trümmerbrocken regnen auf dem Plateau",
  [15328] = "nieder. Diesem Beispiel folgt auch bald der",
  [15329] = "Wasserdampf. Nette kleine Schneeflocken tanzen",
  [15330] = "durch die Luft. Als das Schauspiel vorüber ist,",
  [15331] = "zeigt sich eine quadratische Öffnung im Boden,",
  [15332] = "genau dort, wo vor einer Minute noch der Monolith",
  [15333] = "stand!*",
  [15334] = "Der ausströmende Wasserdampf versiegt. Erstaunlich",
  [15335] = "- da drin scheint es so etwas wie einen enorm",
  [15336] = "effektiven Wasserkessel zu geben.*",
  [15337] = "Die Quelle der Wärme dort drin hat das ganze",
  [15338] = "Schmelzwasser in kurzer Zeit in Dampf verwandelt.",
  [15339] = "Nur noch ein letztes Wölkchen dringt aus der",
  [15340] = "Augenhöhle - dann ist der Dampfstrom versiegt.*",
  [15341] = "Er hält nur für eine kurze Weile. Plop! Der",
  [15342] = "Dampfdruck katapultiert ihn wieder hinaus. Der",
  [15343] = "Edelstein fällt in den Schnee. Gleich darauf ist",
  [15344] = "der Dampfstrom auch schon wieder versiegt.*",
  [15345] = "Das Pech ist nur, daß auch Sie bei dem großen Bums",
  [15346] = "an dieser Stelle standen. Wenn Sie auf dem Mond",
  [15347] = "angekommen sind, dann erkundigen Sie sich bei",
  [15348] = "irgendwem nach der Außenstelle von WELTENSCHMIEDE",
  [15349] = "im Mare Imbrium. Die Jungs da werden Ihnen gerne",
  [15350] = "vielleicht Computer zur Verfügung stellen. Also,",
  [15351] = "bis dann...*",
  [15352] = "Wollen Sie etwa springen? Das wäre nicht",
  [15353] = "anzuraten. Wer weiß, wie tief es dort hinabführt?*",
  [15354] = "Hmmm... damit wir uns nicht mißverstehen... wollen",
  [15355] = "Sie das wirklich einfach dort hinab in die Tiefe",
  [15356] = "werfen? Ohne es hier, am Rand des Schachtes",
  [15357] = "irgendwo zu befestigen?*",
  [15358] = "Wie soll das gehen? Wollen Sie es an einer",
  [15359] = "Schneeflocke festbinden?*",
  [15360] = "Ah... was täten Sie wohl ohne ihr grandioses",
  [15361] = "Universalwerkzeug? Gut. Der Haken findet einen",
  [15362] = "guten Halt am Rand des Schachtes... jetzt werfen",
  [15363] = "wir das Seil hinab in die Tiefe... schwupps!",
  [15364] = "Nun könnten Sie dort hinab steigen! Ob das Seil",
  [15365] = "allerdings lang genug ist - wer weiß das schon?*",
  [15366] = "Das ist - unseren Respekt! - eine fabelhafte Idee!",
  [15367] = "Also los, wir helfen ein bißchen mit... hauruck...",
  [15368] = "und runter mit dem Zeug... hier gibts ja genug...",
  [15369] = "jawoll... das macht ja richtig Spaß... und noch",
  [15370] = "eine Fuhre... gut. Das dürfte genügen. Da unten",
  [15371] = "liegt jetzt garantiert ein ansehnlicher",
  [15372] = "Schneehaufen. Genug jedenfalls, um einen",
  [15373] = "mittelhohen Sturz aufzufangen!*",
  [15374] = "Im Schacht",
  [15375] = "Der Schacht führt lange Zeit senkrecht hinab. Der",
  [15376] = "Abstieg mit Hilfe des Seiles ist nicht un-",
  [15377] = "anstrengend... oh! Verflixt! Das Seil ist zuende!",
  [15378] = "Und unter Ihren Füßen kein Boden!*",
  [15379] = "Es könnte noch ein verdammt weiter Weg bis unten",
  [15380] = "sein! Wollen Sie wirklich das Seil loslassen?*",
  [15381] = "Nicht? Tja, Vorsicht ist die Mutter der",
  [15382] = "Porzellankiste. Vielleicht fällt Ihnen auch noch",
  [15383] = "etwas besseres ein.*",
  [15384] = "Na gut, was hilft es? Aber Moment... Sie sollten",
  [15385] = "Ihr Seil nicht aufgeben. Wer weiß, wie nützlich",
  [15386] = "das Ding noch sein wird...",
  [15387] = "Also los, ein kleiner Klimmzug... und ein heftiger",
  [15388] = "Seil-Schnalzer nach oben.....",
  [15389] = "oooooooohhhhhhhh.......*",
  [15390] = "....rrrrummmmsss!!!",
  [15391] = "Aaaauuuuu!!!!! Der Knöchel! Oh nein... er ist -",
  [15392] = "glatt gebrochen! Das ist ja eine Kathastrophe -",
  [15393] = "hier unten in der Dunkelheit...*",
  [15394] = "Patsch!!!",
  [15395] = "Was für Ein Glück! Sie sind unverletzt in Ihrem",
  [15396] = "Schneehaufen gelandet, und... oh, schnell weg",
  [15397] = "da...",
  [15398] = "Zack!!!",
  [15399] = "... ihr Lieblingswerkzeug haben Sie auch wieder.*",
  [15400] = "Am Grunde des Schachtes",
  [15401] = "Hier, von Ihrem Schneehaufen aus, führt ein",
  [15402] = "höhlenartiger Gang geradeaus nach Westen. Weit",
  [15403] = "oben ist hingegen des helle Viereck des",
  [15404] = "Schachtausgangs zu sehen - so nah und doch so",
  [15405] = "unerreichbar fern!*",
  [15406] = "Den Schneehaufen...? Was soll daran schon sein...",
  [15407] = "ah! Sie haben recht, vielleicht haben Sie was",
  [15408] = "verschüttet...*",
  [15409] = "... tatsächlich! Unter dem vielen Schnee liegt ein",
  [15410] = "großer Schlüssel aus Eisen!*",
  [15411] = "... nein, da ist leider nichts!*",
  [15412] = "Nein, es ist nicht der Schlüssel zur",
  [15413] = "Eisensteinfeste, es ist nur ein ganz gewöhnlicher,",
  [15414] = "wenn auch großer Schlüssel aus Eisen.*",
  [15415] = "Im Gang",
  [15416] = "Die Wände des Ganges bestehen aus roh behauenem",
  [15417] = "Fels, er ist niedrig und führt weiter nach",
  [15418] = "Westen.*",
  [15419] = "Es handelt sich um felsigen Fels... ah! Dort ist",
  [15420] = "ein kleines Schildchen angebracht!*",
  [15421] = "Gegen sie mal näher 'ran mit Ihrem Licht... oh!",
  [15422] = "Wie peinlich. Da steht:",
  [15423] = "WELTENSCHMIEDE Abt. Standard-Kulissen. Gang-West.",
  [15424] = "Felsen, niedrig, roh behauen. Requisiten-Nr. 042A*",
  [15425] = "Gangende",
  [15426] = "Hier endet der Gang an einer massiven Gittertüre.",
  [15427] = "Dahinter liegt ein großer, dunkler Raum... und an",
  [15428] = "der Wand steht ein Schrein! Ja - von dort glänzt",
  [15429] = "Licht herüber - reflektiert von dem Splitter eines",
  [15430] = "Edelsteins, der dort liegt.",
  [15431] = "Aber er scheint bewacht zu sein. Von einem",
  [15432] = "riesigen Eisbären, der mitten im Raum auf dem",
  [15433] = "Boden liegt und schläft!*",
  [15434] = "Die Gittertür scheint stark genug zu sein, um den",
  [15435] = "Eisbären fern zu halten - damit aber sind sie mit",
  [15436] = "Sicherheit ebenfalls ausgesperrt! Vorn drauf ist",
  [15437] = "ein großes Schloß.*",
  [15438] = "Der Schrein ist eine Art kleiner Altar mit einem",
  [15439] = "verzierten Podest oben drauf. Auf dem Podest liegt",
  [15440] = "der Splitter eines großen Edelsteins.*",
  [15441] = "Der Eisbär liegt nur da und schläft. Aber ist",
  [15442] = "derartig groß... das kann kein normaler Eisbär",
  [15443] = "sein!*",
  [15444] = "Der Eisbär stampft ungeduldig und wütend knurrend",
  [15445] = "in der Höhle umher. Offenbar ist er äußerst",
  [15446] = "gereizt. Seine Augen funkeln blutdurstig...",
  [15447] = "ohgott, er hat ja DREI! Ein Glück nur, daß die",
  [15448] = "Gittertür Sie schützt!*",
  [15449] = "Das Schloß knirscht... und der riesige Eisbär",
  [15450] = "fährt hoch! Im nächsten Moment schon hat er sie",
  [15451] = "als Eindringling erkannt, springt knurrend auf,",
  [15452] = "und rennt mit voller Wucht gegen die Gittertür an!",
  [15453] = "Zum Glück öffnet sie nach innen, und hält der Wut",
  [15454] = "des Eisbären stand! Das riesige Tier brüllt",
  [15455] = "wütend, und fixiert sie mit seinen... um Himmels",
  [15456] = "Willen... er hat ja DREI Augen!*",
  [15457] = "Waaas? Bleiben Sie hier! Das wäre Ihr sicherer",
  [15458] = "Tod! Wollen Sie wirklich da rein?*",
  [15459] = "Oh Mann! Sie sind wahrhaft verwegen.... nur",
  [15460] = "vorsichtig... der Eisbär...*",
  [15461] = "In der Höhle",
  [15462] = "Sie sind am Ziel Ihrer Reise in dieser arktischen",
  [15463] = "Welt... hier ist der Schrein, auf dem einer der",
  [15464] = "verlorenen Splitter vom Auge des Kal liegt.*",
  [15465] = "... aber hier gibt es auch einen riesigen,",
  [15466] = "dreiäugigen Eisbären... schon in diesem Moment",
  [15467] = "erhebt sich das Untier mit markdurchdringendem",
  [15468] = "Gebrüll auf die Hinterläufe...*",
  [15469] = "... und stürzt sich einen Augenblick später mit",
  [15470] = "weit ausfgerissenem Maul auf Sie... oh nein...",
  [15471] = "hiiiiilffeeee.....*",
  [15472] = "... und erstarrt, als als er die lichterloh",
  [15473] = "brennende Fackel erblickt! Ein ungläubiges Jaulen",
  [15474] = "entringt sich seiner Kehle, so als hätte er noch",
  [15475] = "nie Feuer gesehen, schon gar nicht ein so großes,",
  [15476] = "helles, qualmendes, stinkendes....*",
  [15477] = "Der mächtige, dreiäugige Eisbär wird von nackter",
  [15478] = "Angst gepackt, als ihm die Fackel gefährlich näher",
  [15479] = "kommt... er quietscht in sehr un-eisbären-hafter",
  [15480] = "Weise... und als ein paar seiner Haare ansengen,",
  [15481] = "dreht er sich um, und rast angstvoll davon, in die",
  [15482] = "Tiefen dieser Höhle hinein! Unglaublich! Sie haben",
  [15483] = "das Ungeheuer besiegt!*",
  [15484] = "Unseren Glückwunsch! Sie haben einen weiteren der",
  [15485] = "Splitter des Auges... und schon im nächsten Moment",
  [15486] = "verschwimmt die Szene um Sie herum, und die",
  [15487] = "geheimnisvolle Kraft schleudert Sie zurück durch",
  [15488] = "Zeit und Raum.....*",
  [25002] = "Als Sie wieder stofflich werden, blendet Sie",
  [25003] = "grelles Sonnenlicht - salziger Geruch sticht in",
  [25004] = "Ihre Nase. Es ist sehr warm, obwohl die Sonne noch",
  [25005] = "tief steht - es kann erst früher Vormittag sein.",
  [25006] = "Als dann mit einem seltsamen Flappen ein mächtiger",
  [25007] = "Schatten über Sie fällt, und Vogelgekreische",
  [25008] = "ertönt, wird die Ahnung zur Gewissheit - Sie sind",
  [25009] = "auf hoher See!*",
  [25010] = "\"Die Rah brassen!\" brüllt von irgendwoher eine",
  [25011] = "grobe Stimme, und ein paar Dutzend eiliger Füße",
  [25012] = "trampeln über Holzplanken. Wieder ertönt das",
  [25013] = "Flappen, und der große Schatten verschwindet. Ein",
  [25014] = "weiteres Segelkommando schallt über das Deck.*",
  [25015] = "Auf Oberdeck",
  [25016] = "Über Ihnen bauschen sich weiße Segel im Wind, und",
  [25017] = "ein Gewirr von Takellage strebt hinauf in den",
  [25018] = "tiefblauen Himmel. Ein paar Volk kreischender",
  [25019] = "Möven kreist um die hohen Masten.",
  [25020] = "Unter Ihren Füßen sind Holzplanken; und dann",
  [25021] = "sehen Sie auch die Reling, Kanonen, Tauwerk,",
  [25022] = "Fässer, Kisten, Segelzeug - und hinten, über dem",
  [25023] = "Achterdeck, eine im Wind flatternde Flagge.*",
  [25024] = "Es ist die Flagge der britischen Admiralität.*",
  [25025] = "Es sind richtige, gußeiserne Kanonen - wie sie vor",
  [25026] = "langer Zeit auf Kriegsschiffen üblich waren.*",
  [25027] = "Die riesigen Segel bilden einen blendendweißen",
  [25028] = "Kontrast vor dem tiefblauen Himmel - es muß ein",
  [25029] = "enorm großes Schiff sein.*",
  [25030] = "Das Achterdeck liegt gute drei Meter höher als das",
  [25031] = "Oberdeck. Ein Offizier mit Napoleons-Hut und",
  [25032] = "goldenen Epauletten auf den Schultern seiner",
  [25033] = "reichverzierten Uniformjacke steht dort oben und",
  [25034] = "hält die Arme hinter dem Rücken verschränkt. Er",
  [25035] = "verfolgt mit strengen Blicken das Segelmanöver.*",
  [25036] = "Sie sehen aus, als würden sie jeden Tag mehrere",
  [25037] = "Male geschrubbt - eine typische Sträflingsarbeit",
  [25038] = "der damaligen Zeit.*",
  [25039] = "Es ist zweifellos der Kapitän. Sein hakennasiges,",
  [25040] = "mißgelauntes Gesicht erweckt den Wunsch, ihm so",
  [25041] = "fern wie möglich zu bleiben.*",
  [25042] = "\"He, du Strolch!\" ruft eine grobe Stimme. Ein",
  [25043] = "riesenhafter Mann kommt auf Sie zu - er trägt",
  [25044] = "Kleider wie die britischen Seeleute in den vielen",
  [25045] = "Piratenfilmen, die pausenlos im Fernsehen laufen -",
  [25046] = "oder sollte man lieber sagen: die erst in einigen",
  [25047] = "hundert Jahren laufen werden?*",
  [25048] = "Der Mann sieht verdächtig nach dem Bootsmann aus.",
  [25049] = "Er ist gebaut wie ein Rhinozeros, fast zwei Meter",
  [25050] = "groß, und hat Schultern, mit denen man schwerere",
  [25051] = "Türen einrennen könnte.*",
  [25052] = "\"Sieh an, ein kleiner Ausreißer!\" brummt der",
  [25053] = "riesige Mann. \"Wenn ich Dich hier nochmal",
  [25054] = "erwische, dann setzt es was!\" brüllt er. \"So wahr",
  [25055] = "ich der Bootsmann der Indian Voyager bin! Los,",
  [25056] = "marsch - ab, an Deine Kanone! Jeden Moment können",
  [25057] = "die Franzosen auftauchen!\" Damit stößt er Sie grob",
  [25058] = "in Richtung einer der großen Kanonen an der",
  [25059] = "Steuerbordseite.*",
  [25060] = "\"Das ist die verkehrte Richtung!\" brüllt der",
  [25061] = "Bootsmann. Mit drei Schritten ist er bei Ihnen,",
  [25062] = "und packt Sie im Genick. \"Willst Du etwa meutern?",
  [25063] = "Wir sind auf Kriegsfahrt, Du Spaßvogel! Wenn Du",
  [25064] = "Dich noch einmal von Deiner Kanone entfernst,",
  [25065] = "lass' ich Dich kielholen! Na los, Kerl!\" Er stößt",
  [25066] = "Sie abermals in Richtung der Kanone.*",
  [25067] = "\"So, jetzt reichts!\" brüllt der Bootsmann.",
  [25068] = "\"Waaache!\"",
  [25069] = "Einige Uniformierte kommen übers Deck gerannt.",
  [25070] = "\"Der Kerl wird gekielholt!\" sagt der Bootsmann",
  [25071] = "wütend.*",
  [25072] = "Die Männer packen Sie grob und schleifen Sie übers",
  [25073] = "Deck bis zu einer Stelle, an der die Reling",
  [25074] = "unterbrochen ist. Einer knotet brutal ein dickes",
  [25075] = "Tau an Ihren Füßen fest, ein anderer befestigt ein",
  [25076] = "zweites an Ihren Armen. Im nächsten Moment baumeln",
  [25077] = "Sie schon über dem Wasser. Das Tau strafft sich -",
  [25078] = "oje, schnell luftholen, jetzt wirds ernst!*",
  [25079] = "Platsch! Schon sind Sie unter Wasser... um Himmels",
  [25080] = "Willen... der scharfkantige Muschelbewuchs des",
  [25081] = "Schiffsrumpfes kommt näher und näher... und der",
  [25082] = "Strömung unter dem Schiffsrumpf entkommt man",
  [25083] = "nicht...*",
  [25084] = "An der Kanone",
  [25085] = "Zwei vierschrötige Kerle stehen bei der großen",
  [25086] = "Kanone, der eine raucht eine dicke Zigarre, der",
  [25087] = "andere rollt gelangweilt eine eiserne Kanonenkugel",
  [25088] = "mit dem Fuß hin und her. Neben der Kanone steht",
  [25089] = "ein Fäßchen mit Pulver, dahinter sind ein Dutzend",
  [25090] = "Kugeln aufgetürmt, jede so groß wie ein Handball.*",
  [25091] = "\"Sieh an, ein Neuer!\" sagt der eine und mustert",
  [25092] = "Sie neugierig. \"Hallo, ich bin Pocken-Pete, und",
  [25093] = "dieser Zwerg hier ist Ochsen-Willy. Einen schönen",
  [25094] = "Todestag wünsch' ich Dir!\" Er grinst Sie",
  [25095] = "vielsagend an.*",
  [25096] = "\"Die Franzosen werden bald kommen, und uns zur",
  [25097] = "Hölle schicken!\" Er hält Ihnen einen langen",
  [25098] = "Holzprügel hin, der auf der einen Seite dicker",
  [25099] = "ist. \"Hier, nimm den Pulverstampfer! Du mußt die",
  [25100] = "Kanone auffüllen und das Pulver feststampfen, wenn",
  [25101] = "wir den Schießbefehl kriegen!\"*",
  [25102] = "\"Was ist?\" fragt Pocken-Pete. Er hält Ihnen noch",
  [25103] = "immer den Pulverstampfer hin. \"Spielst Du nicht",
  [25104] = "mit? Das wird dem Bootsmann nicht gefallen, er",
  [25105] = "schaut schon dauernd nach Dir!\"*",
  [25106] = "\"Hör' doch auf mit dem Blödsinn!\" zischt Pocken-",
  [25107] = "Pete leise. \"Noch haben wir keinen Schießbefehl!",
  [25108] = "Der Bootsmann beobachtet Dich!\"*",
  [25109] = "\"Bleib lieber hier,\" zischt Ochsen-Willy, und",
  [25110] = "zupft Sie am Ärmel. \"Der Bootsmann beobachtet",
  [25111] = "Dich. Mit dem ist nicht zu spaßen!\"*",
  [25112] = "\"Oh Mann, Du Idiot!\" stöhnt Pocken-Pete mit Blick",
  [25113] = "auf den Bootsmann. \"Jetzt bist Du dran!\"*",
  [25114] = "Pocken-Pete ist ein dürrer, sehniger Kerl mit",
  [25115] = "einer Augenklappe. Er trägt zerrissene, dunkle",
  [25116] = "Kleider und scheint ein schlimmes rechtes Bein zu",
  [25117] = "haben - er hinkt stark.*",
  [25118] = "Ochsen-Willy macht seinem Namen alle Ehre. Er ist",
  [25119] = "gebaut wie ein Ochse, trägt helle Kleidung und hat",
  [25120] = "ständig ein hämisches Grinsen im Gesicht. In",
  [25121] = "seinem Mundwinkel hält er lässig eine dicke",
  [25122] = "Zigarre.*",
  [25123] = "Über diese Kanone würde sich jedes Schiffahrts-",
  [25124] = "Museum freuen. Sie ist gute drei Meter lang, aus",
  [25125] = "schwerem Gußeisen, und steht auf einer großen,",
  [25126] = "hölzernen Lafette.*",
  [25127] = "So klein und so kompakt das Ding auch ist - sein",
  [25128] = "Inhalt ist tödlich. Ochsen-Willy ist mit seiner",
  [25129] = "Zigarre gefährlich nahe.*",
  [25130] = "Das sind etliche Pfund feines, trockenes",
  [25131] = "Schießpulver der besten Machart.*",
  [25132] = "Da werden Sie sich anstrengen müssen, wenn Sie",
  [25133] = "eine davon heben wollen!*",
  [25134] = "Der Pulverstampfer ist ein großer, langer",
  [25135] = "Holzprügel; an einem Ende ist er ein gutes Stück",
  [25136] = "dicker.*",
  [25137] = "Hören Sie auf damit - Sie haben doch noch gar",
  [25138] = "keinen Schießbefehl! Und der Bootsmann schaut",
  [25139] = "dauernd zu Ihnen herüber!*",
  [25140] = "Ochsen-Willy macht plötzlich eine kaum",
  [25141] = "wahrnehmbare Bewegung. Dann grinst er Sie breit",
  [25142] = "an, und hält Ihnen vor die Nase, was er in der",
  [25143] = "Hand hat. Einen großen, rötlich schimmernden",
  [25144] = "Splitter eines Edelsteins!",
  [25145] = "Pocken-Pete lacht. \"Ha! Ochsen-Willy ist der beste",
  [25146] = "Taschendieb, den ich kenne!\"*",
  [25147] = "Ochsen-Willy weicht Ihnen aus. \"Immer ruhig",
  [25148] = "bleiben, Junge!\" sagt er besänftigend. \"Laß mich",
  [25149] = "das Prachtstück erstmal ansehen! Du kannst ja",
  [25150] = "ohnehin nichts mehr damit anfangen! Die Franzosen",
  [25151] = "werden uns bald in Stücke schießen, und da wäre es",
  [25152] = "doch schade...*",
  [25153] = "\"Die Franzosen!\" schreit ein Matrose aufgeregt vom",
  [25154] = "Krähennest herab. \"Ein Strich Steuerbord voraus!\"",
  [25155] = "Plötzlich ist auf der Indian Voyager die Hölle",
  [25156] = "los. Offiziere schreien durcheinander, das Schiff",
  [25157] = "macht einen scharfen Schwenk, Matrosen rennen über",
  [25158] = "Deck, und der Kapitän brüllt mit lauter Stimme:",
  [25159] = "\"Ladet die Kanonen! Und dann Feuer frei! Zeigt's",
  [25160] = "den verdammten Franzosen!\"*",
  [25161] = "\"Was ist?\" brüllt Pocken-Pete durch den Lärm.",
  [25162] = "\"Willst Du nicht die Kanone mit Pulver laden?\" Er",
  [25163] = "humpelt zu den Kanonenkugeln und schickt sich an,",
  [25164] = "eine davon aufzunehmen.*",
  [25165] = "Ein unheilvolles Pfeifen schneidet durch die",
  [25166] = "Luft..... Krawommmmmmm! Der Hauptmast ist",
  [25167] = "getroffen! Takelage regnet herab, der Klüverbaum",
  [25168] = "segelt nach unten.... ohweh, schnell... gehen Sie",
  [25169] = "weg daaaaaaa.....!!!",
  [25170] = "Kraaaaaaach!!!*",
  [25171] = "Los, los! Das Pulver haben Sie jetzt! Machen Sie",
  [25172] = "weiter!*",
  [25173] = "Das Pulver rieselt in den Lauf der Kanone....",
  [25174] = "halt, das ist genug! Kaum sind Sie fertig, zischen",
  [25175] = "schon die ersten Kugeln der Franzosen durch die",
  [25176] = "Luft. Eine schlägt knapp vor dem Schiff ins Wasser",
  [25177] = "und reißt eine schillernde Fontäne hoch.",
  [25178] = "\"Schnell, stampf' das Pulver fest!\" schreit",
  [25179] = "Pocken-Pete, der schon mit einer Kugel",
  [25180] = "bereitsteht.*",
  [25181] = "Plötzlich steht eine Brigg der Franzosen direkt",
  [25182] = "steuerbord längsseits vor Ihnen. \"Aus dem Weg!\"",
  [25183] = "schreit Pete. Trotz seines kaputten, rechten",
  [25184] = "Beines, wegen dem er stark hinkt, hat er schnell",
  [25185] = "die Kanonenkugel in den Lauf gesteckt.",
  [25186] = "Kaum hundertfünfzig Meter entfernt laden auch die",
  [25187] = "Franzosen mit großer Hektik ihre Kanonen nach.",
  [25188] = "\"Los, die Kugel feststopfen!\" ruft Pete.*",
  [25189] = "Ochsen-Willy hält kalt lächelnd seine Zigarre an",
  [25190] = "den Zündschacht der Kanone, und eine Sekunde",
  [25191] = "später.... Wuuuummmmmmm!",
  [25192] = "Die Kugel pfeift über das Wasser... rummmms!",
  [25193] = "Volltreffer - direkt unter der Wasserlinie! Das",
  [25194] = "gegenerische Schiff krängt für einen Moment, die",
  [25195] = "Franzosen würden nur ins Wasser schießen, falls",
  [25196] = "sie nun feuerten.*",
  [25197] = "Andere Kanonen ihres Schiffes donnern los. Aber da",
  [25198] = "richtet sich die französische Brigg wieder auf...",
  [25199] = "\"Ich verschwinde!\" schreit Pocken-Pete. \"Lieber",
  [25200] = "lass' ich mich von den Haifischen fressen! Gleich",
  [25201] = "kommt eine volle Breitseite rüber!\" Er hinkt",
  [25202] = "hektisch zur Reling und im nächsten Augenblick",
  [25203] = "sind er und Ochsen-Willy verschwunden.*",
  [25204] = "Was, Sie auch? Ins Wasser, hier mitten im Ozean?",
  [25205] = "Na, dann viel Spaß! Ab.... über die Reeeeeling....",
  [25206] = "uuuunnd....",
  [25207] = "Plaaatsch!!!*",
  [25208] = "Die französische Brigg verschwindet hinter den",
  [25209] = "Pulverwolken losdonnernder Kanonen. Das Pfeifen",
  [25210] = "der Kugeln klingt wie eine gewaltige, verstimmte",
  [25211] = "Kirchenorgel...... und dann schlägt die volle",
  [25212] = "Breitseite auf der Indian Voyager ein! Und Sie",
  [25213] = "stehen mittendrin, in dem Chaos....",
  [25214] = "Ruuuummmmms!!!*",
  [25215] = "Im Meer",
  [25216] = "Sie befinden sich an einem Ort, dessen wichtigstes",
  [25217] = "Merkmal das Vorhandensein von Wasser, Wasser und",
  [25218] = "nochmals Wasser ist.*",
  [25219] = "Hier kann man nicht schwimmen.*",
  [25220] = "Ein paar hübsche bunte Fische huschen umher.",
  [25221] = "Langsam wird die Luft knapp.*",
  [25222] = "Ein guter Gedanke! Japsend durchbrechen Sie die",
  [25223] = "Wasseroberfläche, und holen ein paarmal hastig",
  [25224] = "Luft.*",
  [25225] = "Uns scheint bedenklich, das Sie die Bedürfnisse",
  [25226] = "Ihres Körpers einfach außer acht lassen! Oder",
  [25227] = "haben Sie etwa Kiemen, um unter Wasser atmen zu",
  [25228] = "können?*",
  [25229] = "Bei allem Respekt, dieses Spiel ist für Menschen",
  [25230] = "gemacht! Wir möchten uns energisch dagegen",
  [25231] = "verwahren, mit Amphibien weiterzuspielen! Um die",
  [25232] = "äußere Form zu wahren, erklären wir Sie hiermit",
  [25233] = "für tot und ertrunken!",
  [25234] = "EN....",
  [25235] = "...oder wollten Sie uns nur auf den Arm nehmen?",
  [25236] = "Sind Sie etwa doch ein Mensch?*",
  [25237] = "Nagut. Akzeptiert. Was jetzt?*",
  [25238] = "Wie Sie wollen.*",
  [25239] = "Fein. Ihre Selbsterhaltungstrieb funktioniert mit",
  [25240] = "kaum merklicher Verzögerung! Endlich bekommen Sie",
  [25241] = "wieder Luft.*",
  [25242] = "Auf dem Meer",
  [25243] = "Hier gibt es immerhin zwei Elemente - Wasser und",
  [25244] = "Luft. Der Gesetze der Schwerkraft leider sind es,",
  [25245] = "die den Gang der Dinge bestimmen: alles, was nicht",
  [25246] = "(lange genug) schwimmen kann, geht unter.*",
  [25247] = "Sie treiben durch weite Wellentäler, und manchmal",
  [25248] = "erreichen Sie einen Kamm. Nicht weit südlich von",
  [25249] = "Ihnen liegt die Indian Voyager im Todeskampf. Das",
  [25250] = "halbe Deck brennt schon, die Kanonen donnern,  die",
  [25251] = "Matrosen brüllen. Die französiche Brigg feuert",
  [25252] = "eine weitere Breitseite auf das englische Schiff",
  [25253] = "ab. Von Pete und Willy hingegen ist nichts zu",
  [25254] = "sehen.*",
  [25255] = "Der mörderische Kampf der beiden Segler strebt",
  [25256] = "seinem Höhepunkt entgegen. Dutzende von",
  [25257] = "Kanonenkugeln pfeifen durch die Luft, peitschen",
  [25258] = "ins Wasser, durchschlagen hölzerne Bordwände. Es",
  [25259] = "ist nur noch eine Frage der Zeit, bis eine",
  [25260] = "Pulverkammer getroffen wird! Sie treiben noch",
  [25261] = "immer gefährlich nahe am Ort der Schlacht.*",
  [25262] = "Eine schwere Salve fegt durch die Luft. Die Indian",
  [25263] = "Voyager hinter Ihnen wird mehrfach getroffen.",
  [25264] = "Keine Sekunde später folgt ein ohrenbetäubendes",
  [25265] = "Krachen. Die Pulverkammer ist getroffen! Tausende",
  [25266] = "von zersplitterten Holzplanken wirbeln durch die",
  [25267] = "Luft. Sie sehen  gerade noch, wie ein mächtiges",
  [25268] = "Bruchstück auf Sie zusegelt...*",
  [25269] = "Zu spät. Ein Stück des Hauptmastes kracht über",
  [25270] = "Ihnen ins Wasser, und schickt Sie hinab in das",
  [25271] = "ewige Vergessen des Meeres.*",
  [25272] = "Puh! Glück gehabt! Kaum sind Sie mit dem Kopf",
  [25273] = "unter der Oberfläche, klatscht eine drei Meter",
  [25274] = "lange, schwere Schiffsplanke über Ihnen auf die",
  [25275] = "See. Unter Wasser kann man gut die Geräusche der",
  [25276] = "aufschlagenden Trümmerstücke hören. Nach einer",
  [25277] = "atemlosen Minute ist es endlich vorüber.*",
  [25278] = "Neben Ihnen treibt eine große Schiffsplanke auf",
  [25279] = "dem Wasser.*",
  [25280] = "Von dem stolzen Segelschiff ist nichts mehr zu",
  [25281] = "sehen. Die fränzösische Brigg dreht eben ab, und",
  [25282] = "nur noch ein paar auf dem Wasser treibende Trümmer",
  [25283] = "legen Zeugnis ab von dem tragischen Schicksal der",
  [25284] = "Indian Voyager und ihrer Besatzung.*",
  [25285] = "Die Schiffsplanke ist etwa drei Meter lang, einen",
  [25286] = "Meter breit und gute zehn Zentimeter dick. Das",
  [25287] = "Holz ist schon ein bißchen morsch, und hat viele",
  [25288] = "Astlöcher. Aber es ist wohl stabil genug, um einen",
  [25289] = "Menschen zu tragen.*",
  [25290] = "Wir möchten Ihnen anraten, erstmal auf die Planke",
  [25291] = "zu klettern. Das bietet sich für einen",
  [25292] = "Schiffbrüchigen, wie Sie es sind, ja wohl an,",
  [25293] = "nicht wahr? Oder dachten Sie, wir lassen das gute",
  [25294] = "Stück hier ganz ohne Sinn und Zweck herumtreiben?*",
  [25295] = "Auf der Schiffsplanke",
  [25296] = "Wenn augenblicklich keine motorisierte Segeljacht",
  [25297] = "verfügbar ist, gibt sich der Ertrinkende auch mit",
  [25298] = "einem ordinären Stück Schiffsplanke zufrieden.",
  [25299] = "Dieses hier ist zum Glück sogar ausreichend groß,",
  [25300] = "um sich darauf auszustrecken. Wer fragt da schon,",
  [25301] = "ob das Holz ein bißchen morsch ist, oder gar",
  [25302] = "Astlöcher hat?*",
  [25303] = "In einem großen Astloch in der Mitte der Planke",
  [25304] = "steckt eine Holzstange.*",
  [25305] = "Von der Holzstange hängt ein schlaffes Stück",
  [25306] = "Segeltuch herab.*",
  [25307] = "An der Holzstange ist mit einer Kordel ein",
  [25308] = "Billardstock befestigt.*",
  [25309] = "Auf der Schiffsplanke ist ein behelfsmäßiges Segel",
  [25310] = "errichtet. Der leichte Nordwestwind bläht das",
  [25311] = "Segeltuch, und die Schiffsplanke bewegt sich",
  [25312] = "stetig in Richtung Osten.*",
  [25313] = "In den Ritzen des Holzes hat sich, nach Ihrer",
  [25314] = "Segeltour, hier und da eine dünne Schicht Meersalz",
  [25315] = "angesammelt.*",
  [25316] = "Es ist nichts als ganz gewöhnliches Meersalz. Wohl",
  [25317] = "einer der Rohstoffe auf dieser Welt, der uns",
  [25318] = "niemals ausgehen wird.*",
  [25319] = "Na, ob man das einfach so... okay!",
  [25320] = "Mit den Fingernägeln läßt es sich herauskratzen.",
  [25321] = "Sie besitzen nun eine winzige Menge Meersalz.*",
  [25322] = "Unweit von Ihnen treibt eine Holzstange im Wasser.",
  [25323] = "Wohl ein trauriges Überbleibsel der einst stolzen",
  [25324] = "'Indian Voyager'.*",
  [25325] = "Ein zerrissener Fetzen Segeltuch dümpelt dort",
  [25326] = "drüben auf den Wellen.*",
  [25327] = "Moment - jetzt, von erhöhtem Standpunkt aus... ja,",
  [25328] = "wenn die Schiffsplanke auf einem Wellenkamm",
  [25329] = "treibt... dort, weit im Südosten, scheint ein",
  [25330] = "winziges Eiland im Meer zu liegen!*",
  [25331] = "Was für ein Riesenglück! Das Eiland ist schon ein",
  [25332] = "gutes Stück nähergekommen!*",
  [25333] = "Das Schicksal meint es gut mit Ihnen. Nur noch",
  [25334] = "ein halbes dutzend Meilen trennen Sie vom Strand",
  [25335] = "des kleines Eilands.*",
  [25336] = "Sie verteilen sich über die ganze Schiffsplanke.",
  [25337] = "Irgendwo in der Nähe der Mitte ist ein besonders",
  [25338] = "Großes.*",
  [25339] = "Der hinderliche Rest eines Aststücks befindet sich",
  [25340] = "in dem Loch. Das Loch selbst hat einen Durchmesser",
  [25341] = "von vielleicht sieben Zentimetern.*",
  [25342] = "In dem Arschloch steckt eine hölzerne Stange.*",
  [25343] = "Aber - dann dringt doch Wasser ein, und das Ding",
  [25344] = "geht unt...",
  [25345] = "ach, Quatsch. Ihre Idee ist okay. Aber mit was",
  [25346] = "wollen Sie das tun?*",
  [25347] = "Hauruck... autsch! Wenn Sie so weitermachen,",
  [25348] = "werden Sie sich den Finger brechen!*",
  [25349] = "Das Aststück sitzt zu fest. Wollen Sie es nicht",
  [25350] = "mit etwas anderem probieren?*",
  [25351] = "Das klappt! Mit einem nassen - Plopp! -",
  [25352] = "verschwindet das Aststück in den Tiefen des",
  [25353] = "Meeres.*",
  [25354] = "Das klappt nicht. Das Astloch ist viel zu groß.*",
  [25355] = "Die Stange ist etwa zweieinhalb Meter lang, etwas",
  [25356] = "krumm und hat einen Durchmesser von gut sieben",
  [25357] = "Zentimetern.*",
  [25358] = "Es sind noch etwa zwei Quadratmeter brauchbarer",
  [25359] = "Segelfläche.*",
  [25360] = "Haben Sie gar keine Angst? Hier schwimmen viele",
  [25361] = "Tote im Meer!*",
  [25362] = "Gleich neben Ihnen treibt die übel zugerichtete",
  [25363] = "Leiche eines armen Seemannes... oh nein!!!",
  [25364] = "Haie! Was für ein fataler Fehler! Durch die vielen",
  [25365] = "Toten wurde eine Unzahl von Haifischen angezogen.",
  [25366] = "Schnell... da kommt schon eine riesiger Hai",
  [25367] = "angeschossen... los, zurück auf die Schiffsplanke",
  [25368] = "mit Ihnen....!!!*",
  [25369] = "Zu spät... das Untier ist schon da! Für einen",
  [25370] = "kurzen Moment spüren Sie eine fürchterliche",
  [25371] = "Zahnreihe in Ihrer Seite... und dann ist auch",
  [25372] = "schon alles vorbei!*",
  [25373] = "Das wäre ihr sicherer Tod! Das Salz im Wasser",
  [25374] = "würde Sie entsetzlich durstig machen. Soviel",
  [25375] = "könnten Sie gar nicht trinken, um den",
  [25376] = "nachfolgenden Durst auszugleichen. Zuletzt würden",
  [25377] = "Sie, wie man weiß, wegen dem vielen Salz an",
  [25378] = "Herzversagen sterben.*",
  [25379] = "Das ist ein Stück von ihnen entfernt. Wie wollen",
  [25380] = "Sie denn dorthin kommen?*",
  [25381] = "Mit den bloßen Händen? Nagut. Es wird schon gehen.",
  [25382] = "Dann mal munter los... Fein. Nach ein paar Minuten",
  [25383] = "haben Sie es geschafft. Direkt vor Ihnen treibt",
  [25384] = "die Holzstange im Wasser.*",
  [25385] = "Prima. Nach ein paar Minuten haben Sie es",
  [25386] = "geschafft. Direkt vor Ihnen treibt das zerrissene",
  [25387] = "Segeltuch im Wasser.*",
  [25388] = "Aaaa-ha! Sie haben etwas vor! Gut, die Stange",
  [25389] = "steckt nun in dem Astloch.*",
  [25390] = "Hmm. Das Segeltuch hängt schlaff von der Stange",
  [25391] = "herab.*",
  [25392] = "Der Wind weht sanft von Nordwesten.*",
  [25393] = "Na, das wird aber nichts Gescheites! Versuchen",
  [25394] = "Sie lieber was anderes!*",
  [25395] = "Nun, das ist sicher keine schlechte Idee - aber",
  [25396] = "wie wollen Sie das dort festmachen? Mit Spucke?*",
  [25397] = "Das ist ein ziemlich dickes und steifes Seil.",
  [25398] = "Irendwie klappt das nicht. Der Billardstock",
  [25399] = "rutscht immer wieder 'runter.*",
  [25400] = "Fein, das geht! Sie haben nun ein hübsches Kreuz",
  [25401] = "auf Ihrer Schiffsplanke errichtet. Sie könnten",
  [25402] = "glatt eine heilige Messe abhalten. Leider sind die",
  [25403] = "Haifische hier äußerst unchristliche Gesellen.*",
  [25404] = "Endlich ist die Tat vollbracht! Das Stück",
  [25405] = "Segeltuch fängt den Wind, und ihre Schiffsplanke",
  [25406] = "nimmt gute Fahrt auf. Es geht schnurstracks nach",
  [25407] = "Südosten. Eine halbe Stunde vergeht, und nun",
  [25408] = "können Sie sicher sein: dort ist tatsächlich ein",
  [25409] = "kleines Eiland!*",
  [25410] = "Eine fabelhafte Idee! Ihr Gefährt verliert rasch",
  [25411] = "an Fahrt, und dümpelt schließlich antriebslos im",
  [25412] = "Wasser.*",
  [25413] = "Was für eine sensationell dämliche Idee! Ihre",
  [25414] = "Schiffsplanke segelt ohne Sie davon, und ist bald",
  [25415] = "außer Reichweite.*",
  [25416] = "Ihre Schiffsplanke strebt unaufhaltsam dem Ziel",
  [25417] = "zu. Nach einiger Zeit liegt eine kleine Insel",
  [25418] = "zum Greifen nahe vor Ihnen. Ein Wald aus Palmen",
  [25419] = "und Gestrüpp umgibt einen seltsam geformten,",
  [25420] = "mächtigen Felsen, der in der Inselmitte steht.",
  [25421] = "Wenige Minuten später knirscht Ihre Schiffsplanke",
  [25422] = "auf den feinen, weißen Sand des Inselstrandes.*",
  [25423] = "Inselstrand - Westseite",
  [25424] = "Diese Insel ist nur klein, aber ein wahrhaft",
  [25425] = "idyllisches Fleckchen. Hinter einem schmalen,",
  [25426] = "weißen Sandstrand, an den sanft die grünen Wellen",
  [25427] = "des Ozeans spülen, beginnt ein dichter Urwald. Im",
  [25428] = "Inneren der Insel strebt ein enormer, grauer",
  [25429] = "Felskegel in den tiefblauen Himmel auf.*",
  [25430] = "Am Strand liegt eine Schiffsplanke.*",
  [25431] = "Das Dickicht ist derartig dicht... nein, leider",
  [25432] = "ist hier kein Durchkommen!*",
  [25433] = "Der Felskegel ist seltsam geformt, und oben",
  [25434] = "ziemlich abgeflacht. Er ragt gute zweihundert",
  [25435] = "Meter in die Höhe.*",
  [25436] = "Es handelt sich zumeist um dorniges Dickicht und",
  [25437] = "eine Unzahl von Palmen verschiedenster Gattungen.",
  [25438] = "Nur eine einzige, echte Kokospalme ist darunter.*",
  [25439] = "Es handelt sich zumeist um dorniges Gestrüpp und",
  [25440] = "eine Unzahl von Palmen verschiedenster Gattungen.",
  [25441] = "Nur eine einzige, echte Kokospalme ist darunter.*",
  [25442] = "Was soll es da schon geben? Es handelt sich um ein",
  [25443] = "unüberschaubares Pflanzengewirr aus Ranken,",
  [25444] = "Zweigen und Sträuchern.*",
  [25445] = "Ah! Sie haben eine gute Nase, was? Ja, da wächst",
  [25446] = "tatsächlich Rosmarin! Ein ungewöhnlicher Ort für",
  [25447] = "diese Pflanze, aber dort steht sie!*",
  [25448] = "ROSMARIN (lat. ros marinus, eigtl. \"Meertau\")",
  [25449] = "zählt zur Gattung der Lippenblütler. 60 - 150 cm",
  [25450] = "hoher Halbstrauch; Charakterpflanze der trockenen",
  [25451] = "Machhia im Mittelmeerraum... Blätter werden als",
  [25452] = "Küchengewürz sowie zur Herstellung von Parfüm",
  [25453] = "verwendet...",
  [25454] = "Da staunen Sie, was?*",
  [25455] = "Eine einzige, letzte Kokosnuß hängt dort oben.*",
  [25456] = "Das ist nicht so einfach! Ein Südsee-Insulaner",
  [25457] = "würde geradezu dort hinauf rennen, aber Sie?",
  [25458] = "Vielleicht gibt es noch eine andere Möglichkeit,",
  [25459] = "diese Kokosnuß dort herunter zu holen. Sie, als",
  [25460] = "Europäer, würden sich ohne Frage Hände, Füße und",
  [25461] = "Knie zerschinden! Momentan können wir uns nicht",
  [25462] = "vorstellen, daß Ihnen das irgendwie weiterhelfen",
  [25463] = "könnte. Oder etwa doch? Wollen Sie es dennoch",
  [25464] = "tun?*",
  [25465] = "Tja. Vielleicht finden Sie ja noch einen anderen",
  [25466] = "Weg, an diese Kokosnuß dort oben zu kommen!*",
  [25467] = "Na, ob Sie das schaffen...?",
  [25468] = "Heee... haben Sie mal Baseball gespielt? Sie holen",
  [25469] = "ja aus wie ein...",
  [25470] = "TOCK!",
  [25471] = "Bravo - eine reife Leistung! Die Kokosnuß ist",
  [25472] = "unten!*",
  [25473] = "Nun denn, wenn Sie unbedingt wollen - dann los!",
  [25474] = "Eins und zwei und hopp!... noch ein Stück... immer",
  [25475] = "tapfer bleiben... autsch!... jetzt haben Sie eine",
  [25476] = "schmerzhafte Abschürfung am Knie! Trotzdem gehts",
  [25477] = "weiter... die Hände werden wund... auch die",
  [25478] = "Füße... ohweh... noch ein paar Meter... puuuh,",
  [25479] = "jetzt sind Sie endlich oben.*",
  [25480] = "Auf der Kokospalme",
  [25481] = "Aus der schönen Aussicht wird nichts. Große",
  [25482] = "Palmblätter versperren die Sicht.*",
  [25483] = "Vor Ihnen hängt eine einsame, reife Kokosnuß.*",
  [25484] = "Hier gibt es leider keine Kokosnüsse mehr!*",
  [25485] = "Sie machen einen immer wieder darauf aufmerksam,",
  [25486] = "daß Sie ein Kind der westlichen Zivilisation sind.",
  [25487] = "Glauben Sie denn, daß eine Kokosnuß pflücken kann",
  [25488] = "wie eine reife Brombeere? Sie hängt am Baum, als",
  [25489] = "wäre sie festgeschweißt!*",
  [25490] = "Was würden Sie wohl ohne Ihr Samuraischwert tun?",
  [25491] = "Okay, dann... ooooh! Schon liegt die Kokosnuß",
  [25492] = "unten am Strand.*",
  [25493] = "Eine schöne, reife Kokosnuß. Die grüne Schale ist",
  [25494] = "beim Sturz von der Palme bereits abgeplatzt.*",
  [25495] = "Ohweh! Sie haben eine Menge Abschürfungen und",
  [25496] = "Schnitte an Händen, Knien und Füßen. Ein Glück,",
  [25497] = "daß es hier keine Polizei gibt. Man würde Sie",
  [25498] = "glatt als Zombie verhaften!*",
  [25499] = "Inselstrand - Nordseite",
  [25500] = "Dies ist die Nordseite der Insel. Hier reichen die",
  [25501] = "Palmen bis ans Wasser, hinter ihnen, Richtung",
  [25502] = "Osten, türmt sich ein steiles Stück Felsküste auf.",
  [25503] = "Die Felsen sind zwar nicht hoch, es reicht aber,",
  [25504] = "um den Weg um die Insel herum zu versperren.*",
  [25505] = "Die Felsküste ist an die zehn Meter hoch, und",
  [25506] = "steigt glatt und fast senkrecht auf. Oben scheint",
  [25507] = "es ein paar Vogelnester zu geben. Hier unten ragt",
  [25508] = "ein kleiner Felsen ein gutes Stück nordwärts ins",
  [25509] = "Wasser hinein, das vor dem Strand sehr flach ist.*",
  [25510] = "Nun - was soll es daran besonderes geben... ach,",
  [25511] = "das meinen Sie? Ja, es scheint, als könnte man um",
  [25512] = "den Felsen herum noch ein Stück weiter nach Norden",
  [25513] = "ins Wasser hinein waten. Vielleicht gibt es dort",
  [25514] = "ein paar schmackhafte Krabben?*",
  [25515] = "Wieder einmal kriegen Sie nasse Füße. Aber... um",
  [25516] = "Himmels Willen...was ist denn das...?*",
  [25517] = "Hinter dem Felsen",
  [25518] = "Hier huschen tatsächlich ein paar Krabben zwischen",
  [25519] = "den im Wasser liegenden Steinen und Felsbrocken",
  [25520] = "umher...*",
  [25521] = "Aber... dort, am Rande des Felsens, liegt eine",
  [25522] = "reglose Gestalt im Wasser!*",
  [25523] = "Ein paar Meter vor dem Ufer dümpelt eine Seekiste",
  [25524] = "im flachen Wasser umher.*",
  [25525] = "Es ist eine recht große Kiste, aus altem,",
  [25526] = "schwärzlichem Holz; sie ist mit Eisenbändern",
  [25527] = "umschlungen, die mit Eisenstiften vernagelt sind.",
  [25528] = "Eine recht stabile Angelegenheit. Vorn drauf ist",
  [25529] = "ein Schlüsselloch zu sehen.*",
  [25530] = "Der Deckel ist zu.*",
  [25531] = "Der Deckel ist offen.*",
  [25532] = "Die Kiste ist voll mit staubtrockenem, grauen",
  [25533] = "Pulver. Ob das Schießpulver ist?*",
  [25534] = "Es ist ein graues Pulver, mehr ist daran nicht zu",
  [25535] = "entdecken.*",
  [25536] = "Um Himmels Willen - und wenn das Schießpulver ist?",
  [25537] = "Sie würden in die Luft fliegen! Wollen Sie das",
  [25538] = "wirklich wagen?*",
  [25539] = "Achtuuuuuuuung.....!!!",
  [25540] = "Hm.",
  [25541] = "Nichts passiert. Also Schießpulver scheint das",
  [25542] = "Gottseidank nicht zu sein!*",
  [25543] = "Vielleicht ist das besser so. Das Riskio ist",
  [25544] = "schließlich nicht von der Hand zu weisen!*",
  [25545] = "Urks. Ist das Ihr Ernst? Wenn das Schießpulver",
  [25546] = "ist... nun - wir können nicht sicher sagen, ob",
  [25547] = "Schießpulver ungiftig ist! Wollen Sie das wirklich",
  [25548] = "tun?*",
  [25549] = "Oh Gott! Sie Wahnsinniger.... nein... es...",
  [25550] = "Da!",
  [25551] = "Sehen Sie... das Zeug... uuuuhhh! Es brennt wie",
  [25552] = "Feuer... es ist bestimmt giftig... es... es...",
  [25553] = "ES IST PFEFFER!",
  [25554] = "Ach herrje! Sie haben eine Kiste voll Pfeffer",
  [25555] = "entdeckt!*",
  [25556] = "Es sind... kann das sein? 144 Eisenstifte! Na",
  [25557] = "sowas!? Das muß wirklich ein Zufall sein. Wie soll",
  [25558] = "denn DIESE Kiste hierher kommen???*",
  [25559] = "Um Himmels Willen... als Sie DIESEN Stift",
  [25560] = "hineindrücken... spreizt sich - Twoooiiinng - das",
  [25561] = "neunte Eisenband ab, und dahinter wird ein kleiner",
  [25562] = "Hohlraum sichtbar! Das kann doch nicht wahr sein!*",
  [25563] = "In dem Hohlraum stecken ein kleiner Schlüssel und",
  [25564] = "ein Kärtchen.*",
  [25565] = "Es ist ein kleiner Schlüssel, auf dem das Datum",
  [25566] = "10. September 1437 eingraviert ist!*",
  [25567] = "Oh! Das ist wohl Werbung! Auf dem Kärtchen steht:",
  [25568] = "\"Die ersten zehn Einsender der Bedeutung des",
  [25569] = "Datums, das auf dem Schlüssel steht, erhalten von",
  [25570] = "Software 2000 je ein ÜBERRASCHUNGSGESCHENK!",
  [25571] = "Der Rechtsweg ist ausgeschlossen!*",
  [25572] = " *",
  [25573] = "Oh nein! Durch das Schlüsselloch kann man eine",
  [25574] = "kleine, miniaturisierte Flußlandschaft... nein!",
  [25575] = "Stimmt nicht. Das war wohl nur eine Halluzination.",
  [25576] = "In Wirklichkeit sieht man nichts, der Blick durch",
  [25577] = "das Schlüsselloch offenbart nur finsterste",
  [25578] = "Schwärze. So ein Glück!*",
  [25579] = "Ja, der Schlüssel passt! Klick - das Schloß ist",
  [25580] = "offen! Der noch geschlossene Deckel ruht",
  [25581] = "erwartungsvoll auf der Kiste!*",
  [25582] = "Sie wollen die Kiste gewaltsam öffnen? Das ist",
  [25583] = "aber ein schwieriges Unterfangen - sie sieht sehr",
  [25584] = "stabil aus!",
  [25585] = "Also dann, probieren wir's!",
  [25586] = "Hauruck... und Zack... Knirsch... und nochmal...",
  [25587] = "ja, der Deckel gibt schon nach... hauen Sie",
  [25588] = "nochmal auf das Schloß... Kracks!",
  [25589] = "Bravo, Sie habens tatsächlich geschafft!*",
  [25590] = "Die ist knapp außer Reichweite! Und - oje, da ist",
  [25591] = "eine ganze Kolonie Seeigel auf dem felsigen Grund",
  [25592] = "zu erkennen! Wie wollen Sie da jemals an die Kiste",
  [25593] = "kommen?*",
  [25594] = "Die Seeigel haben sich auf dem felsigen Grund",
  [25595] = "festgekrallt, und manchmal scheint es, als würden",
  [25596] = "ein paar davon höhnisch zu Ihnen heraufgrinsen!*",
  [25597] = "Ah! Ihr Lieblingswerkzeug! Ja, mit einer",
  [25598] = "Enterstange geht das freilich! Also... dann angeln",
  [25599] = "wir mal danaaaach....",
  [25600] = "So, geschafft! Die Kiste schwimmt nun direkt vor",
  [25601] = "Ihnen.*",
  [25602] = "Hui - die ist aber schwer!",
  [25603] = "Also dann... hauruck... ziehn wir sie an Land...",
  [25604] = "ein Wunder, daß sie überhaupt schwamm... so!",
  [25605] = "Fertig. Ihre Kiste steht nun auf dem Sandstrand!*",
  [25606] = "Hier gibt es aber auch etwas Trauriges: der",
  [25607] = "Sandhügel, unter dem Ochsen-Willy begraben liegt!*",
  [25608] = "Oh nein, es ist Ochsen-Willy! Er ist... nein, ein",
  [25609] = "Hauch von Leben scheint noch in ihm zu sein!",
  [25610] = "Sein ganzer Körper ist mit scheußlichen Wunden",
  [25611] = "bedeckt - Wunden, die sehr seltsam aussehen! Als",
  [25612] = "er Sie erkennt, beginnt sein Leib hilflos zu",
  [25613] = "zucken. Es scheint, als habe er Angst vor Ihnen!*",
  [25614] = "\"Du bist es also!\" krächzt er dann kraftlos. Ein",
  [25615] = "dünner Blutfaden läuft aus seinem Mundwinkel.",
  [25616] = "\"Kein Wunder, daß man Dich hier trifft, auf dieser",
  [25617] = "verfluchten Insel! Aber Du kannst beruhigt sein,",
  [25618] = "Dein Edelstein ist schon wieder bei Deinen",
  [25619] = "Freunden!\" Willy hustet röchelnd. Sein Kopf sinkt",
  [25620] = "zurück. \"Fahr zur Hölle!\" flüstert er noch. Dann",
  [25621] = "rührt er sich nicht mehr.*",
  [25622] = "Er hat nichts mehr bei sich. Seine Kleider sind",
  [25623] = "durchweicht.*",
  [25624] = "Es sind unzählige kleine Wunden, die fast den",
  [25625] = "ganzen Körper bedecken. Es ist grauenvoll!*",
  [25626] = "Also hören Sie mal, das grenzt ja an",
  [25627] = "Leichenfledderei! Das lassen wir lieber, gell?*",
  [25628] = "Eine Geste, die darauf hindeutet, daß Sie ein",
  [25629] = "großes Herz haben! Nach einer Stunde sind Sie",
  [25630] = "fertig. Neben dem Felsen deutet ein Sandhügel auf",
  [25631] = "das Grab von Ochsen-Willy hin - der durch etwas",
  [25632] = "Unsagbares umkam, etwas, daß vielleicht auch Sie",
  [25633] = "töten könnte!*",
  [25634] = "An dem Sandhügel ist nichts Besonderes zu",
  [25635] = "entdecken, sieht man einmal davon ab, daß sich der",
  [25636] = "arme Ochsen-Willy, der darunter begraben liegt,",
  [25637] = "sicher etwas anderes vorgestellt hatte, als hier,",
  [25638] = "auf einer einsamen Insel, fernab der Zivilisation,",
  [25639] = "im Sand verscharrt zu werden.*",
  [25640] = "Inselstrand - Südseite",
  [25641] = "An dieser Seite der Insel liegt eine malerische,",
  [25642] = "kleine Bucht. Drüben, am östlichen Ende der Bucht,",
  [25643] = "ragen hingegen steile Felsen ins Wasser, dort",
  [25644] = "herrscht eine kräftige Brandung. Trotzdem ein",
  [25645] = "Paradies für einen, der Ruhe und Einsamkeit",
  [25646] = "sucht.*",
  [25647] = "Das Wasser in der Bucht ist nicht eben flach;",
  [25648] = "drüben, am Strand, brechen sich die Wellen in",
  [25649] = "wilden Kaskaden.*",
  [25650] = "Sollten Sie vorhaben, dort, auf dem Wasserweg, die",
  [25651] = "Steilküste zu überwinden - das wird nichts werden.",
  [25652] = "Die Brandung ist viel zu stark.*",
  [25653] = "Hier wird der Zugang zum Osten der Insel, ebenso",
  [25654] = "wie an der Nordspitze, durch steile Felsen",
  [25655] = "vereitelt.*",
  [25656] = "In der Bucht",
  [25657] = "Einen schöneren Platz wird man auf der Welt kaum",
  [25658] = "finden können. So idyllisch und einsam... oh!",
  [25659] = "Aber... dort steht ja eine Blockhütte! Dies ist",
  [25660] = "offenbar doch kein so weltabgeschiedener Ort, wie",
  [25661] = "zuerst vermutet.*",
  [25662] = "Sie ist geradezu winzigklein, aber wozu sollte sie",
  [25663] = "auch besonders groß sein - hier, wo man ohnehin",
  [25664] = "die meiste Zeit unter freiem Himmel verbringen",
  [25665] = "wird?*",
  [25666] = "Die Tür ist zu.*",
  [25667] = "Die Tür ist geöffnet.*",
  [25668] = "In der Blockhütte",
  [25669] = "Hier ist es ziemlich finster; das einzige Fenster",
  [25670] = "ist vernagelt. Nur durch die Ritzen im Holz",
  [25671] = "dringen schmale Streifen Sonnenlicht. Drüben, an",
  [25672] = "der Wand, steht eine hölzerne Pritsche, ansonsten",
  [25673] = "gibt es hier nur einen Tisch.*",
  [25674] = "Es ist ein selbstgezimmerter Tisch aus Holz.*",
  [25675] = "Es ist Mittag - die Sonne steht hoch und wirft",
  [25676] = "durch die schmalen Ritzen zwischen den Holzbalken",
  [25677] = "schmale Streifen von Licht in die Hütte. Sie",
  [25678] = "werfen kuriose, helle Flecken in die dunklen Ecken",
  [25679] = "der Hütte.*",
  [25680] = "Es ist schon früher Nachmittag geworden - die",
  [25681] = "Sonne ist etwas weiter gewandert und wirft durch",
  [25682] = "die Ritzen zwischen den Holzbalken schmale",
  [25683] = "Streifen von Licht in die Hütte. Sie werfen",
  [25684] = "mitunter kuriose, helle Flecken in die dunklen",
  [25685] = "Winkel der Hütte.*",
  [25686] = "Nun, was soll es da geben... ah! Sie haben eine",
  [25687] = "scharfe Beobachtungsgabe! Dort, im dunkelsten",
  [25688] = "Winkel, unter der Pritsche, fällt nun ein",
  [25689] = "Lichtfleck hin, und beleuchtet - eine uralte",
  [25690] = "Maggiflasche! Na, wie die wohl hierherkomt?*",
  [25691] = "Nun - es ist eine Flasche mit Suppenwürze, von der",
  [25692] = "gleichen Art wie das legendäre Maggi. (Keine",
  [25693] = "Schleichwerbung!) Hm. Ein anderer Abenteurer",
  [25694] = "scheint sie hier wohl vergessen zu haben. Zu",
  [25695] = "Zeiten historischer Seeschlachten dürfte es derlei",
  [25696] = "Suppenwürze in Flaschen kaum gegeben haben.*",
  [25697] = "Außerdem ist sie leer, oder besser: fast leer. Ein",
  [25698] = "letzter Tropfen Suppenwürze fristet am Grund der",
  [25699] = "Maggiflasche ihr Dasein.*",
  [25700] = "Aber leider ist sie vollends leer.*",
  [25701] = "Nun - Ihre Absicht in Ehren, aber wo wollen Sie",
  [25702] = "die Suppenwürze hinein füllen? Da müssten Sie sich",
  [25703] = "erst ein geeignetes Gefäß beschaffen!*",
  [25704] = "Ah - das geht! Schwupps! Der Tropfen Suppenwürze",
  [25705] = "befindet sich nun in dem Kronenkorken!*",
  [25706] = "Da liegt ein Blatt Papier auf dem Tisch, und",
  [25707] = "obendrauf ein großer Stein, offenbar, um das",
  [25708] = "Papier deutlich zu markieren, und es",
  [25709] = "festzuhalten.*",
  [25710] = "Es handelt sich um einen faustgroßen Stein aus",
  [25711] = "Stein.*",
  [25712] = "Da stehen ein paar handgeschriebene Sätze drauf:",
  [25713] = "\"Professor Browne!",
  [25714] = "Diese Insel ist gefährlich. Kehren Sie um, und",
  [25715] = "vergessen Sie mich! Kehren Sie um Gottes Willen",
  [25716] = "um, und gehen Sie nicht in diesen schrecklichen",
  [25717] = "Urwald hinein! Leben Sie wohl!",
  [25718] = "Admiral Atterson.\"*",
  [25719] = "Auch hier ist das Dickicht derartig dicht... nein,",
  [25720] = "so einfach ist da kein Durchkommen!*",
  [25721] = "Diesmal haben Sie Glück! Nach ein paar beherzten",
  [25722] = "Hieben wird hinter fallendem Gestrüpp ein schmaler",
  [25723] = "Pfad nach Norden sichtbar.*",
  [25724] = "Am Palisadenzaun",
  [25725] = "Hier wird der Weg nach Norden durch einen jäh",
  [25726] = "aufragenden, riesenhaften Palisadenzaun versperrt,",
  [25727] = "der von Westen nach Osten verläuft. Der dichte",
  [25728] = "Wald, der in der Nähe der Küste vorherrschte, ist",
  [25729] = "hier einem Gewirr von Dornenbüschen und wilden",
  [25730] = "Brombeerhecken gewichen, die zwischen schlanken",
  [25731] = "Birken und Eschen jeden Zentimeter des Bodens",
  [25732] = "eingenommen haben.*",
  [25733] = "Der Zaun ist aus mächtigen Baumstämmen errichtet,",
  [25734] = "und ragt weit in die Höhe. Er zieht sich in ost-",
  [25735] = "westlicher Richtung am Waldrand entlang. Was",
  [25736] = "dahinter wartet, kann man nicht sagen. Nur der",
  [25737] = "seltsame Geruch, der herüberdringt, legt einige",
  [25738] = "Vermutungen nahe.*",
  [25739] = "Okay - probieren wir's. Uuuunnd... zack! Mist! Der",
  [25740] = "Haken ist abgerutscht! Nochmal.... und...",
  [25741] = "Tock... kläng!",
  [25742] = "Verflixt, er ist schon wieder unten! Er ist",
  [25743] = "offensichtlich zu klein, um sich dort oben",
  [25744] = "irgendwie verhaken zu können. So ein Pech!*",
  [25745] = "Ein süßlicher, schwerer Duft hängt in der Luft,",
  [25746] = "ein Duft, der auf dem Weg hierher bislang nicht zu",
  [25747] = "verspüren gewesen war - er muß von jenseits des",
  [25748] = "Palisadenzaunes stammen. Er mutet an wie von",
  [25749] = "riesigen, urzeitlichen Blüten; Pflanzen von",
  [25750] = "enormer Größe - Ihre Düfte wirken allein schon",
  [25751] = "hier so betörend und betäubend, daß sie einem",
  [25752] = "ahnungslosen Wanderer vielleicht gefährlich werden",
  [25753] = "könnten!*",
  [25754] = "Es handelt sich um Dornenbüsche unbekannter Art -",
  [25755] = "aber sie sehen geradezu gefährlich aus! Die",
  [25756] = "untersten Ranken besitzen Dornen so dick und lang",
  [25757] = "wie Dolche - da sollte man lieber nicht",
  [25758] = "hineinfallen!*",
  [25759] = "Die Dornen sind spitz und lang wie Dolche. Ganz",
  [25760] = "unten am Schaft, besitzen sie einen Wulst.*",
  [25761] = "So leicht geht das nicht! Die Dornen sind dick und",
  [25762] = "kräftig, die kann man nicht so einfach pflücken",
  [25763] = "wie Butterblumen!*",
  [25764] = "Sie säbeln und säbeln - leider erfolglos. Die",
  [25765] = "Dornen sind steinhart und kräftig!*",
  [25766] = "Das geht! Bravo! Die Dornen sind zwar steinhart",
  [25767] = "und spitz wie Dolche, aber sie sind - krach! -",
  [25768] = "ganz unten am Schaft - kracks! - mit einem",
  [25769] = "geeigneten Werkzeug gut abzuschlagen. Leider gibt",
  [25770] = "es hier nicht allzuviele davon... nun, etwa zwei",
  [25771] = "Dutzend haben Sie zusammengekriegt.*",
  [25772] = "Die Baumstämme sind dick, gute 15 Meter hoch und",
  [25773] = "oben zugespitzt. Bis auf ein paar winzige Ritzen",
  [25774] = "sind sie fest aneinandergefügt und bilden ein so",
  [25775] = "gut wie unüberwindliches Hindernis.*",
  [25776] = "Allerdings stecken hier eine Anzahl von großen,",
  [25777] = "kräftigen Dornen im Holz des Palisadenzaunes -",
  [25778] = "sieht so aus, als habe sich hier jemand eine",
  [25779] = "behelfsmäßige Leiter gebaut!*",
  [25780] = "Da gibt es tatsächlich ein paar Ritzen, die breit",
  [25781] = "genug sind, um einen Blick hindurch auf die andere",
  [25782] = "Seite des Zauns zu werfen! Dort drüben herrscht",
  [25783] = "ein unüberschaubar dichtes Gewirr von riesigen",
  [25784] = "Pflanzen, und ihre betörenden Blütendüfte sickern",
  [25785] = "selbst durch die schmalen Ritzen zwischen den",
  [25786] = "Stämmen.*",
  [25787] = "Ah! Was für eine gewitzte Idee! Sie wollen sich",
  [25788] = "eine Leiter bauen, was? Gut, probieren wir's...",
  [25789] = "Zack! Der erste Dorn sitzt, uuund... zack! Der",
  [25790] = "zweite auch. Noch einen, ein Stück weiter oben....",
  [25791] = "ja! Und jetzt hinauf! Ein kleiner Klimmzug, und",
  [25792] = "immer weiter... na, das klappt ja prima!",
  [25793] = "Nach einigen Minuten haben Sie's geschafft.*",
  [25794] = "Auf dem Palisadenzaun",
  [25795] = "Von hier droben hat man eine gute Aussicht. Zwei",
  [25796] = "gute Steinwürfe weit entfernt liegt Richtung",
  [25797] = "Norden der Fuß des großen Felskegels. Bis dorthin",
  [25798] = "allerdings gilt es, ein ungewöhnlich dichten",
  [25799] = "Dschungel zu durchdringen. Wenn man erstmal unten",
  [25800] = "ist!*",
  [25801] = "Auf welcher Seite wollen Sie runter? Nach Innen,",
  [25802] = "zur Inselmitte - oder nach Außen, dorthin, wo Sie",
  [25803] = "hergekommen sind? (z.B.:>Klettere innen runter)*",
  [25804] = "Zum Glück haben Sie noch genügend Dornen. Nach",
  [25805] = "einigen Minuten haben Sie's geschafft.*",
  [25806] = "Am Palisadenzaun - Innenseite",
  [25807] = "Schon hier, direkt am Palisadenzaun, herrscht das",
  [25808] = "urzeitliche Chaos des Dschungels vor. Überall gibt",
  [25809] = "es verfilztes Strauchgewirr, wild wuchernde",
  [25810] = "Vegetation und riesige Blütenblätter.*",
  [25811] = "Es handelt sich um allerlei Pflanzenzeugs; am",
  [25812] = "auffälligsten ist wohl noch der wilde Oregano, der",
  [25813] = "hier überall wächst, und einen aromatischen Duft",
  [25814] = "verströmt.*",
  [25815] = "Es handelt sich dabei um eine Strauchpflanze, die",
  [25816] = "man auch den \"Gemeinen Dost\" nennt, und die",
  [25817] = "zahlreiche, kleine Öldrüsen besitzt, aus denen der",
  [25818] = "aromatische Duft stammt.*",
  [25819] = "Die Pracht der Farben und Formen in dem",
  [25820] = "urzeitlichen Dschungel ist gewaltig. Überall ist",
  [25821] = "ist dichtes Gestrüpp, welches weiters Vordringen",
  [25822] = "nahezu unmöglich macht.*",
  [25823] = "Die Blütenblätter sind teilweise riesiggroß - und",
  [25824] = "verströmen einen derart betäubenden Duft, daß...",
  [25825] = "einem gaaanz schwummrig wird...*",
  [25826] = "Die Blütendüfte erzeugen aus dieser Nähe schon",
  [25827] = "langsam gehöriges Kopfweh.*",
  [25828] = "Am Fuße eines Felsens",
  [25829] = "Hier wird die Barriere des Palisadenzaunes durch",
  [25830] = "einen großen Felsblock unterbrochen, der aber",
  [25831] = "ebenso unüberwindbar hoch ist. Von der Seeseite",
  [25832] = "her bläst ein lauer Wind landeinwärts, und lässt",
  [25833] = "die Bauwipfel gemächlich nicken.*",
  [25834] = "Auch hier, am letzten Stamm direkt westlich des",
  [25835] = "hohen Felsens, findet sich eine schmale Ritze,",
  [25836] = "durch die man hindurchblicken kann. Drüben, auf",
  [25837] = "der anderen Seite, liegt ein schmales Stück Wiese,",
  [25838] = "jenseits derer jedoch bald wieder das dichte",
  [25839] = "Gestrüpp der riesenhaften, düfte-verströmenden",
  [25840] = "Blüten beginnt.*",
  [25841] = "Nach zehn anstrengenden Minuten haben Sie die",
  [25842] = "Krone des Zaunes erreicht. Drüben, auf der anderen",
  [25843] = "Seite, ersteckt sich ein urzeitlicher Dschungel",
  [25844] = "weit hinein ins Inselinnere. Einen Schritt östlich",
  [25845] = "von Ihnen liegt der große Felsblock - auf seinem",
  [25846] = "Gipfel ist eine Art Holzgestell aufgebaut.*",
  [25847] = "Auf dem Felsen",
  [25848] = "Ein guter Platz für eine kurze Verschnaufpause.",
  [25849] = "Hier, auf dem flachen Gipfel des Felsens, kann man",
  [25850] = "gut stehen. Mehr noch, hier befindet sich sogar -",
  [25851] = "nun, das kann man wohl kaum als eine Hütte",
  [25852] = "bezeichnen, es ist wohl eher so etwas wie ein",
  [25853] = "Unterstand.*",
  [25854] = "Er bietet nur zwei oder drei Quadratmeter Raum -",
  [25855] = "sein wichtigstes Merkmal ist wohl das, daß er",
  [25856] = "einen Holzboden besitzt, und überdacht ist. Halt -",
  [25857] = "da zeigt sich, daß auf der Rückseite des",
  [25858] = "Unterstandes eine schmale Leiter nach unten",
  [25859] = "führt!*",
  [25860] = "Also - da ist doch die Höhe! Da liegt, völlig fehl",
  [25861] = "am Platz in einem solchen Szenario, ein ordinärer",
  [25862] = "Kronenkorken auf dem Holzboden. (Verzeihung - hier",
  [25863] = "hat sich wohl einer unserer Kulissenarbeiter eine",
  [25864] = "Flasche Bier genehmigt, und nachher nicht wieder",
  [25865] = "aufgeräumt!)*",
  [25866] = "Es ist ein gewöhnlicher Kronenkorken (Baujahr ca.",
  [25867] = "1992), mit dem Bierflaschen verschlossen werden.*",
  [25868] = "Sieh da - er dient derzeit immerhin als Behälter",
  [25869] = "für einen Tropfen Suppenwürze!*",
  [25870] = "Auf der Wiese",
  [25871] = "Hier, unterhalb des Felsens, liegt ein schmales",
  [25872] = "Stück Wiese. Nordwärts, nur wenige Meter entfernt,",
  [25873] = "beginnt der dichte Dschungel. Die Wiese hingegen",
  [25874] = "ersteckt sich entlang des Zaunes noch ein Stück",
  [25875] = "nach Osten.*",
  [25876] = "Ostende der Wiese",
  [25877] = "Hier endet der sanfte Grasteppich der Wiese vor",
  [25878] = "hochaufragendem Dickicht. Südlich liegt der hohe",
  [25879] = "Palisadenzaun. Außer dem Weg nach Westen über die",
  [25880] = "Wiese wird das Fortkommen durch dichten Dschungel",
  [25881] = "erschwert.*",
  [25882] = "Die Wiese ersteckt sich zwischen dem Palisadenzaun",
  [25883] = "und dem Urwald von hier ein Stück nach Westen bis",
  [25884] = "in die Nähe eines großen Felsblockes. Zwischen den",
  [25885] = "Grashalmen wächst ein kleiner Pilz.*",
  [25886] = "Zwischen den Grashalmen steht der (momentan leider",
  [25887] = "nur 10 Zentimeter große) Admiral Atterson, und",
  [25888] = "sieht Sie erwartungsvoll an.*",
  [25889] = "Der Admiral ist ein stattlicher Mann von",
  [25890] = "hochgewachsener Statur und aristokratischer",
  [25891] = "Haltung, sieht man einmal von seiner Winzigkeit",
  [25892] = "ab. Er ist nur wenig mehr als zehn Zentimeter",
  [25893] = "hoch. Er trägt einen Tropenanzug samt Tropenhelm.*",
  [25894] = "Er ist nur ein paar Zentimeter hoch, verströmt",
  [25895] = "aber einen aromatischen Duft und ähnelt einem",
  [25896] = "kleinen Steinpilz. Mmhmm... das macht einem ja",
  [25897] = "richtig Appetit!*",
  [25898] = "Hmmmm.... der Pilz duftet sehr appetitlich... na",
  [25899] = "denn, Prost Mahlzeit!*",
  [25900] = "He, das ist ja...",
  [25901] = "Was ist denn mit Ihrem Hemd passiert? Plötzlich",
  [25902] = "sind Ihre Ärmel viel zu lang... und auch die",
  [25903] = "Hosenbeine...",
  [25904] = "Um Himmels Willen, Sie schrumpfen ja ein! So",
  [25905] = "bleiben Sie doch da... ohweh!",
  [25906] = "Sie werden immer kleiner... und kleiner... und",
  [25907] = "kleiner... wo sind Sie denn? Ach dort!*",
  [25908] = "Du liebes Bißchen! Sie sind ja nur noch so groß",
  [25909] = "wie eine Murmel! das ist ja schrecklich! Und...",
  [25910] = "schnell, verschwinden Sie da! Dort kommt eine",
  [25911] = "gefräßige Kakerlake daher...*",
  [25912] = "Neeeiiiiinnnnn! Das Insekt ist für Sie so groß wie",
  [25913] = "ein Elefant... schnell... laufen Sie doch endlich",
  [25914] = "weeeeeeeeeg.......",
  [25915] = "Urks.*",
  [25916] = "Im nächsten Moment ertönt ganz aus der Nähe eine",
  [25917] = "leise Stimme. \"Halt! Warten Sie!\"*",
  [25918] = "\"Moment! Warten Sie doch! Nicht den Pilz",
  [25919] = "aufessen!\" ertönt die Stimme wieder. Sie scheint",
  [25920] = "ganz aus der Nähe zu stammen, obwohl sie sehr",
  [25921] = "leise ist... nun, man könnte meinen, sie schalle",
  [25922] = "von UNTEN herauf!*",
  [25923] = "Plötzlich tritt zwischen den Grashalmen auf der",
  [25924] = "Wiese eine winzige Gestalt hervor. Es ist... ein",
  [25925] = "Mensch! Ja, tatsächlich - ein winzigkleiner Mann,",
  [25926] = "in einen sauberen Tropenanzug gekleidet! Er nimmt",
  [25927] = "höflich seinen Tropenhelm vom Kopf, verbeugt sich",
  [25928] = "und sagt: \"Wenn Sie gestatten, Sir: Admiral",
  [25929] = "Atterson, königlich anthropologisches Institut,",
  [25930] = "Birmingham. Willkommen auf der Teufelsinsel!\"*",
  [25931] = "Der Admiral ist ein stattlicher Mann von",
  [25932] = "hochgewachsener Statur und aristokratischer",
  [25933] = "Haltung, sieht man einmal von seiner Winzigkeit",
  [25934] = "ab. Er ist nur wenig mehr als zehn Zentimeter",
  [25935] = "hoch. Er trägt einen Tropenanzug samt Tropenhelm.",
  [25936] = "\"Sie sollten diesen Pilz lieber nicht essen!\" ruft",
  [25937] = "er herauf.*",
  [25938] = "Der Admiral setzt eine nachdenkliche Miene auf.",
  [25939] = "\"Nun, Sir, diese Pilze neutralisieren zwar die",
  [25940] = "betäubende Wirkung der Blütendüfte, sie haben",
  [25941] = "jedoch betrüblicherweise auch eine kleine",
  [25942] = "Nebenwirkung! Wenn Sie mich genau ansehen, werden",
  [25943] = "Sie es gewiss sogleich erkennen, Sir!\"*",
  [25944] = "\"Um durch diesen gefährlichen Dschungel zu",
  [25945] = "gelangen, aß ich von diesen Pilzen. Es ist nur so,",
  [25946] = "daß man langsam einschrumpft. Man wird sogar noch",
  [25947] = "kleiner, als ich es jetzt bin. Ich bin sozusagen",
  [25948] = "seither wieder gewachsen. Aber als ich damals den",
  [25949] = "Dschungel durchquert hatte, war ich schließlich",
  [25950] = "schon sooo klein geworden! Etwa zwei Zentimeter!\"*",
  [25951] = "\"Mit dieser Körpergröße war es mir nicht mehr",
  [25952] = "möglich, genug von den anderen Pilzen zu essen,",
  [25953] = "die jenseits des Dschungels wachsen, und die das",
  [25954] = "Gegenmittel zu diesen hier darstellen, wie ich,",
  [25955] = "leider aber zu spät, herausfand!\"*",
  [25956] = "Der Admiral sieht ein wenig verlegen aus. \"Wenn",
  [25957] = "ich meine ursprüngliche Größe wieder hätte",
  [25958] = "erreichen wollen, nun - ich hätte genausoviele der",
  [25959] = "anderen Pilze essen müssen! Und nun versuchen Sie",
  [25960] = "mal, als zwei Zentimeter großer Mensch einen oder",
  [25961] = "zwei dieser Pilze zu verspeisen! Ich bin seit drei",
  [25962] = "Wochen am Pilze-Essen, und habe ständiges",
  [25963] = "Bauchweh!\"*",
  [25964] = "\"Erst in etwa zwei Wochen werde ich wieder ganz",
  [25965] = "der Alte sein, habe ich mir ausgerechnet!\" erzählt",
  [25966] = "der Admiral weiter. \"Aber vermutlich interessiert",
  [25967] = "es Sie, wie Sie diesen Dschungel mit weniger",
  [25968] = "Problemen passieren können als ich, nicht wahr?\"*",
  [25969] = "\"Fein. Ich verrate es Ihnen auch gern, Sir.",
  [25970] = "Allerdings muß ich auf einer kleinen Gefälligkeit",
  [25971] = "bestehen....*",
  [25972] = "\"Nun, es ist eine etwas gewöhnliche Bitte, muß ich",
  [25973] = "gestehen,\" sagt der Admiral. \"Aber es ist so - ich",
  [25974] = "brauche ein paar Gewürze! Diese Pilzmenues sind",
  [25975] = "schwer zu ertragen, zumal sie von absolut fadem",
  [25976] = "Geschmack sind. Wenn Sie mir etwas Salz, Pfeffer,",
  [25977] = "Rosmarin, Liebstöckel und Majoran besorgen",
  [25978] = "könnten... wollen Sie das für mich tun?*",
  [25979] = "\"Das wäre wahrlich eine große Tat!\" beschwört Sie",
  [25980] = "Admiral Atterson. \"Sie würden mir mein Schicksal",
  [25981] = "erheblich versüßen... oder sagen wir besser:",
  [25982] = "verwürzen, haha! Also, ich warte dann hier auf",
  [25983] = "Sie! Bis später!\"*",
  [25984] = "\"Ah! Da sind Sie ja wieder!\" ertönt eine vertraute",
  [25985] = "Stimme. Zwischen den Grashalmen tritt Admiral",
  [25986] = "Atterson hervor. \"Haben Sie alles gefunden? Dann",
  [25987] = "lassen Sie mal sehen!\"*",
  [25988] = "\"Ah! Oregano - der wilde Majoran! Nun, das dürfte",
  [25989] = "ein durchaus brauchbarer Ersatz sein.\"*",
  [25990] = "\"Huch!\" sagt Admiral Atterson, als er den",
  [25991] = "Kronenkorken sieht. \"Was ist denn das... hmmm.",
  [25992] = "Ich kenne zwar diese Substanz nicht, aber sie",
  [25993] = "riecht deutlich nach Liebstöckel! Das ist wohl",
  [25994] = "eine Essenz, was? Nagut, das wird sicher gehen!\"*",
  [25995] = "\"Fein, Sir! Sie haben ein großes Herz, dies für",
  [25996] = "mich zu tun. Aber das ist ja leider noch nicht",
  [25997] = "alles. Erinnern Sie sich, was ich alles wollte?",
  [25998] = "Salz, Pfeffer, Rosmarin, Liebstöckel und Majoran.",
  [25999] = "Wenn Sie mir die fehlenden Gewürze noch bringen,",
  [26000] = "dann werde ich Ihnen mit Freuden helfen!*\"",
  [26001] = "Admiral Atterson ist hocherfreut. \"Das ist ja",
  [26002] = "wirklich sehr schön! Aber es fehlt noch etwas,",
  [26003] = "nicht wahr? Wissen Sie noch, was ich alles wollte?",
  [26004] = "Salz, Pfeffer, Rosmarin, Liebstöckel und Majoran.",
  [26005] = "Sie werden das Restliche sicher auch noch",
  [26006] = "finden!\"*",
  [26007] = "\"Ich bin höchst beglückt, mein Herr!\" ruft der",
  [26008] = "Admiral erfreut aus. \"Sie sorgen sich wahrlich um",
  [26009] = "mein Wohlergehen! Leider aber fehlt noch eine",
  [26010] = "letzte Zutat. Sie wissen ja, was ich alles wollte:",
  [26011] = "Salz, Pfeffer, Rosmarin, Liebstöckel und",
  [26012] = "Majoran!\"*",
  [26013] = "\"Sie sind ein wahrer Gentleman, Sir!\" ruft Admiral",
  [26014] = "Atterson aus. \"Ich danke Ihnen! Was nun Ihr",
  [26015] = "Problem angeht, habe ich Ihnen einen dieser",
  [26016] = "speziellen Champignons von jenseits des Waldes",
  [26017] = "besorgt! Um durch den Wald zu gelangen, sollten",
  [26018] = "Sie einen Pilz und diesen Champignon hier",
  [26019] = "gleichzeitig essen!\" Er hält ihnen einen",
  [26020] = "Champignon hin.*",
  [26021] = "\"Wollen Sie den Champignon nicht nehmen?\" fragt",
  [26022] = "der Admiral, und hält ihn Ihnen hin.*",
  [26023] = "\"Dies, verehrter Herr,\" lehnt der Admiral höflich",
  [26024] = "ab,\" kann ich nicht gebrauchen. Behalten Sie es",
  [26025] = "lieber selbst!\"*",
  [26026] = "\"Nun, Sir, diese Sachen kennen Sie doch sicher,",
  [26027] = "nicht wahr? Salz, Pfeffer, Rosmarin, Liebstöckel",
  [26028] = "und Majoran. Es handelt sich um gewöhnliche",
  [26029] = "Gewürze, und ich zweifle nicht im Mindesten daran,",
  [26030] = "daß ein Abenteurer und Forscher von ihrem Format",
  [26031] = "an jedem Ort der Erde so etwas auftreiben kann!\"*",
  [26032] = "Der Admiral schmunzelt. \"Sie haben vollkommen",
  [26033] = "recht, Sir. Majoran dürfte hierzulande schwer",
  [26034] = "aufzutreiben sein. Aber wenn Sie Oregano finden",
  [26035] = "könnten, die wilde Form des Majoran, bin ich auch",
  [26036] = "völlig zufrieden!\"*",
  [26037] = "Der Champignon ähnelt seinem europäischen Pendant",
  [26038] = "fast völlig, er ist nur ein bißchen grünlicher.",
  [26039] = "Nun - das wird wohl von den besonderen Kräften",
  [26040] = "stammen, die in ihm schlummern sollen!*",
  [26041] = "Sie haben Hunger? Na denn... Champignons sind zum",
  [26042] = "Essen da... haps. Er ist schon weg.*",
  [26043] = "Im Dschungel",
  [26044] = "Hier herrscht nur noch das wildwuchernde Ranken-",
  [26045] = "und Pflanzengewirr des Dschungels vor. Die Düfte",
  [26046] = "der Blüten sind mehr als betäubend - ja, sie",
  [26047] = "verursachen einem geradezu Kopfweh! Nordwärts",
  [26048] = "sieht es so aus, als könne man sich durch das",
  [26049] = "Dickicht hindurchzwängen.*",
  [26050] = "Tiefer im Dschungel",
  [26051] = "Ohweh. Hoffentlich gibt es hier keine Schlangen...",
  [26052] = "(grüne Baumnattern), oder Käfer... (die große,",
  [26053] = "gelbgepunktete Sorte mit den mit den giftigen",
  [26054] = "Zangen), oder SPINNEN... (die kleinen, schwarzen",
  [26055] = "Schnuckiputzis mit dem langsamwirkenden",
  [26056] = "Nervengift)...*",
  [26057] = "Oje, wie weit werden Sie noch kommmmen... ooooh...",
  [26058] = "diese Gerüche... das steigt eim ja dermaaaaßen...",
  [26059] = "in den Kopffff...*",
  [26060] = "... pppfffff... dasss hält ja niiiemand aussss....",
  [26061] = "alllles drethh sich... ooooo... wo ist hiieer der",
  [26062] = "Ausssgang........*",
  [26063] = "Noch tiefer im Dschungel",
  [26064] = "Uiuiui! Hoffentlich gibts hier keine Hyänenameisen",
  [26065] = "(die niedlichen, rattengroßen), und keine",
  [26066] = "Elefantenmoskitos... (die besonders niedlichen,",
  [26067] = "fasanengroßen), und keine Krätzebazillen... (die",
  [26068] = "super-niedlichen, fußballgroßen)....*",
  [26069] = "Am Felskegel",
  [26070] = "Der Dschungel ist gottlob zuende, und hier steigt",
  [26071] = "der steile, graue Felskegel in den Himmel auf. Ein",
  [26072] = "Stück weiter westlich beginnt ein abenteuerlicher,",
  [26073] = "schmaler Felspfad, der an der Wand hinauf führt.*",
  [26074] = "Der Pfad schmiegt sich, wie in den besten Tarzan-",
  [26075] = "Filmen, eng an den grauen Fels, und steigt in",
  [26076] = "schwindelnde Höhen hinan.*",
  [26077] = "Auf dem Felspfad",
  [26078] = "Über Ihnen ragt der steile Felsenkegel noch immer",
  [26079] = "gute zweihundert Meter hoch in den blauen",
  [26080] = "Himmel. Hier, an dieser Stelle, sind ein gutes",
  [26081] = "Drittel des Weges bewältigt, der direkt an der",
  [26082] = "Wand hinauf in die Höhe führt. Weiter oben scheint",
  [26083] = "eine Art Felsvorsprung zu sein.*",
  [26084] = "Die Felswand ist außergewöhnlich glatt, irgendwie",
  [26085] = "wirkt dieser Felskegel nicht so, als wäre er",
  [26086] = "gänzlich natürlichen Ursprungs!*",
  [26087] = "Sie sollten weiter hinauf klettern, von hier ist",
  [26088] = "da nicht viel zu erkennen.*",
  [26089] = "Auf dem Felsvorsprung",
  [26090] = "Hier, in guten einhundert Metern Höhe, gibt es",
  [26091] = "einen schmalen Felsvorsprung, der aus der steilen",
  [26092] = "Wand herausragt. Nach Westen führt ein schmaler",
  [26093] = "Weg weiter um die Wand herum, direkt nach oben",
  [26094] = "hingegen geht es in einen gefährlichen Felskamin!*",
  [26095] = "Der Felskamin führt senkrecht hinauf, und zwar die",
  [26096] = "letzten Hundert Meter bis ganz hinauf zum Gipfel.",
  [26097] = "Wie geschaffen für Reinhold Messner und ähnliche",
  [26098] = "Spezialisten.*",
  [26099] = "Oh, oh, oh! Das ist eine wahrlich verwegene",
  [26100] = "Absicht! Wollen Sie das wirklich wagen?*",
  [26101] = "Im Felskamin",
  [26102] = "Nach höchst gefährlicher, und anstrengender",
  [26103] = "Kletterei haben Sie die Hälfte des Kamins",
  [26104] = "bezwungen. Glücklicherweise gibt es hier einen",
  [26105] = "Absatz für eine kleine Pause. Weiter oben",
  [26106] = "allerdings sieht es noch schwieriger aus. Der",
  [26107] = "Kamin wird weiter, und bietet kaum noch die",
  [26108] = "Möglichkeit, sich einzustemmen!*",
  [26109] = "Der Absatz, auf dem Sie stehen, ist kaum breit",
  [26110] = "genug für einen sicheren Halt. Ein hartnäckiges",
  [26111] = "Gewächs hat sich in einem Riss festgeklammert,",
  [26112] = "aber sonst gibt es hier keinerlei - wie sagt man",
  [26113] = "so schön: Lebensraum, der einem Lebewesen",
  [26114] = "angenehme Zukunftsaussichten böte.*",
  [26115] = "Es muß sich um eine winzige, mutige Bergkiefer",
  [26116] = "handeln, die aus dem Riss herauswächst. Sie dürfte",
  [26117] = "hier sehr einsam sein, aber immerhin hat sie eine",
  [26118] = "schöne Aussicht über die Insel und das Meer.*",
  [26119] = "Das sollten Sie sich für den Gipfel aufheben,",
  [26120] = "falls sie ihn jemals lebend erreichen!*",
  [26121] = "Aha, Sie wollen Sich anseilen? Kein schlechter",
  [26122] = "Gedanke...",
  [26123] = "Nein, nehmen Sie das Seil lieber doppelt, dann",
  [26124] = "können Sie es später wieder hochziehen...",
  [26125] = "So, jetzt noch... Ach Du lieber Himmel! Nicht um",
  [26126] = "den Hals, Sie Künstler! Um den Bauch!",
  [26127] = "Okay, jetzt sind Sie an der kleinen Bergkiefer",
  [26128] = "angeseilt. Mehr können Sie im Moment nicht tun.*",
  [26129] = "Gut. Probieren wir's, und hoffen wir, daß...",
  [26130] = "Vorsicht! Der Stein ist locker! Ja, besser den da",
  [26131] = "drüben...",
  [26132] = "Prima. Und noch ein Stück... und noch eins...",
  [26133] = "geht's noch?",
  [26134] = "Und noch ein kleiner Klimmzuuuuug.... Vorsicht!",
  [26135] = "Ihre Haaaaaaaannnnnndddd..........*",
  [26136] = "Rrrruuummsss!!!",
  [26137] = ".... uff... was für ein Glück... leben Sie noch?",
  [26138] = "Das Seil und die Bergkiefer haben jedenfalls",
  [26139] = "gehalten!",
  [26140] = "Also los, ein paar Mal durchatmen, und wiederrauf...",
  [26141] = "Nach einer anstrengenden Viertelstunde haben Sie",
  [26142] = "es geschafft!*",
  [26143] = "Lassen Sie das Seil lieber festgebunden. Oder",
  [26144] = "wollen Sie unbedingt sterben?\"*",
  [26145] = "Gut. Probieren wir's nochmal. Hoffentlich geht es",
  [26146] = "diesmal besser.",
  [26147] = "Vorsicht! Das war der lockere Stein! Ja, besser",
  [26148] = "den da drüben... Prima. Und noch ein Stück... und",
  [26149] = "noch eins...",
  [26150] = "Eine weitere halbe Stunde später haben Sie es",
  [26151] = "geschafft. Schnell noch das Seil heraufziehen...",
  [26152] = "So. Auch das ist erledigt.*",
  [26153] = "Auf dem Gipfel",
  [26154] = "Hier oben weht ein munteres Lüftchen. Der Ausblick",
  [26155] = "über die Insel und das Meer ist einfach fabelhaft.",
  [26156] = "Aber es gibt noch etwas viel Interessanteres:",
  [26157] = "Mitten auf dem Gipfel, auf einem Podest, steht",
  [26158] = "eine kleine, hölzerne Truhe. Die Truhe ist nicht",
  [26159] = "viel größer als ein Schuhkarton, dafür aber schön",
  [26160] = "verziert, und mit Samt ausgeschlagen.*",
  [26161] = "Die Truhe ist offen. Auf dem Samt liegt der",
  [26162] = "Splitter eines Edelsteins!*",
  [26163] = "Kaum haben Sie den Edelstein an sich genommen,",
  [26164] = "kracht der Deckel der kleinen Truhe zu. Rrrumms!!",
  [26165] = "\"Mist, verdammter!\" tönt eine krächzende Stimme.",
  [26166] = "Dann aber beginnt schon wieder die Welt um Sie",
  [26167] = "herum zu verschwimmen, und die geheimnisvolle",
  [26168] = "Kraft wirbelt Sie wieder durch Zeit und Raum...*",
  [26169] = "Vorsicht, Ihre Finger...! Klapppp!!!",
  [26170] = "Mit einem energischen Ton knallt der Deckel der",
  [26171] = "kleinen Truhe herunter, und auf Ihrer Oberseite",
  [26172] = "wird ein kleines, geschnitztes Gesicht sichtbar,",
  [26173] = "das sich plötzlich zu bewegen beginnt!*",
  [26174] = "\"So nicht, mein Lieber!\" krächzt das hölzerne",
  [26175] = "Gesicht, das, wie von Geisterhand, zum Leben",
  [26176] = "erwacht ist. \"Du kannst nicht einfach die Splitter",
  [26177] = "des Auges von überall wegholen - dabei aber schon",
  [26178] = "gefundene wieder verlieren! Diesen hier bekommst",
  [26179] = "Du erst, wenn Du den Splitter, den Du verloren",
  [26180] = "hast, wieder an Dich gebracht hast! Basta!\" Damit",
  [26181] = "erstarren die hölzernen Züge des Gesichtes wieder",
  [26182] = "zur Bewegungslosigkeit.*",
  [26183] = "Auf dem Deckel der kleinen Truhe ist ein kleines,",
  [26184] = "runzliges Gesicht eingeschnitzt...",
  [26185] = "Nun... offengestanden, sieht es dem Antlitz von",
  [26186] = "Andi Niedermeier recht ähnlich... es ist nur etwas",
  [26187] = "hübscher... *",
  [26188] = "Ohweh - Sie haben wohl immer noch nicht genug, von",
  [26189] = "der Kraxelei, was? Dummerweise gibt es hier",
  [26190] = "nichts, woran Sie Ihr Seil festmachen könnten...",
  [26191] = "Naja, das ist wohl nicht so schlimm. Sie wollen ja",
  [26192] = "nur runter, nicht wahr? Das schaffen Sie mit",
  [26193] = "Sicherheit. Irgendwie, haha.",
  [26194] = "Also dann... langsam, nicht so hastig, das war nur",
  [26195] = "ein Scherz...*",
  [26196] = "Am Riß",
  [26197] = "Vor Ihnen befindet sich ein senkrechter Riß, der",
  [26198] = "von oben bis unten die ganze Felswand durchläuft.",
  [26199] = "Glücklicherweise können Sie auf dieser Seite gut",
  [26200] = "stehen. Drüben, auf der westlichen Seite des",
  [26201] = "Risses, befindet sich ein weiterer Felsabsatz, auf",
  [26202] = "dem eine seltsame Konstruktion aufgebaut ist. Bis",
  [26203] = "dort hinüber sind es aber gute vier Meter.*",
  [26204] = "Der schmale Brettersteg einer kleinen, hölzernen",
  [26205] = "Zugbrücke verbindet die beiden Felsabsätze.*",
  [26206] = "An einen Sprung ist nicht zu denken, denn dort",
  [26207] = "drüben befindet sich eine seltsame Konstruktion",
  [26208] = "aus Brettern und Balken, die eine sichere Landung",
  [26209] = "nach einem Sprung unmöglich macht. Ein tödlicher",
  [26210] = "Sturz hinab in den Riß wäre wäre die sichere",
  [26211] = "Folge!*",
  [26212] = "Ein komisches Ding, aber... ja, tatsächlich! Das",
  [26213] = "ist eine Art Zugbrücke! Es handelt sich um einen",
  [26214] = "schmalen Brettersteg, den man von der anderen",
  [26215] = "Seite herunterlassen könnte, um den Riß gefahrlos",
  [26216] = "zu überqueren. Doch der Steg ist hochgezogen!",
  [26217] = "Links befindet sich die Seilwinde, leider ist sie",
  [26218] = "völlig außer Reichweite.*",
  [26219] = "Die Seilwinde scheint schon ziemlich alt und",
  [26220] = "kaputt zu sein. Es ist eine hölzerne Konstruktion",
  [26221] = "mit einer großen Trommel und einer Kurbel, die auf",
  [26222] = "einem Holzgestell befestigt sind. Damit sich die",
  [26223] = "Trommel nicht von selbst abspult, ist sie",
  [26224] = "behelfsmäßig mit einem großen Holzknüppel am",
  [26225] = "Gestell verkeilt.*",
  [26226] = "Die Seilwinde ist freigegeben - und damit die",
  [26227] = "Zugbrücke heruntergelassen.*",
  [26228] = "Der Knüppel ist einen guten Meter lang und ragt",
  [26229] = "seitlich weg.*",
  [26230] = "Oh! Wollen Sie dies wirklich als Wurfgeschoß",
  [26231] = "verschwenden? Das sollten Sie sich nochmal gut",
  [26232] = "überlegen!*",
  [26233] = "Ihre Absicht ist löblich, aber - schauen Sie noch",
  [26234] = "mal genau hin! Der Knüppel ist so angebracht, daß",
  [26235] = "ein Herüberziehen mittels des Seiles (sollten Sie",
  [26236] = "ihn treffen) nichts nützen würde! Er muß in die",
  [26237] = "andere Richtung - von Ihnen weg - bewegt werden!*",
  [26238] = "Tock!",
  [26239] = "Mist, das war zwar ein Treffer - aber der Knüppel",
  [26240] = "hat sich nicht ganz gelöst!*",
  [26241] = "Uuuund.... Zack!",
  [26242] = "Super - das war ein Volltreffer... schnell - einen",
  [26243] = "Schritt zurück....",
  [26244] = "Rrrumssss!",
  [26245] = "Die Zugbrücke ist heruntergeknallt - jetzt ist der",
  [26246] = "Weg frei!*",
  [26247] = "An der Steintür",
  [26248] = "In der Felswand vor Ihnen befindet sich eine",
  [26249] = "kleine, quadratische Tür aus grauem Stein, die",
  [26250] = "Richtung Norden führt. Sie ist nicht groß, man",
  [26251] = "könnte durch den Durchgang, der dahinter liegt,",
  [26252] = "allenfalls kriechen.*",
  [26253] = "Die Tür besteht aus blankem Stein und ist etwa 60",
  [26254] = "mal 60 Zentimeter groß. Leider ist da nirgends ein",
  [26255] = "Schloß oder ein Griff zu erblicken - wie wird",
  [26256] = "diese Tür wohl zu öffnen sein?*",
  [26257] = "Die Seilwinde ist derzeit abgespult, und die",
  [26258] = "Zugbrücke heruntergelassen.*",
  [26259] = "Na, dann! Einmal in die Hände gespuckt, und",
  [26260] = "hauruck....",
  [26261] = "So. Die Zugbrücke ist nun wieder hochgekurbelt...",
  [26262] = "sieh da! Gleichzeitig hat sich die kleine",
  [26263] = "Steintür geöffnet!*",
  [26264] = "Rummmms! Als Sie die Kurbel loslassen, knallt der",
  [26265] = "Brettersteg herunter. Die Steintür ist wieder",
  [26266] = "zu.*",
  [26267] = "Fein. Die Seilwinde ist nun verkantet, und die",
  [26268] = "Zugbrücke kann nicht mehr 'runterrasseln. Die",
  [26269] = "kleine Tür im Fels bleibt erfreulicherweise",
  [26270] = "offen!*",
  [26271] = "Die Seilwinde ist aufgespult und mit einem",
  [26272] = "Billardstock verkantet.*",
  [26273] = "Die Seilwinde ist aufgespult und mit dem Griff",
  [26274] = "des Billardstockes verkantet.*",
  [26275] = "Die Seilwinde ist aufgespult und mit dem Schaft",
  [26276] = "des Billardstockes verkantet.*",
  [26277] = "Die Seilwinde ist aufgespult und mit der Spitze",
  [26278] = "des Billardstockes verkantet.*",
  [26279] = "Die Zugbrücke ist hochgekurbelt. Gleichermaßen hat",
  [26280] = "sich die kleine Steintür geöffnet!*",
  [26281] = "Im Gang",
  [26282] = "Sie haben die Mitte eines langen, sehr schmalen",
  [26283] = "und niedrigen Ganges erreicht, der offensichtlich",
  [26284] = "weiter nach Norden führt. Hier herrscht ein",
  [26285] = "wahrhaft abscheulicher Gestank. Aus der Ferne",
  [26286] = "dringen leise schmatzende und gluckernde Geräusche",
  [26287] = "herüber. Irgendetwas Grausiges lauert hier. Aber",
  [26288] = "in der unmittelbaren Nähe ist nichts zu",
  [26289] = "entdecken.*",
  [26290] = "Tiefer im Gang",
  [26291] = "Noch ein Stück weiter nördlich von hier muß sich",
  [26292] = "eine schwache Lichtquelle befinden. Leider aber",
  [26293] = "beleuchtet sie den Gang kaum.",
  [26294] = "Ohgott! In einer Einbuchtung in der Tunnelwand",
  [26295] = "liegt eine reglose Gestalt!*",
  [26296] = "Pocken-Pete liegt hier. Der arme Kerl hat sein",
  [26297] = "Leben schon seit Stunden ausgehaucht. War er im",
  [26298] = "Leben schon durch sein schlimmes Bein gestraft -",
  [26299] = "auch im Tode hat das Schicksal kein Erbarmen mit",
  [26300] = "ihm. Sein Körper ist erschlafft - unzählige kleine",
  [26301] = "und häßliche Wunden bedecken ihn.*",
  [26302] = "Er trägt nur noch seine einfachen, dunklen Kleider",
  [26303] = "und seine Augenklappe.*",
  [26304] = "Er trägt nur noch seine einfachen, dunklen",
  [26305] = "Kleider.*",
  [26306] = "Er trägt nur noch seine Augenklappe.*",
  [26307] = "Pete hat nichts mehr bei sich.*",
  [26308] = "Auf den ersten Blick könnte man meinen, es handle",
  [26309] = "sich um Abschürfungen, wie man sie sich vielleicht",
  [26310] = "beim Klettern zuziehen könnte, dann aber zeigt",
  [26311] = "sich, daß es eine Unzahl von kleinen Wunden sind,",
  [26312] = "so als hätte ein namenloses Wesen Pete in seine",
  [26313] = "Fänge bekommen, und ihn förmlich ausgesaugt!*",
  [26314] = "Du lieber Himmel! Was für eine geschmacklose Idee!",
  [26315] = "Wollen wir hoffen, daß einen wirklich sinnreichen",
  [26316] = "Grund für diese Tat haben!",
  [26317] = "Okay. Sie besitzen nun Pete's Kleider.*",
  [26318] = "Aha, Sie haben etwas vor. Gut... Sie tragen nun",
  [26319] = "Pete's Kleider.*",
  [26320] = "Naja, einen Leichnam zu plündern... hoffentlich",
  [26321] = "dient Ihre Maßnahme einem sinnvollen Zweck!",
  [26322] = "Gut. Sie besitzen nun Pete's Augenklappe.*",
  [26323] = "Diese Augenklappe steht Ihnen nicht einmal",
  [26324] = "schlecht! Mr. Threepwood wäre neidisch!*",
  [26325] = "Nunmehr erscheint es als eine glückliche Fügung,",
  [26326] = "daß Sie sich bei Ihrer Palmen-Klettertour ein paar",
  [26327] = "kleine Abschürfungen zugezogen haben. Sie sehen",
  [26328] = "Pocken-Pete recht ähnlich!*",
  [26329] = "In der Katakombe",
  [26330] = "Hier ist das Ende des langen, schmalen Ganges, und",
  [26331] = "der Gestank an diesem Ort ist absolut",
  [26332] = "überwältigend! Unter Ihnen liegt eine große, etwa",
  [26333] = "kuppelförmige Katakombe. Sie ist zu einem guten",
  [26334] = "Drittel mit einer stinkenden, schwarzen Brühe",
  [26335] = "ausgefüllt. Ein paar schlammige Treppenstufen",
  [26336] = "führen hinab. In der Mitte der Katakombe ragt eine",
  [26337] = "Felsnadel aus der Brühe. Diffuses, bläuliches",
  [26338] = "Licht herrscht in diesem Raum.*",
  [26339] = "Dann plötzlich regt sich etwas: Eine unsagbar",
  [26340] = "scheußliche Kreatur taucht aus der Brühe auf!*",
  [26341] = "Ein gräßliches Tentakelwesen suhlt sich dort unten",
  [26342] = "in der stinkenden, schwarzen Brühe. Dann blickt es",
  [26343] = "herauf zu Ihnen, und erstarrt. Für einige Zeit",
  [26344] = "beobachtet es Sie ehrfürchtig.*",
  [26345] = "Das Monster entspannt sich wieder, und beginnt,",
  [26346] = "schmatzend und kreischend zu lachen. \"Haaaa! Du",
  [26347] = "willst mich verkohlen, Menschlein! Doch ich",
  [26348] = "erkenne Dich! Für einen Moment dachte ich, du",
  [26349] = "wärest Kal, mein einziger Gott - in der Gestalt",
  [26350] = "eines Wesens, dem ich kürzlich das Leben bis zum",
  [26351] = "letzten Tropfen ausgesaugt hatte! Aber nein, Du",
  [26352] = "verrätst Dich, Du bist nicht Kal!\"*",
  [26353] = "\"Komm herab zu mir, o Herrscher der Schwarzen",
  [26354] = "Stadt, und laß Dir von mir geben, was Dein ist!\"",
  [26355] = "sagt das Monster mit ehrfürchtig zitternder",
  [26356] = "Stimme. Aber schon im nächsten Augenblick verzieht",
  [26357] = "sich seine Fratze. \"Weiche von mir Du Komödiant,",
  [26358] = "ich habe Dich erkannt! Du bist nicht Kal - in der",
  [26359] = "Gestalt des Wesens, dem ich heute das Leben",
  [26360] = "aussaugte! Ha! Du hast Dich verraten!\"*",
  [26361] = "\"Komm herab zu mir, o Herrscher der Schwarzen",
  [26362] = "Stadt, und laß Dir geben, was Dein ist!\" sagt das",
  [26363] = "Monster mit zitternder Stimme. Es verneigt sich so",
  [26364] = "tief, daß es fast im Schlamm der Katakombe",
  [26365] = "versinkt. Dann reicht es Ihnen unter mehrfachen,",
  [26366] = "unterwürfigen Verbeugungen den Edelstein... und",
  [26367] = "zuckt zurück! \"Ha!\" dröhnt es. \"Hebe Dich hinfort,",
  [26368] = "Du Betrüger, ich habe Dich erkannt!\"*",
  [26369] = "\"Komm herab zu mir, o Herrscher der Schwarzen",
  [26370] = "Stadt, und laß Dir geben, was Dein ist!\" sagt das",
  [26371] = "Monster mit zitternder Stimme. Es verneigt sich so",
  [26372] = "tief, daß es fast im Schlamm der Katakombe",
  [26373] = "versinkt. Dann hält es Ihnen unter mehrfachen,",
  [26374] = "unterwürfigen Verbeugungen den Splitter hin.*",
  [26375] = "Als Sie den Edelstein entgegengenommen haben,",
  [26376] = "taucht das schreckliche Tentakelwesen ehrfürchtig",
  [26377] = "in den Schlamm hinab, und ward nicht mehr",
  [26378] = "gesehen.*",
  [26379] = "Auf der Spitze der Felsnadel liegt, recht",
  [26380] = "verheißungsvoll drapiert, ein Edelsteinsplitter.*",
  [26381] = "Die Felsnadel ragt einen guten Meter aus der",
  [26382] = "stinkenden, schlammigen Brühe empor.*",
  [26383] = "Es ist ein grausiges Tentakelwesen mit einem guten",
  [26384] = "Dutzend Armen. Sie sind mit kleinen Stacheln und",
  [26385] = "Saugnäpfen bewehrt. Der Leib hat die Form eines",
  [26386] = "plumpen Fasses. Der flache Kopf besitzt ein Maul",
  [26387] = "mit bängstigend langen und spitzen Zähnen. Das",
  [26388] = "Monster schmatzt und sabbert - drei glühende,",
  [26389] = "blaßblaue Augen blitzen Sie gierig an!*",
  [26390] = "Dieses schreckliche Untier hat tatsächlich drei",
  [26391] = "Augen... ein wahrlich bedeutungsvolles Indiz!*",
  [26392] = "Es scheint eine Weile zu dauern, bis das Wesen",
  [26393] = "begriffen hat, daß Sie anwesend sind. Dann beginnt",
  [26394] = "es zu gröhlen. \"Ha! Ist das nicht ein Festtag! Mir",
  [26395] = "ist, als hätte ich heute schon mal Besuch gehabt!",
  [26396] = "Oder war das gestern? Oder vor tausend Jahren? Oh,",
  [26397] = "mein Gedächtnis! Ach, egal! \"Komm zu mir herab,",
  [26398] = "Menschlein! Ich sehe zwar böse aus, aber ich bin",
  [26399] = "ganz lieb! Ich werde Dir bestimmt nichts tun!\"*",
  [26400] = "Sie besitzen wirklich ein grenzenloses Vertrauen!",
  [26401] = "Aber für den Augenblick tut Ihnen das Monster",
  [26402] = "wirklich nichts.*",
  [26403] = "An der Felsnadel",
  [26404] = "Hier stehen Sie, kaum einen Schritt über der",
  [26405] = "stinkenden Brühe, in der Nähe der schmalen",
  [26406] = "Felsnadel.*",
  [26407] = "Auf der Felsnadel liegt, verheißungsvoll drapiert,",
  [26408] = "der Splitter eines Edelsteins.*",
  [26409] = "Allerdings hat sich zwischen Ihnen und Ihrem Ziel",
  [26410] = "ein an Abscheulichkeit kaum zu überbietendes",
  [26411] = "Tentakelwesen aufgebaut.*",
  [26412] = "\"Ich weiß schon, was Du willst!\" gröhlt das",
  [26413] = "schreckliche Tentakelwesen sabbernd. Ein Schwall",
  [26414] = "von heißer, stinkender Luft weht Ihnen aus dem",
  [26415] = "Maul entgegen. \"Du willst diesen Edelstein! Aber",
  [26416] = "ich werde ihn niemals herausgeben!\" Dann",
  [26417] = "verwandelt sich die Stimme in einen sakralen",
  [26418] = "Singsang:*",
  [26419] = "\"Allein der Große Kal hat die Macht, mir zu",
  [26420] = "befehlen! Oh, Du einziger Gott der Vernichtung, Du",
  [26421] = "Herrscher der Schwarzen Stadt, Du, der Du als",
  [26422] = "einziger die Toten erwecken - ja sogar ihre",
  [26423] = "Gestalt annehmen kannst! Lange hast Du mir kein",
  [26424] = "Zeichen mehr gegeben, seit Äonen habe ich Dich",
  [26425] = "nicht mehr erblickt! Gib mir ein Zeichen!\"*",
  [26426] = "Dann funkelt das Monster Sie wieder an. \"Wer bist",
  [26427] = "denn Du?\" knurrt es. Und dann, nach einer geraumen",
  [26428] = "Weile: \"Ach, jetzt erinnere ich mich wieder! Das",
  [26429] = "Menschlein, das den Splitter vom Auge des Kal",
  [26430] = "haben will! Nein, ich werde ihn Dir niemals geben!",
  [26431] = "Deshalb hebe Dich hinfort, bevor ich Dich",
  [26432] = "vernichte!\" Die Warnung war deutlich genug. Schon",
  [26433] = "zucken die tödlichen Tentakeln in Ihre Richtung!*",
  [26434] = "Huiii! Das war knapp! Gerade noch geschafft!*",
  [26435] = "Ohweh, Sie Unglücklicher! Laufen Sie doch endlich",
  [26436] = "weg.... das gräßliche Monstrum schnappt nach",
  [26437] = "Ihnen....  Umpff*",
  [26438] = "Bis hier herauf reichen die Tentakeln des Monsters",
  [26439] = "nicht. Es bleibt dort unten in seiner stinkenden",
  [26440] = "Brühe.*",
  [26441] = "Sie sieht aus wie eine Kokosnuß - kaum zu glauben.*",
  [26442] = "Sie hängt deperimierend weit außer Reichweite.*",
  [20000] = "------------------------------------------------",
  [20001] = "------------------------------------------------",
  [20002] = "In der Vertiefung sind sechs Steinquader zu einem",
  [20003] = "Kreis angeordnet. Jeder dieser Steinquader ist auf",
  [20004] = "seiner Oberseite mit einer römischen Ziffer von I",
  [20005] = "bis VI markiert. Zudem befinden sich auf dem Boden",
  [20006] = "in dem Kreis sechs verschieden-farbige Felder, in",
  [20007] = "den Farben Weiß, Gelb, Grün, Rot, Blau und",
  [20008] = "Schwarz.*",
  [20009] = "Im Steinkreis",
  [20010] = "Hier, in diesem Kreis der Steine, zwischen den",
  [20011] = "Quadern und farbigen Feldern, herrscht eine",
  [20012] = "bedrückende Athmosphäre des Übernatürlichen vor.",
  [20013] = "Der Gedanke drängt sich auf, daß das Abenteuer nun",
  [20014] = "erst richtig beginnt, daß man von hier aus an Orte",
  [20015] = "gelangen kann, die jeder Vorstellung spotten. Aber",
  [20016] = "wie geht es? Wie kommt man von hier aus weiter?*",
  [20017] = "Die Quader sind etwa dreißig Zentimeter hoch, oben",
  [20018] = "abgeflacht, und an diesen Stellen tragen Sie je",
  [20019] = "eine der römischen Ziffern von I bis VI.*",
  [20020] = "Die sechs Felder sind wie die Stücke einer Torte",
  [20021] = "zwischen den Quadern zu einem Kreis angeordnet.",
  [20022] = "Jedes hat eine andere Farbe, es sind die Farben",
  [20023] = "Weiß, Gelb, Grün, Rot, Blau und Schwarz.*",
  [20024] = "Ah! Sie wollen diesen geheimnisvollen Mechanismus",
  [20025] = "in Kraft setzen, nicht wahr? Sie sollten sich aber",
  [20026] = "zuerst für eines der Felder entscheiden. Aber",
  [20027] = "geben Sie acht! Es ist gefährlich! Haben Sie auch",
  [20028] = "Juggers Tagebuch genau durchgelesen?*",
  [20029] = "Gut, Sie stehen nun auf dem grünen Feld. Was",
  [20030] = "wollen Sie nun tun?*",
  [20031] = "Gut, Sie stehen nun auf dem roten Feld. Was",
  [20032] = "wollen Sie nun tun?*",
  [20033] = "Gut, Sie stehen nun auf dem weißen Feld. Was",
  [20034] = "wollen Sie nun tun?*",
  [20035] = "Gut, Sie stehen nun auf dem blauen Feld. Was",
  [20036] = "wollen Sie nun tun?*",
  [20037] = "Gut, Sie stehen nun auf dem gelben Feld. Was",
  [20038] = "wollen Sie nun tun?*",
  [20039] = "Gut, Sie stehen nun auf dem schwarzen Feld. Was",
  [20040] = "wollen Sie nun tun?*",
  [20041] = "Nein...! Nicht da drauf... haben Sie denn Harold",
  [20042] = "Juggers Warnung nicht gelesen...",
  [20043] = "Von irgenwoher ertönt plötzlich ein Geräusch, als",
  [20044] = "wäre etwas zerplatzt... dann wallt plötzlich",
  [20045] = "gelber Staub auf... oh nein... was ist das...?",
  [20046] = "Das ist das Ende....",
  [20047] = "Hilfeeeeee.......!!!*",
  [20048] = "Es ist seltsam... irgendetwas geschah hier immer,",
  [20049] = "aber in diesem Fall passiert nichts. Rein gar",
  [20050] = "nichts. Kann es sein, daß Sie für diese Reise noch",
  [20051] = "etwas zu früh dran sind?*",
  [20052] = "Oh.... was ist das...? Um Sie herum beginnt sich",
  [20053] = "alles zu drehen... eine Kaskade aus grellen Farben",
  [20054] = "beginnt aus dem Sechseck-Symbol über Ihrem Kopf zu",
  [20055] = "sprühen.... Vorsicht....!!!",
  [20056] = "Plötzlich werden Sie, wie von einer eisernen",
  [20057] = "Faust, von einer unsagbaren Kraft gepackt, und",
  [20058] = "durch Zeit und Raum geschleudert....*",
  [20059] = "Sie sind in den geheimen Kellerraum des Hawthorne-",
  [20060] = "Hauses zurückgekehrt. Abermals stehen Sie im Kreis",
  [20061] = "der Sechs Steinquader!*",
  [30002] = "Ein seltsames, um nicht zu sagen: mulmiges Gefühl,",
  [30003] = "begleitet diese finale Reise durch Zeit und Raum.",
  [30004] = "Nicht mehr lange wird es dauern, bis es heißt, dem",
  [30005] = "schrecklichen Kal Auge in Auge gegenüberzutreten.",
  [30006] = "Einen kleinen Vorteil allerdings sollten Sie sich",
  [30007] = "bis dahin erkämpft haben: Dieses \"Auge in Auge\"",
  [30008] = "soweit zu ihren Gunsten verschoben zu haben, daß",
  [30009] = "sich Kal's Auge in IHREM Besitz befindet...!*",
  [30010] = "Im Bergwerk",
  [30011] = "Eine bodenlose, schwarze Schlucht begrenzt die",
  [30012] = "westliche Seite eines gewaltigen Bergwerks. Auf",
  [30013] = "dieser Seite hingegen arbeiten Dutzende von",
  [30014] = "Sklaven, die von Wächtern beaufsichtigt werden.",
  [30015] = "Der Lärm der Hämmer und Pickel dröhnt durch die",
  [30016] = "unterirdische Halle. Vor Ihnen, in der Felswand,",
  [30017] = "führt ein Gang Richtung Osten. Die Schienen einer",
  [30018] = "Lorenbahn führen in den Gang.*",
  [30019] = "Tief unten in der Schlucht bewegt sich träge ein",
  [30020] = "Strom geschmolzenen Gesteins und schickt seine",
  [30021] = "Hitze bis hier herauf ins Bergwerk.*",
  [30022] = "Die Felswände bestehen aus schwarzem",
  [30023] = "Basaltgestein, überall liegen losgebrochene Steine",
  [30024] = "herum.*",
  [30025] = "Es sind nur Unmengen von schwarzen Basaltsteinen,",
  [30026] = "die hier überall herumliegen.*",
  [30027] = "Belasten Sie sich nicht damit - wenn sie jemals",
  [30028] = "einen davon brauchen sollten: Sie würden sie hier",
  [30029] = "auf jedem Quadratmeter finden.*",
  [30030] = "Kleine Karren zum Transport losgehauenen Gesteins",
  [30031] = "bewegen sich hier und da auf den Schienen. Die",
  [30032] = "Schienen verlaufen in nord-südlicher Richtung im",
  [30033] = "Bergwerk; zwei weitere Stränge zweigen davon",
  [30034] = "Richtung Osten ab, und führen in einen Gang",
  [30035] = "hinein. Vor dem Gang stehen zwei breitschultrige",
  [30036] = "Wachsoldaten.*",
  [30037] = "Die Wachsoldaten schauen grimmig drein - sie sehen",
  [30038] = "nicht so aus, als wollten Sie mit jemandem",
  [30039] = "Konversation betreiben, oder als könnte man sie",
  [30040] = "gar überreden, den Gang betreten zu dürfen.*",
  [30041] = "\"He!\" ruft einer der Wachsoldaten, und packt sie",
  [30042] = "am Arm.",
  [30043] = "\"Hau bloß ab! Du weißt genau, daß Du hier nicht",
  [30044] = "'reindarfst!\" Er stößt Sie grob zurück.*",
  [30045] = "\"Bleib mir vom Leib!\" knurrt der Wachsoldat und",
  [30046] = "hebt drohend sein Schwert. \"Mach, daß Du wieder an",
  [30047] = "Deine Artbeit kommst!\"*",
  [30048] = "Die Wächter patroullieren hier und da im Bergwerk",
  [30049] = "umher, grunzen erschöpften Sklaven drohende Worte",
  [30050] = "zu, und verbreiten eine Athmosphäre von",
  [30051] = "gnadenloser Härte und Unterdrückung.*",
  [30052] = "Jeder der Karren bietet einen Raum von vielleicht",
  [30053] = "eineinhalb Kubikmetern. Die schwitzenden Sklaven",
  [30054] = "füllen sie mit Gestein. Wenn sie voll sind, werden",
  [30055] = "sie auf ein Fördergleis geschoben, und von dort",
  [30056] = "automatisch abtransportiert.*",
  [30057] = "Es sind schwitzende und offensichtlich",
  [30058] = "ausgehungerte Männer, die teilnahmslos, aber nicht",
  [30059] = "minder schwer und angstrengt unter den",
  [30060] = "mitleidslosen Blicken der Wächter schuften.*",
  [30061] = "\"Bleib mir vom Leib!\" knurrt der Wächter. Er hebt",
  [30062] = "drohend sein Schwert. \"Und sieh zu, daß Du Dich an",
  [30063] = "Deine Arbeit machst!\"*",
  [30064] = "Eine Sekunde voller blitzendem Stahl. Dann ist Ihr",
  [30065] = "Abenteuer zuende.*",
  [30066] = "Nordende des Bergwerks",
  [30067] = "Überall der gleiche Anblick. Sklaven bearbeiten",
  [30068] = "die schwarzen Felswände - von schwerbewaffneten",
  [30069] = "Wächtern mißtrauisch beobachtet.*",
  [30070] = "Die Felswände bieten überall den gleichen Anblick:",
  [30071] = "schwarzes Basaltgestein, und überall herumliegende",
  [30072] = "Gesteinsbrocken.*",
  [30073] = "Es handelt sich um nichts weiter als schwarze",
  [30074] = "Steine, die hier in Unmengen überall herumliegen.*",
  [30075] = "In der Nähe steht ein Wächter, der Sie mit",
  [30076] = "mißtrauischen Blicken beobachtet.*",
  [30077] = "\"He! Hast Du nichts zu arbeiten, Kerl?\" tönt",
  [30078] = "plötzlich die Stimme des Wächters.*",
  [30079] = "Der Wächter kommt auf Sie zu, und packt Sie am",
  [30080] = "Arm. \"Verflucht nochmal, Du Tagedieb!\" brüllt er",
  [30081] = "Sie an. \"Wo ist Dein Pickel? Warum bist Du nicht",
  [30082] = "an Deinem Arbeitsplatz?\"*",
  [30083] = "\"Dir werd ich's zeigen!\" grunzt der Wächter. \"Du",
  [30084] = "kommst 30 Tage in Dunkelhaft!\"",
  [30085] = "Er winkt ein paar seiner Kollegen herbei, und bald",
  [30086] = "hat man sie gepackt, weggeschleift und in ein",
  [30087] = "finsteres Loch geworfen.",
  [30088] = "Und dann folgen lange Stunden, Tage und Wochen in",
  [30089] = "absoluter Dunkelheit...*",
  [30090] = "Südende des Bergwerks",
  [30091] = "Auch hier sieht es genauso aus, wie überall in",
  [30092] = "diesem riesigen Bergwerk. Sklaven bearbeiten die",
  [30093] = "schwarzen Felswände, beladen die Lorenbahn und",
  [30094] = "schieben die Karren auf den Schienen entlang.",
  [30095] = "Grimmige Wächter beaufsichtigen sie mißtrauisch.*",
  [30096] = "Ganz in der Nähe liegt ein erschöpfter Mann am",
  [30097] = "Boden, der von einem Wächter rüde beschimpft",
  [30098] = "wird.*",
  [30099] = "In der Nähe liegt ein erschöpfter Mann am Boden.*",
  [30100] = "Es ist ein hellhäutiger, blonder Mann, aber er",
  [30101] = "sieht furchtbar aus. Abgemagert, unterernährt und",
  [30102] = "völlig ausgezehrt. Er liegt, halb bewußtlos, über",
  [30103] = "seinem Pickel zusammengesunken.*",
  [30104] = "Es ist ein hellhäutiger, blonder Mann, aber er",
  [30105] = "sieht furchtbar aus. Abgemagert, unterernährt und",
  [30106] = "völlig ausgezehrt. Er sitzt an die Wand gelehnt,",
  [30107] = "ist aber halb bewußtlos.*",
  [30108] = "Es ist ein hellhäutiger, blonder Mann, und er",
  [30109] = "sieht schon wesentlich besser aus, als zu dem",
  [30110] = "Zeitpunkt, da Sie ihn zum erstenmal trafen. Er ist",
  [30111] = "offenbar noch immer auf der Suche nach seinem",
  [30112] = "Werkzeug.*",
  [30113] = "Der Mann reagiert nicht. Er ist zu erschöpft und",
  [30114] = "halb bewußtlos.*",
  [30115] = "Der Mann kann nur mit Mühe trinken, als sie ihm",
  [30116] = "das Elixier einflößen. Dann aber zeigt sich eine",
  [30117] = "erstaunliche Wirkung. Mit jeder Sekunde scheint er",
  [30118] = "kräftiger zu werden, bis er sich schließlich -",
  [30119] = "wesentlich besser anzusehen - aufrichtet.",
  [30120] = "\"Du bist ein guter Mensch!\" dankt er Ihnen. \"Jetzt",
  [30121] = "kann ich wieder arbeiten, und die Wächter werden",
  [30122] = "mich nicht in die Schlucht werfen! Ich danke",
  [30123] = "Dir!\"*",
  [30124] = "Der Mann steht auf, und sucht nach seinem",
  [30125] = "Pickel. Schon im nächsten Augenblick erscheint",
  [30126] = "einer der Wächter, und brüllt ihn an: \"Was ist",
  [30127] = "los? Willst Du nicht arbeiten? Wo ist dein",
  [30128] = "Werkzeug?\"*",
  [30129] = "\"Na los, du Tagedieb!\" brüllt der Wächter. \"Ich",
  [30130] = "hab Dich hier schon eine Weile beobachtet! Du hast",
  [30131] = "geschlafen wie ein Baby!\"",
  [30132] = "Von irgendwoher erschallt ein Ruf, und der Wächter",
  [30133] = "dreht sich um. Dann wendet er sich wieder dem Mann",
  [30134] = "zu. \"Ich muß jetzt weg, aber wenn ich wiederkomme,",
  [30135] = "und du Dein Werkzeug nicht gefunden hast, und",
  [30136] = "nicht arbeitest, dann gnade Dir der große Kal!\"",
  [30137] = "Der Wächter stampft wütend davon.*",
  [30138] = "Hier läuft ein Mann umher und sucht verzweifelt",
  [30139] = "nach seinem Werkzeug, ohne das er nicht arbeiten",
  [30140] = "kann.*",
  [30141] = "\"Du hast also meinen Pickel!\" sagt der Mann und",
  [30142] = "nimmt ihn entgegen. \"Was für ein Glück! Wenn mich",
  [30143] = "der Wächter ohne den Pickel sehen würde, ginge es",
  [30144] = "mir schlecht!\"",
  [30145] = "Er sieht Sie fragend an. \"Jetzt aber hast Du",
  [30146] = "keinen mehr!\" stellt er fest. \"Aber ich glaube, Du",
  [30147] = "gehörst ohnehin nicht hierher, was? Also, steig in",
  [30148] = "die Karre, ich werde Dir helfen, hier wegzukommen!",
  [30149] = "Damit verschwindet der Mann.*",
  [30150] = "Es ist ein ganz normaler Pickel - in Fachkreisen",
  [30151] = "sagt man mitunter auch \"Spitzhacke\" dazu -",
  [30152] = "allerdings ist er vom harten Gestein schon",
  [30153] = "ziemlich abgenutzt und stumpf.*",
  [30154] = "Wie wollen Sie den nehmen? Der Mann liegt ja",
  [30155] = "darüber!*",
  [30156] = "Ohgott - so lassen Sie ihn doch liegen...!",
  [30157] = "Er hat ja überhaupt keine Kraft mehr... ach so!",
  [30158] = "Sie wollen den Pickel haben! Na dann vorsichtig...",
  [30159] = "gut. Der Mann sitzt jetzt an den Felsen gelehnt,",
  [30160] = "und der Pickel ist frei.*",
  [30161] = "Die Schienen führen von hier zu dem bewachten",
  [30162] = "Gang, der in der Mitte des Bergwerkes nach Osten",
  [30163] = "führt.*",
  [30164] = "Kleine Karren zum Transport losgehauenen Gesteins",
  [30165] = "werden von Sklaven auf den Schienen geschoben. Die",
  [30166] = "Schienen verlaufen von hier in nördlicher",
  [30167] = "Richtung, und zweigen in der Mitte des Bergwerkes",
  [30168] = "nach Osten in einen breiten, bewachten Gang ab.",
  [30169] = "Hier ist zur Zeit nicht viel los: nur eine leere",
  [30170] = "Karre steht herum.*",
  [30171] = "Die Karre, die hier steht, ist zum Transport",
  [30172] = "von Steinen gebaut. Sie hat einen großen, leeren",
  [30173] = "Ladekübel, ein Fahrgestell und eine Mechanik.*",
  [30174] = "Das Fahrgestell ist aus kräftigen Eisenteilen",
  [30175] = "gebaut, und besitzt vier kleine Räder, die in den",
  [30176] = "Schienen der Lorenbahn sitzen.*",
  [30177] = "Es ist eine Mechanik zum Entleeren der Karre. Mit",
  [30178] = "einem Hebel kann man den Ladekübel entriegeln - er",
  [30179] = "würde dann zur Seite wegkippen, und seinen Inhalt",
  [30180] = "- was immer auch drin ist, auf den Boden",
  [30181] = "ergießen.*",
  [30182] = "Es ist ein langer Hebel, der zur Seite wegsteht.",
  [30183] = "Man muß ihn nach oben ziehen, um den Ladekübel zu",
  [30184] = "entriegeln.*",
  [30185] = "An dem Hebel der Karre ist ein Seil befestigt.*",
  [30186] = "An dem Hebel der Karre ist ein Seil befestigt, das",
  [30187] = "in den leeren Ladekübel hineinhängt.*",
  [30188] = "Da rührt sich nichts. Der Ladekübel ist leer, und",
  [30189] = "hat kein Übergewicht, das ihn zur Seite kippen",
  [30190] = "lassen würde.*",
  [30191] = "Sie wollen Ihr Seil an den Hebel binden? Eine",
  [30192] = "Art... hm: drahtloser Fernbedienung, was? Haha!",
  [30193] = "Gut. Sie sollen Ihren Willen haben. Das Seil ist",
  [30194] = "jetzt am Hebel festgebunden.*",
  [30195] = "Also: machen wir es wieder ab. Das Seil ist nun",
  [30196] = "wieder in ihrem Besitz.*",
  [30197] = "Hm. Dunkel ist Ihrer Rede, oder besser: Ihrer",
  [30198] = "Handlung Sinn. Aber gut - das andere Ende Ihres",
  [30199] = "Seiles liegt nun in der Karre.*",
  [30200] = "Da wollen Sie rein...?",
  [30201] = "Gut, dann... puuh! Ist das dreckig hier! Aber was",
  [30202] = "soll's? Vielleicht die einzige Möglichkeit, hier",
  [30203] = "weg zu kommen!*",
  [30204] = "In der Karre",
  [30205] = "Hier ist es eng, und schrecklich dreckig. Die",
  [30206] = "Wände der Karre sind zum Glück hoch genug, daß man",
  [30207] = "von außen nicht hinein sehen kann.*",
  [30208] = "Inzwischen sind Sie halb unter - ächz! - kantigen",
  [30209] = "Steinen begraben.*",
  [30210] = "Außerdem befinden sie in der fragwürdigen Lage,",
  [30211] = "vollständig unter schwarzen Steinen begraben zu",
  [30212] = "sein! Ein Glück, daß Sie noch ein bißchen Luft",
  [30213] = "kriegen.*",
  [30214] = "Ein langes Seil reicht hier herein, dessen anderes",
  [30215] = "Ende sich irgendwo außerhalb der Karre befindet.*",
  [30216] = "Geben Sie acht, da kommt schon einer der",
  [30217] = "Sklaven... er sieht Sie fragend an. Dann kippt er",
  [30218] = "ungerührt einen Korb voller Steine über Sie.",
  [30219] = "Schnell ziehen Sie den Kopf ein!",
  [30220] = "Klänggg-a-dännggg!!! Die Steine poltern in die",
  [30221] = "Karre, und Sie werden halb darunter begraben.",
  [30222] = "Aufgepasst, da kommt schon die nächste Fuhre...*",
  [30223] = "Waaas? Das ist... nein, das ist nun wirklich",
  [30224] = "Quatsch! Ihre Idee ist schlau genug, um sie jetzt",
  [30225] = "nicht wieder zu verderben. Da draußen steht",
  [30226] = "inzwischen ein Wächter, der würde Sie sofort sehen",
  [30227] = "und verhaften! Bleiben Sie lieber, wo Sie sind!*",
  [30228] = "Der Sklave arbeitet unbeirrt weiter. Nach einiger",
  [30229] = "Zeit ist Ihre Karre voll. Das Gewicht der Steine",
  [30230] = "lastet schwer über Ihnen, aber es ist",
  [30231] = "auszuhalten.*",
  [30232] = "Da kommt schon einer der Sklaven... es ist der",
  [30233] = "blonde Mann, den Sie gerettet haben! Er zwinkert",
  [30234] = "Ihnen zu, und kippt - so vorsichtig er kann, einen",
  [30235] = "Korb voller Steine über Ihnen aus.",
  [30236] = "Klänggg-a-dännggg!!! Die Steine poltern in die",
  [30237] = "Karre, und Sie werden halb darunter begraben.",
  [30238] = "Aufgepasst, da kommt schon die nächste Fuhre...*",
  [30239] = "Der blonde Mann arbeitet unbeirrt weiter. Bevor er",
  [30240] = "die letzte Ladung über Sie kippt, nickt er Ihnen",
  [30241] = "aufmunternd - und irgendwie bedeutungsvoll zu. Das",
  [30242] = "Gewicht der Steine lastet schwer über Ihnen, aber",
  [30243] = "es ist auszuhalten.*",
  [30244] = "Wir haben eine gute und eine schlechte Nachricht",
  [30245] = "für Sie... welche wollen Sie zuerst hören?*",
  [30246] = "Die Gute...? Also: Sie leben noch.",
  [30247] = "Noch.*",
  [30248] = "Die schlechte Nachricht ist... nun, das sind etwa",
  [30249] = "vier Zentner blankes Vulkangestein über Ihnen. Für",
  [30250] = "jemanden, der sich fast überhaupt nicht rühren",
  [30251] = "kann, ist das ein gewaltiges Hindernis!*",
  [30252] = "Die schlechte Nachricht ist... nun, das sind etwa",
  [30253] = "vier Zentner blankes Vulkangestein über Ihnen. Für",
  [30254] = "jemanden, der sich nicht rühren kann, und dem",
  [30255] = "langsam die Luft ausgeht, ist das ein Hindernis",
  [30256] = "der vierten Art. Wissen Sie, was das ist?*",
  [30257] = "Nun, die erste Art ist tödliche Müdigkeit.",
  [30258] = "Die zweite Art: tödliche Müdigkeit, Handschellen,",
  [30259] = "Fußfesseln und Kopfweh. Die Dritte: tödliche",
  [30260] = "Müdigkeit, Handschellen, Fußfesseln, Knebel,",
  [30261] = "Kopfweh, Daumenschrauben, und keine Chance mehr,",
  [30262] = "den nächsten Tag zu erleben. Und die Vierte, das",
  [30263] = "ist.. soetwas... wie.... Sie..... es.......",
  [30264] = "gerade....... erle......... pffft.*",
  [30265] = "Sie wollen gar keine Informationen mehr? Nun, es",
  [30266] = "hilft auch nichts mehr... denn gerade ist der",
  [30267] = "Steinhaufen über Ihnen noch ein Stück weiter in",
  [30268] = "sich zusammengerutscht... oh nein, die Luft geht",
  [30269] = "aus.... hhhhhhhhhh.........*",
  [30270] = "Nach langer Zeit setzt sich die Karre endlich in",
  [30271] = "Bewegung. Für eine Weile geht die Fahrt gemächlich",
  [30272] = "dahin, dann kommt eine Kurve, und schließlich",
  [30273] = "rattert Ihr Gefährt in rasanter Fahrt abwärts.",
  [30274] = "Durch die Erschütterungen rütteln sich die Steine",
  [30275] = "über Ihnen fest. Es wird langsam unbequem. Zum",
  [30276] = "Glück kriegen sie noch ein bißchen Luft. Dann,",
  [30277] = "nach einer halben Ewigkeit, kommt die Lore mit",
  [30278] = "einem unsanften Ruck zum Stehen. Um Sie herum",
  [30279] = "herrscht vollkommene Stille.*",
  [30280] = "Sie sind gut... wie soll denn das so leicht",
  [30281] = "gehen...? Also wursteln sie sich erstmal die",
  [30282] = "Handgelenke frei... autsch! ... ja, nur weiter...",
  [30283] = "langsam entsteht ein bißchen Platz... und nun das",
  [30284] = "Seil... Zentimeter für Zentimeter.... Vorsicht!!",
  [30285] = "Rrrrruummmmsssss!!!",
  [30286] = "Mit lautem Gepolter kracht der Ladekübel zur Seite",
  [30287] = "und die Steine und Sie purzeln mit Getöse auf",
  [30288] = "einen harten Boden. Um Sie herum ist es",
  [30289] = "stockfinster.*",
  [30290] = "Machen Sie lieber erstmal Licht! Hier ist es so",
  [30291] = "finster wie in einem Bergwerk! Mhm.*",
  [30292] = "Lorenbahnhof",
  [30293] = "Dies ist die hohe und sehr langestreckte",
  [30294] = "Halle eines unterirdischen Rangierbahnhofs. Im",
  [30295] = "spärlichen Licht sind Dutzende von gefüllten",
  [30296] = "Karren auf Gleisen zu sehen - sechsspurig",
  [30297] = "nebeneinander, die Reihen verlieren sich Richtung",
  [30298] = "Norden in der Ferne. Nach Osten führt ein Gang.",
  [30299] = "In der Nähe steht eine leere Karre.*",
  [30300] = "Hier liegt ein Haufen schwarzer Steine herum - es",
  [30301] = "sind die, die mitsamt Ihnen aus Ihrer Karre",
  [30302] = "gekippt sind.*",
  [30303] = "Oh! Was ist das? Dort, zwischen den Steinen, da",
  [30304] = "liegt ja ein...",
  [30305] = "Du lieber Himmel, es ist der gesuchte sechste",
  [30306] = "Splitter von Auge des Kal! Das muß der blonde Mann",
  [30307] = "gewesen sein! Es ist sein Geschenk für Sie!*",
  [30308] = "Nordende der Halle",
  [30309] = "Hier ist das nördliche Ende des Lorenbahnhofs.",
  [30310] = "Eine automatische Anlage befördert gemächlich",
  [30311] = "einzelne Karren auf eine Plattform hinauf und",
  [30312] = "kippt ihre Ladekübel. Die Steine poltern in einen",
  [30313] = "schwarzen Schlund.*",
  [30314] = "Hier liegen ein paar schwarze Steine auf dem",
  [30315] = "Boden. Sie untgerscheiden sich in nichts von all",
  [30316] = "den anderen, die es hier im Bergwerk gibt.*",
  [30317] = "Da sieht man nur einen einen Haufen mechanischer",
  [30318] = "Gestänge, Zahnräder und ähnliches.*",
  [30319] = "Es ist nichts zu erkennen, die Steine verschwinden",
  [30320] = "in der Dunkelheit. Nach den Geräuschen zu",
  [30321] = "urteilen, dauert es ziemlich lange, bis sie",
  [30322] = "irgendwo tief unten ankommen.*",
  [30323] = "Wollen Sie sich umbringen? Nein, nein, so geht das",
  [30324] = "nicht! Sie haben schließlich die Welt zu retten,",
  [30325] = "oder so.*",
  [30326] = "Es sind etwa siebzig bis achtzig volle Karren, die",
  [30327] = "hier auf den Gleisen stehen. Wegen der Dunkelheit",
  [30328] = "lässt sich ihre Zahl nur schätzen. Sie werden",
  [30329] = "langsam aber stetig hinauf auf die Plattform",
  [30330] = "gezogen, und dort ausgeleert.*",
  [30331] = "Auf der Plattform",
  [30332] = "Hier ist es nicht ungefährlich, denn der vordere",
  [30333] = "Teil der Plattform kippt jedesmal nach unten weg,",
  [30334] = "wenn einer der Karren ausgeleert wird. Ansonsten",
  [30335] = "gibt es hier aber nicht viel zu sehen. Es ist nur",
  [30336] = "dunkel, staubig und laut an diesem Ort.*",
  [30337] = "Die Karren kommen voll hier oben an, befreien sich",
  [30338] = "polternd von der Last ihrer Steine, und rollen",
  [30339] = "dann langsam weiter in eine Kopplungsanlage, wo",
  [30340] = "sie aneinandergehängt werden.*",
  [30341] = "Hier auf der Plattform liegen einige der schwarzen",
  [30342] = "Basaltsteine herum, die beim Auskippen der Karren",
  [30343] = "nicht den richtigen Weg gefunden haben. Aber sie",
  [30344] = "sind allesamt nur schwarz und langweilig, so wie",
  [30345] = "alle anderen Steine hier sonst auch.*",
  [30346] = "Es handelt sich um eine automatische Anlage, die",
  [30347] = "die einzelnen Wagen aneinander koppelt. Die so",
  [30348] = "entstandenen, kleinen Züge rollen nach Norden",
  [30349] = "davon, zu einem Transportgleis.*",
  [30350] = "Auf dem Transportgleis werden die Karrenzüge",
  [30351] = "beschleunigt, und rollen dann polternd durch einen",
  [30352] = "Tunnel davon.*",
  [30353] = "Es handelt sich um einen schmalen Tunnel, der",
  [30354] = "durch ein automatisches Gitter verschlossen ist,",
  [30355] = "das sich immer nur für kurze Zeit öffnet, wenn ein",
  [30356] = "Karrenzug in den Tunnel fahren muß.*",
  [30357] = "Es ist ein automatisches Gitter, das sich nur dann",
  [30358] = "öffnet, wenn ein ausreichend schweres Objekt über",
  [30359] = "die Schienen fährt.*",
  [30360] = "Am Transportgleis",
  [30361] = "Hier gibt es momentan einen Stau. Eine einzelne",
  [30362] = "Karre hat sich losgelöst. Die automatische Anlage,",
  [30363] = "welche die Karren-Züge beschleunigen soll, scheint",
  [30364] = "darauf zu warten, daß nachdrängende Karren den",
  [30365] = "ersten nach vorne schieben, währenddessen die",
  [30366] = "Kopplungsanlage darauf wartet, daß der einzelne",
  [30367] = "Karren den Weg freigibt. Dieser aber scheint zu",
  [30368] = "leicht zu sein, um die automatische Reibungsbremse",
  [30369] = "zu überwinden. Hm. Ein schwerwiegendes Problem!*",
  [30370] = "Die Kopplungsanlage liegt auf einer Plattform hier",
  [30371] = "ganz in der Nähe. Sie arbeitet im Moment nicht, da",
  [30372] = "hier irgendwie ein Stau entstanden ist. Vielleicht",
  [30373] = "durch jene einzelne, leere Karre, die heute hier",
  [30374] = "unten ankam, und mit der auch der schlaueste",
  [30375] = "automatische Lorenbahnhof nicht rechnet.*",
  [30376] = "Die Reibungsbreme ist im Gleis eingebaut, und soll",
  [30377] = "einen Karrenzug wohl solange festhalten, bis er",
  [30378] = "lang genug ist. Der einzelne Karren, der hier",
  [30379] = "steht, ist offensichtlich zu leicht, um sie zu",
  [30380] = "überwinden. Deshalb der Stau.*",
  [30381] = "Ah! Jetzt tut sich was... zwar nur zögernd, aber",
  [30382] = "immerhin! Langsam rollt Ihre Karre los, auf dem",
  [30383] = "Gleis quietscht es zuerst ein bißchen, dann aber",
  [30384] = "packt das Transportgleis zu, beschleunigt die",
  [30385] = "Karre, und ab geht's durch das automatische Gitter",
  [30386] = "in den langen Tunnel...*",
  [30387] = "Für lange Zeit geht die Fahrt durch schwärzeste",
  [30388] = "Finsternis. Doch dann erscheint, weit vor Ihnen,",
  [30389] = "endlich wieder Licht. Die Karre wird plötzlich von",
  [30390] = "einer rasselnden Förderkette gepackt, und steil",
  [30391] = "bergauf gezogen. Zwei Minuten später taucht Ihre",
  [30392] = "Karre wieder in der Bergwerkshalle auf. Die Hämmer",
  [30393] = "und Pickel dröhnen in der altbekannten Weise.*",
  [30394] = "Vorsicht, da guckt einer der Wächter herüber...",
  [30395] = "so, jetzt können Sie raus!",
  [30396] = "Kaum, daß Sie wieder auf festem Boden stehen,",
  [30397] = "kommt schon ein Sklave daher, bemächtigt sich",
  [30398] = "Ihrer Karre, und schiebt sie nach Süden davon.*",
  [30399] = "Für lange Zeit geht die Fahrt durch schwärzeste",
  [30400] = "Finsternis. Doch dann erscheint, weit vor Ihnen,",
  [30401] = "endlich wieder Licht. Die Fahrt wird erheblich",
  [30402] = "langsamer.*",
  [30403] = "Dann wird die Karre plötzlich von einer rasselnden",
  [30404] = "Förderkette gepackt.*",
  [30405] = "Die Förderkette zieht Sie steil bergauf. Zwei",
  [30406] = "Minuten später taucht Ihre Karre wieder in der",
  [30407] = "Bergwerkshalle auf. Die Hämmer und Pickel dröhnen",
  [30408] = "in der altbekannten Weise.*",
  [30409] = "Sie wollen hier aussteigen? Ja, aber...",
  [30410] = "Halt! So bleiben Sie doch da! Oh...",
  [30411] = "Sehen Sie, das haben Sie nun davon! Ihre Karre",
  [30412] = "rattert hinauf, und Sie stehen nun hier",
  [30413] = "mutterseelenallein in diesem kalten Tunnel.*",
  [30414] = "Südende der Halle",
  [30415] = "Hier ist das Südende des Lorenbahnhofs. Eine",
  [30416] = "automatische Weichenanlage befördert die vollen",
  [30417] = "Loren, die hier eintreffen, auf eines der sechs",
  [30418] = "Gleise. Durch einen schmalen Gang, der in",
  [30419] = "südlicher Richtung steil aufwärts führt, kommen",
  [30420] = "die Loren von Zeit zu Zeit an.*",
  [30421] = "Einige mechanische Gestänge verlaufen neben und",
  [30422] = "zwischen den Gleisen. Dahinter folgt ein System",
  [30423] = "von Weichen.*",
  [30424] = "Der Gang ist eng und führt aufwärts. Ein einzelnes",
  [30425] = "Gleis läuft hindurch. Er ist nur so breit, daß",
  [30426] = "gerade eine Lore hindurchpasst. Von weit oben",
  [30427] = "dringt spärliches Licht herab.*",
  [30428] = "Warten Sie! Gerade kommt eine Lore",
  [30429] = "heruntergesaust! Ratadommmm...!",
  [30430] = "So, jetzt ist der Weg frei! Aber es ist ein gutes",
  [30431] = "Stück bis dort hinauf! Glauben Sie, Sie schaffen",
  [30432] = "das, bis die nächste volle Lore herunterkommt?*",
  [30433] = "So? Wir nicht.*",
  [30434] = "Wir auch nicht.*",
  [30435] = "Na denn. Bald haben Sie schon dreißig oder vierzig",
  [30436] = "Meter geschafft. In diesem Augenblick verdunkelt",
  [30437] = "sich das Licht dort oben. Am Gepolter, das gleich",
  [30438] = "darauf ertönt, läßt sich abschätzen, daß die",
  [30439] = "Karre, die auf dem Weg zu Ihnen ist, mitsamt den",
  [30440] = "Steinen etwa zwei Tonnen wiegen muß.*",
  [30441] = "Schnell... beeilen Sie sich, um Himmels Willen...",
  [30442] = "die Karre donnert im D-Zug-Tempo herab...*",
  [30443] = "Ja, noch ein paar Meter... lassen Sie sich",
  [30444] = "fallen... und jetzt zur Seite....",
  [30445] = "wrrruuummmmm.....!!!",
  [30446] = "Puuh! Das war knapp! Die Karre donnert an ihnen",
  [30447] = "vorbei, und wird gleich darauf von der",
  [30448] = "Weichenanlage gebremst.*",
  [30449] = "Es wäre fast erforderlich, für so übermütige",
  [30450] = "Abenteurer wie Sie einen Glücksfaktor zu",
  [30451] = "programmieren. Haben Sie etwa erwartet, die Lore",
  [30452] = "würde extra eine Kurve um Sie herum machen?",
  [30453] = "Nein, macht sie nicht....",
  [30454] = "Rrrrruummmmsssss....!!!*",
  [30455] = "Im östlichen Gang",
  [30456] = "Dies ist ein weiterer der vielen Gänge hier unten",
  [30457] = "im Bergwerk. Er führt in östlicher Richtung vom",
  [30458] = "Lorenbahnhof weg... mal sehen, wohin man hier",
  [30459] = "gelangt...*",
  [30460] = "Plötzlich ist ein Licht zu sehen. Es stammt von",
  [30461] = "einer... Laterne!",
  [30462] = "Kurze Zeit darauf kommt Ihnen ein Mann entgegen.",
  [30463] = "Es ist ein alter Mann, in einen weißen Umhang",
  [30464] = "gewandet. Er bleibt vor Ihnen stehen, und hält die",
  [30465] = "Laterne hoch.*",
  [30466] = "Der Alte betrachtet Sie erstaunt.",
  [30467] = "\"Es ist... selten, daß ich hier unten Besuch",
  [30468] = "bekomme,\" sagt er zögernd. \"Kommst Du von oben,",
  [30469] = "aus dem Bergwerk? Ich meine... bist Du ein Sklave,",
  [30470] = "der weggelaufen ist?\"*",
  [30471] = "\"Ich weiß nicht, was Du meinst,\" sagt der Alte.",
  [30472] = "\"Willst Du meine Frage nicht beantworten - bist Du",
  [30473] = "ein entflohener Sklave?\"*",
  [30474] = "\"Willst Du meine Frage nicht beantworten - bist Du",
  [30475] = "ein entflohener Sklave?\"*",
  [30476] = "\"Wirklich? Nun, ich weiß nicht, ob ich Dir",
  [30477] = "überhaupt helfen kann. Ich bin selbst hier",
  [30478] = "eingesperrt, und weiß keinen Ausgang. Meine",
  [30479] = "einzige Aufgabe besteht darin, auf eine bestimmte",
  [30480] = "Begebenheit zu warten - aber das tue ich schon",
  [30481] = "sehr, sehr lange.\"*",
  [30482] = "\"Nein? Dann...\" Der Alte wird mißtrauisch. \"Dann",
  [30483] = "kann ich mir nicht vorstellen, aus welchem Grunde",
  [30484] = "Du Dich den Gefahren ausgesetzt hast, bis hierher",
  [30485] = "zu gelangen? Suchst Du hier jemanden?\"*",
  [30486] = "Der Alte wird mißtrauisch. \"Ich wüßte nicht, was",
  [30487] = "Dich das anginge,\" meint er. \"Und ich kann mir",
  [30488] = "nicht vorstellen, aus welchem Grunde Du Dich den",
  [30489] = "Gefahren ausgesetzt hast, bis hierher zu gelangen.",
  [30490] = "Suchst Du hier jemanden?\"*",
  [30491] = "Der Gesichtsausdruck des Alten entspannt sich.",
  [30492] = "\"Nun - dann haben wir ohnehin nichts miteinander",
  [30493] = "zu tun. Leider kann ich Dir auch keinen Weg hier",
  [30494] = "heraus zeigen. Ich muß jetzt wieder gehen. Leb",
  [30495] = "wohl!\"",
  [30496] = "Der Alte senkt seine Laterne wieder, und",
  [30497] = "marschiert Richtung Osten davon. Bald darauf ist",
  [30498] = "er verschwunden.*",
  [30499] = "Der Alte wird noch mißtrauischer. \"So? Dann sag",
  [30500] = "mir den Namen desjenigen, den Du suchst!\"*",
  [30501] = "\"So einen Namen habe ich noch nie gehört,\" sagt",
  [30502] = "der Alte. \"Es ist besser, Du gehst jetzt wieder.",
  [30503] = "Ich kann Dir ohnehin nicht helfen! Leb wohl.\"",
  [30504] = "Der Alte senkt seine Laterne wieder, und",
  [30505] = "marschiert Richtung Osten davon. Bald darauf ist",
  [30506] = "er verschwunden.*",
  [30507] = "Der Alte Mann wird blaß.",
  [30508] = "\"Du... du weißt meinen Namen?\" ruft er erstaunt.",
  [30509] = "Dann verwandeln sich seine Züge zu einem Ausdruck",
  [30510] = "ungeheurer Glückseeligkeit.",
  [30511] = "\"Ich kann es nicht glauben! Solltest Du derjenige",
  [30512] = "sein...? Schnell, beweise es mir! Zeige mir die",
  [30513] = "anderen Splitter vom Auge des Kal. Du mußt sie ja",
  [30514] = "haben, sonst wärest Du nicht bis hierher",
  [30515] = "gekommen!\"*",
  [30516] = "\"Nun mach schon! Zeig mir die Splitter! Damit ich",
  [30517] = "Dir glauben kann!\"*",
  [30518] = "Tells Gesichtsausdruck verwandelt sich in maßlose",
  [30519] = "Enttäuschung. \"Es stimmt also doch nicht,\" sagt er",
  [30520] = "ärgerlich. \"Du wolltest mich nur zum Besten",
  [30521] = "halten! Es ist besser, Du gehst jetzt wieder. Ich",
  [30522] = "kann Dir ohnehin nicht helfen! Leb wohl.\"",
  [30523] = "Der Alte senkt seine Laterne wieder, und",
  [30524] = "marschiert Richtung Osten davon. Bald darauf ist",
  [30525] = "er verschwunden.*",
  [30526] = "Tell nimmt die Splitter entgegen. \"Tatsächlich!",
  [30527] = "Die Weissagung hat sich also doch erfüllt: Du bist",
  [30528] = "derjenige, der die Welt von dem schrecklichen Kal",
  [30529] = "befreien soll!\"",
  [30530] = "Doch dann stutzt er. \"Oh... es sind nur fünf! Ja,",
  [30531] = "ich kann es mir denken - den Sechsten, der sich",
  [30532] = "hier irgendwo im Bergwerk befinden muß, hast Du",
  [30533] = "noch nicht gefunden! Tja, das ist ein besonderes",
  [30534] = "Problem! Aber komm erstmal mit mir!\" sagt er und",
  [30535] = "winkt Ihnen. \"Wir wollen in die Schmiede gehen!\"",
  [30536] = "Damit marschiert er Richtung Osten davon.*",
  [30537] = "Tell nimmt die Splitter entgegen. \"Tatsächlich!",
  [30538] = "Die Weissagung hat sich also doch erfüllt: Du bist",
  [30539] = "derjenige, der die Welt von dem schrecklichen Kal",
  [30540] = "befreien soll!\"",
  [30541] = "\"Komm mit mir!\" sagt er und winkt Ihnen. \"Wir",
  [30542] = "wollen in die Schmiede gehen!\" Damit marschiert er",
  [30543] = "Richtung Osten davon.*",
  [30544] = "In der Vulkanschmiede",
  [30545] = "Dies ist ein großer, kuppelförmiger Raum. Jeder",
  [30546] = "Schritt, jeder Laut, hallt gespenstisch von der",
  [30547] = "Decke wieder. In der Mitte der Schmiede befindet",
  [30548] = "sich eine großer, runder Schacht im Boden, der",
  [30549] = "hüfthoch ummauert ist. An der Wand steht ein",
  [30550] = "großer steinerner Tisch. Es ist entsetzlich heiß.",
  [30551] = "Der alte Mann ist hier.*",
  [30552] = "Sein Alter ist absolut unbestimmbar. Er ist",
  [30553] = "hochgewachsen, schlank, trägt einen (für solche",
  [30554] = "Spiele unvermeidlichen) langen, weißen Bart, und",
  [30555] = "ist in einen (ebenso unvermeidlichen) weißen",
  [30556] = "Umhang gekleidet.*",
  [30557] = "Der Schacht ist ummauert wie ein Brunnen, und",
  [30558] = "darunter führt es weit hinab in die Tiefe des",
  [30559] = "Berges. Dort unten brodelt ein heißer Lavasee, und",
  [30560] = "enorme Hitze steigt durch den Schacht herauf.*",
  [30561] = "Es ist ein großer, steinerner Tisch, der einst aus",
  [30562] = "der Felswand herausgearbeitet wurde.*",
  [30563] = "Auf dem Tisch liegt eine Art Gußform.*",
  [30564] = "Es ist eine Form aus einem seltsam schimmernden",
  [30565] = "Metall, an deren oberem Ende eine lange, lange",
  [30566] = "Kette befestigt ist.*",
  [30567] = "Das Metall kann man schlecht beschreiben - aber es",
  [30568] = "sieht so glatt und hart aus, daß man meint, es",
  [30569] = "könnte extrem hohe Temperaturen aushalten.*",
  [30570] = "Die Kette scheint aus dem gleichen Metall zu",
  [30571] = "bestehen, wie die Gußform.*",
  [30572] = "Diese Dinge sind von besonderer Art, und sollten",
  [30573] = "nur von kundiger Hand benutzt werden. Es hilft",
  [30574] = "Ihnen mehr, wenn Sie sie lassen, wo sie sind.*",
  [30575] = "\"Du bist es?\" fragt der alte Mann erstaunt. \"Was",
  [30576] = "willst Du denn noch? Ich dachte, Du wärest hier",
  [30577] = "nur zufällig hingeraten. Suchst Du etwa doch nach",
  [30578] = "jemandem?\"*",
  [30579] = "\"So einen Namen habe ich noch nie gehört,\" sagt",
  [30580] = "der Alte. \"Es ist besser, Du gehst jetzt wieder.",
  [30581] = "Ich kann Dir ohnehin nicht helfen! Leb wohl.\"",
  [30582] = "Er nimmt sie sanft aber bestimmt bei den",
  [30583] = "Schultern, und schiebt sie hinaus.*",
  [30584] = "Tells Gesichtsausdruck verwandelt sich in maßlose",
  [30585] = "Enttäuschung. \"Es stimmt also doch nicht,\" sagt er",
  [30586] = "ärgerlich. \"Du wolltest mich nur zum Besten",
  [30587] = "halten! Es ist besser, Du gehst jetzt wieder. Ich",
  [30588] = "kann Dir ohnehin nicht helfen! Leb wohl.\"",
  [30589] = "Er nimmt sie sanft aber bestimmt bei den",
  [30590] = "Schultern, und schiebt sie hinaus.*",
  [30591] = "Tell nimmt die Splitter entgegen. \"Tatsächlich!",
  [30592] = "Die Weissagung hat sich also doch erfüllt: Du bist",
  [30593] = "derjenige, der die Welt von dem schrecklichen Kal",
  [30594] = "befreien soll!\"*",
  [30595] = "Tell setzt sich. Sein Gesichtsausdruck wirkt",
  [30596] = "plötzlich unendlich müde. \"Wir haben leider ein",
  [30597] = "Problem!\" sagt er. \"Ohne es gelöst zu haben, wirst",
  [30598] = "Du Kal nicht besiegen können!\"*",
  [30599] = "\"Das Problem besteht darin, daß der sechste",
  [30600] = "Splitter sich hier irgendwo Im Inneren des Berges",
  [30601] = "befinden muß. Deshalb gibt es hier soviel Sklaven,",
  [30602] = "die ihn suchen müssen.",
  [30603] = "Daß Du jetzt hier bist, bedeutet, daß der sechste",
  [30604] = "Splitter wahrscheinlich bald gefunden werden wird.",
  [30605] = "Die Zeit ist gekommen! Du mußt nun wieder gehen,",
  [30606] = "und versuchen, ihn vor den Sklaven zu finden!\"*",
  [30607] = "\"Ich weiß nicht, was Du meinst,\" sagt der Alte.*",
  [30608] = "\"Darüber weiß ich nichts!\" sagt der Alte.*",
  [30609] = "\"Die Weissagung stammt von meinem Freund Lharas,",
  [30610] = "der aber schon lange tot ist,\" berichtet Tell. \"Er",
  [30611] = "sagte, daß eines Tages ein Mensch aus der realen",
  [30612] = "Welt kommen wird, um die Splitter des Auges zu",
  [30613] = "finden, und mit Ihrer Hilfe den schrecklichen Gott",
  [30614] = "Kal vernichten wird.\"*",
  [30615] = "\"Die Sklaven durchwühlen seit ungezählen Jahren",
  [30616] = "diesen Berg, in einst der sechste Splitter",
  [30617] = "verloren ging. Haben Sie ihn gefunden, wird zwar",
  [30618] = "Kal dadurch sein Augenlicht nicht zurückbekommen,",
  [30619] = "aber es wird einem wie Dir auch unmöglich sein,",
  [30620] = "das Auge des Kal zu vervollständigen, und ihn",
  [30621] = "damit zu besiegen!\"*",
  [30622] = "\"Lharas war mein Freund,\" berichtet Tell. \"Aber",
  [30623] = "ist schon lange tot. Er schlug Kal einst sein Auge",
  [30624] = "aus, und ich verteilte die Splitter über die",
  [30625] = "Zeiten und Räume dieser Welt. Lharas wurde von Kal",
  [30626] = "in ein schreckliches, augenloses Montrum",
  [30627] = "verwandelt, aber bevor er nach vielen Jahren",
  [30628] = "endlich starb, befahl er mir, hier in der",
  [30629] = "Vulkanschmiede auf den Auserwählten zu warten, und",
  [30630] = "machte mir die Weissagung.\"*",
  [30631] = "\"Das Auge des Kal!\" sagt Tell nachdenklich",
  [30632] = "nickend. \"Das ist das Ziel Deiner Mission! Seine",
  [30633] = "sechs Splitter zu finden, und mit Ihrer Hilfe den",
  [30634] = "schrecklichen Kal zu vernichten!\"*",
  [30635] = "\"Da bist Du ja wieder, mein Freund!\" ruft Tell",
  [30636] = "erfreut, und eilt Ihnen entgegen. \"Bist Du fündig",
  [30637] = "geworden? Hast Du den sechsten Splitter",
  [30638] = "gefunden?\"*",
  [30639] = "\"Nein?\" Tells Züge zeigen Besorgnis. \"Du mußt es",
  [30640] = "nochmal versuchen! Wenn Du ihn nicht vor den",
  [30641] = "Sklaven findest, dann ist alles zu spät! Dann",
  [30642] = "wirst Du Kal niemals besiegen können! Und nun geh!",
  [30643] = "Versuche Dein Glück nochmal!\"*",
  [30644] = "\"Du hast ihn tatsächlich gefunden?\" Tell nimmt mit",
  [30645] = "feuchten Augen und überglücklich den Splitter",
  [30646] = "entgegen. \"Dann laß' uns beginnen. Wir wollen das",
  [30647] = "Auge des Kal wieder vollständig zusammenfügen!\"*",
  [30648] = "Tell macht sich an die Arbeit, und bereitet die",
  [30649] = "historische Tat vor. Er fügt die sechs Splitter in",
  [30650] = "der Form auf die richtige Weise zusammen, hebt sie",
  [30651] = "dann über den Rand des Schachtes, und läßt Sie an",
  [30652] = "der Kette hinunter in den glühenden Schlund.",
  [30653] = "Bald steigt ein gewaltiger Hitzeschwall herauf.",
  [30654] = "Während Tell eine beschwörerische Melodie",
  [30655] = "intoniert, kocht und brodelt es tief unten, und",
  [30656] = "Kaskaden von glühenden Funken steigen herauf.*",
  [30657] = "Dann, nach einigen Minuten, brausen glühendheiße",
  [30658] = "Luftströme herauf - die Temperatur wird fast",
  [30659] = "unerträglich, und plötzlich, nach einem gewaltigen",
  [30660] = "Donnern, ist alles plötzlich wieder ruhig.",
  [30661] = "Tell zieht die Form wieder herauf, schlägt sie mit",
  [30662] = "einem Hammer auseinander, und holt einen riesigen,",
  [30663] = "hellschimmernden Edelstein hervor.",
  [30664] = "\"Das Auge!\" sagt er mit ehrfürchtiger Stimme, und",
  [30665] = "hält den Edelstein in die Höhe. \"Das Auge des",
  [30666] = "Kal!\"*",
  [30667] = "Es ist ein blau schimmernder Edelstein",
  [30668] = "von der erstaunlichen Größe einer Orange. Aus",
  [30669] = "seiner Mitte dringt irrisierendes Licht, das einem",
  [30670] = "schwarzen, pulsierenden Schleier zu entspringen",
  [30671] = "scheint.*",
  [30672] = "\"Jetzt ist es an Dir!\" sagt Tell dramatisch.",
  [30673] = "Damit allein kann der schreckliche Gott Kal",
  [30674] = "besiegt werden! Nimm diesen Edelstein, und suche",
  [30675] = "Kal! Er schläft in seinem Tempel, in dieser, der",
  [30676] = "sechsten Welt! Nur mit Hilfe des Auges kann er für",
  [30677] = "immer besiegt werden!\"",
  [30678] = "Mit einem aufmunternden Nicken hält Tell Ihnen das",
  [30679] = "\"Auge\" hin.*",
  [30680] = "\"Was ist? Willst Du das \"Auge\" nicht nehmen?\"",
  [30681] = "fragt Tell. \"Jetzt beginnt das letzte, große",
  [30682] = "Abenteuer für Dich!\"*",
  [30683] = "Du lieber Himmel! Wollen Sie den Erfolg Ihrer",
  [30684] = "ganzen Mission aufs Spiel setzen?",
  [30685] = "Behalten Sie das \"Auge\", und passen Sie gut darauf",
  [30686] = "auf!*",
  [30687] = "Im Lorentunnel",
  [30688] = "Hier beginnt das letzte steile Schienenstück, das",
  [30689] = "hinauf ins Bergwerk führt. Nach Osten hingegen",
  [30690] = "führt der Tunnel zurück in die Dunkelheit.*",
  [30691] = "Die Schienen sind auf einem schmalen,",
  [30692] = "freitragenden Holzgestell montiert - bei dieser",
  [30693] = "Beleuchtung ist es schlichtweg unmöglich, dort",
  [30694] = "hinauf zu klettern, ohne sich den Hals zu",
  [30695] = "brechen!*",
  [30696] = "Gangabzweigung",
  [30697] = "Hier kommt von Osten der Tunnel, durch den die",
  [30698] = "Schienen der Lorenbahn bis hinauf ins Bergwerk",
  [30699] = "verlaufen; nach Norden hingegen zweigt ein",
  [30700] = "schmaler, geheimnisvoller Gang ab.*",
  [30701] = "In dieser Richtung liegt nur ein langweiliger",
  [30702] = "Tunnel, der letztlich vor dem automatischen Gitter",
  [30703] = "des Lorenbahnhofs endet. Ganz ehrlich: Da gibt es",
  [30704] = "nichts von Interesse.*",
  [30705] = "Der schmale Gang führt endlos durch das Innere des",
  [30706] = "Berges. Endlich, nach langer Zeit, wird wieder",
  [30707] = "Licht sichtbar.*",
  [30708] = "Sklavenquartier",
  [30709] = "Hier liegt eine große Halle tief unter Ihren",
  [30710] = "Füßen. Der Gang führt wie eine Balustrade am",
  [30711] = "obersten Teil der Wand entlang weiter nach Norden,",
  [30712] = "und verschwindet auf der anderen Seite durch einen",
  [30713] = "Tunneleingang wieder im Inneren des Berges.",
  [30714] = "Unten in der Halle hingegen, sind Betten, Schränke",
  [30715] = "und Tische für mehrere hundert Sklaven aufgebaut.*",
  [30716] = "Der Gang führt wie eine Balustrade am obersten",
  [30717] = "Teil der Wand entlang weiter nach Norden, und",
  [30718] = "verschwindet auf der anderen Seite durch einen",
  [30719] = "Tunneleingang wieder im Inneren des Berges.*",
  [30720] = "Es handelt sich um das Sklavenquartier. Die",
  [30721] = "Betten, Tische und Schränke sind eng und",
  [30722] = "kasernenmäßig aufgebaut. Eine Anzahl Sklaven, die",
  [30723] = "wohl Freischicht haben, werden von etlichen",
  [30724] = "Wachleuten, die dort unten patroullieren, streng",
  [30725] = "beaufsichtigt.*",
  [30726] = "Am Tunneleingang",
  [30727] = "Hier, vom nördlichen, oberen Teil der Halle, hat",
  [30728] = "man einen ebensoguten Ausblick über das große",
  [30729] = "Sklavenquartier. Nach Norden geht es in einen",
  [30730] = "schmalen Tunnel hinein.*",
  [30731] = "Ein alter Mann fegt den Boden mit einem",
  [30732] = "Reisigbesen. Er trägt einen weiten Umhang mit",
  [30733] = "Kapuze. Sein Gesicht ist nicht zu erkennen.*",
  [30734] = "Tell ist hier, verborgen unter seiner Kapuze, und",
  [30735] = "er fegt hier noch immer den Boden. Als er Sie",
  [30736] = "erkennt, winkt er Sie herbei. \"Was ist mit Dir?",
  [30737] = "Hast Du noch eine Frage? Dann stelle sie.\"*",
  [30738] = "Der Mann blickt auf, und lupft seine Kapuze ein",
  [30739] = "wenig. Tells Gesicht kommt zum Vorschein! 'Pssst!'",
  [30740] = "zischt er und winkt Sie herbei.*",
  [30741] = "Tell sieht sich nervös um. \"Hier ist es gefährlich",
  [30742] = "für mich, ich muß bald wieder fort! Also höre mir",
  [30743] = "gut zu! Dein Weg wird nun sehr schwierig, denn Du",
  [30744] = "mußt nun bald durch die Schwarze Krypta der",
  [30745] = "Dreiäugigen Bestie! Aber ich habe noch eine kleine",
  [30746] = "Hilfe für Dich!\"",
  [30747] = "Er holt unter seiner Kutte ein kleines, goldenes",
  [30748] = "Amulett hervor. \"Nimm dies!\" sagt er, und hält es",
  [30749] = "Ihnen hin.*",
  [30750] = "\"Hier, nun nimm das Amulett schon!\" sagt Tell",
  [30751] = "ungeduldig, und hält es Ihnen vor die Nase.*",
  [30752] = "\"Wenn Du es öffnest, kommt Pit, ein kleiner",
  [30753] = "Kobold, herausgesprungen. Er ist ein lieber Freund",
  [30754] = "von mir, und kennt sich in der Schwarzen Krypta",
  [30755] = "gut aus. Er wird Dir helfen. Nur zwei Dinge noch:",
  [30756] = "Öffne das Amulett erst, wenn Du die Krypta",
  [30757] = "erreicht hast, sonst läuft er Dir davon. Und Pit",
  [30758] = "hat einen kleinen Fimmel: er ist sehr belesen, und",
  [30759] = "spricht immer in Reimen und Rätseln, weil er mit",
  [30760] = "seinem Wissen angeben will. Das ist nunmal sein",
  [30761] = "einziges Vergnügen. Also höre ihm gut zu, und",
  [30762] = "überlege gründlich, was er meint!\"*",
  [30763] = "\"Pit ist ein guter Kerl, aber er ist ein bißchen",
  [30764] = "verrückt. Er spricht aus purer Angabe immer in",
  [30765] = "Rätseln und Reimen, aber störe Dich nicht daran.",
  [30766] = "Denke gut darüber nach, was er meint, denn er ist",
  [30767] = "der einzige, der den Weg durch die Schwarze Krypta",
  [30768] = "weiß. Und laß ihn erst dort heraus, sonst läuft er",
  [30769] = "Dir davon! Das ist sehr wichtig!",
  [30770] = "Noch etwas: Pit riecht nicht sehr gut. Er könnte",
  [30771] = "wohl mal ein ausgiebiges Bad gebrauchen, aber das",
  [30772] = "will er nicht. Störe Dich also auch daran nicht!\"*",
  [30773] = "\"Die Bestie ist sehr gefährlich!\" sagt Tell. \"Aber",
  [30774] = "Ihre Gefährlichkeit liegt darin, daß Sie das",
  [30775] = "verleugnet, was Du eigentlich siehst! Sie ist wie",
  [30776] = "ein böser Geist, der einen in die Irre führen",
  [30777] = "will. Traue nur Deinen fünf Sinnen, und nicht dem,",
  [30778] = "was sie Dir vorspielen will!\"",
  [30779] = "Er macht eine kurze Pause, und sagt dann",
  [30780] = "bedeutungsvoll: \"Eines Tages wirst Du verstehen,",
  [30781] = "wer sie eigentlich ist!\"*",
  [30782] = "\"Die Schwarze Krypta ist ein schreckliches",
  [30783] = "Labyrinth. Du bist absolut verloren, wenn Du nur",
  [30784] = "einmal den falschen Weg gehst! Aber Pit kann Dir",
  [30785] = "helfen, denn er kennt die Krypta gut. Außerdem ist",
  [30786] = "Pit sehr stark. Naja, er ist auch sehr",
  [30787] = "eigensinnig, ich habe noch nie erlebt, daß er",
  [30788] = "jemanden mit seiner Kraft half... oder gar, haha,",
  [30789] = "daß er ein Bad genommen hätte!\"*",
  [30790] = "\"Ich wünsche Dir Glück!\" ruft Tell Ihnen",
  [30791] = "hinterher. Dann nimmt er seinen Besen, und fegt",
  [30792] = "unauffällig weiter.*",
  [30793] = "Das Amulett sieht aus wie ein goldenes Tee-Ei, und",
  [30794] = "ist auch etwa so groß wie ein solches. Es besitzt",
  [30795] = "eine lange, goldene Kette.*",
  [30796] = "Eine piepsige Stimme ruft zornig heraus:",
  [30797] = "\"Laß mich 'raus, Du Höllenhund!",
  [30798] = "sonst hau ich Dir was auf den Mund!'*",
  [30799] = "Kaum ist das Ei offen, hopst ein kleiner Kobold",
  [30800] = "heraus, und setzt sich kurz auf Ihre Hand. Er",
  [30801] = "wirft sich in die Brust wie Othello und ruft:",
  [30802] = "\"Ein Kerl mit Herz, ich muß schon sagen!",
  [30803] = "Trotzdem werd' ich nicht lange fragen,",
  [30804] = "Und schnellstens hier die Kurve kratzen,",
  [30805] = "Laß' mir doch nicht den Tag verpatzen!",
  [30806] = "Haha!\"",
  [30807] = "Damit hüpft der kleine Kerl von Ihrer Hand, und",
  [30808] = "ist im nächsten Moment schon verschwunden.*",
  [30809] = "An der Brücke",
  [30810] = "Hier endet der enge Gang. Eine beängstigend",
  [30811] = "schmale Brücke spannt sich über einen Lavastrom,",
  [30812] = "der sich tief unten in einer Schlucht träge",
  [30813] = "dahinwälzt. Mattes, rötliches Licht dringt herauf.",
  [30814] = "Hinter der Brücke, Richtung Osten, liegen",
  [30815] = "Treppenstufen.*",
  [30816] = "Die Brücke ist aus Stein, in der Mitte unangenehm",
  [30817] = "dünn und kaum einen halben Meter breit. Es gibt",
  [30818] = "weder Brüstung noch Geländer.*",
  [30819] = "In der Schlucht - bestimmt in hundert Metern",
  [30820] = "Tiefe, wälzt sich ein Strom rotglühender Lava nach",
  [30821] = "Süden dahin. Wabernde Hitze steigt herauf.*",
  [30822] = "Ein langes Seil, das an einem Lautsprecher",
  [30823] = "festgeknüpft ist, der in der Mitte der Brücke",
  [30824] = "liegt, reicht bis hierher.*",
  [30825] = "Ihr Trick funktioniert! Die Brücke bricht -",
  [30826] = "rrrummmsss - zusammen, aber Sie bekommen trotzdem",
  [30827] = "den Preis für die äh... unintelligenteste Tat seit",
  [30828] = "der Erfindung der Computerspiele. Jetzt stehen Sie",
  [30829] = "hier drüben, und können nie mehr auf die andere",
  [30830] = "Seite gelangen... oje, oje!*",
  [30831] = "Auf der Brücke",
  [30832] = "Dies ist die Mitte der Brücke... nein, sehen Sie",
  [30833] = "lieber nicht hinunter - hier ist die schmalste",
  [30834] = "Stelle, und hier hilft nur der Blick geradeaus.*",
  [30835] = "Oh - dort drüben rührt sich etwas... eine dunkle",
  [30836] = "Gestalt, die auf den Treppenstufen saß, erhebt",
  [30837] = "sich und tritt ins Licht. Es ist... oh nein,",
  [30838] = "die dreiäugige Bestie!*",
  [30839] = "\"Da bist Du ja endlich! Hast lange gebraucht, bis",
  [30840] = "hierher! Haha!\" dröhnt die Stimme der Bestie mit",
  [30841] = "übernatürlicher Lautstärke herüber.",
  [30842] = "Dann verfinstern sich ihre scheußlichen Züge.",
  [30843] = "\"Aber egal - dies ist mein Reich, und hier kommst",
  [30844] = "Du lebend nicht durch! Siehst Du die kleine,",
  [30845] = "silberne Kugel, die zu Deinen Füßen auf der Brücke",
  [30846] = "liegt? Ohne sie ist Dein Weg hier zuende, mit ihr",
  [30847] = "aber auch, hahaha!\"*",
  [30848] = "Es ist eine beängstigend schmale Brücke aus Stein,",
  [30849] = "die sich über einen Abgrund spannt - tief unten",
  [30850] = "wälzen sich rotglühende Lavamassen dahin.*",
  [30851] = "In der Mitte der Brücke liegt eine kleine, silbern",
  [30852] = "schimmernde Kugel auf dem Boden. Sie liegt in",
  [30853] = "einer kleinen Vertiefung.*",
  [30854] = "In der Mitte der Brücke liegt ein Lautsprecher, an",
  [30855] = "dessen Magneten ein kleine, silbern schimmernde",
  [30856] = "Kugel klebt, rücklings auf einer Vertiefung.*",
  [30857] = "In der Mitte der Brücke liegt ein Lautsprecher, an",
  [30858] = "dessen Magneten ein kleine, silbern schimmernde",
  [30859] = "Kugel klebt, rücklings auf einer Vertiefung. An",
  [30860] = "dem Lautsprecher ist ein Seil befestigt.*",
  [30861] = "Die Kugel hat einen Durchmesser von fünf",
  [30862] = "Zentimetern. Sie glänzt metallisch, und ist völlig",
  [30863] = "glatt, so als wäre sie poliert.*",
  [30864] = "Gut... die Kugel gehört nun Ihnen. Oh - dort aus",
  [30865] = "der Vertiefung ragt nun ein kleiner, metallener",
  [30866] = "Stift hervor.*",
  [30867] = "Der Stift in der Vertiefung ist dünn, und führt in",
  [30868] = "den Stein hinein. Er ragt dort hervor, wo zuvor",
  [30869] = "die Kugel lag.*",
  [30870] = "Gut. Die Kugel liegt nun wieder in der",
  [30871] = "Vertiefung.*",
  [30872] = "Es ist eine kleine Vertiefung mit etwa fünf",
  [30873] = "Zentimetern Durchmesser in der steinernen",
  [30874] = "Oberfläche der Brücke.*",
  [30875] = "Eine kleine, metallene Kugel liegt darin.*",
  [30876] = "Ein kleiner, metallener Stift ragt daraus hervor.*",
  [30877] = "Ein Lautsprecher, an dessen Magneten ein kleine,",
  [30878] = "silbern schimmernde Kugel klebt, liegt rücklings",
  [30879] = "auf einer Vertiefung in der Brückenmitte.*",
  [30880] = "Ein Lautsprecher, an dessen Magneten ein kleine,",
  [30881] = "silbern schimmernde Kugel klebt, rücklings auf",
  [30882] = "einer Vertiefung in der Brückenmitte. An dem",
  [30883] = "Lautsprecher ist ein Seil befestigt.*",
  [30884] = "Ohweh... ob das klappt? Der Gegenstand, der dort",
  [30885] = "liegt, sollte eigentlich richtig in die Vertiefung",
  [30886] = "hineinpassen, und das entsprechende Gewicht",
  [30887] = "haben...*",
  [30888] = "Bei allem Respekt: Sie können nicht an einem Seil,",
  [30889] = "das so dick ist, daß einst einen schweren",
  [30890] = "Kristall-Lüster trug, eine kleine Kugel",
  [30891] = "festbinden!*",
  [30892] = "Tock!!!",
  [30893] = "Als der Lautsprecher in die Nähe der Kugel kommt,",
  [30894] = "springt sie aus der Vertiefung auf, und bleibt",
  [30895] = "sofort mit eiserer Kraft an dem Magneten des",
  [30896] = "Lautsprechers kleben. Nicht schlecht, aber wir",
  [30897] = "sollten das Ganze wieder zurechtlegen...",
  [30898] = "So, der Lautsprecher liegt jetzt rücklings auf der",
  [30899] = "Vertiefung, und die Kugel ist an ihrem Platz.*",
  [30900] = "Gut. Legen wir das Ganze ein wenig zurecht...",
  [30901] = "So, der Lautsprecher liegt jetzt rücklings auf der",
  [30902] = "Vertiefung, und die Kugel ist an ihrem Platz.*",
  [30903] = "Oh... diese eine Bewegung war zuviel. Ein",
  [30904] = "seltsames Knirschen ertönt. Mit lähmender",
  [30905] = "Langsamkeit scheint sich die Brücke nach unten",
  [30906] = "durchzubiegen... und dann: Kraaach! In einem",
  [30907] = "winzigen Augenblick ist es geschehen: die Brücke",
  [30908] = "zerbirst in tausend Stücke. Nur noch für einen",
  [30909] = "letzten Moment trennen Sie hundert sichere Meter",
  [30910] = "von dem Lavastrom....",
  [30911] = ".... aaaaaahhhhhhh......*",
  [30912] = "Jenseits der Schlucht",
  [30913] = "Hier besteht eine beruhigende Distanz zu der",
  [30914] = "tiefen Schlucht, in deren Tiefe sich, westlich von",
  [30915] = "hier, ein rotglühender Lavastrom dahinwälzt.",
  [30916] = "Weiter östlich hingegen sind die Stufen einer",
  [30917] = "breiten Treppe zu erkennen, die hinauf in die",
  [30918] = "Dunkelheit führt.*",
  [30919] = "\"Sieh an, Du hast die Brücke überwunden!\" dröhnt",
  [30920] = "mit beängstigender Lautstärke die Stimme der",
  [30921] = "dreiäugigen Bestie herüber, die auf den untersten",
  [30922] = "Treppenstufen steht.",
  [30923] = "\"Haha! Ich sagte ja: OHNE die Kugel kommst Du",
  [30924] = "ebenfalls nicht weiter! Und gib acht: vor Dir, im",
  [30925] = "Boden, befindet sich ein tiefer, breiter Spalt, Du",
  [30926] = "wirst ihn nur schwerlich erkennen können! Aber",
  [30927] = "probier's doch: komm her zu mir!\"*",
  [30928] = "Die Brücke, die sich einst über die Schlucht",
  [30929] = "spannte, existiert inzwischen nicht mehr.*",
  [30930] = "Pit marschiert hier herum, und schimpft leise vor",
  [30931] = "sich hin, daß die Brücke nicht mehr da ist. \"Ah!\"",
  [30932] = "sagt er, \"da bist Du ja! Was hast Du Dir",
  [30933] = "eigentlich gedacht, als Du diese Brücke zerstört",
  [30934] = "hast, hm? Wie soll ich jetzt hier 'rüber kommen?",
  [30935] = "So ein Mist!\"*",
  [30936] = "Pit, der Kobold, marschiert hier herum, und",
  [30937] = "schimpft leise vor sich hin, daß die Brücke nicht",
  [30938] = "mehr da ist.*",
  [30939] = "Der Boden ist völlig glatt und eben... hmmm.",
  [30940] = "Nun - es scheint aber irgendwie... irgendwie",
  [30941] = "scheint es fast... als wäre dort eine Art Riß,",
  [30942] = "oder ein Spalt im Boden!*",
  [30943] = "Ja, tatsächlich! Da ist ein Riß, ein sehr breiter",
  [30944] = "sogar - plötzlich hat er sich weit geöffnet -",
  [30945] = "mindestens fünf Meter! Oh Gott, wie soll man da",
  [30946] = "drüber kommen?*",
  [30947] = "\"Ha!\" dröhnt die Bestie mit kolossaler Lautstärke.",
  [30948] = "\"Du hast ihn also doch gesehen, den Spalt! Ich",
  [30949] = "sagte es ja! Also, dann komm doch zu mir rüber!*",
  [30950] = "Der Spalt ist viel zu breit. Da kommen Sie nicht",
  [30951] = "drüber!*",
  [30952] = "Vorsicht, da ist doch der Spaaaaahhhh.......*",
  [30953] = "\"Das möchtest Du gerne wissen, was? Ha!\" röhrt die",
  [30954] = "Bestie ohrenbetäubend, sodaß es von allen Wänden",
  [30955] = "und Decken widerhallt.",
  [30956] = "\"Aber das verrate ich Dir nicht!\"*",
  [30957] = "\"Willst Du hier ein Kinder-Quiz mit mir",
  [30958] = "veranstalten, Du Clown? Bereite Dich lieber darauf",
  [30959] = "vor, in die ewigen Jagdgründe einzugehen, Haha!\"*",
  [30960] = "Das Monster ist schrecklich anzusehen - es trieft",
  [30961] = "vor Schleim, hat eine schuppige Haut und einen",
  [30962] = "langen Echsenschwanz, der anriffslustig hin- und",
  [30963] = "herpeitscht. Seine drei bösen, blaßblauen Augen",
  [30964] = "sind in tödlichem Haß auf Sie gerichtet!*",
  [30965] = "Als Sie, völlig ohne in irgendeinen Spalt dieser",
  [30966] = "Welt zu plumpsen, die Treppe betreten, prallt die",
  [30967] = "schreckliche, dreiäugige Bestie bestürzt zurück.*",
  [30968] = "Ein langes Seil reicht von der Mitte der Brücke,",
  [30969] = "wo es an einem Lautsprecher befestigt ist, bis",
  [30970] = "hierher.*",
  [30971] = "Ah! Sie haben wirklich das Zeug, den schrecklichen",
  [30972] = "Kal zu besiegen. Ihr Trick funktioniert",
  [30973] = "phantastisch: die kleine Kugel bleibt an dem",
  [30974] = "Lautsprechermagneten kleben, während die Brücke -",
  [30975] = "Radommmm - mit lautem Getöse zusammenbricht.*",
  [30976] = "Auf der Treppe",
  [30977] = "Breite Treppenstufen führen hier hinauf in die",
  [30978] = "Dunkelheit, die weiter oben alles Sichtbare",
  [30979] = "verschluckt. Nach Westen geht es hinüber zur",
  [30980] = "Brücke.*",
  [30981] = "\"Du hast meinen kleinen Trick durchschaut, was?\"",
  [30982] = "krächzt die dreiäugige Bestie wütend. \"Nun pass'",
  [30983] = "mal auf!\" Die Bestie deutet nach oben an die",
  [30984] = "Decke. \"Schau mal, was da oben an der Decke",
  [30985] = "baumelt!\"*",
  [30986] = "\"Du sollst da hochschauen, verdammt noch mal!\"",
  [30987] = "dröhnt die Bestie, noch immer mit überirdischer",
  [30988] = "Lautstärke. \"Da oben! Schau Dir an, was an der",
  [30989] = "Decke hängt!\"*",
  [30990] = "Die dreiäugige Bestie wird entsetzlich wütend. Sie",
  [30991] = "richtet sich zu ihrer vollen, imponierenden Größe",
  [30992] = "auf, und macht einen drohenden Schritt auf Sie zu.",
  [30993] = "\"Wenn Du jetzt nicht sofort meinem Befehl",
  [30994] = "gehorchst, dann ist es aus mit Dir!\" brüllt sie.",
  [30995] = "\"Los, schau Dir an, was an der Decke hängt!\"*",
  [30996] = "Die dreiäugige Bestie ist völlig außer sich.",
  [30997] = "Schreiend tobt sie herum, flucht und spottet, und",
  [30998] = "brüllt zuletzt, daß Sie keine verdammte Lust mehr",
  [30999] = "habe. Sie reißt sich wütend irgendwelches Zeug vom",
  [31000] = "Leib, knallt es auf die Treppenstufen und brüllt:",
  [31001] = "\"Soll der verdammte Kal diese dickschädeligen und",
  [31002] = "sturen Abenteurer-Kerle doch selber kaltstellen!",
  [31003] = "Ich kündige! Ich gehe! Und zwar gleich!\" Damit",
  [31004] = "dreht sich das Monstrum um, stampft davon, und ist",
  [31005] = "gleich darauf in der Dunkelheit verschwunden.*",
  [31006] = "Um Himmels Willen! Dort oben, in der Dunkelheit,",
  [31007] = "hängt ein riesiger Gitterkäfig - direkt über Ihrem",
  [31008] = "Kopf!\"*",
  [31009] = "Vorsicht....",
  [31010] = "...Rrruuummmmmssss!!!",
  [31011] = "Der Gitterkäfig ist über Ihnen heruntergekracht,",
  [31012] = "und hat Sie hilflos eingesperrt! Und da... da",
  [31013] = "sitzt eine fette, gräßliche Giftspinne in der",
  [31014] = "Ecke...*",
  [31015] = "... und schon springt Sie los... landet auf Ihrem",
  [31016] = "Hals... und...",
  [31017] = "... aaarrrggghhhh.....!!!*",
  [31018] = "Es sind breite, steinerne Stufen, die hinauf in",
  [31019] = "die Dunkelheit führen.*",
  [31020] = "Oh - da liegt ja etwas... das hat die schreckliche",
  [31021] = "Bestie von sich geworfen...",
  [31022] = "Na, sowas! Es ist ein kleines Mikrophon; so eines",
  [31023] = "mit einem dünnen Kabel, zum Anstecken an die",
  [31024] = "Jacke, wie es in Talk-Shows benutzt wird!*",
  [31025] = "Es ist ein kleines Mikrofon - so eines mit einem",
  [31026] = "dünnen Kabel, zum Anstecken an die Jacke.*",
  [31027] = "Es handelt sich um ein dünnes, schwarzes,",
  [31028] = "Mikrofonkabel... da wollen wir doch mal schaun, wo",
  [31029] = "das Ding hinführt... schnapp! Ach, Mist - jetzt",
  [31030] = "ist es abgerissen! Aber... was ist denn das da?",
  [31031] = "Sieh an, was für ein Schwindel! Da steht eine",
  [31032] = "ziemlich riesige Verstärkerbox in der Dunkelheit -",
  [31033] = "kein Wunder, daß die Stimme der dreiäugigen Bestie",
  [31034] = "so unbändig laut war!*",
  [31035] = "Es ist nur ein dünnes, schwarzes Mikrofonkabel;",
  [31036] = "lang, aber offenbar wenig widerstandsfähig.*",
  [31037] = "Es ist eine - nun: schlichtweg riesige",
  [31038] = "Verstärkerbox. Von soetwas dürfte sogar der alte",
  [31039] = "Eddie van Halen träumen. Sie ist bestimmt zwei",
  [31040] = "Meter hoch und eineinhalb Meter breit. Oben in der",
  [31041] = "Mitte ist der Amp eingebaut, die Rückseite der Box",
  [31042] = "ist offen. Dort sind eine Menge ziemlich großer",
  [31043] = "Tweeter, Tieftöner und Mitteltonhörner eingebaut.*",
  [31044] = "Tjaaaa... also das Ding dürfte ein paar Hundert",
  [31045] = "Watt bringen... sollen wir's mal aufdrehen?",
  [31046] = "Hm, lieber nicht, das würde Ihre Soundkarte nicht",
  [31047] = "aushalten...*",
  [31048] = "Es handelt sich um eine ganze Galerie von",
  [31049] = "sogenannten (wie Sie bestimmt wissen) Tweetern,",
  [31050] = "also solchen Lautsprechern, die hohe Töne",
  [31051] = "(piiieeeps) verbreiten.*",
  [31052] = "Dort sind ein halbes Dutzend von Mitteltonhörnern",
  [31053] = "befestigt, also der Art von Lautsprechern, die",
  [31054] = "mittelhohe Töne (bäääää) produzieren.*",
  [31055] = "Die Verstärkerbox verfügt über zwei ziemlich dicke",
  [31056] = "Tieftöner, also jene Lautsprecher, die tüüüfe Töne",
  [31057] = "(umph, umph) verbreiten. Oh - der eine",
  [31058] = "Lautsprecher hat sich schon fast verselbständigt -",
  [31059] = "er fällt gleich aus seiner Halterung heraus!*",
  [31060] = "Die Verstärkerbox verfügt über zwei... nein, nur",
  [31061] = "noch einen, ziemlich dicken Tieftöner, also jene",
  [31062] = "Lautsprecher, die tüüüfe Töne (umph, umph)",
  [31063] = "erzeugen.*",
  [31064] = "Es ist ziemlich großer Lautsprecher, (hat bestimmt",
  [31065] = "'nen Schalldruck von 98 Dezib... ach, lassen wir",
  [31066] = "das), und sein nicht unbeträchtliches Gewicht",
  [31067] = "stammt zum größten Teil von dem riesigen",
  [31068] = "Magnetkern an seiner Rückseite.*",
  [31069] = "Er hängt schon ziemlich locker - fällt wohl gleich",
  [31070] = "aus seiner Halterung heraus!*",
  [31071] = "Nun, solche Magnetkerne haben, besonders bei Bass-",
  [31072] = "Lautsprechern, eine ziemliche Anziehungskraft.*",
  [31073] = "An diesem hier klebt zum Beispiel eine kleine",
  [31074] = "Metallkugel, als wäre sie festgeschweißt!*",
  [31075] = "Ein Seil ist an dem Lautsprecher festgeknüpft -",
  [31076] = "und die Membran ist zerstört - so ein Jammer.*",
  [31077] = "Tock!!!",
  [31078] = "Die metallne Kugel bleibt sofort mit eiserner",
  [31079] = "Kraft an dem Magneten des Lautsprechers kleben.*",
  [31080] = "Also hören Sie mal!",
  [31081] = "Ein HiFi-Spezialist sind Sie wohl nicht gerade,",
  [31082] = "was? Man führt Lautsprechern den Strom über KABEL",
  [31083] = "zu, nicht über Seile! Also sowas!*",
  [31084] = "Sie sind unverbesserlich, was? Na, sie werden",
  [31085] = "schon sehen, daß das mit Seilen nicht geht. Und",
  [31086] = "nun müssen wir auch noch die Membran des",
  [31087] = "Lautsprechers kaputtmachen! Ein Jammer - das gute",
  [31088] = "Stück! Aber was hilft's - wenn Sie darauf",
  [31089] = "bestehen... Kkkkkrrrkksss.",
  [31090] = "So. Das Seil ist nun am Lautsprecher befestigt.*",
  [31091] = "Ach, hören Sie doch auf mit diesen Spielereien!",
  [31092] = "Wir haben hier schließlich eine todernste Aufgabe",
  [31093] = "zu erledigen, nicht?*",
  [31094] = "Schnapp!",
  [31095] = "Oh - jetzt ist das dünne Kabel des Mikrophons",
  [31096] = "irgendwo abgerissen. Vermutlich dort, wo es",
  [31097] = "angeschlossen war! So ein Pech!*",
  [31098] = "Ende der Treppe",
  [31099] = "Hier endet die dunkle Treppe vor einer Felswand,",
  [31100] = "in der eine große, hölzerne Tür eingelassen ist.*",
  [31101] = "Die Tür besteht aus Holz und ist sehr solide",
  [31102] = "gebaut. Vor drauf befindet sich eine Blende mit",
  [31103] = "einem... nun, das könnte so eine Art Schlüsselloch",
  [31104] = "sein.*",
  [31105] = "Es ist ein kleines Loch, etwa fünf Zentimeter im",
  [31106] = "Durchmesser. Es ist nichts weiteres zu erkennen,",
  [31107] = "das heißt, das Loch ist innen völlig glatt. Es",
  [31108] = "gibt scheinbar keine Mechanik, wie es sonst in",
  [31109] = "Schlüssellöchern üblich ist.*",
  [31110] = "Das passt nicht da rein. Probieren Sie lieber",
  [31111] = "etwas anderes aus.*",
  [31112] = "Klickediklick! Die kleine Kugel ist verschwunden.",
  [31113] = "Und dann: langsam schwingt die Türe nach innen",
  [31114] = "auf! Dahinter wird ein finsterer Gang sichtbar,",
  [31115] = "der nach Norden führt.*",
  [31116] = "Nördlicher Gang",
  [31117] = "Hier führt ein Gang geradeaus weiter nach Norden.",
  [31118] = "Es ist sehr feucht hier, Wasser tropft von den",
  [31119] = "Wänden und der Decke. Scheußliche, kleine",
  [31120] = "Insekten, Mäuse und magere Ratten flitzen umher -",
  [31121] = "es wird langsam ziemlich ungemütlich!*",
  [31122] = "Es sind welche von der schnellen Sorte: Sie",
  [31123] = "krabbeln und flitzen so schnell über die felsigen",
  [31124] = "Wände und den Boden, daß einen das unangenehme",
  [31125] = "Gefühl beschleicht, man könnte ihnen nicht",
  [31126] = "entkommen, sollten sie es auf einen abgesehen",
  [31127] = "haben.*",
  [31128] = "Die Ratten sehen ziemlich abgemagert aus - und",
  [31129] = "sind auch wohl recht kraftlos - vorerst noch keine",
  [31130] = "Gefahr. Aber sie könnten mal eine ordentliche",
  [31131] = "Mahlzeit vertragen...*",
  [31132] = "In der Schwarzen Krypta",
  [31133] = "Hier beginnt das schreckliche Labyrinth der",
  [31134] = "dreiäugigen Bestie. Der Raum ist klein und",
  [31135] = "niedrig, nichts desto trotz gibt es hier sechs",
  [31136] = "Ausgänge: je einen in die vier Himmelsrichtungen,",
  [31137] = "und je einen nach oben und unten - dort gibt es",
  [31138] = "schmale Leitern. Allein durch den südlichen",
  [31139] = "Ausgang geht es zurück in den rettenden Gang.*",
  [31140] = "Ein Stück Papier liegt auf dem Boden.*",
  [31141] = "Es ist eine Botschaft der dreiäugigen Bestie:",
  [31142] = "\"Nun bist Du verloren, Du Wurm! Kal sagte mir",
  [31143] = "voraus, daß Du mich überwinden würdest, und so",
  [31144] = "habe ich beizeiten diese schwarze Krypta wieder",
  [31145] = "geöffnet - eigens für Dich! Ich habe mich davon",
  [31146] = "überzeugt, daß die giftigen Spinnen noch immer",
  [31147] = "hier sind! Sie warten auf Dich! Es gibt unendlich",
  [31148] = "viele Räume in der Krypta, aber nur einen Weg",
  [31149] = "hinaus. Jeder Raum hat sechs Ausgänge. In jedem",
  [31150] = "Raum führen fünf Wege ins Verderben - zu den",
  [31151] = "Giftspinnen! Nur ein einziger ist der richtige,",
  [31152] = "aber glaubst Du, Du wirst ihn jedesmal finden",
  [31153] = "können? Hahaha! Stirb, Du erbärmlicher Narr!\"*",
  [31154] = "Das goldene Ei glänzt in ihrer Hand. In seinem",
  [31155] = "Inneren läßt Pit, der Kobold, üble",
  [31156] = "Schimpfkanonaden los. Sie klingen leider ein",
  [31157] = "bißchen dümmlich, denn Pit erzeugt immerzu Reime",
  [31158] = "aus seinen wütenden Flüchen: \"Verdammter Mist, ich",
  [31159] = "will hier raus! Mach auf, sonst schmeckst Du meine",
  [31160] = "Faust!\"*",
  [31161] = "Pit springt zornig heraus, krabbelt Ihnen am Arm",
  [31162] = "hinauf, schwingt sich über Ihren Kragen, und",
  [31163] = "donnert ihnen seine winzige Rechte gegen das Kinn.",
  [31164] = "\"So, Du Hund, jetzt sind wir quitt! Nochmal",
  [31165] = "spielst Du mir nicht so mit! Was willst Du",
  [31166] = "überhaupt von mir?\" Er wirft einen kurzen Blick",
  [31167] = "auf die Umgebung.\"Ach ja, ich weiß - wir sind ja",
  [31168] = "HIER!\"*",
  [31169] = "Pit ist ein winziger Kobold, kaum fünf Zentimeter",
  [31170] = "groß. Er sieht aus wie ein kleiner Wurzelzwerg,",
  [31171] = "mit Bart, knallroter Nase und echten Waldschrat-",
  [31172] = "Kleidern. Man muß leider noch erwähnen, daß er",
  [31173] = "ebenso ungut riecht. Genauergesagt, er stinkt, als",
  [31174] = "hätte er sich mindestens zwölfhundert Jahre lang",
  [31175] = "nicht gewaschen!*",
  [31176] = "Pit setzt sich auf Ihre Schulter, sieht sich den",
  [31177] = "Ort genauer an, und rümpft seine winzige Nase.",
  [31178] = "\"Oje, das ist ja erst der Anfang! Du lieber",
  [31179] = "Himmel, bist Du langsam!\"*",
  [31180] = "Pit verzieht ablehnend das Gesicht.",
  [31181] = "In Sekundenschnelle schon hat er einen seiner",
  [31182] = "Knüttel-Verse parat:",
  [31183] = "\"Vergiß es, Mann. Wir sind nicht hier, um",
  [31184] = "irgendwas zu diskutier'n. Besinn Dich lieber auf",
  [31185] = "die Fragen, durch welchen Ausgang wir uns wagen!\"*",
  [31186] = "Pit macht sich's auf Ihrer Schulter gemütlich,",
  [31187] = "verschränkt die Arme hinterm Kopf, und lehnt sich",
  [31188] = "frech gegen Ihren Hals. \"Ich schlage vor, wir",
  [31189] = "sollten gehn - den gleichen Weg wie Amundsen!\"",
  [31190] = "orakelt er.*",
  [31191] = "In der Krypta",
  [31192] = "Sie befinden sich in einem kalten, kleinen Raum,",
  [31193] = "der sechs Ausgänge besitzt. Sie führen in die vier",
  [31194] = "Himmelsrichtungen, und mittels schmaler Leitern",
  [31195] = "nach oben und unten. Fette, weißliche Spinnen",
  [31196] = "krabbeln träge an Wänden und Decken entlang.*",
  [31197] = "In der Krypta",
  [31198] = "Ein weiterer niedriger Raum dieses verwirrenden",
  [31199] = "Labyrinthes. Auch hier gibt es die sechs Ausgänge:",
  [31200] = "nach Nord, Süd, Ost und West, sowie nach oben und",
  [31201] = "unten. Es ist feucht und kalt hier - ein Ort, dem",
  [31202] = "man, so schnell es geht, entrinnen möchte!*",
  [31203] = "In der Krypta",
  [31204] = "Der nächste der ungezählten Räume der schwarzen",
  [31205] = "Krypta. Hier ist allerlei Getier unterwegs, aber",
  [31206] = "bei dieser unangenhemen, feuchten Kälte hier",
  [31207] = "unten, erscheint es rätselhaft, wie es hier",
  [31208] = "überhaupt ein lebendes Wesen längere Zeit",
  [31209] = "aushalten kann. Auch hier finden sich wieder die",
  [31210] = "obligaten sechs Ausgänge.*",
  [31211] = "Es sind magere Ratten, weißliche Spinnen, Mäuse",
  [31212] = "und allerlei umherhuschende Insekten.*",
  [31213] = "Die Spinnen haben eine ekelhaft weißliche Färbung.",
  [31214] = "Sie sind nicht groß, aber sie haben Leiber, in",
  [31215] = "denen gewiß genug Gift ist, um in Sekunden einen",
  [31216] = "Ochsen niederzustrecken.*",
  [31217] = "Dort lang...?",
  [31218] = "Also gut, wagen wir's. Gaaanz vorsichtig... ah, es",
  [31219] = "geht. Nach einem kurzen Gang folgt ein enger",
  [31220] = "Raum.*",
  [31221] = "Oje, ob das gut geht...?",
  [31222] = "Ja, Glück gehabt. Sie sind nicht gefressen worden.",
  [31223] = "Schon bald haben Sie den nächsten Raum erreicht.*",
  [31224] = "Alsdann - nur Mut...!",
  [31225] = "Puuuh! Es klappt. Dieser Durchgang ist frei von",
  [31226] = "den niedlichen Spinnentierchen... bald darauf",
  [31227] = "erreichen Sie den nächsten Raum.*",
  [31228] = "Nun denn, auf ein neues...!",
  [31229] = "Es... klappt! Auch hier gibt es keine von diesen",
  [31230] = "ekligen Spinnen zu entdecken - schon bald haben",
  [31231] = "Sie den nächsten Raum erreicht.*",
  [31232] = "Da wollen Sie rauf...?",
  [31233] = "Also los, gaaanz vorsichtig... uff! Glück gehabt.",
  [31234] = "Sie leben noch, und haben schon den nächsten Raum",
  [31235] = "erreicht.*",
  [31236] = "Urks... hoffentlich wird das kein Abstieg in die",
  [31237] = "Hölle...",
  [31238] = "Nein, es geht. Was für eine Erleichterung. Auch",
  [31239] = "hier gibt es keine Spinnen, und Sie stehen schon",
  [31240] = "im nächsten Raum.*",
  [31241] = "Als Sie diese Gang hinter sich gebracht haben,",
  [31242] = "stellt sich heraus, daß es offenbar der letzte der",
  [31243] = "Schwarzen Kypta war! Was für ein Glück! Sie haben",
  [31244] = "gewonnen!*",
  [31245] = "Pit richtet sich auf, und grinst Sie vielsagend",
  [31246] = "an. \"Kennst Du Dich aus mit Literatur? Oder mit",
  [31247] = "Jerry Cotton nur?\" Sein Grinsen wird breiter, und",
  [31248] = "er hebt seinen winzigen Finger. \"Die Gefahr ist",
  [31249] = "dort gebannt, wo Remarque nichts Neues fand! Ha!\"*",
  [31250] = "Pit, der schlechteste Poet aller Zeiten, weiß",
  [31251] = "einen neuen Spruch: \"Das Kreuz, nach dem die",
  [31252] = "Schiffe fahren, wird vor Verderben Dich bewahren!\"",
  [31253] = "verkündet er stolz.*",
  [31254] = "\"Hier bin ich lang nicht mehr gewesen, wo gehts",
  [31255] = "denn hin, ich komm nicht drauf!\" sagt Pit. \"Es ist",
  [31256] = "so finster, kann nichts sehen, wann geht denn hier",
  [31257] = "die Sonne auf?\"*",
  [31258] = "Pit wirkt ärgerlich. \"Zum Teufel mit der Sucherei,",
  [31259] = "wann ist das endlich mal vorbei?\" keifert er.",
  [31260] = "\"Nach Norden, Süden, Westen, Osten, das wird uns",
  [31261] = "noch das Leben kosten!\"*",
  [31262] = "Pit scheint sich einen neuen seiner erstaunlichen",
  [31263] = "Verse auszudenken. Dann erhellt sich sein Gesicht.",
  [31264] = "\"Die Venus ist ein schöner Stern, in diese",
  [31265] = "Richtung geh' ich gern!\" platzt er freudig heraus.",
  [31266] = "Uff!*",
  [31267] = "Und wieder folgt der unvermeidliche, ernüchtende",
  [31268] = "Reim, eines [zurecht] verhinderten Dichters: \"Wo",
  [31269] = "Wege nur nach Süden führen, da öffen sich Dir alle",
  [31270] = "Türen!\"*",
  [31271] = "Pit denkt eine Zeitlang nach, dann hat er wieder",
  [31272] = "einen seiner unnachahmlichen Verse gedichtet. Er",
  [31273] = "erhebt seine Stimme, und breitet die Arme aus. Mit",
  [31274] = "donnernder Stimme intoniert er: \"Kennst Du ein",
  [31275] = "lästiges Insekt, das gern am Pflaumenkuchen",
  [31276] = "schleckt? Weil da was falsches drinnensteckt, hast",
  [31277] = "Du den Weg noch nicht entdeckt! Hihi!\"*",
  [31278] = "(Unser automatischer System-Check zeigt uns an,",
  [31279] = "daß Ihr Computer langsam unter der literarischen",
  [31280] = "Wucht dieser epochalen Poesie überhitzt. Hoffen",
  [31281] = "wir... oh nein, es geht schon wieder los:)",
  [31282] = "\"Weißt Du, wo der Vulkanberg steht, durch den -",
  [31283] = "wie er im Buche steht, ein Forscher einst stieg",
  [31284] = "weit hinab, noch tiefer als ins tiefste Grab!",
  [31285] = "Wenn Du noch weißt, wer dies Buch schrieb, dann",
  [31286] = "schau schnell nach, wo der Berg liegt!\"*",
  [31287] = "Pit hat sich ein neues Machwerk überlegt. Er wirft",
  [31288] = "sich in die Brust, und rezitiert mit großer Geste:",
  [31289] = "(Moment... wir ziehen es vor, und die Ohren zu",
  [31290] = "verstopfen.... so, jetzt!): \"Wo Pinguine Fische",
  [31291] = "jagen, und Eisbär'n sich mit Kälte plagen, wo",
  [31292] = "Cowboys sich mit Indsmen schlagen, und Frauen",
  [31293] = "täglich Schleier tragen, wo tote Seelen jammernd",
  [31294] = "klagen, da gehts Dir sicher an den Kragen!\"",
  [31295] = "(Ist er fertig...? Gut, wir schalten uns wieder",
  [31296] = "dazu.)*",
  [31297] = "Pit, der Unnachahmliche, setzt zum nächsten,",
  [31298] = "umwerfenden Vers an: \"Die Gefahr ist da vorbei, wo",
  [31299] = "das Häschen legt ein Ei! Hahahahaha....!\"*",
  [31300] = "\"Oh nein, das ist der falsche Weg!\" kreischt Pit",
  [31301] = "entsetzt. \"Oje, jetzt isses schon zu spät!\"",
  [31302] = "Der Kobold hat schmerzlich recht. Er hüpft eilig",
  [31303] = "von Ihrer Schulter, und verschwindet. Auf seinem",
  [31304] = "Platz hat sich allerdings rasch eine Ablösung",
  [31305] = "eingefunden. Raten Sie mal, wer....*",
  [31306] = "\"Ohweh, ich hau jetzt besser ab. Geh' lieber ohne",
  [31307] = "mich ins Grab!' quiekt Pit angstvoll, und springt",
  [31308] = "von Ihrer Schulter. Kaum ist er verschwunden,",
  [31309] = "streicht Ihnen so etwas wie ein Spinnennetz übers",
  [31310] = "Gesicht. Und dann fängt es an zu kribbeln und zu",
  [31311] = "krabbeln....*",
  [31312] = "Am unterirdischen See",
  [31313] = "Nordwärts tut sich in geheimnisvollem Zwielicht,",
  [31314] = "und von dünnen Nebelschwaden verhangen, ein",
  [31315] = "riesiges Gewölbe auf. Vierzig oder fünfzig Meter",
  [31316] = "senkrecht unter Ihren Füßen grenzen die dunklen,",
  [31317] = "unbewegten Wasser eines großen, unterirdischen",
  [31318] = "Sees an den Felsen. Hier also endet jeglicher",
  [31319] = "Weg!*",
  [31320] = "\"Oh Mann, Du hast's ja doch geschafft!\" jubelt",
  [31321] = "Pit, als er die große unterirdische Halle",
  [31322] = "erblickt. \"Ich bin schon ganz schön",
  [31323] = "abgeschlafft!\"*",
  [31324] = "Der geheimnisvolle, stille See reicht weit nach",
  [31325] = "Norden in die Dunkelheit hinein. Daß es hier nicht",
  [31326] = "völlig finster ist, ist den Nebelschwaden zu",
  [31327] = "verdanken, die unbewegt über dem Wasser schweben.",
  [31328] = "Sie strahlen ein floureszierendes Licht aus.*",
  [31329] = "Pit richtet sich auf Ihrer Schulter auf, und",
  [31330] = "streckt seine Glieder. \"Mein Freund, ich sag es",
  [31331] = "Dir ganz ehrlich, ab jetzt wird's mir hier zu",
  [31332] = "gefährlich! Ich geh' nach Haus, verschwind von",
  [31333] = "hier, der Rest ist nämlich nun Dein Bier!\"",
  [31334] = "Damit hüpft er von Ihrer Schulter herunter, und",
  [31335] = "landet auf dem Boden. Er schaut in die Tiefe",
  [31336] = "hinab, und schüttelt sich.*",
  [31337] = "Pit winkt Ihnen einen freundschaftlichen Gruß zu,",
  [31338] = "und marschiert davon - zurück in die schwarze",
  [31339] = "Krypta.*",
  [31340] = "\"Du Mistkäfer, was hast Du vor?\" kreischt Pit",
  [31341] = "wütend. \"Ich hab meinen Job erledigt! Was willst",
  [31342] = "Du denn noch von mir?\" Es ist auffällig, daß Pit",
  [31343] = "plötzlich auch normal sprechen kann. Vor lauter",
  [31344] = "Wut scheint ihm offenbar seine Reim-Sucht abhanden",
  [31345] = "gekommen zu sein.*",
  [31346] = "Pit entwindet sich ihrem Griff, und hüpft davon.",
  [31347] = "\"Du Rüpel!\" schimpft er. \"Sieh doch zu, wie Du",
  [31348] = "selber zurecht kommst!\" Mit diesen Worten huscht",
  [31349] = "er davon, und ward nicht mehr gesehen.*",
  [31350] = "Pit wehrt sich heftig, aber es geht so schnell,",
  [31351] = "daß ihm keine Chance bleibt. Schon ist er wieder",
  [31352] = "in seinem Amulett eingesperrt.*",
  [31353] = "Mit einem piepsigen Schrei segelt der kleine",
  [31354] = "Kobold abwärts.",
  [31355] = "\"Warum tust Du mir das an?\" schreit er hilflos.",
  [31356] = "\"Ich werde draufgehen... ich will nicht baden...\"",
  [31357] = "....Platsch!*",
  [31358] = "Kaum ist Pit ins Wasser eingetaucht, beginnt es",
  [31359] = "unten im See zu brodeln. Es scheint, als würde das",
  [31360] = "Wasser kochen, als plötzlich ein riesiges Ungetüm",
  [31361] = "aus den Wogen hebt. Es sieht grauenvoll aus - ein",
  [31362] = "schwimmender Saurier mit einem Maul, das vor",
  [31363] = "Zähnen starrt! Es stürzt sich auf den winzigen",
  [31364] = "Pit, der prustend im Wasser planscht. Im nächsten",
  [31365] = "Augenblick hat das Untier den kleinen Kobold",
  [31366] = "verschluckt, und taucht wieder in die Tiefen des",
  [31367] = "Sees hinab.*",
  [31368] = "Einige Minuten lang tut sich nichts. Plötzlich",
  [31369] = "aber zerreißt ein dumpfer Schlag die Stille des",
  [31370] = "Gewölbes, und im See steigen dicke Blasen auf.",
  [31371] = "Dann kommt Pit wieder an die Oberfläche. Er hebt",
  [31372] = "drohend die Faust. \"Seit tausendzweihundert Jahren",
  [31373] = "hab' ich mich nicht mehr gewaschen! Du Hundesohn!",
  [31374] = "Bloß, um diesen widerlichen Bool aus dem Weg zu",
  [31375] = "räumen! Warum hast Du Dir nicht selbst was",
  [31376] = "einfallen lassen, hä? Verdammter Mist!\" Mit",
  [31377] = "ärgerlicher Mine taucht Pit blubbernd davon.*",
  [31378] = "\"Laß mich raus, Du Hund! Elender, mistiger Hund!",
  [31379] = "Was willst Du noch von mir? Gleich hab ich mich",
  [31380] = "befreit, und dann geht es Dir schlecht! Gib nur",
  [31381] = "acht! Ich will nach Hause, hörst Du? Ich hab keine",
  [31382] = "Lust auf den schrecklichen Bool!\"*",
  [31383] = "\"Das ist dieses Monster da unten im See! Laß mich",
  [31384] = "'raus, ich will nach Hause!\"*",
  [31385] = "Ohweh. Das sind gute fünfzig Meter bis da",
  [31386] = "hinunter! Wollen Sie das wirklich tun?*",
  [31387] = "Sie sind lieber vorsichtig, was? Nun, wer könnte",
  [31388] = "Ihnen das auch verdenken - bei dieser Tiefe!*",
  [31389] = "Also gut. Bauch rein, Brust raus - Augen",
  [31390] = "schließen, Nase zuhalten und jetzt...",
  [31391] = "uiuiuiuiui.... Plaaatsch!!!",
  [31392] = "Gar nicht übel! Die Klippenspringer von Acapulco",
  [31393] = "hätten Beifall geklatscht. Leider ist keiner da.",
  [31394] = "Sie tauchen prustend wieder auf.*",
  [31395] = "Kaum sind Sie in den Gang gekrochen, da",
  [31396] = "streicht Ihnen so etwas wie ein Spinnennetz übers",
  [31397] = "Gesicht. Und dann fängt es an zu kribbeln und zu",
  [31398] = "krabbeln....*",
  [31399] = "\"Wenn Du nicht durchs Labyrinth gehen willst,",
  [31400] = "dann zisch ich ab!\" schreit Pit, hüpft von Ihrer",
  [31401] = "Schulter und läuft davon.*",
  [31402] = "Pit sitzt auf Ihrer Schulter.*",
  [35002] = "\"Warte!\" ruft Tell, und eilt Ihnen hinterher. \"Ich",
  [35003] = "kann Dir nicht sehr helfen, aber dieses Elixier",
  [35004] = "ist vielleicht nützlich für Dich, Es bringt einen",
  [35005] = "wieder zu Kräften. Verwende es mit Verstand!\"",
  [35006] = "Damit hält er Ihnen ein kleines Fläschchen",
  [35007] = "hin.*",
  [35008] = "\"Hier, nimm es schon!\" sagt Tell, und hält",
  [35009] = "Ihnen das Fläschchen vor die Nase. \"Es wird",
  [35010] = "Dir nützen.\"*",
  [35011] = "\"Es ist ein Art Krafttrunk! Verwende es mit",
  [35012] = "Verstand!\" sagt Tell mit erhobenem Finger.*",
  [35013] = "Es handelt sich um ein kleines Fläschchen.*",
  [35014] = "Das Elixier, ein trüber Saft, ist darin.",
  [35015] = "Es ist wohl gerade mal eine Portion.*",
  [35016] = "Es ist aber leider schon gänzlich leer.*",
  [35017] = "Haben Sie Tell's Worte vergessen? Heben Sie sich",
  [35018] = "das Elixier lieber noch ein Weilchen auf, bis",
  [35019] = "sich eine sinnreiche Gelegenheit ergibt, die",
  [35020] = "kostbare Flüssigkeit zu verwenden.*",
  [35021] = "Hier liegt ein kleines Fläschchen.*",
  [35022] = "Da steht eine riesige Verstärkerbox in der",
  [35023] = "Dunkelheit.*",
  [35024] = "Hier in der Schleuse liegt ein riesiges",
  [35025] = "Robotermonstrum auf dem trocknen Boden - es ist",
  [35026] = "gestrandet, und zum Glück momentan",
  [35027] = "bewegungsunfähig.*",
  [35028] = "Der eingeschlossene Kathaura wütet in der Schleuse",
  [35029] = "herum.*",
  [40002] = "Im See",
  [40003] = "Als sich die Wasser des Sees wieder beruhigt",
  [40004] = "haben, kommt die geheimnisvolle Kraft dieses Ortes",
  [40005] = "erst richtig zur Wirkung. Unbewegt unter den",
  [40006] = "leuchtenden Nebelschwanden ruhend, erstreckt sich",
  [40007] = "der dunkle See weit nach Norden hin ins",
  [40008] = "Ungewisse.*",
  [40009] = "Es ist Süßwasser - und nicht einmal allzu kalt.",
  [40010] = "Trotzdem sollten Sie sich bald eine Stelle suchen,",
  [40011] = "an der Sie aus dem Wasser können. Niemand kann",
  [40012] = "ewig schwimmen.*",
  [40013] = "Ihr Badevergnügen währt nicht lange. Hätten Sie",
  [40014] = "Augen an den Füßen, dann könnten Sie jetzt sehen,",
  [40015] = "wie sich unter Ihnen eine Szene entwickelt, die an",
  [40016] = "das Filmplakat vom \"Weißen Hai\" erinnert.",
  [40017] = "Schnapp... das waren ihre Füße. Schnapp... jetzt",
  [40018] = "sind die Beine auch schon weg, so ein Pech. Machen",
  [40019] = "wir lieber Schluß, bevor Ihnen etwas Ernsteres",
  [40020] = "zustößt...*",
  [40021] = "Für bange Minuten schwimmen sie weiter, aber dann",
  [40022] = "scheint sicher zu sein, daß Pit dem schrecklichen",
  [40023] = "Bool tatsächlich den Garaus gemacht hat.*",
  [40024] = "Blubblubb...",
  [40025] = "Hier unten ist es dunkel und finster, und auch",
  [40026] = "nicht sehr tief. Der Grund des Sees ist felsig,",
  [40027] = "ansonsten gibt es nichts Interessantes zu",
  [40028] = "entdecken. Also: wieder rauf, an die frische",
  [40029] = "Höhlen-Luft.*",
  [40030] = "In der Mitte des Sees",
  [40031] = "Hier gibt es nur die stille Wasserfläche, und den",
  [40032] = "floureszierenden Nebel, der bewegungslos darüber",
  [40033] = "schwebt.*",
  [40034] = "Etwa hier muß in unbekannter Tiefe der Kadaver des",
  [40035] = "schrecklichen Bool liegen. Ein ungutes Gefühl.*",
  [40036] = "Westseite des Sees",
  [40037] = "Vor Ihnen steigt eine senkrechte Felswand auf, die",
  [40038] = "hier den See begrenzt. Aber leider ist sie völlig",
  [40039] = "glatt und unersteigbar.*",
  [40040] = "Die Felswand besteht aus grauem, glatten Gestein.*",
  [40041] = "Ostseite des Sees",
  [40042] = "Vor Ihnen steigt eine senkrechte Felswand aus dem",
  [40043] = "Wasser auf, die den See nach Osten hin begrenzt.",
  [40044] = "Leider bietet sie keinen Halt und keinen Griff.*",
  [40045] = "Nordufer des Sees",
  [40046] = "Sie treiben einige Dutzend Meter vor dem Nordufer",
  [40047] = "des Sees im Wasser. Ein steiniger, schmaler Strand",
  [40048] = "zieht sich an der aufsteigenden, glatten Felswand",
  [40049] = "entlang. Hier scheint die einzige Stelle des Sees",
  [40050] = "zu sein, an der man an Land gehen könnte.*",
  [40051] = "Oh... was ist das? Aus der Tiefe des Wassers",
  [40052] = "dringt ein schmaler Lichtstrahl zu Ihnen herauf.*",
  [40053] = "Hier schwimmt Ihr morsches Holzstück im Wasser.*",
  [40054] = "Hier schwimmt Ihr morsches Holzstück im Wasser.",
  [40055] = "Eine Wurzelranke, die innen hohl ist, ist daran",
  [40056] = "festgebunden. Sicher kein schlechtes Tauchgerät!*",
  [40057] = "Blubblubb... hier ist das Wasser ziemlich tief...",
  [40058] = "nach zehn Metern, als die Luft schon knapp wird,",
  [40059] = "ist der Lichtstrahl schon ein wenig heller",
  [40060] = "geworden. Aber es scheint noch einiges an Tiefe zu",
  [40061] = "fehlen, um die Quelle des Strahles zu erreichen.",
  [40062] = "Leider ist nicht erkennbar, was sich dort unten",
  [40063] = "befindet. So, jetzt müssen Sie aber schnellstens",
  [40064] = "wieder rauf....",
  [40065] = "Pfffff... prustend durchbrechen Sie die",
  [40066] = "Wasseroberfläche.*",
  [40067] = "Blubblubb... hier ist das Wasser ziemlich tief...",
  [40068] = "nach zehn Metern ist die Wurzelranke zuende.",
  [40069] = "Gut, dann tief Luft geholt... und ohne Ranke noch",
  [40070] = "ein Stück tiefer...",
  [40071] = "... nein es geht nicht, als die Luft ausgeht, ist",
  [40072] = "der Lichtstrahl noch ein bißchen heller geworden,",
  [40073] = "aber es scheinen noch immer gute zehn Meter zu",
  [40074] = "fehlen, um seine Quelle zu erreichen. Jetzt müssen",
  [40075] = "Sie aber dringend wieder rauf.... Pfffff...",
  [40076] = "prustend durchbrechen Sie die Wasseroberfläche.*",
  [40077] = "Mit dem Sauerstoffgerät ist das Tauchen, selbst",
  [40078] = "hier - an der tiefsten Stelle des Sees, freilich",
  [40079] = "kein Problem. Alsdann... jetzt geht's abwärts...*",
  [40080] = "Am Ufer",
  [40081] = "Das Ufer ist nur wenige Meter breit, dahinter",
  [40082] = "steigt eine weitere Felswand in die Höhe auf. Hier",
  [40083] = "gibt es viel weißlichen, feinen Sand.*",
  [40084] = "Es ist nichts als ein ganzer Strand voll feinem,",
  [40085] = "hellen Sand.*",
  [40086] = "Wollen Sie ein bißchen spielen? Schade. Wir haben",
  [40087] = "vergessen, Ihnen ein paar Förmchen und",
  [40088] = "Schäufelchen hier zu lassen... ah, da kommt ein",
  [40089] = "altes, trockenes und morsches Holzstück zum",
  [40090] = "Vorschein. Schade, hier sollte eigentlich eine",
  [40091] = "Schatztruhe liegen - die hat der Programmierer",
  [40092] = "doch glatt unterschlagen! Ah - deshalb ist der",
  [40093] = "Kerl im Winter immer auf den Bahamas...!*",
  [40094] = "Wollen Sie ein bißchen spielen? Schade. Wir haben",
  [40095] = "vergessen, Ihnen ein paar Förmchen und",
  [40096] = "Schäufelchen hier zu lassen... so, genug",
  [40097] = "gespielt!*",
  [40098] = "Bei diesem Holzstück scheint sich um den morschen,",
  [40099] = "vertrockneten Rest eines Baumstammes zu handeln.",
  [40100] = "Das Stück ist etwa einen halben Meter lang, und",
  [40101] = "wiegt nicht viel mehr als ein Blatt Papier.*",
  [40102] = "Eine innen hohle, ziemlich lange Wurzelranke ist",
  [40103] = "daran befestigt.*",
  [40104] = "Die Felswand ist fast völlig glatt, nur in ein",
  [40105] = "paar Rissen haben sich kleine, zähe Pflanzen",
  [40106] = "festgekrallt. Trotzdem dürften sich die Risse kaum",
  [40107] = "zu klettern eignen. Wohin auch?*",
  [40108] = "Es sind nur ein paar kleine Pflanzen - sie haben",
  [40109] = "sich in den Rissen festgekrallt. Sie sind von",
  [40110] = "unbekannter Art... nunja, diese eine sieht ein",
  [40111] = "bißchen so aus wie Steinkraut.*",
  [40112] = "Es sind nur ein paar kleine Pflanzen - sie haben",
  [40113] = "sich in den Rissen festgekrallt. Sie sind von",
  [40114] = "unbekannter Art.*",
  [40115] = "Was wollen Sie denn mit dem Steinkraut? Na, also,",
  [40116] = "dann ziehen wir mal vorsichtig... Oh! Das sitzt",
  [40117] = "aber verdammt fest in dem Riss! So leicht ist es",
  [40118] = "nicht von dort loszubekommen, ohne dabei die",
  [40119] = "Pflanze kaputtzumachen! Aber das wollen Sie doch",
  [40120] = "sicher nicht!*",
  [40121] = "Also gut, probieren wirs nochmal... ah, jetzt gibt",
  [40122] = "sie ein wenig nach. Ruckeln Sie mal ein bißchen...",
  [40123] = "oh! Da hängt ja eine ewig lange... na, ziehen Sie",
  [40124] = "schon weiter... ja, tatsächlich! Es ist eine ewig",
  [40125] = "lange Wurzelranke... schnapp! Jetzt ist sie",
  [40126] = "zuende! Du lieber Himmel - das Ding reicht ja bis",
  [40127] = "nach Bangkok!*",
  [40128] = "Wie schade! Wer weiß wie lange das Ding hier",
  [40129] = "schon... schnapp! Oh, was war das? Da ist die",
  [40130] = "Wurzel abgerissen! Das ist aber traurig. Dieses",
  [40131] = "Steinkaut ist zum Sterben verurteilt. Was für ein",
  [40132] = "Jammer!*",
  [40133] = "Es handelt sich um ein kleines Büschel... nun, um",
  [40134] = "eine Art von Steinkraut, könnte man sagen.*",
  [40135] = "Hintendran hängt eine meterlange, ziemlich dicke",
  [40136] = "Wurzelranke.*",
  [40137] = " *",
  [40138] = "Da ist nicht viel zu sehen. Nur, daß eine",
  [40139] = "fingerdicke Wurzelranke in den Felsen hineinführt.",
  [40140] = "Sie ist innen hohl.*",
  [40141] = "Nun, es ist eine Wurzelranke, so dick wie ihr",
  [40142] = "kleiner Finger. Sie ist ziemlich lang - so an die",
  [40143] = "zehn Meter, ungefähr.*",
  [40144] = "Nun, es ist eine Wurzelranke, so dick wie ihr",
  [40145] = "kleiner Finger. Sie ist ziemlich lang - so an die",
  [40146] = "zehn Meter, ungefähr. Und - sieh an, Sie ist innen",
  [40147] = "hohl!*",
  [40148] = "Gut, machen wir die Wurzel ab - vielleicht gibt's",
  [40149] = "da ja eine Überraschung... oh! Tatsächlich! Die",
  [40150] = "Wurzelranke ist innen hohl!*",
  [40151] = "Aha! Sie haben mal wieder eine ihrer Erfindungen",
  [40152] = "im Sinn was? Na, da sind wir schon mal gespannt,",
  [40153] = "was das wieder wird. Gut, die Ranke ist an dem",
  [40154] = "Holzstück befestigt.*",
  [40155] = "Also... nichts gegen Ihre Idee, aber unser",
  [40156] = "geheimer Tip lautet in diesem Fall: probieren sie",
  [40157] = "noch etwas anderes mit diesem Holzstück! Das",
  [40158] = "bringt sie viel eher zum Erfolg!*",
  [40159] = "Ja, inzwischen war uns schon klar, daß Sie damit",
  [40160] = "tauchen wollen. Tun Sie's nur - das Atmen dürfte",
  [40161] = "sich dann schon von selber einstellen - meinen Sie",
  [40162] = "nicht?*",
  [40163] = "An der tiefsten Stelle des Sees",
  [40164] = "Sie haben die Quelle des Lichtstrahles erreicht.",
  [40165] = "Hier, am felsigen Grund des Sees, befindet sich",
  [40166] = "eine riesige, quadratische Felsplatte im Boden,",
  [40167] = "so groß wie ein Tennisplatz. In der Mitte befindet",
  [40168] = "sich ein winziges Loch, aus dem ein scharfer,",
  [40169] = "gebündelter Lichtstrahl dringt, so dünn wie eine",
  [40170] = "Nadel. Das Wasser ist düster und still, es nur",
  [40171] = "wird von dem gleißenden Strahl zerschnitten.*",
  [40172] = "An der tiefsten Stelle des Sees",
  [40173] = "Hier, im felsigen Grund des Sees, befindet sich",
  [40174] = "eine riesige, quadratische Öffnung im Boden, so",
  [40175] = "groß wie ein Tennisplatz. Darunter geht es hinab",
  [40176] = "in gar finsterliche Tiefen.*",
  [40177] = "Von hier aus, an der tiefsten Stelle des Sees,",
  [40178] = "gibt es nur einen tauchbaren Weg nach oben, oder",
  [40179] = "Richtung Süden, dorthin, wo der schreckliche Bool",
  [40180] = "auf dem Grund des Sees liegt. In allen anderen",
  [40181] = "Richtungen steigt der felsige Grund wieder an.*",
  [40182] = "Von hier aus, an der tiefsten Stelle des Sees,",
  [40183] = "gibt es nur einen tauchbaren Weg nach oben, oder",
  [40184] = "Richtung Süden, dorthin, wo der schreckliche Bool",
  [40185] = "auf dem Grund des Sees liegt. Allerdings könnten",
  [40186] = "Sie auch noch weiter hinab - durch die finstere",
  [40187] = "quadratische Öffnung im Boden!*",
  [40188] = "Die Felsplatte ist grau und muß Hunderte von",
  [40189] = "Tonnen wiegen. Überall an ihrem Rand, dort wo die",
  [40190] = "Platte in die sich wölbenden Felsen des Sees-Grund",
  [40191] = "übergeht, befinden sich seltsame, glitzernde",
  [40192] = "Würfel.*",
  [40193] = "Die Würfel entpuppen sich als exakt würfelförmig.",
  [40194] = "Sie sind grünlich, haben etwa fünf Zentimeter",
  [40195] = "Kantenlänge und leuchten leicht - sie scheinen das",
  [40196] = "bißchen Licht hier unten einzufangen und zu",
  [40197] = "speichern. Es scheint fast, als wären sie eine Art",
  [40198] = "Positionslichter, die die Felsplatte markieren",
  [40199] = "sollen.*",
  [40200] = "Gut... nein, leider klappt das nicht. Bei einem",
  [40201] = "Versuch stellt sich heraus, daß der Würfel, den",
  [40202] = "Sie nehmen wollten, irgendwie am felsigen Boden",
  [40203] = "befestigt ist.*",
  [40204] = "Oh. Der wahre Abenteurer gibt nie auf, was? Ja,",
  [40205] = "Sie haben recht. Etwas, das irgendwie befestigt",
  [40206] = "ist, muß auch mit irgendeiner Methode zu lösen",
  [40207] = "sein. Und diese würfelförmigen Würfel hier sind",
  [40208] = "festgeschraubt! Das geht zwar nur sehr schwer...",
  [40209] = "ah, da ist einer, der loszukriegen ist! Bravo. Sie",
  [40210] = "besitzen nun einen der Würfel.*",
  [40211] = "Es handelt sich um einen kristallnen Würfel mit",
  [40212] = "einer Kantenlänge von etwa 5 Zentimetern.",
  [40213] = "Er leuchtet schwach.*",
  [40214] = " *",
  [40215] = "Es handelt sich um einen kristallnen Würfel mit",
  [40216] = "einer Kantenlänge von etwa 5 Zentimetern.",
  [40217] = "Er verstrahlt ein kräftiges Licht.*",
  [40218] = " *",
  [40219] = "Der Lichtstrahl ist extrem hell und grünlich. Erst",
  [40220] = "nachdem er fünf Meter das Wasser durchschnitten",
  [40221] = "hat, zerstreut er sich langsam, wird diffus, und",
  [40222] = "erreicht die Oberfläche nur als undeutlicher",
  [40223] = "Schein. Man möchte meinen, es wäre eine Art von",
  [40224] = "Laserlicht.*",
  [40225] = "Der Grund des Sees ist sehr uneben, die Felsen",
  [40226] = "türmen und wölben sich in alle Richtungen. Sie",
  [40227] = "scheinen aus massivem Basalt zu be...",
  [40228] = "Oh! Dieser da ist ganz offensichtlich eine",
  [40229] = "Attrappe! Und überdies: Obendrauf befindet sich",
  [40230] = "ein gut getarntes, aber dem aufmerksamen Auge",
  [40231] = "nicht entgehendes Kästchen aus Metall!*",
  [40232] = "Das Metallkästchen ist ziemlich klein, und",
  [40233] = "obendrauf ist ein Loch. Durch das Loch kann man",
  [40234] = "hineinsehen... und erblickt eine Art Linse!*",
  [40235] = "Die Linse ist... nun, was soll man da sagen? Sie",
  [40236] = "wird vermutlich einem bestimmten Zweck dienen.",
  [40237] = "Vielleicht handelt es sich um eine Fernsehkamera",
  [40238] = "oder um eine... tja, vielleicht um eine",
  [40239] = "Fotozelle!*",
  [40240] = "Sie sind ganz schön schlau! Sackelzement!",
  [40241] = "Schon nach Sekunden hat sich der Würfel in dem",
  [40242] = "intensiven Licht aufgeladen, und verstrahlt nun",
  [40243] = "einen kräftigen Schein!*",
  [40244] = "He, das ist gar keine so unschlaue Idee! Probieren",
  [40245] = "wir's also... nein, noch ein bißchen weiter nach",
  [40246] = "links... ja, so fällt der Lichtstrahl auf das",
  [40247] = "Kästchen....",
  [40248] = "Krrrrrkkkkssss.....",
  [40249] = "Mit einem heftig durch die Stille der",
  [40250] = "Unterwasserwelt knirschenden Geräusch, beginnt",
  [40251] = "sich die riesige Felsplatte zu verschieben, und",
  [40252] = "gibt den Weg nach unten frei!*",
  [40253] = "Am Grund des Sees",
  [40254] = "Das Licht hier unten ist nur noch sehr schwach.",
  [40255] = "Trotzdem ist leicht erkennbar, daß dies ein",
  [40256] = "wahrhaft grauenvoller Ort ist. Der Kadaver des",
  [40257] = "entsetzlichen Monstrums, das Pit \"den",
  [40258] = "schrecklichen Bool\" nannte, liegt hier unten, im",
  [40259] = "düsteren Schweigen, am Grund des Sees.*",
  [40260] = "Unterhalb von Ihnen liegt eine einzelne Schuppe",
  [40261] = "vom Bauch des Monstrums auf dem Grund des Sees.*",
  [40262] = "Die Schuppe ist etwas größer als ein DIN-A-4",
  [40263] = "Blatt. Sie reflektiert das Licht und glänzt hell",
  [40264] = "und silbrig.*",
  [40265] = "Der Leib des Untiers muß an die zwanzig Meter lang",
  [40266] = "sein. Es besitzt den Rachen eines Haifisches, nur",
  [40267] = "noch viel größer - mit messerscharfen Zähnen, wohl",
  [40268] = "einen halben Meter lang. Zwei riesige, walfisch-",
  [40269] = "ähnliche Flossen ragen aus den Seiten, der",
  [40270] = "peitschenartige Schwanz endet in einem knochigen",
  [40271] = "Blatt, größer als ein Wagenrad. Die stechenden",
  [40272] = "Augen von der Größe von Bowlingkugeln sind gelb",
  [40273] = "und geschlitzt wie die einer Katze.*",
  [40274] = "Das Tier liegt verkrümmt auf dem Rücken und",
  [40275] = "streckt ihnen die Haut seines silbrig-schimmernden",
  [40276] = "Bauches entgegen, wo man die Ursache seines",
  [40277] = "Dahinscheidens sehen kann: ein ausgefranste Wunde,",
  [40278] = "durch die man einen Baumstamm stecken könnte. Der",
  [40279] = "Gedanke ist beängstigend, daß Pit sich auf diese",
  [40280] = "unschöne und durchschlagende Weise aus dem Magen",
  [40281] = "des Monsters befreit hat.*",
  [40282] = "Der Schwanz ist viele Meter lang, das knochige",
  [40283] = "Blatt am seinem Ende diente wohl zum Rudern. Es",
  [40284] = "hat die Form einer großen Walfisch-Schwanzflosse.*",
  [40285] = "Die Flossen an den Seiten des Leibes deuten auf",
  [40286] = "eine immense Kraft hin, sie sind langgestreckt und",
  [40287] = "muskulös.*",
  [40288] = "Die Wunde sieht aus, als wäre von innen eine",
  [40289] = "Kanonenkugel herausgeschossen worden. An den",
  [40290] = "Rändern hängen seltsame Gewebefetzen herum.*",
  [40291] = "Das Gewebe sieht seltsam aus. Es ist völlig",
  [40292] = "schwarz, und sieht aus wie zähes Plastik.*",
  [40293] = "Die Augen des Untiers bergen eine Überraschung:",
  [40294] = "sie sehen aus, als wären sie aus Glas.*",
  [40295] = "Die Haut des Monstrums schimmert silbrig.*",
  [40296] = "Der Rachen steht weit offen. Es ist so groß, daß",
  [40297] = "man mit einem VW-Käfer hineinfahren könnte. Aber",
  [40298] = "den langen Zähnen könnte der Käfer wohl nicht",
  [40299] = "wiederstehen, selbst wenn er aus Gußeisen wäre.*",
  [40300] = "Der Rachen des Monstrums ist geschlossen.*",
  [40301] = "Ach du lieber Himmel. Da wird einem ja ganz flau",
  [40302] = "im Magen. Vielleicht lebt das Monster noch ein",
  [40303] = "bißchen...? Oder vielleicht lässt ein letzter",
  [40304] = "Reflex das Maul zuschnappen? Und da drinnen ist es",
  [40305] = "stockfinster - man sieht kaum die Hand vor Augen!",
  [40306] = "Wollen Sie das wirklich wagen?*",
  [40307] = "Möglicherweise die bessere Idee. Vielleicht",
  [40308] = "gelingt es Ihnen ja, Ihre Chancen, dies zu",
  [40309] = "bewältigen, noch ein wenig zu verbessern.*",
  [40310] = "Also gut, wenn Sie unbedingt wollen? Aber geben",
  [40311] = "Sie acht, die Zähne sind verdammt scharf... und da",
  [40312] = "drinnen, im Rachen des Untiers ist es schrecklich",
  [40313] = "finster...!",
  [40314] = "Uuuch... schon ist es passiert! Sie haben sich",
  [40315] = "Ihren Dings abgeschnitten..., ihren, äh...",
  [40316] = "dingsbums, na, wie sagt man denn.... ihren",
  [40317] = "ZEIGEFINGER! Und das blutet vielleicht... ohgott,",
  [40318] = "das Blut löst einen letzten Reflex des Monsters",
  [40319] = "aus.... Schnapp - kracht das Gebiß zu...!*",
  [40320] = "Also gut, wenn Sie unbedingt wollen? Aber geben",
  [40321] = "Sie acht, die Zähne sind verdammt scharf... und da",
  [40322] = "drinnen, ist es so finster... das schwache Licht",
  [40323] = "Ihres Würfels hilft auch nicht viel...",
  [40324] = "Uuuch... schon ist es passiert! Sie haben sich",
  [40325] = "Ihren Dings abgeschnitten..., ihren, äh...",
  [40326] = "dingsbums, na, wie sagt man denn.... ihren",
  [40327] = "ZEIGEFINGER! Und das blutet vielleicht... ohgott,",
  [40328] = "das Blut löst einen letzten Reflex des Monsters",
  [40329] = "aus.... Schnapp - kracht das Gebiß zu...!*",
  [40330] = "Auweh, auweh, auweh.... sie sollten sich beim",
  [40331] = "Secret Service bewerben... soviel Mut hat selten",
  [40332] = "einer... wir ziehen es vor, wegzugucken....",
  [40333] = "Als Sie hindurchtauchen, können Sie förmlich die",
  [40334] = "Zähne in Ihren Seiten spüren... dann sind sie im",
  [40335] = "Rachen... schließlich liegt die hübsch anzusehende",
  [40336] = "Speiseröhre hinter Ihnen.... und....",
  [40337] = "Uff! Was ist das?*",
  [40338] = "Im Inneren des Monsters",
  [40339] = "Es ist unglaublich. Das Monster ist gar nicht",
  [40340] = "echt! Es ist künstlich, tot, aus Plastik, Metall",
  [40341] = "und Pappdeckel! Es ist ein Roboter!",
  [40342] = "Sie befinden sich mitten in einem unübersehbaren",
  [40343] = "Gewühl von Gestängen, Plastikteilen und ähnlichem.",
  [40344] = "Gleich oberhalb von Ihnen ist alles zerfetzt -",
  [40345] = "hier hat sich Pit offenbar einen Tunnel nach",
  [40346] = "draußen gebahnt. Nach Norden geht es durchs Maul",
  [40347] = "wieder hinaus. Direkt vor Ihnen ist eine kleine",
  [40348] = "Armaturentafel angeschraubt.*",
  [40349] = "Hm. Das wird nicht klappen... das Maul des",
  [40350] = "Monsters ist zu.*",
  [40351] = "Das war nur ein Spaß. Pappdeckel würde sich hier",
  [40352] = "natürlich sofort auflösen.*",
  [40353] = "Die Armaturentafel besitzt einen Druckknopf und",
  [40354] = "einen Schalter. Obendrüber ist ein Schildchen",
  [40355] = "angeschraubt.*",
  [40356] = "Da steht: 'Vorsicht! Nur für Fachpersonal!'*",
  [40357] = "Der Druckknopf ist rot angemalt. Obendrüber steht:",
  [40358] = "\"Auf - Zu\".*",
  [40359] = "Wer weiß, was dann passiert! Wollen Sie das",
  [40360] = "wirklich wagen?*",
  [40361] = "Tja, mitunter ist es besser, sich zuvor über die",
  [40362] = "Funktion eines Knopfes im Klaren zu sein, nicht?*",
  [40363] = "Krach! Als Sie den Knopf niederdrücken, tönt",
  [40364] = "plötzlich ein lauter Knall durch das Monster. Hm -",
  [40365] = "sonst passiert nichts.*",
  [40366] = "Plötzlich müssen Sie feststellen, daß anstelle von",
  [40367] = "Luft nun Wasser durch Ihren Wurzelranke dringt!",
  [40368] = "Sie muß leck sein! Ohgott.... der Knall vorhin!",
  [40369] = "Sie haben durch den Kopfdruck das Gebiß",
  [40370] = "zuschnappen lassen.... und da war Ihre Wurzelranke",
  [40371] = "dazwischen...!",
  [40372] = "Hhhhhhh....*",
  [40373] = "Ohgott... die Lungen sind schon halb voll",
  [40374] = "Wasser... schnell... es... aaaaaahhhhh...*",
  [40375] = "Ohgott! Das Ding ist leer! Es ist keine Luft zum",
  [40376] = "Atmen da... Hilfeeeee......*",
  [40377] = "Bis auf ein kraftloses Zischen geschieht nichts.",
  [40378] = "Es scheint, als wären die Energiereserven der",
  [40379] = "Maschinen erschöpft. So ein Pech, jetzt ist das",
  [40380] = "Maul zu!*",
  [40381] = "Der Schalter ist gelb angemalt, man kann ihn",
  [40382] = "offenbar nach rechts oder links drehen. Über der",
  [40383] = "rechten Position steht: \"Aufladen\", über der",
  [40384] = "linken: \"Entriegelung\".*",
  [40385] = "In welche Richtung wollen Sie ihn denn drehen?",
  [40386] = "Nach links oder nach rechts?*",
  [40387] = "Wissen Sie denn, was dann passiert? Wollen Sie das",
  [40388] = "wirklich tun?*",
  [40389] = "Das Geräusch eines elektrischen Aggregats ertönt.",
  [40390] = "Es knirscht und spotzt, der ganze Korpus des",
  [40391] = "Monstrums vibriert für eine Zeit, dann ist der",
  [40392] = "Spuk vorbei. Nichts rührt sich mehr.*",
  [40393] = "Klack! Gleich rechts von Ihnen springt eine",
  [40394] = "Blechverkleidung auf. Dahinter liegt ein",
  [40395] = "Hohlraum.*",
  [40396] = "Hm. Nichts geschieht.*",
  [40397] = "Es ist eine ganz normale Blechverkleidung - ah,",
  [40398] = "dort an der Innenseite steckt in einem Halter ein",
  [40399] = "Engländer!*",
  [40400] = "Nun - ein Engländer ist eine Art verstellbarer",
  [40401] = "Schraubenschlüssel. Dies hier ist ein etwas",
  [40402] = "rostiges, aber sicher noch funktionstüchtiges",
  [40403] = "Exemplar dieser Gattung.*",
  [40404] = "In dem Hohlraum steht... was für ein phänomenales",
  [40405] = "Glück... ein Sauerstoffgerät!*",
  [40406] = "Es handelt sich um die Art von Atemgerät, wie man",
  [40407] = "es gemeinhin aus Film und Fernsehen, (und mancher",
  [40408] = "wohl auch aus der Praxis), kennt.*",
  [40409] = "Gut, dann schnallen Sie sich das Ding mal um...",
  [40410] = "so, und jetzt die Sauerstoffzufuhr aufdrehen...",
  [40411] = "urks.",
  [40412] = "Schnell, nehmen Sie wieder Ihre Wurzelranke! Da",
  [40413] = "kommt nicht das kleinste Luftbläschen, um Ihre",
  [40414] = "Lungen zu erfrischen!*",
  [40415] = "Okay, stellen wirs wieder zurück... aha - es",
  [40416] = "rastet in einer Vorrichtung ein!*",
  [40417] = "Okay. Die Blechverkleidung schnappt ein... sie ist",
  [40418] = "jetzt wieder zu.*",
  [40419] = "Vorsicht... ein lautes Zischen ertönt, riesige",
  [40420] = "Luftblasen blubbern umher... dann ist der Spuk",
  [40421] = "vorbei.*",
  [40422] = "Gut, dann schnallen Sie sich das Ding mal um...",
  [40423] = "so, und jetzt die Sauerstoffzufuhr aufdrehen...",
  [40424] = "Sehr gut! Das Ding funktioniert. Das ist eine",
  [40425] = "deutliche Verbesserung für Ihre Bewegungsfreiheit",
  [40426] = "und Überlebenschancen.*",
  [40427] = "Was? Ist das Ihr Ernst? Wenn man unter Wasser",
  [40428] = "keine Luft zum atmen hat, dann ertrinkt man! Haben",
  [40429] = "Sie schon davon gehört? Ja? Also: dann behalten",
  [40430] = "Sie es lieber um!*",
  [40431] = "Das wird nicht klappen! So lang Ihre Wurzelranke",
  [40432] = "auch ist - hier ist der Weg zuende. Sie ist schon",
  [40433] = "straff gespannt.*",
  [40434] = "Im Tunnel",
  [40435] = "Eine bessere Bezeichnung für diesen Ort gibt es",
  [40436] = "nicht, denn es ist genau das, was sich der kleine,",
  [40437] = "erstaunliche Pit durch das Innere des",
  [40438] = "Robotermonsters gebahnt hat. Um Sie herum ist",
  [40439] = "alles verbeult, zerstört und verbogen.*",
  [40440] = "Leider ist hier kein weiteres Fortkommen mehr",
  [40441] = "möglich, denn eine massive Metallstange aus dem",
  [40442] = "Bewegungsmechanismus des Monsters verläuft quer",
  [40443] = "durch den Tunnel.*",
  [40444] = "Es handelt sich um eine dicke Metallstange, die",
  [40445] = "weiter vorn an einem Gelenkmechanismus befestigt",
  [40446] = "ist, und irgendeine Bedeutung für die Bewegung des",
  [40447] = "Monsters haben muß.*",
  [40448] = "Der Gelenkmechanismus hat einen riesigen Exzenter,",
  [40449] = "und die Metallstange muß einen enormen Hub haben.",
  [40450] = "Möglicherweise bewegt sie den Schwanz des",
  [40451] = "Monsters. Schade, daß der Exzenter ausgerechnet in",
  [40452] = "einer Stellung stehengeblieben ist, bei der die",
  [40453] = "Metallstange quer durch den Tunnel verläuft!*",
  [40454] = "An der Außenhaut",
  [40455] = "Hier endet der Tunnel; ein großes Loch führt durch",
  [40456] = "die Außenhaut des Monster-Roboters nach draußen.*",
  [40457] = "Es ist etwa so groß wie ein Fußball.*",
  [40458] = "Es wäre groß genug, daß Sie hindurchpassen.*",
  [40459] = "Die Außenhaut besteht aus Plastik und einem",
  [40460] = "Metallgewebe.*",
  [40461] = "Da passen Sie nicht durch.*",
  [40462] = "Zwecklos. Die Außenhaut besteht aus Plastik und",
  [40463] = "Metallgewebe. Das lässt sich nicht zerschneiden.*",
  [40464] = "Das Plastik ist außerordentlich zäh und schwarz.*",
  [40465] = "Das Metallgewebe besitzt in einem regelmäßigen",
  [40466] = "Muster Ösen, durch die dicke Bolzen",
  [40467] = "hindurchschauen.*",
  [40468] = "Hm... irgendwelche Sachen sind von außen damit",
  [40469] = "befestigt - ah, da sieht man es! Die Bolzen dienen",
  [40470] = "offenbar dazu, die einzelnen Schuppen zu",
  [40471] = "befestigen, aus denen die Außenhaut besteht.*",
  [40472] = "Tja, das ginge vielleicht schon, aber nicht mit",
  [40473] = "der bloßen Hand!*",
  [40474] = "Na, dann wollen wir mal probieren... ja, das geht",
  [40475] = "einigermaßen. So... noch ein paar Umdrehungen...",
  [40476] = "ooohh! Jetzt ist der Engländer abgerutscht... und",
  [40477] = "purzelt hinab... Mist!",
  [40478] = "Aber Sie haben Glück im Unglück! Der Bolzen war",
  [40479] = "schon so weit gelöst, daß er sich nun mit der Hand",
  [40480] = "abdrehen läßt. Draußen löst sich irgendein Teil...",
  [40481] = "bravo, das Loch ist nun groß genug, daß Sie",
  [40482] = "durchpassen!*",
  [40483] = "Plötzlich schaltet sich ringsumher eine kräftige",
  [40484] = "Beleuchtung ein. Aber... im nächsten Moment",
  [40485] = "schließt sich über Ihnen auch die große",
  [40486] = "Schleusenöffnung.*",
  [40487] = "In der Schleuse",
  [40488] = "Sie befinden sich in einem großen",
  [40489] = "Schleusenraum, der etwa zwanzig Meter hoch ist.",
  [40490] = "Die Wände sind aus weißgestrichenem Metall, ein",
  [40491] = "paar Rohrleitungen führen hierhin und dorthin, und",
  [40492] = "an einer Stelle liegt ein großer, vergitterter",
  [40493] = "Pumpkanal. In der westlichen Wand befindet sich",
  [40494] = "ein riesiges und schweres Metallgitter; direkt",
  [40495] = "daneben ist eine Steuereinheit angebracht. Nach",
  [40496] = "Norden hin liegt ein großes Stahltor.*",
  [40497] = "Die Schleuse ist mit Wasser erfüllt.*",
  [40498] = "Die Schleuse ist gänzlich leergepumpt.*",
  [40499] = "Auf dem Boden der Schleusenkammer liegt ein",
  [40500] = "riesiges Roboter-Monstrum. Der zweite",
  [40501] = "\"schreckliche Bool\"! Er ist hier gestrandet, und",
  [40502] = "zappelt, so riesig er auch ist, hilflos umher.*",
  [40503] = "Der Pumpkanal führt irgendwohin in die Tiefe. Er",
  [40504] = "ist mit dicken Streben vergittert.*",
  [40505] = "Das große Gitter besteht aus enorm dicken Rohren,",
  [40506] = "die weiß gestrichen sind. Sie sind jedoch so weit",
  [40507] = "auseinander, daß Sie gerade noch hindurchschlüpfen",
  [40508] = "könnten. Dahinter schließt sich ein breiter Tunnel",
  [40509] = "an, der nach Westen verläuft.*",
  [40510] = "Es ist geschlossen.*",
  [40511] = "Es ist offen.*",
  [40512] = "Es ist ein großer Tunnel, mit quadratischem",
  [40513] = "Querschnitt, wohl gute zehn Meter im Durchmesser.",
  [40514] = "Er führt zuerst nach Westen und dann, nach einem",
  [40515] = "deutlichen Knick, schräg abwärts.*",
  [40516] = "Er ist, da sich in der Schleusenkammer Wasser",
  [40517] = "befindet, zur Gänze geflutet.*",
  [40518] = "Das Stahltor besteht aus Metall. Es ist weiß",
  [40519] = "gestrichen, und bestimmt 5 Meter hoch. Es sieht so",
  [40520] = "aus, als würde es hierher, nach innen, zu öffnen",
  [40521] = "sein.*",
  [40522] = "Die Steuereinheit ist an der Wand direkt neben dem",
  [40523] = "schweren Gitter abgebracht. Ein Kabel führt von",
  [40524] = "oben an der Wand herab, und mündet in die Einheit.",
  [40525] = "Sie hat einen Knopf, eine Taste und einen Regler,",
  [40526] = "letzteren kann man in zwei verschiedene Positionen",
  [40527] = "drehen. Obendrüber steht auf einem Schild: \"Opto-",
  [40528] = "Aktion-Service. Einheit No. 2. Äußerste Vorsicht!",
  [40529] = "Nur für speziell ausgebildetes Fach-Personal!\"*",
  [40530] = "Es ist ein Regler, den man drehen kann - in zwei",
  [40531] = "verschiedene Positionen: Null und Eins.*",
  [40532] = "Der Regler steht derzeit auf Position Null.*",
  [40533] = "Der Regler steht derzeit auf Position Eins.*",
  [40534] = "Der Knopf ist mit den Buchstaben GIT-A-Z",
  [40535] = "beschriftet.*",
  [40536] = "Die Taste ist mit den Buchstaben TOR-A-Z",
  [40537] = "beschriftet.*",
  [40538] = "Die Steuereinheit und ihre Armaturen sind aus",
  [40539] = "Metall. Da können Sie nichts kaputtmachen.*",
  [40540] = "Es handelt sich um ein mitteldickes, schwarzes,",
  [40541] = "wasserdichtes Kabel aus der Weltenschmiede-",
  [40542] = "Requisiten-Abteilung. Lager-Nummer KA-SW-WD-",
  [40543] = "000467888456-A Q-UI-Z 555-TPVL-0011 ZX-a.*",
  [40544] = "Es handelt sich um ein mitteldickes, schwarzes,",
  [40545] = "kaputtes, wasserdichtes Kabel aus der",
  [40546] = "Weltenschmiede-Requisiten-Abteilung. Lager-Nummer",
  [40547] = "KA-SW-WD-KPTT-000467888456-B Q-UI-Z 555-TPVL-",
  [40548] = "0011 ZX-a. Wiegesagt, es ist kaputt. Mitten-",
  [40549] = "durchgeschnitten.*",
  [40550] = "Uiuiui! Das ist aber gefährlich...",
  [40551] = "Ob der Holzgriff als Isolation ausreicht? Knirsch!",
  [40552] = "Peng! Es klappt. Sie haben überlebt, und das Kabel",
  [40553] = "ist entzwei! Ein Funkenregen sprüht auf Sie",
  [40554] = "herab.*",
  [40555] = "Uiuiui! Das ist aber gefährlich...",
  [40556] = "Wasser ist doch ein hervorragender Leiter für",
  [40557] = "Stroooooooo.......*",
  [40558] = "Da wird sich nichts mehr tun. Hier hat ein Vandale",
  [40559] = "das Kabel sabotiert. Es ist entzweigeschnitten.*",
  [40560] = "In welche Position wollen Sie ihn denn drehen?",
  [40561] = "(Geben Sie bitte die Zahl an, z.B: >drehe den",
  [40562] = "Regler auf Eins.)*",
  [40563] = "In dieser Position steht der Regler bereits!*",
  [40564] = "Irgendwo springt eine große Maschine an. Lautes",
  [40565] = "Rattern und Vibrieren ertönt, während aus dem",
  [40566] = "Pumpkanal Wassermassen in die Schleuse schießen.",
  [40567] = "Doch das läuft durch das offene Stahltor wieder",
  [40568] = "davon. Dann plötzlich ertönt von dort draußen das",
  [40569] = "elektrische Krachen eines gigantischen",
  [40570] = "Kurzschlusses... und Sie stehen im Wasser....",
  [40571] = "aaaaggggrrrhhhhzzzz....*",
  [40572] = "Irgendwo springt eine große Maschine an. Für",
  [40573] = "einige Zeit ertönt lautes Rattern und Vibrieren,",
  [40574] = "während das Wasser in der Schleuse rasch steigt,",
  [40575] = "bis Sie ganz voll Wasser ist. Dann zischen",
  [40576] = "Ventile, und das Geräusch verebbt wieder.*",
  [40577] = "Oh Gott! Das Robotermonster kommt frei! Es schießt",
  [40578] = "auf Sie zu... oh nein... schnell... weg",
  [40579] = "hiiiiiier...*",
  [40580] = "Irgendwo springt eine große Maschine an. Für",
  [40581] = "einige Zeit ertönt lautes Rattern und Vibrieren,",
  [40582] = "während der Wasserstand in der Schleuse rasch",
  [40583] = "fällt, bis sie ganz leer ist. Dann zischen ein",
  [40584] = "paar Ventile, und das Geräusch verebbt wieder.*",
  [40585] = "Die Schleuse ist jetzt ganz mit Wasser erfüllt.*",
  [40586] = "Die Schleuse ist jetzt ganz leergepumpt.*",
  [40587] = "Irgendwo springt ein mächtiger Motor an. Es brummt",
  [40588] = "eine Weile lautstark... dann beginnt mit einem Mal",
  [40589] = "das Wasser wärmer zu werden! Das Geräusch wird",
  [40590] = "unregelmäßig, es beginnt zu knirschen und zu",
  [40591] = "krachen... oh, nein... die westliche Wand wölbt",
  [40592] = "sich immer weiter in den Raum hinein, immer",
  [40593] = "weiter.... und plötzlich, mit einem",
  [40594] = "ohrenzerreißenden Schlag, zerplatzt sie mit",
  [40595] = "tödlicher Gewalt... Krrrrrwuuummmmmm......!*",
  [40596] = "Eine Hydraulik erwacht irgendwo zum Leben. Rasch",
  [40597] = "schwingt das schwere Stahltor nach innen auf - und",
  [40598] = "gibt einen Durchgang nach Norden frei!*",
  [40599] = "Die Hydraulik erwacht wieder zum Leben. Das",
  [40600] = "schwere Stahltor schwingt zu - wummm!!! ...und",
  [40601] = "schließt den Durchgang nach Norden.*",
  [40602] = "Rasselnd öffnet sich das riesige Stahlgitter, und",
  [40603] = "gibt den Zugang in den Tunnel nach Westen frei...",
  [40604] = "nunja, den hätten auch so betreten können. Die",
  [40605] = "Gitterstäbe sind weit genug auseinander.*",
  [40606] = "Mit lautem Geknirsche senkt sich das Stahlgitter",
  [40607] = "wieder herab. Rummms. Der Tunnel nach Westen ist",
  [40608] = "wieder zu.*",
  [40609] = "Rasselnd öffnet sich das riesige Stahlgitter. Und",
  [40610] = "es dauert keine zehn Sekunden, da kommt aus der",
  [40611] = "Öffnung in der südlichen Wand ein riesiges Untier",
  [40612] = "in die Schleuse geschossen: ein Ebenbild des",
  [40613] = "\"schrecklichen Bool\"! Das Roboter-Monster rauscht",
  [40614] = "zu voller Länge in die Schleusenkammer, erblickt",
  [40615] = "Sie mit seinen kalten, gläsernen Augen und zeigt",
  [40616] = "Ihnen sein schauerliches Gebiß! Und leider... der",
  [40617] = "kleine Pit ist nicht da...*",
  [40618] = "Im Tunnel",
  [40619] = "Sie befinden sich an der Stelle, an der sich der",
  [40620] = "Tunnel abwärts krümmt. Dort unten scheint es ein",
  [40621] = "großes Becken zu geben. Hier, an der Wand,",
  [40622] = "befindet sich eine weitere Steuereinheit.*",
  [40623] = "Der Tunnel ist, ebenso wie die Schleuse, zur Gänze",
  [40624] = "leergepumpt. Das Becken, das unter Ihnen liegt,",
  [40625] = "ist allerdings voll Wasser. Der Wasserspiegel",
  [40626] = "beginnt zu Ihren Füßen.*",
  [40627] = "Der Tunnel ist ganz mit Wasser erfüllt.*",
  [40628] = "Um Himmels Willen...! Was ist das? Da kommt ja",
  [40629] = "ein... oh, Gott! Der \"Schreckliche Bool\"! Ein",
  [40630] = "Ebenbild des Roboter-Monsters taucht aus dem",
  [40631] = "Becken herauf.... hilffeeeeeee.....*",
  [40632] = "Schnell... tauchen Sie, was Sie können... los...",
  [40633] = "das Untier kommt immer näher....",
  [40634] = "Uff!!!",
  [40635] = "Das war Glück! Im letzten Augenblick huschen Sie",
  [40636] = "durch die Gitterstäbe, und der \"Schreckliche Bool\"",
  [40637] = "knallt mit seiner Roboterschnauze dagegen.",
  [40638] = "Enttäuscht taucht er wieder davon.*",
  [40639] = "Ohgott! Warum sind Sie nicht geflohen...? Es",
  [40640] = "scheint fast, als wäre in den Zügen des",
  [40641] = "mechanischem Wesens ein gräßliches Grinsen zu",
  [40642] = "sehen, als es nach Ihnen schnappt....",
  [40643] = "Krrrrrrackkkssss.....*",
  [40644] = "Dort unten liegt ein sehr großes Becken, sozusagen",
  [40645] = "ein Quartier für Robotermonster!*",
  [40646] = "Denn dort taucht ein Ebenbild des \"Schrecklichen",
  [40647] = "Bool\" umher, er kann Sie aber zum Glück nicht",
  [40648] = "erreichen, weil in dem Tunnel, in dem Sie stehen,",
  [40649] = "kein Wasser ist.*",
  [40650] = "Zum Glück aber ist kein Monster mehr in dem",
  [40651] = "Becken, dank Ihnes zündenden Einfalls, (und dem",
  [40652] = "Wohlwollen unseres Programmierers, haha!)*",
  [40653] = "Es ist das genaue Ebenbild der Steuereinheit in",
  [40654] = "der Schleusenkammer. Ein Kabel führt von oben an",
  [40655] = "der Wand herab, und mündet in die Einheit. Sie hat",
  [40656] = "einen Knopf, eine Taste und einen Regler,",
  [40657] = "letzteren kann man in zwei Positionen drehen.",
  [40658] = "Obendrüber steht auf einem Schild: \"Opto-Aktion-",
  [40659] = "Service. Einheit No. 3. Äußerste Vorsicht! Nur für",
  [40660] = "speziell ausgebildetes Fach-Personal!\"*",
  [40661] = "Es ist ein Regler, den man drehen kann - in zwei",
  [40662] = "verschiedene Positionen: Null und Eins.*",
  [40663] = "Der Regler steht derzeit auf Position Null.*",
  [40664] = "Der Regler steht derzeit auf Position Eins.*",
  [40665] = "Der Knopf ist mit den Buchstaben GIT-A-Z",
  [40666] = "beschriftet.*",
  [40667] = "Die Taste ist mit den Buchstaben TOR-A-Z",
  [40668] = "beschriftet.*",
  [40669] = "Die Steuereinheit und ihre Armaturen sind aus",
  [40670] = "Metall. Da können Sie nichts kaputtmachen.*",
  [40671] = "Es handelt sich um ein mitteldickes, schwarzes,",
  [40672] = "wasserdichtes Kabel aus der Weltenschmiede-",
  [40673] = "Requisiten-Abteilung. Lager-Nummer KA-SW-WD-",
  [40674] = "000467888457-A Q-UI-Z 555-TPVL-0011 ZX-a.*",
  [40675] = "Es handelt sich um ein mitteldickes, schwarzes,",
  [40676] = "kaputtes, wasserdichtes Kabel aus der",
  [40677] = "Weltenschmiede-Requisiten-Abteilung. Lager-Nummer",
  [40678] = "KA-SW-WD-KPTT-000467888457-B Q-UI-Z 555-TPVL-",
  [40679] = "0011 ZX-b. Wiegesagt, es ist kaputt. Mitten-",
  [40680] = "durchgeschnitten.*",
  [40681] = "Uiuiui! Das ist aber gefährlich...",
  [40682] = "Ob der Holzgriff als Isolation ausreicht? Knirsch!",
  [40683] = "Peng! Es klappt. Sie haben überlebt, und das Kabel",
  [40684] = "ist entzwei! Ein Funkenregen sprüht auf Sie",
  [40685] = "herab.*",
  [40686] = "Uiuiui! Das ist aber gefährlich...",
  [40687] = "Wasser ist doch ein hervorragender Leiter für",
  [40688] = "Stroooooooo.......*",
  [40689] = "Da wird sich nicht mehr viel tun. Irgendein",
  [40690] = "Vandale hat das Kabel sabotiert.*",
  [40691] = "Irgendwo springt ein mächtiger Motor an. Es brummt",
  [40692] = "eine Weile lautstark... dann beginnt, selbst hier",
  [40693] = "im Tunnel, das Wasser wärmer zu werden! Das",
  [40694] = "Geräusch wird unregelmäßig, es beginnt zu",
  [40695] = "knirschen und zu krachen... oh, nein...",
  [40696] = "plötzlich, mit einem ohrenzerreißenden Schlag,",
  [40697] = "detoniert etwas mit tödlicher Gewalt... die",
  [40698] = "Druckwelle.... krrrrrwuuummmmmm......!*",
  [40699] = "Eine Hydraulik erwacht irgendwo zum Leben. Draußen",
  [40700] = "in der Schleuse, scheint sich das schwere Stahltor",
  [40701] = "geöffnet zu haben.*",
  [40702] = "Die Hydraulik erwacht wieder zum Leben. Wummm!",
  [40703] = "Draußen, in der Schleuse, donnert das schwere",
  [40704] = "Stahltor zu.*",
  [40705] = "Rasselnd öffnet sich das riesige Stahlgitter, und",
  [40706] = "gibt den Weg zurück in die Schleuse frei... nunja,",
  [40707] = "die hätten Sie auch so betreten können. Die",
  [40708] = "Gitterstäbe sind weit genug auseinander.*",
  [40709] = "Mit lautem Geknirsche schließt sich das",
  [40710] = "Stahlgitter wieder. Rummms! Nun ist der Durchgang",
  [40711] = "wieder zu.*",
  [40712] = "Im Becken",
  [40713] = "Als ob Sie immer noch nicht genug vom Schwimmen",
  [40714] = "hätten, Sie Wasserratte! Das Becken ist",
  [40715] = "würfelförmig wie die Schleusenkammer....*",
  [40716] = "... und ein Ebenbild des Schrecklichen Bool taucht",
  [40717] = "hier herum.... hilffeeeee.....*",
  [40718] = ".. und gottseidank leer - es gibt hier nichts von",
  [40719] = "Interesse.*",
  [40720] = "Kathaura's Wache",
  [40721] = "Sie befinden sich in einem hohen und breiten Gang,",
  [40722] = "der jenseits des Stahltores zur Schleuse durch den",
  [40723] = "Felsen nach Norden führt. Hoch droben an den",
  [40724] = "Wänden brennen riesige Fackeln, und nicht weit vor",
  [40725] = "Ihnen befindet sich ein breiter Durchgang.*",
  [40726] = "Die Fackeln hängen in einer Höhe von fünf Metern.",
  [40727] = "Sie sind so groß und hängen so hoch, daß sie nur",
  [40728] = "von Kathaura dort oben angebracht worden sein",
  [40729] = "können. Der Felsen dort oben ist dick mit Ruß",
  [40730] = "überkrustet - hier müssen schon unzählige Fackeln",
  [40731] = "abgebrannt sein.*",
  [40732] = "Ein schweres Eisengitter versperrt den Weg nach",
  [40733] = "Norden unter einem weiten Felsbogen hindurch.*",
  [40734] = "Unter einem weiten Felsbogen hindurch kann man in",
  [40735] = "einem weiteren Gang nach Norden gelangen.*",
  [40736] = "Ach, das kennen Sie doch schon... oh! Sie haben",
  [40737] = "recht, auf dem dunklen Felsen neben dem Stahltor",
  [40738] = "ist der Kasten einer weiteren Steuereinheit leicht",
  [40739] = "zu übersehen.*",
  [40740] = "Sie gleicht jener in der Schleusenkammer aufs",
  [40741] = "Haar: ein Regler mit zwei Positionen, ein Knopf",
  [40742] = "und eine Taste. Oben steht:",
  [40743] = "\"Opto-Action-Service. Einheit No. 1. Äußerste",
  [40744] = "Vorsicht! Nur für speziell ausgebildetes",
  [40745] = "Fachpersonal!\"*",
  [40746] = "Das Stahltor zur Schleuse ist geöffnet.*",
  [40747] = "Das Stahltor zur Schleuse ist zu.*",
  [40748] = "Es ist ein Regler, den man drehen kann - in zwei",
  [40749] = "verschiedene Positionen.*",
  [40750] = "Der Regler steht derzeit auf Position Null.*",
  [40751] = "Der Regler steht derzeit auf Position Eins.*",
  [40752] = "Der Knopf ist mit den Buchstaben GIT-A-Z",
  [40753] = "beschriftet.*",
  [40754] = "Die Taste ist mit den Buchstaben TOR-A-Z",
  [40755] = "beschriftet.*",
  [40756] = "Die Steuereinheit und ihre Armaturen sind aus",
  [40757] = "Metall. Da können Sie nichts kaputtmachen.*",
  [40758] = "Es handelt sich um ein mitteldickes, schwarzes",
  [40759] = "Kabel aus der Weltenschmiede-Requisiten-Abteilung.",
  [40760] = "Lager-Nummer KA-SW-000467888458-A Q-UI-Z 555-TPVL-",
  [40761] = "0011 ZX-a.*",
  [40762] = "Es handelt sich um ein mitteldickes, schwarzes,",
  [40763] = "kaputtes Kabel aus der Weltenschmiede-Requisiten-",
  [40764] = "Abteilung. Lager-Nummer KA-SW-KPTT-000467888458-",
  [40765] = "B Q-UI-Z 555-TPVL-0011 ZX-b. Wiegesagt, es ist",
  [40766] = "kaputt. Mitten-durchgeschnitten.*",
  [40767] = "Uiuiui! Das ist aber gefährlich...",
  [40768] = "Ob der Holzgriff als Isolation ausreicht? Knirsch!",
  [40769] = "Peng! Es klappt. Sie haben überlebt, und das Kabel",
  [40770] = "ist entzwei! Ein Funkenregen sprüht auf Sie",
  [40771] = "herab.*",
  [40772] = "Mit verblüfftem Gesichtausdruck verfolgt Kathaura",
  [40773] = "Ihre Tat. Er kratzt sich unschlüssig am Kopf, kann",
  [40774] = "sich keinen Reim darauf machen, was Sie damit",
  [40775] = "bezwecken wollen.*",
  [40776] = "Da wird sich nichts mehr tun. Hier hat ein Vandale",
  [40777] = "das Kabel sabotiert. Es ist entzweigeschnitten.*",
  [40778] = "In welche Position wollen Sie ihn denn drehen?",
  [40779] = "(Geben Sie bitte die Zahl an, z.B: >drehe den",
  [40780] = "Regler auf Eins.)",
  [40781] = "In dieser Position steht der Regler bereits!*",
  [40782] = "Irgendwo springt eine große Maschine an. Lautes",
  [40783] = "Rattern und Vibrieren ertönt, während aus dem",
  [40784] = "Pumpkanal Wassermassen in die Schleuse schießen.",
  [40785] = "Doch das läuft durch das offene Stahltor zu Ihnen",
  [40786] = "her. Dann plötzlich ertönt ganz aus der Nähe das",
  [40787] = "elektrische Krachen eines gigantischen",
  [40788] = "Kurzschlusses... und Sie stehen im Wasser....",
  [40789] = "aaaaggggrrrhhhhzzzz....*",
  [40790] = "Irgendwo springt eine große Maschine an. Für",
  [40791] = "einige Zeit ertönt lautes Rattern und Vibrieren,",
  [40792] = "während das Wasser drinnen in der Schleuse rasch",
  [40793] = "steigt. Dann zischen Ventile, und das Geräusch",
  [40794] = "verebbt wieder.*",
  [40795] = "Irgendwo springt eine große Maschine an. Für",
  [40796] = "einige Zeit ertönt lautes Rattern und Vibrieren,",
  [40797] = "während der Wasserstand in der Schleuse rasch",
  [40798] = "fällt. Dann zischen ein paar Ventile, und das",
  [40799] = "Geräusch verebbt wieder.*",
  [40800] = "Dann sind einige laute Schläge aus der",
  [40801] = "Schleusenkammer zu hören... das muß der",
  [40802] = "schreckliche Bool sein, der hilflos in der",
  [40803] = "trockenen Schleuse liegt, und um sich schlägt!*",
  [40804] = "Ganz in Ihrer Nähe springt ein mächtiger Motor an.",
  [40805] = "Es brummt eine Weile lautstark... dann beginnt es",
  [40806] = "in Ihrer Umgebung sehr viel wärmer zu werden! Um",
  [40807] = "Himmels Willen, das ist der Motor, der Tür nach",
  [40808] = "innen öffnen will... gegen den Wasserdruck... es",
  [40809] = "beginnt zu knirschen und zu krachen... und",
  [40810] = "plötzlich, mit einem  ohrenzerreißenden Schlag,",
  [40811] = "explodiert die Maschine mit tödlicher Gewalt...",
  [40812] = "Krrrrrwuuummmmmm......!*",
  [40813] = "Eine Hydraulik erwacht irgendwo zum Leben. Rasch",
  [40814] = "schwingt das schwere Stahltor auf - und gibt den",
  [40815] = "Weg nach Süden in die Schleuse frei.*",
  [40816] = "Die Hydraulik erwacht wieder zum Leben. Das",
  [40817] = "schwere Stahltor schwingt zu - wummm!!! und",
  [40818] = "schließt den Durchgang nach Süden.*",
  [40819] = "Rasselnd öffnet sich, drinnen in der Schleuse, das",
  [40820] = "riesige Stahlgitter.*",
  [40821] = "Mit lautem Rasseln sinkt, drinnen in der Schleuse,",
  [40822] = "das Stahlgitter wieder nach unten.*",
  [40823] = "Rasselnd öffnet sich, drinnen in der Schleuse, das",
  [40824] = "riesige Stahlgitter. Und es dauert keine zehn",
  [40825] = "Sekunden, da sind deutliche Geräusche zu",
  [40826] = "vernehmen, daß ein größeres Etwas in die Schleuse",
  [40827] = "hineinschwimmt.*",
  [40828] = "Mit lautem Rasseln schließt sich, drinnen in der",
  [40829] = "Schleuse, das riesige Stahlgitter.",
  [40830] = "Rummmsss!!! Ein lauter Schlag ertönt... das war",
  [40831] = "mit Sicherheit der schreckliche Bool, der gegen",
  [40832] = "das schon geschlossene Stahlgitter gedonnert ist,",
  [40833] = "als er zurückschwimmen wollte! Ha, jetzt ist er in",
  [40834] = "der Schleuse gefangen!*",
  [40835] = "Das Eisengitter ist groß und schwer, und besteht",
  [40836] = "aus schwarzem Metall. In der Felswand daneben ist",
  [40837] = "eine kleine Metallplatte eingelassen. Auf ihr",
  [40838] = "befindet sich ein roter Zugriegel.*",
  [40839] = "An dem Zugriegel ist nichts besonderes zu",
  [40840] = "vermerken. Er sieht so aus wie der Griff einer",
  [40841] = "Notbremse.*",
  [40842] = "Boooooooaaaanggggg.......",
  [40843] = "Ein gewaltiger Gong erschallt. Noch für Minuten",
  [40844] = "dröhnt das Metall... dann werden Schritte hörbar -",
  [40845] = "mächtige Schritte!",
  [40846] = "Um Himmels Willen, was ist das? Ein Mann, ein ganz",
  [40847] = "normaler Mann, schwer mit Muskeln bepackt - er",
  [40848] = "trägt eine riesige Keule.... aber er ist fünf",
  [40849] = "Meter groß! Er kommt ruhig bis an das Gitter",
  [40850] = "heran, beugt sich hernieder, und grinst Sie",
  [40851] = "spöttisch an.*",
  [40852] = "\"Sieh an!\" sagt er höhnend. \"Wohl wieder mal ein",
  [40853] = "Abenteurerlein! Haha!\" Der Mann erhebt sich",
  [40854] = "wieder. \"Sieh mich an, Du Wicht!' fordert er Sie",
  [40855] = "auf. \"Ich bin Kathaura, der Wächter der Schwarzen",
  [40856] = "Stadt. Ich wache hier seit über viertausend",
  [40857] = "Jahren, und es ist noch keinem gelungen, dieses",
  [40858] = "Tor zu passieren! Es sollte mich wundern, wenn es",
  [40859] = "in den nächsten viertausend Jahren einer schafft.",
  [40860] = "Also geh lieber wieder nach Hause!\"",
  [40861] = "Damit wendet er sich ab, und stapft davon.*",
  [40862] = "Wieder ertönt der riesige Gong. Doch er ist noch",
  [40863] = "nicht verhallt, da steht Kathaura wieder vor",
  [40864] = "Ihnen. Abermals beugt er sich herab. \"Du bist",
  [40865] = "hartnäckig, was?\" sagt er nachdenklich. \"Aber wenn",
  [40866] = "Du unbedingt sterben willst, dann bitte! Du hast",
  [40867] = "jetzt zwei Möglichkeiten! Entweder Du läufst ganz",
  [40868] = "schnell wieder nach Hause, oder Du ziehst den",
  [40869] = "Riegel nocheinmal! Dann wird sich ganz langsam",
  [40870] = "diese Türe hier öffnen. Dabei hast Du dann die",
  [40871] = "Gelegenheit, ein letztes Gebet zu sprechen!\"*",
  [40872] = "Kathaura trägt nur einen Lendenschurz und hoch",
  [40873] = "geschnürte Sandalen - wie ein Gladiator aus dem",
  [40874] = "alten Rom. Er hat seine riesige Keule geschultert",
  [40875] = "und trottet jenseits des Gitters hin und her. Ab",
  [40876] = "und zu schenkt er ihnen ein nicht unfreundliches,",
  [40877] = "aber doch sehr überlegenes und mitleidiges",
  [40878] = "Lächeln.*",
  [40879] = "\"Langweile mich nicht mit Deinem Geschwätz,\" sagt",
  [40880] = "Kathaura ärgerlich. \"Komm zur Sache, oder geh nach",
  [40881] = "Haus, okay?\"*",
  [40882] = "Kathaura richtet sich auf, nimmt seine Keule in",
  [40883] = "beide Hände, und geht in Angriffs-Stellung.*",
  [40884] = "Unendlich langsam öffnet sich das Tor zur",
  [40885] = "Schwarzen Stadt.*",
  [40886] = "Das Tor ist offen. Kathaura springt schnell wie",
  [40887] = "ein Panther heraus, seine Keule saust herab...",
  [40888] = "Bong.*",
  [40889] = "Das große Gitter in Kathauras Wache ist offen. Nur",
  [40890] = "ein knapper Vorsprung trennt Sie von Kathaura, der",
  [40891] = "eben den Durchgang passiert, und Ihnen in die",
  [40892] = "Schleuse folgt. Da kommt er schon durch das",
  [40893] = "Stahltor herein!*",
  [40894] = "Kathaura schenkt der Umgebung keinen einzigen",
  [40895] = "Blick - seine Aufmerksamkeit gehört ganz Ihnen!",
  [40896] = "Keine Sekunde später ist der Riese über Ihnen.",
  [40897] = "Seine Keule saust herab...",
  [40898] = "Bong.*",
  [40899] = "Oh, oh! Das hilft doch nichts! Das Gitter ist ja",
  [40900] = "offen! Wenige Augenblicke später schon hat",
  [40901] = "Kathaura Sie erreicht. Und dann saust seine",
  [40902] = "riesige Keule herab....",
  [40903] = "Bong.*",
  [40904] = "Uuuiii! Das war knapp! Kaum sind Sie durch die",
  [40905] = "Gitterstäbe geschlüpft, saust Kathauras Keule",
  [40906] = "hinter Ihnen auf den Stahlboden der Schleuse...",
  [40907] = "Rrrrummmmsss!",
  [40908] = "Er richtet sich langsam wieder auf. \"Was soll das",
  [40909] = "nun wieder, Du Narr?\" sagt er ärgerlich. \"Nun hast",
  [40910] = "Du Dich selber eingesperrt! Ich werde Dich ganz",
  [40911] = "leicht da herausholen!\" Kathaura wendet sich zur",
  [40912] = "Steuereinheit, und drückt den Knopf.",
  [40913] = "Das Gitter beginnt sich rasselnd zu öffen.*",
  [40914] = "Zu spät! Kathaura ist schon unter dem Gitter",
  [40915] = "hindurchgeschlüpft! Und dann kommt er auf Sie zu,",
  [40916] = "holt mit seiner riesigen Keule aus, und...",
  [40917] = "Bong.*",
  [40918] = "Uuuiii! Das war knapp! Kaum sind Sie durch die",
  [40919] = "Gitterstäbe geschlüpft, saust Kathauras Keule",
  [40920] = "hinter Ihnen auf den Stahlboden... Rrrrummmmsss!",
  [40921] = "Er stößt einen Fluch aus, als er das kaputte Kabel",
  [40922] = "der Steuereinheit sieht. \"Wart nur, ich krieg Dich",
  [40923] = "schon noch!\" ruft er. Damit dreht er sich um,",
  [40924] = "läuft rasch zur Schleuse hinaus, und drückt auf",
  [40925] = "der Steuereinheit 1 den Knopf. Im nächsten Moment",
  [40926] = "beginnt sich das Gitter zu öffnen. Kathaura kommt",
  [40927] = "wieder herein.*",
  [40928] = "Es ertönt ein lautes Knirschen, dann dreht sich",
  [40929] = "die Bewegungsrichtung des Gitters um, und es",
  [40930] = "schließt sich wieder. Kathaura kommt daher, da ist",
  [40931] = "das Gitter aber schon wieder zu. Er stößt einen",
  [40932] = "Fluch aus. \"Mistkerl!\" ruft er, und läuft wieder",
  [40933] = "hinaus. Abermals drückt er den Knopf auf Einheit",
  [40934] = "1, und rennt schnell zurück in die Schleuse.*",
  [40935] = "Wieder knirscht es, und das Gitter beginnt sich zu",
  [40936] = "schließen. Auch diesmal kommt Kathaura zu spät. Er",
  [40937] = "flucht saftig, als er erkennt, daß er Ihnen so",
  [40938] = "nicht beikommt. \"Wart nur!\" sagt er zornig, \"ich",
  [40939] = "erwische Dich schon noch!\"",
  [40940] = "Dann marschiert er wieder hinaus, um sich in",
  [40941] = "seiner Wache zu überlegen, wie er an sie",
  [40942] = "'rankommen könnte.*",
  [40943] = "Freude überstrahlt Kathauras Gesicht, als sich das",
  [40944] = "Gitter nach oben schiebt. Er kommt munter",
  [40945] = "hereinspaziert, wirft ihnen ein dankbares",
  [40946] = "Kußhändchen zu, und gleich anschließend kommt",
  [40947] = "seine Keule hinterher...",
  [40948] = "Bong.*",
  [40949] = "Uuuiii! Das war knapp! Kaum sind Sie durch die",
  [40950] = "Gitterstäbe geschlüpft, saust Kathauras Keule",
  [40951] = "hinter Ihnen auf den Stahlboden der Schleuse...",
  [40952] = "Rrrrummmmsss!",
  [40953] = "Als er das kaputte Kabel der Steuereinheit sieht,",
  [40954] = "stößt er einen derben Fluch aus. Und dann fällt",
  [40955] = "ihm auch das Kabel der Einheit 1 ein, das Sie",
  [40956] = "sabotiert haben. \"Wart nur, ich krieg Dich schon",
  [40957] = "noch!\" brüllt er, und rüttelt wütend am Gitter.*",
  [40958] = "Kathaura geht nachdenklich vor dem Gitter auf und",
  [40959] = "ab, und überlegt sich, wie er an Sie 'rankommen",
  [40960] = "könnte.*",
  [40961] = "Kathaura marschiert wieder hinaus, um sich in",
  [40962] = "seiner Wache weiter zu überlegen, wie er an Sie",
  [40963] = "'rankommen könnte.*",
  [40964] = "Oh! Sie wollen Kathaura... Du lieber Himmel, sind",
  [40965] = "Sie grob! Naja, schließlich würde er Sie auch",
  [40966] = "nicht mit dem Leben davonkommen lassen...",
  [40967] = "Ach herrje! Kaum haben Sie den Regler gedreht -",
  [40968] = "wird der Causus Knacksus offenbar! Das Wasser",
  [40969] = "strömt durch das offene Stahltor aus der",
  [40970] = "Schleuse... kurz darauf ertönt der trockene Knall",
  [40971] = "eines gigantischen Kurzschlusses, und... oh nein -",
  [40972] = "Sie stehen doch im Wasssssszzzzzz.....*",
  [40973] = "Rummss!",
  [40974] = "Das Stahltor draußen in der Schleuse knallt zu!",
  [40975] = "Kathaura ist eingesperrt!*",
  [40976] = "Oh! Sie wollen Kathaura... Du lieber Himmel, sind",
  [40977] = "Sie grob! Naja, schließlich würde er Sie auch",
  [40978] = "nicht mit dem Leben davonkommen lassen...",
  [40979] = "Ach herrje! Kaum haben Sie den Regler gedreht -",
  [40980] = "wird der Causus Knacksus offenbar! Das Wasser",
  [40981] = "steigt, und mit ihm taucht der schreckliche Bool",
  [40982] = "hinter Ihnen aus dem Waaaaaahhhhh.....*",
  [40983] = "Oh! Sie wollen Kathaura... Du lieber Himmel, sind",
  [40984] = "Sie grob! Naja, schließlich würde er Sie auch",
  [40985] = "nicht mit dem Leben davonkommen lassen...",
  [40986] = "Also, dann....",
  [40987] = "Sekunden später strömt das Wasser in die Schleuse",
  [40988] = "hinein... Kathaura stöhnt entsetzt auf.... der",
  [40989] = "Schreckliche Bool regt sich, kommt langsam",
  [40990] = "frei...",
  [40991] = "(Also, wir blenden uns hier lieber vorübergehend",
  [40992] = "aus! Sie sind doch einverstanden, oder? Dies ist",
  [40993] = "schließlich kein Rambo-Film!)*",
  [40994] = "(...)",
  [40995] = "Während das Wasser einströmt, ertönen heftige",
  [40996] = "Geräusche aus der Schleuse...",
  [40997] = "Dann herrscht Stille! Der Spuk ist vorbei, und es",
  [40998] = "sieht so aus, als wären Sie der letztendliche",
  [40999] = "Gewinner!*",
  [41000] = "Erstaunlich! Kein Kathaura und kein Bool sind hier",
  [41001] = "mehr zu sehen! Wir wollen hoffen, daß die",
  [41002] = "beiden... oh. Da liegt eine kleine Plakette auf",
  [41003] = "dem Boden der Schleuse! Die gehört aber nicht",
  [41004] = "hierher!*",
  [41005] = "(Also, das ist eine Information, die eigentlich",
  [41006] = "nicht ins Spiel gehört. Aber damit Sie nicht",
  [41007] = "denken, wir wollten Gewalt verherrlichen, sagen",
  [41008] = "wir's Ihnen doch:",
  [41009] = "Es ist eine Kaffee-Marke aus der Weltenschmiede-",
  [41010] = "Kantine. Dort nämlich sitzen jetzt Kathaura und",
  [41011] = "Bool jetzt gutgelaunt bei Kaffee und Kuchen, und",
  [41012] = "verbreiten sich großartig darüber, wie sie Sie",
  [41013] = "beinah drangekriegt hätten!)*",
  [41014] = "Sie sind am Ziel Ihrer Reise angelangt! Damit",
  [41015] = "haben Sie etwas geschafft, was noch keinem vor",
  [41016] = "Ihnen gelungen ist! Bei allen Späßen, die wir uns",
  [41017] = "bisher mit Ihnen erlaubt haben: Bravo!*",
  [41018] = "Auf dem Schwarzen Weg",
  [41019] = "Dies ist der Gipfelgrat eines riesigen Berges. Der",
  [41020] = "Himmel ist dunkel; Regen störmt unaufhörlich",
  [41021] = "herab. Vor Ihnen führt ein schmaler Weg nordwärts,",
  [41022] = "links und rechts davon geht es nur hinab in",
  [41023] = "bodenlose Tiefen. Ein kleines Stück südlich führt",
  [41024] = "ein Gang zurück zu Kathauras Wache. Direkt östlich",
  [41025] = "von hier befindet sich eine große Holztür in",
  [41026] = "letzten Stück der Felswand.*",
  [41027] = "Hier steht ein riesiger Stuhl.*",
  [41028] = "Der Gipfelgrat, auf dem der Schwarze Weg verläuft,",
  [41029] = "strebt in nicht allzu steilem Winkel Richtung",
  [41030] = "Norden - bis hin zum Tor der Schwarzen Stadt!*",
  [41031] = "Der Regen ist warm - so wie es auch ungewöhnlich",
  [41032] = "schwül und windstill an diesem Ort ist.*",
  [41033] = "Manchmal, wenn die Sturzbäche des Regens",
  [41034] = "nachlassen, wird nördlich von hier, auf dem Gipfel",
  [41035] = "des Berges, die SCHWARZE STADT sichtbar! Es ist",
  [41036] = "eine gigantische, schwarze Festung mit himmelhohen",
  [41037] = "Mauern, Zinnen und Türmen, die direkt auf der",
  [41038] = "Spitze des Berges steht - ihre Mauern verschmelzen",
  [41039] = "mit den schwarzen Felswänden, die beinahe",
  [41040] = "senkrecht hinab ins Bodenlose führen. Blitze",
  [41041] = "zucken von Zeit zu Zeit herab - die Schwarze Stadt",
  [41042] = "liegt schweigend und unergründlich vor Ihnen.*",
  [41043] = "Die Mauern, Zinnen und Türme dieser riesigen",
  [41044] = "Festung bestehen aus tiefschwarzem, glatten",
  [41045] = "Felsen, der unheimlich in den Sturzbächen des",
  [41046] = "Regens, der daran herabrinnt, schimmert.*",
  [41047] = "Die Tür ist riesig groß, mindestens sechs Meter",
  [41048] = "hoch. In einer Höhe von drei Metern befindet sich",
  [41049] = "eine Türklinke - eine ziemlich große.*",
  [41050] = "Die Türklinke liegt zu hoch, da kommen Sie nicht",
  [41051] = "dran!*",
  [41052] = "Ah, Ihr Phantasie hat noch nicht nachgelassen!",
  [41053] = "Fein - die werden Sie bald auch in voller Stärke",
  [41054] = "benötigen. So - dann... Klick!",
  [41055] = "Prima, es hat geklappt, die riesige Tür schwingt",
  [41056] = "langsam knarrend auf, und gibt einen Zugang in",
  [41057] = "einen hellerleuchteten Raum nach Osten frei.*",
  [41058] = "Kathauras Wohnung",
  [41059] = "Sie befinden sich im spartanischen Domizil des",
  [41060] = "verblichenen Riesen. Der Raum ist quadratisch und",
  [41061] = "recht groß - jedenfalls für Ihre Maßstäbe. Eine",
  [41062] = "Matraze - zwei mal fünf Meter groß - liegt in",
  [41063] = "einer Ecke. Hoch droben an der Wand hängt in",
  [41064] = "einem Bilderrahmen ein eingerahmter Spruch.*",
  [41065] = " *",
  [41066] = "Da steht... ähem: \"Die Stadt is schwarz, un ich",
  [41067] = "bin weiß, Khalin sieht mich immer, so'n Scheiß!\"*",
  [41068] = "Die Sitzfläche des Stuhles liegt in gut einem",
  [41069] = "Meter fünfzig Höhe. Die Lehne ist nochmal einen",
  [41070] = "Meter höher. Das ganze Ding ist reichlich riesig.*",
  [41071] = "Ha! Sie sind gut! Dieser Stuhl könnte allenfalls",
  [41072] = "SIE nehmen, nur ist er zum Glück nicht lebendig!*",
  [41073] = "Sie wollen ihn verschieben? Nun... naja, das",
  [41074] = "könnte vielleicht klappen. Aber geben Sie bitte",
  [41075] = "an, wohin Sie ihn schieben wollen. (z.B. >schiebe",
  [41076] = "den Stuhl nach Osten)*",
  [41077] = "Na, dann in die Hände gespuckt... uuuund...",
  [41078] = "Hauruck!",
  [41079] = "Krrrrkkkk. Na bitte! Der Stuhl wiegt wohl zwei",
  [41080] = "Zentner, aber es klappt doch!*",
  [41081] = "Auf Kathauras Stuhl",
  [41082] = "Nun, Sie befinden sich nun in luftigen eineinhalb",
  [41083] = "Metern Höhe. Die Aussicht von hier ist aber auch",
  [41084] = "nicht sehr viel ergiebiger.*",
  [41085] = "Auf der Lehne",
  [41086] = "Uiuiui! Passen Sie auf, daß Sie da nicht",
  [41087] = "'runterfallen... Wir müssen Ihnen leider",
  [41088] = "mitteilen, daß wir Ihnen, trotz dieses",
  [41089] = "Kunststückes, auch nicht weiterhelfen können.",
  [41090] = "Leider haben wir keinerlei Verbindungen in die",
  [41091] = "Zirkus- oder Akrobaten-Branche.*",
  [41092] = "Auf der Lehne",
  [41093] = "Gut, Sie stehen nun auf der Lehne. Wahrscheinlich",
  [41094] = "wollen Sie ja an eine dieser Fackeln kommen, nicht",
  [41095] = "wahr? Das geht zwar, aber die Dinger sind leider",
  [41096] = "so riesig, daß nicht daran zu denken ist, eine",
  [41097] = "davon herunterzuholen. Steigen Sie lieber wieder",
  [41098] = "'runter. Sie machen sich nur furchtbar dreckig.",
  [41099] = "Die Wände sind voll von Ruß.*",
  [41100] = "Was soll daran schon besonderes sein? Es handelt",
  [41101] = "sich um fettigen, schwarzen Ruß der übelsten",
  [41102] = "Sorte, von den Fackeln in Kathauras Wache",
  [41103] = "stammend.*",
  [41104] = "Puuh! Sie haben vielleicht Ideen! Nagut - nehmen",
  [41105] = "wir eine Handvoll davon. Was wollen Sie damit tun?",
  [41106] = "Wollen Sie sich etwa schminken?*",
  [41107] = "Na, wie auch immer. Ihren Ruß haben Sie ja jetzt.*",
  [41108] = "Wie...?",
  [41109] = "Aaaah - jetzt ist der Groschen gefallen!",
  [41110] = "Vielleicht gar keine schlechte Idee. Tarnung, wie?",
  [41111] = "Gut, dann beginnen wir mal das heikle Werk...",
  [41112] = "leider wird auch Ihre Kleidung dran glauben",
  [41113] = "müssen... ihr hübsch buntes Hemd... und Ihre helle",
  [41114] = "Hose...",
  [41115] = "... fein. Sie sind nun so schwarz wie ein Neger",
  [41116] = "bei Nacht in einem Eisenbahntunnel. Bravo!*",
  [41117] = "Auf dem Gipfelgrat",
  [41118] = "Es ist klar, warum dieser Pfad \"Schwarzer Weg\"",
  [41119] = "genannt wird: er ist aus glattem, tiefschwarzen",
  [41120] = "Felsen gehauen, und führt schmal und gefährlich",
  [41121] = "über einen Abgrund, dessen ungeheure Tiefe nicht",
  [41122] = "abzuschätzen ist. Der Regen strömt unaufhörlich",
  [41123] = "herab. Immer wieder zucken Blitze vom finsteren",
  [41124] = "Himmel herab, und tauchen die Schwarze Stadt, die",
  [41125] = "sich unmittelbar vor Ihnen auf dem Gipfel des",
  [41126] = "Berges erhebt, in gespenstisches Licht.*",
  [41127] = "Nördlich von Ihnen, in beunruhigender Nähe, türmen",
  [41128] = "sich die Mauern und Zinnen der Schwarzen Stadt in",
  [41129] = "den Himmel. Dort, an der südlichen Ecke der",
  [41130] = "Festungsmauer, endet der Schwarze Weg. Und dort",
  [41131] = "ist auch der Eingang zur Festung: ein",
  [41132] = "sechseckiges, schwarzes Tor, das von einer",
  [41133] = "monumentalen Felsenplatte verschlossen ist.*",
  [41134] = "Symbolträchtig wurde diesem Tor einst die",
  [41135] = "sechseckige Form gegeben. Es ist von einer",
  [41136] = "monumentalen, schwarzen und glatten Felsenplatte",
  [41137] = "verschlossen.*",
  [41138] = "An der Festungsmauer",
  [41139] = "Vor Ihnen erhebt sich der enorme, sechseckige",
  [41140] = "Eingang zur Schwarzen Stadt. Eine riesige",
  [41141] = "Felsenplatte verschließt den Eingang in der Art",
  [41142] = "einer gigantischen Tresortüre. In Augenhöhe jedoch",
  [41143] = "befindet sich ein kleines Fenster, daneben ist ein",
  [41144] = "schwarzer Knopf eingelassen.*",
  [41145] = "Die Mauer muß über hundert Meter hoch sein, sie",
  [41146] = "schimmert matt wie geschliffener, schwarzer",
  [41147] = "Marmor. Sturzbäche von Regen rinnen an ihr herab.*",
  [41148] = "Der Eingang ist sechseckig und gute zwanzig Meter",
  [41149] = "hoch. Er wird von einer riesigen, schwarzen",
  [41150] = "Felsenplatte verschlossen.*",
  [41151] = "Nunja... hm, eigentlich sieht er wie ein ganz",
  [41152] = "banaler... Klingelknopf aus!*",
  [41153] = "Da ist nur ein kleiner, aber nicht minder",
  [41154] = "beeindruckender Teil vom Inneren der Festung zu",
  [41155] = "sehen. Der Blick führt geradeaus auf einen großen",
  [41156] = "Platz in der Mitte der Festung. Dort steht ein",
  [41157] = "weißer, steinerner Pavillion, und unter seinem",
  [41158] = "Dach ein Tisch und eine Bank. Auf ihr sitzt das",
  [41159] = "wohl beeindruckenste Wesen, das jemals ein Mensch",
  [41160] = "erblickt hat!*",
  [41161] = "Vergessen Sie alles, was Sie jemals über schöne",
  [41162] = "Frauen gehört haben, denn hier ist Khalin, die",
  [41163] = "Göttin der Rache, und Anwärterin auf sämtliche",
  [41164] = "Schönheitspreise des Universums!",
  [41165] = "Sie ist zwanzig Meter hoch, und muß wohl um die",
  [41166] = "zweihundert Tonnen wiegen. Wenn sie schlank wäre,",
  [41167] = "dann würden bestimmt Dreiviertel ihres Gewichtes",
  [41168] = "wegfallen. Ihr Bauch wölbt sich gigantisch, unter",
  [41169] = "ihren Brüsten, so groß wie aufgeblähte",
  [41170] = "Fallschirme, könnte sich wohl eine ganze Kompanie",
  [41171] = "vor dem Regen schützen.*",
  [41172] = "Sie hat Arme in der Dicke von transkoninentalen",
  [41173] = "Pipelines und mit den Füßen könnte Sie wohl einen",
  [41174] = "Ochsen wie Ungeziefer zertreten. Ihr Antlitz",
  [41175] = "jedoch ist der Gipfel allen Liebreizes: narbige",
  [41176] = "Wangen, fettige Runzeln, verfaulte Zähne und ein",
  [41177] = "Haarschopf vom Duft und der Fülle eines",
  [41178] = "Komposthaufens. Sie trägt ein grellbuntes",
  [41179] = "Freizeitkleid Marke \"Wühltisch-Sonderangebote\".*",
  [41180] = "Auf ihrer Nase sitzt eine kleine, häßliche",
  [41181] = "Brille.*",
  [41182] = "Sie liest in einer Zeitschrift: \"Die Dame von",
  [41183] = "Welt\".*",
  [41184] = "Der Regen prasselt herab; wieder schlägt irgendwo",
  [41185] = "ein Blitz ein und drohender Donner rollt über Sie",
  [41186] = "hinweg.*",
  [41187] = "Es ertönt... nun, kein gewaltiger chinesischer",
  [41188] = "Gong, und auch keine drei Meter durchmessende",
  [41189] = "Bronzeglocke, sondern eine Art Gebimmel, das",
  [41190] = "peinlich an einen Küchenwecker erinnert.",
  [41191] = "Durch das kleine Fenster kann man sehen, wie",
  [41192] = "Khalin, die in einem kleinen weißen Pavillion",
  [41193] = "sitzt, hochzuckt, die Augen hinter ihrer Brille",
  [41194] = "zusammenkneift und in Richtung des Tores peilt.",
  [41195] = "\"Ei, da isser ja schon!\" summt sie im",
  [41196] = "Selbstgespräch, erhebt sich, und stampft auf das",
  [41197] = "Festungstor zu.*",
  [41198] = "Das große, sechseckige Tor schwingt auf. Khalin,",
  [41199] = "groß, vollschlank und schön, steht vor Ihnen.",
  [41200] = "\"Hallöchen!\" flötet Sie, und winkt Ihnen keck mit",
  [41201] = "den Fingerspitzen zu.*",
  [41202] = "\"Huch, Du bist ja ganz schwarz!\" Sie blickt Sie",
  [41203] = "vorwurfsvoll und kopfschüttelnd an.*",
  [41204] = "\"Meine Güte, seit Tausenden von Jahren warte ich",
  [41205] = "schon! Aber Du kommst genau im rechten Moment, der",
  [41206] = "Tee wird bald fertig sein! Komm herein, mein",
  [41207] = "kleiner Held!\"*",
  [41208] = "\"Endlich bist Du wieder da!\" sagt Khalin",
  [41209] = "erleichtert. \"Fein. Komm herein. Der Tee ist",
  [41210] = "gleich fertig!\"*",
  [41211] = "\"Was, Du gehst schon wieder?\" ruft Ihnen Khalin",
  [41212] = "überrascht hinterher. \"Ach ja, ich weiß, Du hast",
  [41213] = "etwas vergessen! Also, bis gleich!\"",
  [41214] = "Rummmms! Das Tor der Festung ist wieder zu.*",
  [41215] = "Am Festungstor",
  [41216] = "Hier liegt, Richtung Süden, das große, sechseckige",
  [41217] = "Tor der Schwarzen Stadt. Nach Norden führt eine",
  [41218] = "breite Straße in die Mitte der Festung - nach",
  [41219] = "Westen hin liegt eine kleine Straße, die zwischen",
  [41220] = "den riesigen, schwarzen Türmen hindurchführt.",
  [41221] = "Weiterhin regnet es in Strömen.*",
  [41222] = "Das große Tor zur Festung donnert wieder zu.",
  [41223] = "Khalin stampft Ihnen hinterher, und bleibt dann",
  [41224] = "neben Ihnen stehen. \"Hübsch hier, nicht wahr?\"",
  [41225] = "tiriliert sie, und deutet stolz auf die Bauwerke",
  [41226] = "der Schwarzen Stadt. \"Hab' ich alles",
  [41227] = "selbergebaut!\"*",
  [41228] = "Das Tor der Festung ist über zwanzig Meter hoch,",
  [41229] = "und besitzt eine sechseckige Form. Es ist von",
  [41230] = "einer massiven, schwarzschimmernden Felsenplatte",
  [41231] = "verschlossen.*",
  [41232] = "Hm - da haben Sie wohl schlechte Karten! Nirgends",
  [41233] = "scheint es hier etwas zu geben. mit dem man das",
  [41234] = "Tor öffnen könnte!*",
  [41235] = "Das Innere der Festung ist wahrhaft erstaunlich.",
  [41236] = "Innerhalb der hohen Mauern stehen riesige Türme -",
  [41237] = "es müssen über 200 sein. Sie sind vollkommen",
  [41238] = "schwarz: die Türme, die Gebäude und die Mauern -",
  [41239] = "nur das Pflaster der Straßen und Plätze ist grau.",
  [41240] = "Die Stadt wirkt phantastisch und unwirklich - und",
  [41241] = "doch ist sie vorhanden. Innerhalb der titanischen",
  [41242] = "Mauern, die ein riesiges Sechseck bilden, führen",
  [41243] = "unzählige Wege und Straßen in jede erdenkliche",
  [41244] = "Richtung - das muß ein perfektes Labyrinth sein.*",
  [41245] = "Die Türme streben hoch hinauf - jeder von Ihnen",
  [41246] = "ist mindestens zweihundert Meter hoch. Sie stehen",
  [41247] = "noch enger beieinander, als die Wolkenkratzer",
  [41248] = "einer amerikanischen Großstadt. Sie besitzen",
  [41249] = "Erker, Fenster, Zinnen, Dächer und Giebel in",
  [41250] = "unendlich großer Zahl. Jede Einzelheit an ihnen",
  [41251] = "ist tiefschwarz, so wie die ganze Stadt.*",
  [41252] = "Es mutet phantastisch an, wie diese Türme gebaut",
  [41253] = "sind - man könnte fast meinen, man befinde sich in",
  [41254] = "einem Abenteuer von Weltenschmiede!*",
  [41255] = "Die Mauern, die die Schwarze Stadt in einer",
  [41256] = "Sechseckform umgeben, sind fünfzig oder sechzig",
  [41257] = "Meter hoch, und bestehen aus schwarzem Stein.*",
  [41258] = "Die Straßen und Wege führen kreuz und quer",
  [41259] = "zwischen den Türmen und Gebäuden hindurch - es",
  [41260] = "sind unzählig viele, und man muß Angst haben, sich",
  [41261] = "hoffnungslos zu verirren, wenn man sie betritt.",
  [41262] = "Die einzige Orientierung, die es hier gibt, sind",
  [41263] = "die zwei breiten Straßen, die von Nord nach Süd,",
  [41264] = "und von Ost nach West durch die ganze Stadt",
  [41265] = "laufen, und sich in der Mitte kreuzen - dort, wo",
  [41266] = "der zentrale Platz der Schwarzen Stadt liegt.*",
  [41267] = "Überall gibt es Plätze, groß und klein, auf denen",
  [41268] = "seltsame Denkmäler stehen: Medusen, Minotauren",
  [41269] = "Gorgonenhäupter, Sartyre, Harpyien und ähnliche",
  [41270] = "Fabelwesen aus der Mythologie.*",
  [41271] = "Ach, da gäbe es viel zu erzählen. Aber leider ist",
  [41272] = "hier kein Platz dafür. Wir müssen Sie leider an",
  [41273] = "ihr Lexikon verweisen.*",
  [41274] = "Das Pflaster der Straßen und Plätze sind",
  [41275] = "dunkelgrau, zum Glück - sonst könnte man sich hier",
  [41276] = "gar nicht mehr orientieren!*",
  [41277] = "\"Komm, der Tee wird bald soweit sein,\" sagt",
  [41278] = "Khalin freundlich, und schubst Sie sanft Richtung",
  [41279] = "Norden, hin zu dem Platz in der Mitte der",
  [41280] = "Schwarzen Stadt, wo ein kleiner, weißer Pavillion",
  [41281] = "steht.*",
  [41282] = "\"Ja, genau!\" sagt Khalin und hebt einen",
  [41283] = "Zeigefinger, der an einen Telefonmasten erinnert.",
  [41284] = "\"Wir wollten ja Tee trinken!\" Khalin führt Sie mit",
  [41285] = "tänzelnden Schritten zu dem Platz, der sich in der",
  [41286] = "Mitte der Festung befindet, und an dem ein",
  [41287] = "kleiner, weißer Pavillion steht. Sie scheint",
  [41288] = "bestens gelaunt zu sein.*",
  [41289] = "\"Kal? Och, der schläft tief und fest, in seinem",
  [41290] = "Tempel. Hast ja schon davon gehört, nicht?\"*",
  [41291] = "\"Nun, der Tempel liegt hier unterhalb der",
  [41292] = "Schwarzen Stadt. Er ist ja verkehrtherum in die",
  [41293] = "Erde hineingebaut, wie Du sicher weißt. Aber der",
  [41294] = "Zugang - nun, den kenne nur ich!\"*",
  [41295] = "Khalin lacht und droht ihnen neckisch mit dem",
  [41296] = "Zeigefinger. \"Na, na! Du wirst doch wohl nicht zu",
  [41297] = "ihm wollen, oder? Das ist nichts für solche",
  [41298] = "kleinen Burschen wie Dich! Erstens würde ich Dich",
  [41299] = "gar nicht hinlassen, denn ich bewache ihn ja, und",
  [41300] = "zweitens könntest Du den Zugang gar nicht finden,",
  [41301] = "denn er liegt hier irgendwo in diesem Labyrinth",
  [41302] = "versteckt! Das hat noch keiner geschafft. Haha!\"*",
  [41303] = "\"Tja,\" sagt sie, und deutet stolz in die Runde.",
  [41304] = "\"Das hab ich alles selber gebaut. Hübsch, nicht?",
  [41305] = "Hier irgendwo, in diesem Labyrinth, liegt der",
  [41306] = "Zugang zu Kal's unterirdischem Tempel - aber den",
  [41307] = "könnte nur ich finden. Ich war zwar selber lange",
  [41308] = "nicht mehr unten - aber ich denke, ich ich würde",
  [41309] = "es noch schaffen ihn zu öffnen!\"*",
  [41310] = "\"Schau Dich nur um!\" sagt Khalin stolz. \"Aber nur",
  [41311] = "von hier. Geh nicht weg - Du würdest Dich",
  [41312] = "hoffnunglos verirren. Hab ich alles selber gebaut.",
  [41313] = "Hauptsächlich zu dem Zweck, daß niemand den Zugang",
  [41314] = "zu Kal's Tempel finden kann - der ist hier",
  [41315] = "irgendwo versteckt, hihi! Ich würde wohl selbst",
  [41316] = "eine Zeitlang brauchen, bis ich ihn öffnen",
  [41317] = "könnte!\"*",
  [41318] = "\"In dem Pavillion bin ich meistens,\" sagt Khalin.",
  [41319] = "\"Sozusagen mein Domizil. Ich dachte, es wäre",
  [41320] = "hübsch, wenn er weiß ist. Im Gegensatz zur Stadt.",
  [41321] = "Findest Du nicht?\"*",
  [41322] = "\"Darüber weiß ich entweder nichts, oder ich will",
  [41323] = "es Dir nicht sagen,\" sagt Khalin geheimnisvoll",
  [41324] = "lächelnd. \"Du darfst Dir eines davon aussuchen!\"*",
  [41325] = "Auf der südlichen Straße",
  [41326] = "Sie befinden sich auf halbem Weg zwischen dem",
  [41327] = "Festungstor und dem zentralen Platz. Um Sie herum",
  [41328] = "streben riesige Gebäude und Türme in den Himmel",
  [41329] = "auf - der nach wie vor seine Wasser über die",
  [41330] = "Schwarze Stadt ergießt. Nach Osten führt eine",
  [41331] = "schmalere Straße in das Labyrinth der Bauwerke",
  [41332] = "hinein.*",
  [41333] = "Am Großen Platz",
  [41334] = "Dieser Platz hat die Form eines Sechseckes und ist",
  [41335] = "von riesigen Türmen umgeben. Vier breite Straßen",
  [41336] = "führen nach Norden, Süden, Westen und Osten. Regen",
  [41337] = "plätschert herab.*",
  [41338] = "Im Zentrum des Platzes steht ein kleiner, offener",
  [41339] = "Pavillion, der im krassen Gegensatz zum Rest der",
  [41340] = "Stadt aus weißem Stein besteht.*",
  [41341] = "Im Zentrum des Platzes, dort, wo zuvor der kleine",
  [41342] = "weiße Pavillion stand, gähnt nun ein schwarzes",
  [41343] = "Loch im Boden.*",
  [41344] = "Das Loch führt hinab in finsterliche Tiefen... da",
  [41345] = "scheint es aber eine Wendeltreppe am Rand der",
  [41346] = "Loches zu geben! Hier muß der Zugang zum Tempel",
  [41347] = "des Kal liegen. Sie haben es geschafft!*",
  [41348] = "Auch dieser Pavillion ist sechseckig. (Uff!) Der",
  [41349] = "große Unterschied zum Rest der Schwarzen Stadt",
  [41350] = "besteht darin, daß er ganz aus weißem Stein",
  [41351] = "besteht. Nur der Boden ist ebenso dunkelgrau wie",
  [41352] = "die Straßen der Stadt. Er ist nach allen Seiten",
  [41353] = "offen, sein Dach wird von sechs Säulen getragen.",
  [41354] = "Das ganze Ding hat den unschätzbaren Vorteil, daß",
  [41355] = "es darunter trocken ist. Eine steinerne Bank und",
  [41356] = "ein großer Tisch stehen darin. *",
  [41357] = "Khalin führt Sie in den Pavillion hinein, und",
  [41358] = "plaziert ihre enorme Leibesmasse auf einer",
  [41359] = "riesigen, steinernen Bank. Dann hebt sie Sie",
  [41360] = "behutsam auf den Tisch hinauf, wo ein kleiner",
  [41361] = "(Ihrer Körpergröße angemessener) Stuhl steht.",
  [41362] = "Der versprochene Tee läßt noch auf sich warten -",
  [41363] = "er ist offernbar noch nicht fertig.*",
  [41364] = "Auf dem Tisch",
  [41365] = "Dieser riesige Tisch ist besteht aus ganz weißem",
  [41366] = "Stein. Bis hinunter zum Boden sind es gute sieben",
  [41367] = "Meter - bis zur Steinbank hingegen nur etwa drei.*",
  [41368] = "Khalin sitzt Ihnen gegenüber auf der Steinbank,",
  [41369] = "groß wie eine Sphinx, und lächelt Sie freundlich",
  [41370] = "an.*",
  [41371] = "Hier steht ein hölzerner Stuhl und eine Tasse",
  [41372] = "Tee.*",
  [41373] = "Hier steht ein hölzerner Stuhl.*",
  [41374] = "Hier steht eine Tasse.*",
  [41375] = "Es ist ein einfacher hölzerner Stuhl, recht",
  [41376] = "solide, aber sonst sehr gewöhnlich.*",
  [41377] = "Ein Seil ist an ihm festgebunden.*",
  [41378] = "Es handelt sich um eine hübsche kleine Tasse.*",
  [41379] = "Sie ist mit aromatisch duftendem Tee gefüllt.*",
  [41380] = "Hmmm - dieser Tee duftet so verführerisch -",
  [41381] = "aber... nun, irgendwie stinkt er auch! Um es genau",
  [41382] = "zu sagen: er stinkt nach Verrat! Wer weiß, was",
  [41383] = "passiert, wenn Sie dieses Gebräu trinken!*",
  [41384] = "Ah... der Tee schmeckt gut... so süß und warm...",
  [41385] = "pppfffff..... ohgott... da ist was drin...*",
  [41386] = "Die Steinbank ist so weiß wie alles hier im",
  [41387] = "Pavilion - außem dem dunkelgrauen Boden. Sie steht",
  [41388] = "direkt vor dem Tisch, und ist recht hoch - so an",
  [41389] = "die dreieinhalb Meter, könnte man sagen. Für eine",
  [41390] = "Riesin wie Khalin gerade die rechte Sitzhöhe.*",
  [41391] = "Die Oberkante der Brüstung liegt in guten sieben",
  [41392] = "Metern Höhe - und ist etwa genausoweit von hier",
  [41393] = "entfernt. Sie ist recht breit, man könnte leicht",
  [41394] = "einen Spaziergang darauf machen.*",
  [41395] = "Eine Brille liegt auf ihrer Kante - eine ziemlich",
  [41396] = "große Brille. Sie gehört Khalin.*",
  [41397] = "Die Brille ist eine Brille - zugegebenermaßen",
  [41398] = "etwas überdimensional - die Gläser sind beinahe so",
  [41399] = "groß wie Wagenräder.*",
  [41400] = "Die riesige Brille Khalins liegt - in tausend",
  [41401] = "Stücke zersprungen - am Boden. Oje, das wird Ärger",
  [41402] = "geben!*",
  [41403] = "\"So!\" sagt Khalin, und macht es sich gemütlich.",
  [41404] = "\"Noch ein paar Minuten, dann ist der Tee fertig.",
  [41405] = "Wir können uns ja solang ein bißchen",
  [41406] = "unterhalten.\"*",
  [41407] = "\"Nun, wie war Deine Reise? Du hast es nicht immer",
  [41408] = "leicht gehabt, sagte man mir! Haha. Na, Du hast es",
  [41409] = "ja geschafft... was schaust Du mich so an?\"",
  [41410] = "Khalin wirkt irritiert. Dann nimmt Sie ihre",
  [41411] = "kleine, häßliche Brille ab, legt sie auf die",
  [41412] = "Brüstung des Pavillions, und lächelt. \"Jaja, ich",
  [41413] = "weiß, die Brille ist ziemlich häßlich. Aber es ist",
  [41414] = "meine letzte, und ohne sie sehe ich fast nichts.",
  [41415] = "Also: hast Du das Auge des Kal gefunden?\"*",
  [41416] = "Khalin lächelt und winkt ab. \"Ha, Du willst mich",
  [41417] = "verkohlen - freilich hast Du das Auge komplett!",
  [41418] = "Dann gib es mir nun, ich werde es Kal bringen. Und",
  [41419] = "Du erhältst eine reiche Belohnung!\" Sie nickt",
  [41420] = "Ihnen aufmunternd zu.*",
  [41421] = "Khalin lächelt. \"Das ist fein! Dann gib es mir",
  [41422] = "nun, ich werde es Kal bringen. Und Du erhältst",
  [41423] = "eine reiche Belohnung!\" Sie nickt Ihnen",
  [41424] = "aufmunternd zu.*",
  [41425] = "\"Willst Du meine Frage nicht beantworten?\" fragt",
  [41426] = "Khalin tadelnd. \"Hast Du das Auge des Kal komplett",
  [41427] = "zusammengetragen?\"*",
  [41428] = "\"Du möchtest es mir nicht geben?\" fragt sie",
  [41429] = "erstaunt. \"Ach ja... Du willst sicher wissen, was",
  [41430] = "es für eine Belohnung ist, nicht wahr? Warte hier",
  [41431] = "einen Moment. Ich komme gleich wieder.\"",
  [41432] = "Sie erhebt sich und hebt lächelnd den Zeigefinger.",
  [41433] = "\"Aber lauf' mir nicht weg, hörst Du?\"",
  [41434] = "Dann dreht sie sich um und stampft davon.*",
  [41435] = "\"Ah!\" sagt Khalin hocherfreut, und nimmt das Auge",
  [41436] = "entgegen. Sie bewundert es, während sie es in die",
  [41437] = "Höhe hält. Dann wendet Sie sich Ihnen wieder zu.",
  [41438] = "\"So. Und hier ist nun Deine Belohnung...!\"",
  [41439] = "Im nächsten Augenblick saust eine Hand auf Sie",
  [41440] = "herab, so groß wie ein Scheunentor....",
  [41441] = "Klatsch!*",
  [41442] = "Herrje! Sie wollen bis hinab auf den Boden",
  [41443] = "springen? Das sind ja mindestens sieben Meter! Sie",
  [41444] = "würden sich mindestens ein Bein brechen - und das",
  [41445] = "jetzt! Wollen Sie das wirklich tun?*",
  [41446] = "Wir haben Sie gewarnt! Also, hopp.....Kracks!*",
  [41447] = "Das ist wohl auch besser so. Vielleicht gibt es",
  [41448] = "einen anderen Weg.*",
  [41449] = "Ah! Das könnte klappen! Also vorsichtig...",
  [41450] = "Huuiiii..... Tock!",
  [41451] = "Glück gehabt. Sie sind sicher gelandet!*",
  [41452] = "Ah! Sie wollen die Brille zerstören? Na, ob Ihr",
  [41453] = "Wurfgeschoß diesem riesigen Ding etwas anhaben",
  [41454] = "kann? Wohl kaum. Probieren Sie es lieber mit etwas",
  [41455] = "anderem!*",
  [41456] = "Hm. Der Stuhl könnte - wenn Sie treffen - die",
  [41457] = "Brille hinab auf den Boden stürzen lassen. Wollen",
  [41458] = "Sie?*",
  [41459] = "Also los... kräftig ausholen, und",
  [41460] = "..... huuuiiiii. Rumms!",
  [41461] = "Ach, Mist. Das war knapp daneben. Aber knapp",
  [41462] = "daneben ist auch vorbei! Pech gehabt. Der Stuhl",
  [41463] = "purzelt nach unten, und knallt auf den Boden des",
  [41464] = "Pavillions.",
  [41465] = "Oh - dort kommt Khalin schon wieder...*",
  [41466] = "Gut. Meditieren Sie vorher noch ein bißchen.*",
  [41467] = "Gut. Das wird gehen. Mit Hilfe des Seiles haben",
  [41468] = "Sie so viele Versuche, wie Sie wollen!",
  [41469] = "Also los... kräftig ausholen, und",
  [41470] = "..... huuuiiiii. Rumms!",
  [41471] = "Mist. Das war knapp daneben. Also, dann ziehen wir",
  [41472] = "den Stuhl wieder her... gut. Nun können Sie",
  [41473] = "nochmal.*",
  [41474] = "Also, noch einmal.... hauruck.... Rumms!",
  [41475] = "Ha! Bravo! Volltreffer! Die Brille rutscht weg...",
  [41476] = "stürzt sieben Meter in die Tiefe... knallt auf den",
  [41477] = "Boden... und zerbirst in tausend Stücke!",
  [41478] = "Oh - das war höchste Zeit, denn dort hinten kommt",
  [41479] = "Khalin schon wieder...*",
  [41480] = "Khalin kehrt zurück.",
  [41481] = "\"So, da bin ich wieder!\" sagt sie, setzt sich, und",
  [41482] = "greift sich Ihre Brille.*",
  [41483] = "Khalin ist wieder da.",
  [41484] = "\"So, hier bin ich wieder!\" sagt sie, setzt sich,",
  [41485] = "und schaut Sie bedeutungsvoll an.",
  [41486] = "\"Ich habe Deine Belohnung dabei. Du kannst mir",
  [41487] = "jetzt das Auge geben!*",
  [41488] = "\"Nun, ich empfehle Dir,\" sagt Sie freundlich, \"mir",
  [41489] = "das Auge jetzt zu geben. \"Dann kann ich Dich für",
  [41490] = "Deine Dienste belohnen!\"*",
  [41491] = "\"Gut!\" sagt Sie. \"Dann muß ich es mir nehmen!\" Im",
  [41492] = "nächsten Augenblick saust ihre Hand herunter, so",
  [41493] = "groß wie ein Scheunentor...",
  [41494] = "Klatsch!*",
  [41495] = "\"Halt, hiergeblieben!\" ruft Khalin. \"Erst das",
  [41496] = "Geschäftliche!\"*",
  [41497] = "Auf der Steinbank",
  [41498] = "Von hier aus ist es hinab zum Boden schon nicht",
  [41499] = "mehr so hoch, wie von dem riesigen Tisch. Nur noch",
  [41500] = "etwa dreieinhalb Meter. Das haben Sie schon einmal",
  [41501] = "überstanden.*",
  [41502] = "\"He, he - hiergeblieben!\" ruft Khalin. Gleich",
  [41503] = "darauf hat sie Sie erwischt, und setzt Sie zurück",
  [41504] = "auf den Tisch.*",
  [41505] = "Da kommen Sie ohne Leiter nicht mehr hoch! Und",
  [41506] = "eine Leiter - die gibt es hier nicht.*",
  [41507] = "Im Pavillion",
  [41508] = "Sie stehen hier auf dem dunkelgrauen Steinboden",
  [41509] = "des Pavillions. Durch einen breiten Durchgang",
  [41510] = "können Sie hinaus auf den zentralen Platz der",
  [41511] = "Schwarzen Stadt gehen.*",
  [41512] = "Wollen Sie den Pavillion verlassen, und hinaus auf",
  [41513] = "den Platz?*",
  [41514] = "Der Steinboden besteht aus großen, grauen",
  [41515] = "Pflastersteinen. Es gibt eine Reihe von dunkleren,",
  [41516] = "steinernen Platten darunter, die in einem",
  [41517] = "wohlbekannten Muster angeordnet sind: einem",
  [41518] = "Sechseck.*",
  [41519] = "Es erscheint sehr bedeutungsvoll, daß hier, genau",
  [41520] = "in der Mitte der Schwarzen Stadt, ein solches",
  [41521] = "Sechseck existiert. Aha - dort vorn, jene",
  [41522] = "steinerne Platte, die am weitesten nach Osten hin",
  [41523] = "liegt, schaut ein wenig weiter aus dem Boden",
  [41524] = "heraus, als die übrigen!*",
  [41525] = "Oh, oh! Schnell - treten Sie ein Stück zurück! Das",
  [41526] = "ist ja unglaublich! Der Ganze Paillion ist in",
  [41527] = "Bewegung geraten, und versinkt nun lautlos im",
  [41528] = "Boden...",
  [41529] = "Er sinkt sogar immer tiefer - ein einen schwarzen",
  [41530] = "Schacht hinein, der offenbar weit hinab in die",
  [41531] = "Tiefe führt.*",
  [41532] = "\"He, he!\" erschallt Khalins Stimme. Sie kommt mit",
  [41533] = "wallenden Fettmassen dahergeeilt, und packt Sie.",
  [41534] = "Drei Sekunden später sitzen Sie wieder auf dem",
  [41535] = "Tisch. \"Wir haben doch noch etwas Geschäftliches",
  [41536] = "zu regeln!\"*",
  [41537] = "\"Halt, warte!\" ruft Khalin, eilt herbei, und",
  [41538] = "greift sich Ihre Brille. Gleich darauf hat sie Sie",
  [41539] = "erwischt, und drei Sekunden später sitzen Sie",
  [41540] = "wieder auf dem Tisch. \"Wir haben doch noch etwas",
  [41541] = "Geschäftliches zu regeln!\"*",
  [41542] = "\"Halt, warte!\" ruft Khalin, eilt herbei, und",
  [41543] = "greift nach Ihrer Brille. \"He... wo ist denn...\"",
  [41544] = "sagt sie erstaunt, und entdeckt dann ächzend die",
  [41545] = "Trümmer Ihres wertvollen Sehwerkzeuges auf dem",
  [41546] = "Boden. Aber gleich darauf hat sie Sie doch",
  [41547] = "erwischt, und drei Sekunden später sitzen Sie",
  [41548] = "wieder auf dem Tisch. \"Du bist hier, in der",
  [41549] = "Schwarzen Stadt, auch ohne Brille leicht zu",
  [41550] = "erkennen, mit Deinen bunten Kleidern!\" lächelt",
  [41551] = "sie.*",
  [41552] = "\"Halt, warte!\" ruft Khalin, eilt herbei, und",
  [41553] = "greift nach Ihrer Brille. \"He... wo ist denn...\"",
  [41554] = "sagt sie erstaunt, und entdeckt dann ächzend die",
  [41555] = "Trümmer Ihres wertvollen Sehwerkzeuges auf dem",
  [41556] = "Boden. Dann sucht Sie verzweifelt die Umgebung",
  [41557] = "ab... aber kann Sie nicht erkennen! Schwarz",
  [41558] = "getarnt, wie Sie sind, verschmilzen Sie für Khalin",
  [41559] = "mit dem dunklen Boden... hurra! Sie sind frei!*",
  [41560] = "Das ist zu nichts mehr nütze, lassen Sie es lieber",
  [41561] = "hier!*",
  [41562] = "Khalin, fuchsteufelswild und wütend, rennt ziellos",
  [41563] = "umher. \"Wo bist Du? Ich kann Dich nicht sehen!\"",
  [41564] = "brüllt sie.*",
  [41565] = "Khalin hastet außer sich vor Zorn in der Schwarzen",
  [41566] = "Stadt hin und her. \"Ich krieg Dich schon noch, Du",
  [41567] = "Wicht! Und dann geht es Dir schlecht!\"*",
  [41568] = "\"Miststück, elendes!\" brüllt die wütende Khalin,",
  [41569] = "während Sie in der Stadt umherirrt. \"Wo steckst",
  [41570] = "Du? Ich erwische Dich! Irgendwann!\"*",
  [41571] = "Auf der nördlichen Straße",
  [41572] = "Sie befinden sich hier auf halbem Weg zwischen dem",
  [41573] = "Großen Platz und der nördlichen Festungsmauer. Um",
  [41574] = "Sie herum streben riesige Gebäude und Türme in den",
  [41575] = "Himmel auf. Nach überallhin führen schmalere",
  [41576] = "Straßen in den Irrgarten Schwarzen Stadt hinein.*",
  [41577] = "An der nördlichen Mauer",
  [41578] = "Hier endet die nördliche Straße vor einer hoch",
  [41579] = "aufragenden, schwarzen Mauer. In jede Richtung",
  [41580] = "führen schmale Wege in das Gewühl der Bauwerke und",
  [41581] = "Türme hinein - perfekt geschaffen, um",
  [41582] = "sich dort hoffnungslos zu verirren.*",
  [41583] = "Auf der östlichen Straße",
  [41584] = "Dieser Punkt markiert den halben Weg zwischen dem",
  [41585] = "Großen Platz und der östlichen Festungsmauer. Auch",
  [41586] = "hier streben riesige Gebäude und Türme in den",
  [41587] = "finsteren Himmel auf. Ungezählte Straßen führen in",
  [41588] = "das Labyrinth der Schwarzen Stadt hinein. Der",
  [41589] = "Regen will nicht enden.*",
  [41590] = "An der östlichen Mauer",
  [41591] = "Hier endet die östliche Straße vor der hoch",
  [41592] = "aufragenden, schwarzen Ostmauer der Festung. Nach",
  [41593] = "überallhin führen schmale Wege in das Gewühl",
  [41594] = "der Bauwerke und Türme hinein - sehr gut geeignet,",
  [41595] = "um sich dort drin hoffnungslos zu verlaufen.*",
  [41596] = "Auf der westlichen Straße",
  [41597] = "Sie befinden sich hier auf halbem Weg zwischen dem",
  [41598] = "Großen Platz und der westlichen Festungsmauer. Um",
  [41599] = "Sie herum streben die gewaltigen Türme und",
  [41600] = "Bauwerke der Schwarzen Stadt in den Himmel auf.",
  [41601] = "In jegliche Richtung führen schmalere Straßen in",
  [41602] = "den Irrgarten der Schwarzen Stadt hinein. Noch",
  [41603] = "immer plätschert der unaufhörliche Regen herab.*",
  [41604] = "An der westlichen Mauer",
  [41605] = "Hier endet die nördliche Straße vor einer hoch",
  [41606] = "aufragenden, schwarzen Mauer. Viele schmale Wege",
  [41607] = "führen in das Gewühl der Gebäude und Türme hinein",
  [41608] = "- perfekt geschaffen, um sich dort hoffnungslos zu",
  [41609] = "verirren.*",
  [41610] = "Bleiben Sie lieber hier, und versuchen Sie ihre",
  [41611] = "Chance zu nutzen! Aus diesem Irrgarten würden Sie",
  [41612] = "nie mehr herausfinden, und so enden, wie all die",
  [41613] = "anderen Abenteurer, die sich dort hineingewagt",
  [41614] = "haben!*",
  [41615] = "Für lange, lange Zeit geht es abwärts. Das Licht",
  [41616] = "wird schwächer, aber dann schließlich durch",
  [41617] = "Beleuchtungskörper ersetzt. Und weiter geht die",
  [41618] = "Reise, bis Sie schließlich den Punkt erreicht",
  [41619] = "haben, bis zu dem der kleine, weiße Pavillion",
  [41620] = "hinabgesunken ist.*",
  [41621] = "Am Pavilion",
  [41622] = "Sie befinden sich am Rande des Schachtes auf der",
  [41623] = "Wendeltreppe, die noch weiter hinab zu führen",
  [41624] = "scheint - währenddessen sich direkt neben Ihnen",
  [41625] = "der kleine Pavillion befindet. Der aber hat eine",
  [41626] = "wundersame Veränderung erfahren!*",
  [41627] = "Der Pavillion scheint nicht mehr zur Gänze aus",
  [41628] = "Stein zu bestehen, nein - das wirkt wie Metall!",
  [41629] = "Die Spitze des Daches ist schlanker geworden, und",
  [41630] = "die vormals offenen Seitenteile sind nun mit einer",
  [41631] = "Art Glas verkleidet - wirklich erstaunlich!*",
  [41632] = "Tja, da könnte man auch nur spekulieren, was es",
  [41633] = "damit auf sich hat. Aber vielleicht erfahren Sie",
  [41634] = "mehr, wenn Sie die Wendeltreppe noch weiter",
  [41635] = "hinabsteigen?*",
  [41636] = "Sie haben das Ende Ihrer Reise erreicht. Dies ist",
  [41637] = "der Ort, an dem sich der gefürchtete Kal aufhält -",
  [41638] = "ein Ort, den außer ihm seit über viertausend",
  [41639] = "Jahren kein Mensch mehr betreten hat.*",
  [41640] = "Kals Tempel - Südende",
  [41641] = "Sie befinden sich in am Südende einer großen",
  [41642] = "unterirdischen Halle. Der Raum ist rechteckig und",
  [41643] = "gute zwanzig Meter hoch. Überall stapeln sich",
  [41644] = "elektronische Geräte in hohen Türmen und auf dem",
  [41645] = "Boden. Auf Labortischen gluckern gefährlich",
  [41646] = "aussehende Flüssigkeiten in Reagenzgläsern;",
  [41647] = "riesige Apparate sind aufgebaut, der Raum ist hell",
  [41648] = "erleuchtet. Ein breiter Weg führt nach Norden",
  [41649] = "zwischen den Gerätetürmen hindurch.*",
  [41650] = "Das, was einmal Khalins steinerner Pavillion war,",
  [41651] = "ist nun ofenbar zu einem höchst modernen",
  [41652] = "Raumschiff geworden. Seine schlanke Form",
  [41653] = "verspricht bestes Kurvenverhalten und große",
  [41654] = "Geschwindigkeit! (...oder so!) Leider ist momentan",
  [41655] = "noch keine Einstiegsluke oder ähnliches zu",
  [41656] = "entdecken.*",
  [41657] = "Die Geräte sind offenbar von modernster Bauart,",
  [41658] = "aber sie sehen nicht so aus, als wären sie von",
  [41659] = "Menschen hergestellt worden.*",
  [41660] = "Auf den Tischen stapeln sich fremdartige Apparate",
  [41661] = "und Versuchsgeräte.*",
  [41662] = "Der Verwendungs-Zweck dieser Dinge ist beim besten",
  [41663] = "Willen nicht ersichtlich.*",
  [41664] = "Wer weiß, was das für alles Geräte sind... lassen",
  [41665] = "Sie sie lieber in Ruh!*",
  [41666] = "Lassen Sie das Zeug lieber stehen, es ist saumäßig",
  [41667] = "giftig. Dioxin, DDT, PCB, Schwefelsäure, und....",
  [41668] = "MILCH!!!*",
  [41669] = "Hier steht ein weißer, glatter Kasten von etwa der",
  [41670] = "Größe einer Bierkiste. Obendrauf ist ein Schild:",
  [41671] = "\"Sigmazelle\".*",
  [41672] = "Die Sigmazelle ist elend schwer. Aber es gelingt",
  [41673] = "Ihnen, sie hochzuheben. Wohin damit?*",
  [41674] = "Kals Tempel - Nordende",
  [41675] = "Hier findet das Wunder seine Fortsetzung - kein",
  [41676] = "archaischer Tempel, kein Dämonengott, sondern eine",
  [41677] = "hochtechnisierte Station. Neben vielen",
  [41678] = "erstaunlichen Geräten, die hier aufgebaut sind,",
  [41679] = "steht eine riesige Maschine hier am Nordende der",
  [41680] = "Halle. Weiter nach Norden geht es in einen kurzen",
  [41681] = "Gang hinein.*",
  [41682] = "Die Maschine ist gute zwanzig Meter lang und fünf",
  [41683] = "Meter hoch. Sie ist eine unregelmäßige",
  [41684] = "Veransammlung von Röhren, Schienen, Kabelbäumen",
  [41685] = "und elektronischen Kästen. In Ihrer Mitte befindet",
  [41686] = "sich eine zwei Meter durchmessende, runde",
  [41687] = "Plattform. Auf diese Plattform zeigt eine",
  [41688] = "Konstruktion, die wie eine Elektronen-Kanone",
  [41689] = "aussieht. Hinter der Kanone befindet sich ein",
  [41690] = "Schaltpult.*",
  [41691] = "Die Kanone ist etwa fünf Meter lang und ragt aus",
  [41692] = "einem schwarzen Block hervor.*",
  [41693] = "Die Plattform hat nichts Besonderes an sich, außer",
  [41694] = "vielleicht der bedeutungsvollen Tatsache, daß die",
  [41695] = "Elektronenkanone in ihre Mitte zielt.*",
  [41696] = "Auf der Plattform steht ein fremdartiger Kasten -",
  [41697] = "die Sigma-Zelle.*",
  [41698] = "Das Schaltpult besitzt einen Monitor und eine Art",
  [41699] = "Computertastatur. Rechts davon befindet sich der",
  [41700] = "Netzschalter für die riesige Maschine: man braucht",
  [41701] = "einen Sicherheits-Schlüssel, um ihn aktivieren zu",
  [41702] = "können.*",
  [41703] = "Der Schlüssel ist nicht da.*",
  [41704] = "Aber der Schlüssel steckt in dem Schlüsselloch des",
  [41705] = "Netzschalters.*",
  [41706] = "Ein Summen erfüllt plötzlich die riesige Maschine.",
  [41707] = "Der Monitor flammt auf. Einige Zeilen erscheinen",
  [41708] = "auf dem Monitor: \"System im Standby-Status. Bitte",
  [41709] = "bereiten Sie das System für den Test-Lauf vor.",
  [41710] = "Geben Sie dann 'READY' ein.\"*",
  [41711] = "Eine neue Meldung erscheint auf dem Monitor:",
  [41712] = "\"System-Fehler. Der Testlauf kann nicht",
  [41713] = "stattfinden. Bitte überprüfen.\"*",
  [41714] = "Ein kurzer Gang führt von hier nach Norden,*",
  [41715] = "Im Gang",
  [41716] = "Der Gang ist schon nach wenigen Metern zuende.",
  [41717] = "Nach Westen hin liegt eine Glaswand und eine Tür,",
  [41718] = "gegenüber davon befindet sich an der Wand ein",
  [41719] = "Schlüsselbord und darunter ein Knopf. Hinter der",
  [41720] = "Glaswand befindet sich eine Art Wohnung.*",
  [41721] = "Ein kleiner Schlüssel hängt an dem Bord.*",
  [41722] = "Mit dem Rücken zu Ihnen sitzt ein Mann in einem",
  [41723] = "weißen Kittel gedankenversunken an einem Tisch.*",
  [41724] = "Es ist eine ganz normale kleine Wohnung für eine",
  [41725] = "Person - dort gibt es nichts Besonderes.*",
  [41726] = "Es ist eine Gittertür - man könnte meinen, die",
  [41727] = "Wohnung wäre eine Art Zelle.*",
  [41728] = "Der Knopf wird möglicherweise dazu gedacht sein,",
  [41729] = "die Tür zu öffnen.*",
  [41730] = "Langsam! Sie sollten sich erstmal ein bißchen",
  [41731] = "informieren, meinen Sie nicht? Wer weiß, was Ihnen",
  [41732] = "alles blüht, wenn Sie leichtfertig diesen Knopf",
  [41733] = "drücken!*",
  [41734] = "Man kann nur den Rücken des Mannes sehen. Aber ein",
  [41735] = "schöner Rücken kann, wie die Wissenschaft kürzlich",
  [41736] = "unwiederlegbar bewiesen hat, auch entzücken.*",
  [41737] = "Der Mann dreht sich um, springt plötzlich",
  [41738] = "erschrocken auf, und starrt Sie an.*",
  [41739] = "Der Mann sieht in seinem Kittel aus wie ein",
  [41740] = "Wissenschaftler. Dabei ist er aber jung und",
  [41741] = "muskulös gebaut. In der Brusttasche seines Kittels",
  [41742] = "trägt er eine Menge Kugelschreiber. Sein Haar ist",
  [41743] = "stahlgrau. Er sieht ebenso intelligent wie listig",
  [41744] = "aus. Auf seinem Kittel ist ein Namensschild",
  [41745] = "aufgenäht.*",
  [41746] = "Ach herrje! Halten Sie sich fest! Dieser Mann",
  [41747] = "ist... KAL! Der Gott der Zerstörung persönlich!",
  [41748] = "Jedenfalls steht da 'Cal' auf dem Namensschild!",
  [41749] = "Das ist ja kaum zu glauben!*",
  [41750] = "Seine Stimme dringt durch die Scheibe. \"Wer sind",
  [41751] = "denn Sie?\" fragt er unschlüssig. Dann fällt sein",
  [41752] = "Blick auf den großen Kristall, den Sie bei sich",
  [41753] = "haben und seine Augen werden groß und kugelrund.",
  [41754] = "\"Der Kristall!\" ächzt er fassungslos.*",
  [41755] = "Er starrt Sie seltsam an, und packt die",
  [41756] = "Gitterstäbe. \"Schnell!\" ruft er im Befehlston.",
  [41757] = "\"Lassen Sie mich hier raus! Drücken Sie den Knopf",
  [41758] = "unter dem Schlüsselbord und geben Sie mir den",
  [41759] = "Kristall.\" Er sieht Sie fragend an. \"Na los doch!\"",
  [41760] = "ruft er ärgerlich, und rüttelt am Gitter.*",
  [41761] = "\"Ach verdammt!\" sagt der Mann niedergeschlagen.",
  [41762] = "\"Ich weiß. Sie müssen ein unsagbares Strapazen",
  [41763] = "hinter sich gebracht haben, um mit diesem Kristall",
  [41764] = "bis hierher zu gelangen. Und Sie glauben ohne",
  [41765] = "Zweifel, daß ich ein böser Gott bin.\" Er lächelt",
  [41766] = "hintergründig. 'Aber sehen Sie mich an! Schaue ich",
  [41767] = "aus wie ein Gott? Die Ganze Kal-Story ist eine",
  [41768] = "riesige Komödie. Wenn Sie mich hier herauslassen,",
  [41769] = "dann erzähle ich Ihnen die Wahrheit. Machen Sie",
  [41770] = "das Gitter auf. Soviel Vertrauen müssen Sie schon",
  [41771] = "haben!\"*",
  [41772] = "\"Machen Sie zuerst auf!\" beharrt er.*",
  [41773] = "\"Na endlich!\" ruft er, als die Türe zurückgleitet.",
  [41774] = "Er stürmt heraus, und entreißt Ihnen den Kristall.",
  [41775] = "Dann eilt er in die Halle hinaus, und verweilt in",
  [41776] = "ihrer Mitte für einen Augenblick. Er sieht den",
  [41777] = "Pavillion, der inzwischen qanz herabgesunken ist,",
  [41778] = "und sich völlig verwandelt hat. Er lächelt.*",
  [41779] = "\"Phantastisch!\" ruft er. Dann durchquert er die",
  [41780] = "Halle, und erreicht ihr Nordende. Dort bleibt er",
  [41781] = "an einem elektronischen Gerät kurz stehen, starrt",
  [41782] = "es ungläubig an, und sieht dann zu Ihnen herüber.",
  [41783] = "\"Kathaura ist tot? Bool ist zerstört? Die",
  [41784] = "dreiäugige Bestie weg? Und Khalin haben Sie auch",
  [41785] = "überrumpelt? Unglaublich, Mann! Vor Ihnen muß man",
  [41786] = "ja direkt Angst haben!\"*",
  [41787] = "In der Wohnung",
  [41788] = "Hier gibt es nicht viel von Interesse. Ein Bett,",
  [41789] = "ein Stuhl, ein Tisch, alles recht spartanisch, und",
  [41790] = "am Boden festgeschraubt.*",
  [41791] = "Cal ist hier. Er sitzt auf seinem Stuhl, und",
  [41792] = "starrt betrübt die Wand an. Als er Sie nahen hört,",
  [41793] = "dreht er sich hoffnungsvoll um.",
  [41794] = "\"Na, haben Sie sich's doch noch überlegt? Wollen",
  [41795] = "Sie mit mir kommen?\"*",
  [41796] = "\"Tatsächlich?\" ruft er begeistert, und springt",
  [41797] = "auf. \"Na, dann los, aber sofort!\" Er packte Sie am",
  [41798] = "Arm, und zieht Sie mit hinaus in die Halle.*",
  [41799] = "\"Nein? Schade!\" Damit dreht er sich wieder um, und",
  [41800] = "starrt trübsinnig die Wand an.*",
  [41801] = "\"Ach, vergessen Sie's!\" sagt Cal niedergschlagen.",
  [41802] = "\"Ich hab keine Lust zum diskutieren. Lassen Sie",
  [41803] = "mich allein. Wenn Sie mir helfen wollen, dann",
  [41804] = "klopfen Sie gegen die Scheibe. Ansonsten will ich",
  [41805] = "nur noch meine Ruhe haben!\"*",
  [41806] = "Kal, oder besser: \"Cal\", wie es auf seinem",
  [41807] = "Namensschild steht, ist wieder herüber zum",
  [41808] = "Nordende der Halle gekommen und macht sich an der",
  [41809] = "großen Maschine zu schaffen. Er steigt auf den",
  [41810] = "schwarzen Block hinauf, aus dem die",
  [41811] = "Elektronenkanone hervorschaut, und versenkt das",
  [41812] = "\"Auge des Kal\" vorsichtig darin. Dann begibt er",
  [41813] = "sich an das Schaltpult der Maschine. \"So. Jetzt",
  [41814] = "brauche ich nur noch die Sigmazelle. Sie steht an",
  [41815] = "der Südseite der Halle. Würden Sie sie mir bitte",
  [41816] = "holen?\"*",
  [41817] = "\"Wollen Sie mir nicht helfen? Ich habe hier noch",
  [41818] = "einiges Zu tun!\" sagt Cal, und deutet auf seinen",
  [41819] = "Monitor. \"Die Sigmazelle steht am Südende der",
  [41820] = "Halle. Holen Sie sie doch bitte. Es ist so ein",
  [41821] = "großer, weißer Kasten!\"*",
  [41822] = "\"Na, sehr hilfsbereit sind Sie ja nicht!\" sagt Cal",
  [41823] = "und geht, um selber die Sigmazelle zu holen. Nach",
  [41824] = "fünf Minuten ist er wieder da. Er legt die",
  [41825] = "Sigmazelle auf die Plattform der großen Maschine,",
  [41826] = "und begibt sich an die Kontrollen.*",
  [41827] = "Uff! Das war Schwerstarbeit. Kal steht am",
  [41828] = "Schaltpult der großen Maschine, und deutet Ihnen,",
  [41829] = "daß Sie die Sigma-Zelle auf die Plattform der",
  [41830] = "Maschine legen sollen.*",
  [41831] = "Na los, wir helfen Ihnen... hauruck! So. Die",
  [41832] = "Sigma-Zelle liegt nun auf der Plattform.*",
  [41833] = "Hauruck! So. Die Sigma-Zelle liegt nun auf der",
  [41834] = "Plattform.*",
  [41835] = "Die Maschine beginnt zu summen, Cal springt vom",
  [41836] = "Schaltpult herab, und gesellt sich zu Ihnen. \"Es",
  [41837] = "dauert nicht mehr lange, dann ist alles geschafft.",
  [41838] = "Diese Maschine hier ist der Grund für den ganzen",
  [41839] = "verflixten Kal-Mythos, und dafür, daß ich hier",
  [41840] = "über viertausend Jahre lang eingesperrt war. Es",
  [41841] = "ist eine verdammt lange Geschichte. Soll ich Ihnen",
  [41842] = "nun erzählen?\"*",
  [41843] = "Cal lacht. \"Es wäre ja ein Wunder, wenn Sie das",
  [41844] = "nun nicht mehr interessieren würde!",
  [41845] = "Also hören Sie gut zu. Ich bin kein Mensch, obwohl",
  [41846] = "ich so aussehe. Ebenso waren Khalin und Kathaura",
  [41847] = "Wir stammen von einem Planeten, der so weit",
  [41848] = "entfernt ist, daß Sie es sich nicht vorstellen",
  [41849] = "können. Vor viertausend Jahren kamen wir mit einem",
  [41850] = "Raumschiff in diesen Teil der Galaxis. Wir waren",
  [41851] = "auf der Flucht.*",
  [41852] = "Wir stießen auf die Erde, und fanden, daß es hier",
  [41853] = "günstige Lebensbedingungen für uns gab. Es schien",
  [41854] = "uns ein sicherer Platz vor unseren Vorfolgern zu",
  [41855] = "sein, und so landeten wir. Wir brachten unsere",
  [41856] = "Geräte hierher, demontierten das Raumschiff, und",
  [41857] = "errrichteten diese Station, in der wir einige Zeit",
  [41858] = "ungestört verbringen wollten. Wir nahmen auch",
  [41859] = "diese große Maschine hier mit, den sogenannten",
  [41860] = "\"Molekular-Modulator\".*",
  [41861] = "Der Molekular-Modulator ist eine unglaubliche",
  [41862] = "Erfindung. Mittels eines Mesonen-Strahls kann man",
  [41863] = "damit Moleküle aufknacken, sie umsortieren, und",
  [41864] = "neu wieder zusammenschmelzen, sodaß man fast jedes",
  [41865] = "Material in ein beliebiges anderes umwandeln kann.",
  [41866] = "Man könnte damit tatsächlich aus Blei Gold machen!",
  [41867] = "Das Herz der Maschine ist, wie Sie wahrscheinlich",
  [41868] = "schon vermutet haben, jener Kristall, den Sie als",
  [41869] = "das \"Auge des Kal\" kennen. Damit begann dann auch",
  [41870] = "die Katastrophe.*",
  [41871] = "Zu der Zeit, als wir auf der Erde landeten, war",
  [41872] = "hier gerade eine andere raumfahrende Rasse zu",
  [41873] = "Gast. Die Menschheit war eine wilde Horde",
  [41874] = "abergläubischer Barbaren, aber sie verstanden sich",
  [41875] = "gut mit der anderen Rasse, die sie die \"Alten",
  [41876] = "Wesen\" nannten. Sie tolerierten uns anfangs, da",
  [41877] = "wir uns ruhig verhielten.",
  [41878] = "Doch dann tanzte Khalin plötzlich aus der Reihe,",
  [41879] = "und brachte auch Kathaura auf ihre Seite, der",
  [41880] = "schon immer in die alte Schachtel verliebt war.*",
  [41881] = "Sie sperrten mich hier unten ein, ließen sich im",
  [41882] = "Modulator zu regelrechten Monstern umwandeln, und",
  [41883] = "begannen, die Erde zu terrorisieren. Kathaura tat",
  [41884] = "das unter meinem Namen, weil er ein verdammter",
  [41885] = "Feigling ist. Schließlich wurde das den Alten",
  [41886] = "Wesen zuviel, und Lharas geriet in einen riesigen",
  [41887] = "Streit mit Kathaura. Währenddessen drang Tell hier",
  [41888] = "ein, und stahl - ich muß zugeben,",
  [41889] = "berechtigterweise - den Kristall des Molekular-",
  [41890] = "Modulators. So konnten Khalin und Kathaura keinen",
  [41891] = "Unfug mehr anstellen - unser Raumschiff konnte nun",
  [41892] = "allerdings auch nicht mehr starten.*",
  [41893] = "Khalin baute dann dort oben die Schwarze Stadt,",
  [41894] = "und hoffte darauf, daß sie eines Tages den",
  [41895] = "Kristall zurückerhalten würde, um sich wieder als",
  [41896] = "Rachegöttin aufspielen zu können. Gottseidank",
  [41897] = "bekam sie ihn nicht.",
  [41898] = "Mein Pech dabei war, daß ich wegen dieser leidigen",
  [41899] = "Geschichte nun schon so lange hier unten",
  [41900] = "eingesperrt bin. Ich habe nämlich eine ziemlich",
  [41901] = "wichtige Mission zu erfüllen, und die hätte ich",
  [41902] = "schon vor 3900 Jahren in Angriff nehmen müssen!*",
  [41903] = "Aber jetzt, da der Kristall wieder hier ist, kann",
  [41904] = "ich die Sigma-Zelle wieder aufladen, die ich für",
  [41905] = "den Heimflug brauche.\"",
  [41906] = "Er deutet auf das Objekt, das einmal der Pavillion",
  [41907] = "war, und das nun auf dem Boden der Halle steht.",
  [41908] = "\"Und da die Station mein Raumschiff automatisch",
  [41909] = "schon wieder zusammengebaut hat, steht meinem",
  [41910] = "Rückflug nun nichts mehr im Wege. Das heißt: fast",
  [41911] = "nichts! Leider habe ich ein kleines Problem. Darf",
  [41912] = "ich Ihnen davon erzählen?\"*",
  [41913] = "\"Ich erzähl's Ihnen trotzdem!\" sagt Cal.*",
  [41914] = "\"Das Problem liegt darin, daß Khalin und Kathaura",
  [41915] = "nun nicht mehr mit von der Partie sind. Ich habe",
  [41916] = "ja schon gesagt, daß ich eine Mission zu erfüllen",
  [41917] = "habe. Eine sehr wichtige Mission sogar. Aber",
  [41918] = "allein kann ich sie nicht bewältigen.",
  [41919] = "Ich stamme von einer Welt, die seit langer Zeit",
  [41920] = "von einer Rasse von Unterdrückern beherrscht wird.",
  [41921] = "Und ich bin so etwas wie eine Schlüsselfigur - im",
  [41922] = "Kampf um die Freiheit.*",
  [41923] = "Es ist eine schöne Welt, von der ich stamme,\"",
  [41924] = "erzählt Kal. \"Wir leben nicht an der Oberfläche",
  [41925] = "des Planeten, sondern in gigantischen Hohlräumen",
  [41926] = "unter der Erde, die so groß sind, daß bequem",
  [41927] = "Flugzeuge darin fliegen können. Das Sonnenlicht",
  [41928] = "wird durch Adern von kristallinen Gesteins-",
  [41929] = "Schichten hineingelenkt...\"",
  [41930] = "Dann winkt er ab. \"Ich komme ins Schwärmen,\"",
  [41931] = "erklärt er. \"Tatsache ist, daß ich den Kampf um",
  [41932] = "die Freiheit der Höhlenwelt nicht allein führen",
  [41933] = "kann. Ich brauche Hilfe.*",
  [41934] = "\"Es sind einige Aufgaben zu erledigen, für die",
  [41935] = "Khalin und Kathaura vorgesehen waren, aber da die",
  [41936] = "beiden jetzt nicht mehr da sind... Mein Problem",
  [41937] = "beginnt sogar schon hier: allein kann ich das",
  [41938] = "Schiff nicht starten.\"",
  [41939] = "Cal runzelt die Stirn, und sieht Sie an. \"Wie wäre",
  [41940] = "es mit Ihnen? Sie sind ein kampferprobter",
  [41941] = "Abenteurer, wie man selten einen trifft. Mit Ihnen",
  [41942] = "hätte ich gute Chancen. Wollen Sie mir helfen -",
  [41943] = "und mit mir zur Höhlenwelt zurückkehren?\"*",
  [41944] = "\"Wollen Sie meine Frage nicht beantworten?\" fragt",
  [41945] = "Cal.*",
  [41946] = "\"Schade,\" sagt Cal. \"Ich kann's Ihnen nicht",
  [41947] = "verdenken. Aber somit sind wir beide hier auf ewig",
  [41948] = "eingesperrt. Ich weiß auch nicht, wie wir aus",
  [41949] = "dieser Festung wieder herauskommen könnten.\"",
  [41950] = "Damit wendet er sich deprimiert um, und trottet",
  [41951] = "zurück zu seiner Wohnung.*",
  [41952] = "\"Wirklich?\" fragt Cal ungläubig und hocherfreut",
  [41953] = "zugleich. \"Nun, es ist eine gefährliche Mission!",
  [41954] = "Aber ich verspreche Ihnen eine großartige Reise,",
  [41955] = "und ein phantastisches Abenteuer!",
  [41956] = "Also los, dann packen wir's an!\"",
  [41957] = "\"So - das ist fertig,\" sagt Cal. Er steigt auf die",
  [41958] = "Plattform und nimmt die Sigma-Zelle, die plötzlich",
  [41959] = "federleicht geworden ist. Er trägt sie in das",
  [41960] = "Raumschiff, und montiert fünf Minuten lang herum.",
  [41961] = "Danach steigt das Raumschiff plötzlich in die",
  [41962] = "Höhe, kehrt aber bald darauf wieder zurück.",
  [41963] = "Kal erscheint wieder, geht zum Molekular-",
  [41964] = "Modulator, und drückt ein paar Knöpfe.*",
  [41965] = "\"Jetzt ist alles geschafft,\" sagt Cal. Er nimmt",
  [41966] = "Sie behutsam an der Hand, und führt Sie zum",
  [41967] = "Südende der Halle. Die Einstiegsluke des",
  [41968] = "Raumschiffes steht offen.",
  [41969] = "\"Nur nicht nervös werden,\" sagt er. \"Nachdem, was",
  [41970] = "Sie schon alles durchgemacht haben, dürfte eine",
  [41971] = "Raumreise für Sie ein Klacks sein!\"",
  [41972] = "Im nächsten Moment betreten Sie schon das",
  [41973] = "Raumschiff. Die Tür schließt sich geräuschlos",
  [41974] = "hinter Ihnen.*",
  [41975] = "Im Raumschiff",
  [41976] = "Ringsherum blinken Lichter und flimmern Monitore.",
  [41977] = "Ein leises Summen erfüllt den Raum. Vor einigen",
  [41978] = "breiten Konsolen stehen drei Pilotensessel, und",
  [41979] = "über Ihnen befindet sich ein großes Sichtfenster,",
  [41980] = "durch das jetzt allerdings noch nichts zu sehen",
  [41981] = "ist.*",
  [41982] = "Die Lichter stammen von langen Reihen blinkender",
  [41983] = "Anzeigelämpchen, die überall im Raumschiff",
  [41984] = "verteilt sind.*",
  [41985] = "Es gibt einige Monitore hier, allerdings zeigen",
  [41986] = "sie momentan nur lange Reihen verwirrender",
  [41987] = "Zahlen.*",
  [41988] = "Es gibt vier oder fünf große Konsolen hier, auf",
  [41989] = "denen sich eine Unzahl von Schaltern, Knöpfen,",
  [41990] = "Tasten, Hebeln und Anzeigeinstrumenten befinden.*",
  [41991] = "Es sind große, weiche Pilotensessel, der Flug",
  [41992] = "verspricht nicht unbequem zu werden.*",
  [41993] = "Freuen Sie sich auf Ihre Zeit im All - durch",
  [41994] = "dieses Fenster werden Sie sicher so manches Wunder",
  [41995] = "erblicken können!*",
  [41996] = "Cal hantiert an einigen Bedienelementen herum, das",
  [41997] = "leise Summen des Raumschiffes steigert sich zu",
  [41998] = "einem permanenten Brummton.*",
  [41999] = "Cal kommt zu Ihnen herüber, drückt Sie in einen",
  [42000] = "der Pilotensessel und schnallt Sie fest. Er",
  [42001] = "instruiert Sie, welche Schalter Sie wann zu",
  [42002] = "betätigen haben, und erklärt Ihnen, welche",
  [42003] = "Monitore Sie im Auge behalten müssen.*",
  [42004] = "Cal setzt sich selber in einen Pilotensessel, und",
  [42005] = "schnallt sich an.",
  [42006] = "\"Also dann!\" sagt er. \"Es geht los!\"",
  [42007] = "Er betätigt ein paar Schalter, und plötzlich",
  [42008] = "ertönt ein ohrenbetäubendes Fauchen, und Sie",
  [42009] = "werden von einer enormen Kraft in Ihren Sitz",
  [42010] = "gedrückt.*",
  [42011] = "\"Es läßt gleich wieder nach!\" ruft Cal herüber,",
  [42012] = "...und so ist es auch.",
  [42013] = "Kaum eine Minute später durchstoßen Sie die",
  [42014] = "Wolkendecke, und die ersten Sterne werden durch",
  [42015] = "das große Fenster sichtbar.....*",
  [42016] = "Hm.",
  [42017] = "Das war's wohl. Viel Glück auf der Höhlenwelt,",
  [42018] = "McMullighan! Wir bleiben hier, und sehen zu, daß",
  [42019] = "wir Ihr kommendes Abenteuer auf den Bildschirm",
  [42020] = "kriegen:",
  [42022] = "H E X U M A  II - Dämmerung auf der Höhlenwelt.",
  [42024] = "++++++++++++++++ E N D E ++++++++++++++++++*",
  [42025] = "Blubblubb...",
  [42026] = "Nach ungefähr sechs Metern sind Sie bei dem",
  [42027] = "Kadaver des schrecklichen Bool angekommen. Der",
  [42028] = "Ablick ist bedrückend - das Monster liegt",
  [42029] = "verkrümmt auf der Seite.",
  [42030] = "... aber jetzt müssen Sie schnell wieder hoch -",
  [42031] = "die Luft wird schon knapp...",
  [42032] = "Sekunden später durchbrechen Sie prustend die",
  [42033] = "Wasseroberfläche.*",
  [42034] = "Aha. Sie wollen zu dem Kadaver des schrecklichen",
  [42035] = "Bool hinabtauchen, was? Na, hoffentlich lebt er",
  [42036] = "nicht noch ein bißchen...*",
  [42037] = "Da kommen Sie nicht rauf. Die Felswand ist viel",
  [42038] = "zu glatt und steil. Und außerdem gibt es dort",
  [42039] = "oben rein gar nichts...*",
  [42040] = "Cal ist hier und starrt trübsinnig auf den",
  [42041] = "Tisch.*",
}
